def client_report_mode() -> bool:
    """True when UI should hide backend diagnostics (default)."""
    try:
        if st.session_state.get("iidatech_show_internal_diagnostics"):
            return False
    except Exception:
        pass
    return CLIENT_REPORT_MODE


def _client_hidden_section_key(key: str) -> bool:
    normalized = str(key or "").strip().lower()
    if normalized in CLIENT_HIDDEN_SECTION_KEYS:
        return True
    return any(
        marker in normalized
        for marker in ("verification", "gate status", "readiness", "qa ", "diagnostic", "rescue", "trace audit")
    )


def filter_section_dict_for_client(data: dict) -> dict:
    if not isinstance(data, dict) or not client_report_mode():
        return data
    return {
        key: value
        for key, value in data.items()
        if not _client_hidden_section_key(str(key))
    }


def filter_section_output_for_client(raw: str) -> str:
    if not client_report_mode() or not str(raw or "").strip():
        return raw
    cleaned = re.sub(r"^```(?:json)?\s*|\s*```$", "", str(raw).strip(), flags=re.MULTILINE)
    try:
        data = json.loads(cleaned)
    except json.JSONDecodeError:
        return raw
    if not isinstance(data, dict):
        return raw
    return json.dumps(filter_section_dict_for_client(data), indent=2, ensure_ascii=False)

