def apply_competitor_intelligence_verdict_cap(report_payload: dict) -> None:
    """Cap conviction when competitor/pricing/review intelligence is below funding grade."""
    diligence = report_payload.get("diligence_pack") or {}
    if not isinstance(diligence, dict):
        return
    gate = diligence.get("competitor_intelligence_gate") or {}
    if not isinstance(gate, dict):
        return
    if not gate or gate.get("passed"):
        return
    if str(gate.get("max_verdict", "")).upper() != "CONDITIONAL_YES":
        return
    investment = report_payload.get("investment_decision")
    if isinstance(investment, dict) and str(investment.get("verdict", "")).upper() == "STRONG_YES":
        investment["verdict"] = "CONDITIONAL_YES"
        investment["verdict_capped_by"] = "competitor_intelligence_gate"
    boardroom = report_payload.get("boardroom_strategist")
    if isinstance(boardroom, dict):
        raw_verdict = str(boardroom.get("investment_verdict", "")).upper().replace(" ", "_")
        if raw_verdict == "STRONG_YES":
            boardroom["investment_verdict"] = "CONDITIONAL_YES"
            boardroom["verdict_capped_by"] = "competitor_intelligence_gate"

