def read_env_value(name: str) -> str:
    """Read a key from environment, Streamlit secrets, or nearby .env files."""
    if os.getenv(name):
        return os.getenv(name, "").strip()

    try:
        value = st.secrets.get(name, "")
        if value:
            return str(value).strip()
    except Exception:
        pass

    for env_path in (APP_DIR / ".env", *PRODUCTION_ENV_CANDIDATES):
        if not env_path.exists():
            continue
        try:
            for line in env_path.read_text(encoding="utf-8-sig", errors="ignore").splitlines():
                line = line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                key, value = line.split("=", 1)
                key = key.lstrip("\ufeff")
                if key.strip() == name:
                    return value.strip().strip('"').strip("'")
        except OSError:
            continue
    return ""


def env_source_for(*names: str) -> str:
    """Return where a key was found without exposing the key itself."""
    for name in names:
        if os.getenv(name):
            return "environment"

        try:
            value = st.secrets.get(name, "")
            if value:
                return "Streamlit secrets"
        except Exception:
            pass

        for env_path in (APP_DIR / ".env", *PRODUCTION_ENV_CANDIDATES):
            if not env_path.exists():
                continue
            try:
                for line in env_path.read_text(encoding="utf-8-sig", errors="ignore").splitlines():
                    line = line.strip()
                    if not line or line.startswith("#") or "=" not in line:
                        continue
                    key, _ = line.split("=", 1)
                    key = key.lstrip("\ufeff")
                    if key.strip() == name:
                        if env_path.name == ".env" and env_path.parent.name == "research_llm_production":
                            return "uploaded production .env"
                        if env_path == APP_DIR / ".env":
                            return "files6/.env"
                        try:
                            return str(env_path.relative_to(APP_DIR.parent)).replace("\\", "/")
                        except ValueError:
                            return env_path.name
            except OSError:
                continue
    return "missing"


