def read_int_setting(name: str, default: int, minimum: int = 0, maximum: int = 50) -> int:
    try:
        value = int(read_env_value(name) or os.getenv(name, "") or default)
    except (TypeError, ValueError):
        value = int(default)
    return min(max(value, minimum), maximum)


