def is_dummy_key(value: str) -> bool:
    clean = str(value or "").strip().lower()
    return clean.startswith(("dummy", "dummy_", "test_dummy", "dryrun", "dry_run", "fake_", "placeholder_"))


def is_dummy_endpoint(value: str) -> bool:
    clean = str(value or "").strip().lower()
    if not clean:
        return False
    parsed = urlparse(clean)
    host = parsed.netloc or clean
    return "dummy" in host or host.endswith("example.com") or "example.com/" in clean


def dummy_execution_enabled(*values: str) -> bool:
    return DUMMY_EXECUTION_MODE or any(is_dummy_key(value) or is_dummy_endpoint(value) for value in values)


def dummy_success(service: str, detail: str = "") -> tuple[bool, str]:
    message = f"Dummy {service} dry-run accepted. No external request was sent."
    if detail:
        message = f"{message} {detail}"
    return True, message


