def key_status(value: str) -> str:
    return "configured" if value else "not configured"


def key_status_with_source(value: str, *names: str) -> str:
    if not value:
        return "not configured"
    source = env_source_for(*names)
    return f"configured ({source})" if source != "missing" else "configured"


def partial_key_status(value: str, missing_setup: str, *names: str) -> str:
    """Show that a key exists while a non-secret setup field is still needed."""
    if not value:
        return "not configured"
    return f"{key_status_with_source(value, *names)}; {missing_setup} needed"


def configured_if(condition: bool, missing_setup: str = "OAuth/API connect") -> str:
    return "configured" if condition else f"{missing_setup} needed"


def render_production_runtime_status() -> None:
    """Show durable backend readiness without exposing secrets."""
    if runtime_health_snapshot is None:
        st.warning("Durable runtime backend is not loaded. Check production_runtime.py.")
        return
    try:
        health = runtime_health_snapshot()
    except Exception as exc:
        st.error(f"Durable runtime backend error: {exc}")
        return

    counts = health.get("counts", {}) if isinstance(health, dict) else {}
    st.subheader("Durable runtime backend")
    st.caption(
        "This is the local production-style backend for projects, queued jobs, CRM, usage, audit logs, "
        "outbound messages, and email suppression. It does not store API secrets."
    )
    cols = st.columns(5)
    cols[0].metric("Projects", counts.get("projects", 0))
    cols[1].metric("Pending jobs", health.get("pending_jobs", 0))
    cols[2].metric("CRM contacts", counts.get("crm_contacts", 0))
    cols[3].metric("Suppressed emails", counts.get("email_suppression", 0))
    cols[4].metric("Audit events", counts.get("audit_log", 0))
    with st.expander("Runtime database and worker notes", expanded=False):
        st.code(str(health.get("db_path", "")), language="text")
        st.write("Run queued local jobs with:")
        st.code("python worker_runtime.py --loop --sleep 5", language="bash")
        st.write("Run the API backend with:")
        st.code("uvicorn backend_api:app --host 0.0.0.0 --port 8000", language="bash")
        st.write("For production, replace local SQLite with Postgres and replace the local scheduler with Redis/RQ, Celery, or a managed queue.")
    with st.expander("Business OS backend readiness", expanded=False):
        st.write(
            "The app now has a separate FastAPI backend entrypoint for real server-side jobs, "
            "webhooks, CRM records, outbound drafts, audit logs, usage, and approved integrations."
        )
        st.code("backend_api.py", language="text")
        st.code("BACKEND_RUNTIME_ROADMAP.md", language="text")
        if backend_integration_status is None:
            st.warning("Backend integration status module is not loaded.")
        else:
            status_rows = []
            for name, meta in backend_integration_status().items():
                status_rows.append({
                    "Service": name,
                    "Status": "configured" if meta.get("configured") else "needs setup",
                    "Purpose": meta.get("purpose", ""),
                    "Required env": ", ".join(meta.get("required", [])),
                })
            st.dataframe(status_rows, width="stretch", hide_index=True)
        st.markdown(
            """
**What changed from prototype to backend foundation**

- Automations can now be queued as durable jobs instead of only living in the UI.
- The FastAPI backend can receive webhooks and process jobs while the Streamlit UI is separate.
- Email, Slack, n8n/webhook, NocoDB, Stripe, and PostHog actions are approval-gated.
- The runtime database keeps jobs, CRM records, outbound messages, usage, suppressions, and audit logs.
            """.strip()
        )

