def source_access_class_for_record(record: dict) -> str:
    family = str(record.get("source_family", "") or "").lower()
    url = str(record.get("url", "") or "").lower()
    if family == "statista_public_metadata" or any(domain in url for domain in {"statista.com", "r.statista.com", "cdn.statista-rankings.com"}):
        return "public_metadata_cross_check"
    if family in LIMITED_OR_METADATA_EVIDENCE_FAMILIES:
        return "source_route_only"
    if any(domain in url for domain in PAID_OR_LIMITED_SOURCE_DOMAINS):
        return "paid_or_limited"
    if family in FREE_PUBLIC_EVIDENCE_FAMILIES:
        return "free_public_or_open"
    return "public_or_mixed"


