def industry_source_hint(industry: str) -> str:
    industry_l = industry.lower()
    for key, hint in INDUSTRY_SOURCE_HINTS.items():
        if key in industry_l:
            return hint
    return (
        "official statistics, academic research, regulator data, company filings, trade associations, "
        "credible news, competitor disclosures, pricing pages, and regional policy sources"
    )


def safe_filename(value: str) -> str:
    cleaned = re.sub(r"[^A-Za-z0-9._-]+", "_", value.strip())
    return cleaned.strip("_")[:90] or "report"


def tender_tracker_data_dir() -> Path | None:
    for path in TENDER_TRACKER_DATA_CANDIDATES:
        if (path / "active_tenders.json").exists():
            return path
    return None


def read_json_file(path: Path, default):
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return default


def write_json_file(path: Path, payload) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")


def parse_iso_datetime(value: str | None) -> datetime | None:
    if not value:
        return None
    try:
        return datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except Exception:
        return None


def format_tender_datetime(value: str | None) -> str:
    parsed = parse_iso_datetime(value)
    if not parsed:
        return str(value or "")
    return parsed.strftime("%d %b %Y, %H:%M")


def tender_category(title: str, organization: str = "") -> str:
    text = f"{title} {organization}".lower()
    categories = [
        ("Construction / Civil Works", ("construction", "road", "bridge", "building", "retaining wall", "pcc", "civil")),
        ("Security / Facilities", ("security", "guard", "housekeeping", "facility", "manpower")),
        ("Chemicals / Materials", ("chemical", "acid", "sulphur", "sodium", "fertiliser", "phosphoric", "nahs")),
        ("Equipment / HVAC", ("split ac", "air conditioner", "equipment", "machinery", "instrument", "monitoring")),
        ("IT / Software / Digital", ("software", "it ", "website", "portal", "implementation", "digital", "data", "shield")),
        ("Power / Energy", ("power", "nhpc", "ntpc", "electric", "transmission", "substation")),
        ("Defence / Aerospace", ("defence", "drdo", "ins ", "kalinga", "shipyard", "aerospace")),
        ("Education / Research", ("iiser", "iimb", "institute", "university", "research")),
        ("Food / Agriculture", ("food", "fci", "agriculture", "crop", "grain", "procurement")),
    ]
    for label, terms in categories:
        if any(term in text for term in terms):
            return label
    return "Other Government Procurement"


def tender_metadata(record: dict) -> dict:
    raw = record.get("metadata_json") or record.get("metadata") or {}
    if isinstance(raw, dict):
        return raw
    if not raw:
        return {}
    try:
        parsed = json.loads(str(raw))
        return parsed if isinstance(parsed, dict) else {}
    except Exception:
        return {}


def stable_tender_portal_url(record: dict) -> str:
    source_url = str(record.get("source_url") or "").strip()
    if source_url:
        return source_url
    metadata = tender_metadata(record)
    portal_url = str(metadata.get("portal_url") or "").strip()
    if portal_url:
        return f"{portal_url}?page=FrontEndListTendersbyDate&service=page"
    detail_url = str(record.get("detail_url") or "").strip()
    if "?" in detail_url:
        return detail_url.split("?", 1)[0]
    return detail_url


def normalize_tender_rows(records: list[dict]) -> list[dict]:
    rows = []
    seen = set()
    for record in records:
        if not isinstance(record, dict):
            continue
        dedupe_key = (
            record.get("tender_id")
            or record.get("source_key")
            or record.get("detail_url")
            or record.get("title")
        )
        if dedupe_key in seen:
            continue
        seen.add(dedupe_key)
        organization = str(record.get("organization") or "").replace("||", " / ")
        title = str(record.get("title") or "").strip()
        closing_at = str(record.get("closing_at") or "")
        closing_dt = parse_iso_datetime(closing_at)
        days_to_close = ""
        if closing_dt:
            now = datetime.now(closing_dt.tzinfo) if closing_dt.tzinfo else datetime.now()
            days_to_close = (closing_dt.date() - now.date()).days
        rows.append({
            "Tender": title,
            "Organization": organization,
            "Portal": record.get("portal_name") or record.get("source_name") or "",
            "Tender ID": record.get("tender_id") or record.get("source_key") or "",
            "Reference": record.get("reference_no") or "",
            "Published": format_tender_datetime(record.get("published_at")),
            "Closing": format_tender_datetime(closing_at),
            "Opening": format_tender_datetime(record.get("opening_at")),
            "Days to Close": days_to_close,
            "Status": str(record.get("status") or ""),
            "Category": tender_category(title, organization),
            "Official Portal": stable_tender_portal_url(record),
            "Captured Detail Link": record.get("detail_url") or "",
            "_closing_sort": closing_dt.isoformat() if closing_dt else "",
        })
    return sorted(rows, key=lambda row: (row.get("_closing_sort") or "9999", row.get("Tender") or ""))


def normalize_portal_rows(records: list[dict]) -> list[dict]:
    rows = []
    for record in records:
        if not isinstance(record, dict):
            continue
        rows.append({
            "Portal": record.get("portal_name") or record.get("source_name") or "",
            "Category": record.get("portal_category") or "",
            "URL": record.get("portal_url") or "",
            "Reachable": record.get("reachable", ""),
            "List Page OK": record.get("list_page_ok", ""),
            "Has List Form": record.get("has_list_form", ""),
            "Error": record.get("error", ""),
        })
    return rows


def count_by(rows: list[dict], field: str, limit: int = 12) -> list[dict]:
    counts = {}
    for row in rows:
        key = str(row.get(field) or "Unknown").strip() or "Unknown"
        counts[key] = counts.get(key, 0) + 1
    return [
        {field: key, "Count": value}
        for key, value in sorted(counts.items(), key=lambda item: (-item[1], item[0]))[:limit]
    ]


def html_link_button(url: str, label: str, kind: str = "primary") -> str:
    if not url:
        return ""
    bg = "#dc2626" if kind == "primary" else "#ffffff"
    color = "#ffffff" if kind == "primary" else "#111827"
    border = "#dc2626" if kind == "primary" else "#d1d5db"
    return (
        f'<a href="{html_lib.escape(url, quote=True)}" target="_self" '
        f'style="display:inline-block;margin:6px 8px 0 0;padding:8px 12px;'
        f'border:1px solid {border};border-radius:6px;background:{bg};color:{color};'
        f'text-decoration:none;font-weight:700;font-size:13px;">'
        f'{html_lib.escape(label)}</a>'
    )


def render_clickable_tender_links(rows: list[dict], max_rows: int = 12) -> None:
    st.markdown("**Clickable tender links**")
    st.caption(
        "Use these cards to open tenders. They are normal browser links, not dataframe cells. "
        "The official portal opens in this browser tab so popup blocking cannot swallow the click."
    )
    for idx, row in enumerate(rows[:max_rows], start=1):
        tender = html_lib.escape(str(row.get("Tender") or "Untitled tender"))
        organization = html_lib.escape(str(row.get("Organization") or ""))
        portal = html_lib.escape(str(row.get("Portal") or ""))
        tender_id = html_lib.escape(str(row.get("Tender ID") or "not available"))
        reference = html_lib.escape(str(row.get("Reference") or "not available"))
        closing = html_lib.escape(str(row.get("Closing") or ""))
        official_url = str(row.get("Official Portal") or "")
        captured_url = str(row.get("Captured Detail Link") or "")
        buttons = " ".join([
            html_link_button(official_url, "Open official portal", "primary"),
            html_link_button(captured_url, "Try captured detail", "secondary"),
        ]).strip()
        st.markdown(
            f"""
<div style="border:1px solid #e5e7eb;border-radius:8px;padding:12px 14px;margin:10px 0;background:#ffffff;">
  <div style="font-size:13px;color:#6b7280;margin-bottom:4px;">Tender {idx} | {portal} | Closing: {closing}</div>
  <div style="font-weight:800;color:#111827;line-height:1.35;margin-bottom:6px;">{tender}</div>
  <div style="font-size:13px;color:#374151;line-height:1.4;margin-bottom:6px;">{organization}</div>
  <div style="font-size:12px;color:#4b5563;">Tender ID: <b>{tender_id}</b> | Reference: <b>{reference}</b></div>
  <div>{buttons}</div>
  <div style="font-size:11px;color:#6b7280;margin-top:6px;word-break:break-all;">Portal URL: {html_lib.escape(official_url)}</div>
</div>
""",
            unsafe_allow_html=True,
        )


@st.cache_data(show_spinner=False, ttl=60)
def load_indian_tender_tracker_snapshot() -> dict:
    data_dir = tender_tracker_data_dir()
    if data_dir is None:
        return {"available": False, "data_dir": ""}
    portal_inventory_path = next(
        (
            path
            for path in [
                data_dir / "portalfull_health" / "portal_inventory.json",
                data_dir / "portalfull" / "portal_inventory.json",
                data_dir / "portal_inventory.json",
            ]
            if path.exists()
        ),
        None,
    )
    tenders = read_json_file(data_dir / "active_tenders.json", [])
    news = read_json_file(data_dir / "newspaper_mentions.json", [])
    preview = read_json_file(data_dir / "preview-data.json", {})
    summary = read_json_file(data_dir / "run_summary.json", {})
    portals = read_json_file(portal_inventory_path, []) if portal_inventory_path else []
    return {
        "available": True,
        "data_dir": str(data_dir),
        "active_tenders_path": str(data_dir / "active_tenders.json"),
        "active_tenders_csv_path": str(data_dir / "active_tenders.csv"),
        "news_csv_path": str(data_dir / "newspaper_mentions.csv"),
        "preview_html_path": str(data_dir / "preview.html"),
        "tenders": normalize_tender_rows(tenders if isinstance(tenders, list) else []),
        "news": news if isinstance(news, list) else [],
        "preview": preview if isinstance(preview, dict) else {},
        "summary": summary if isinstance(summary, dict) else {},
        "portals": normalize_portal_rows(portals if isinstance(portals, list) else []),
    }


def render_india_tender_tracker_tab():
    snapshot = load_indian_tender_tracker_snapshot()
    st.markdown("**India Government Tender Tracker**")
    st.caption(
        "Loaded from the uploaded Indian Tender Tracker package. The snapshot is public-procurement data, "
        "separate from report generation, and can be used to identify government demand signals."
    )
    if not snapshot.get("available"):
        st.warning("Tender tracker data is not available yet. Extract the tender package into the workspace and refresh.")
        return

    tenders = snapshot.get("tenders", [])
    preview = snapshot.get("preview", {})
    summary = snapshot.get("summary", {})
    portals = snapshot.get("portals", [])
    news = snapshot.get("news", [])
