STARTER_COMPANY_EMPLOYEE_IDS = [
    "ceo_strategy",
    "market_research",
    "marketing_manager",
    "sales_lead",
    "operations_manager",
]


def predefined_company_employee_catalog(idea: str = "", industry: str = "", geography: str = "") -> list[dict]:
    """Full employee catalog. Catalog employees are added only through an explicit user action."""
    return default_company_employees(idea, industry, geography)


def starter_company_employees(idea: str = "", industry: str = "", geography: str = "") -> list[dict]:
    """Small starter team for new workspaces; the rest of the catalog stays on the hiring bench."""
    catalog = predefined_company_employee_catalog(idea, industry, geography)
    by_id = {employee.get("id"): employee for employee in catalog}
    starter = [by_id[emp_id] for emp_id in STARTER_COMPANY_EMPLOYEE_IDS if emp_id in by_id]
    return starter or catalog[:3]


def employee_identity_key(employee: dict) -> str:
    name = re.sub(r"\s+", " ", str(employee.get("name") or "").strip().lower())
    title = re.sub(r"\s+", " ", str(employee.get("title") or employee.get("role") or "").strip().lower())
    return f"{name}|{title}" if name or title else ""


def employee_already_exists(employees: list[dict], candidate: dict) -> bool:
    candidate_id = safe_filename(str(candidate.get("id") or ""))
    candidate_key = employee_identity_key(candidate)
    for employee in employees:
        if candidate_id and safe_filename(str(employee.get("id") or "")) == candidate_id:
            return True
        if candidate_key and employee_identity_key(employee) == candidate_key:
            return True
    return False


def dedupe_company_employees(employees: list[dict]) -> list[dict]:
    """Preserve the first copy of an employee by id or name/title and discard duplicates."""
    deduped: list[dict] = []
    seen_ids: set[str] = set()
    seen_keys: set[str] = set()
    for idx, employee in enumerate(employees):
        if not isinstance(employee, dict):
            continue
        normalized = normalize_employee(employee, idx)
        emp_id = normalized.get("id", "")
        key = employee_identity_key(normalized)
        if emp_id in seen_ids or (key and key in seen_keys):
            continue
        seen_ids.add(emp_id)
        if key:
            seen_keys.add(key)
        deduped.append(normalized)
    return deduped


def add_predefined_employees_to_roster(
    employees: list[dict],
    selected_ids: list[str],
    idea: str = "",
    industry: str = "",
    geography: str = "",
) -> tuple[list[dict], list[dict], list[str]]:
    """Add selected catalog employees exactly once and report skipped IDs."""
    catalog = predefined_company_employee_catalog(idea, industry, geography)
    catalog_by_id = {employee.get("id"): normalize_employee(employee, idx) for idx, employee in enumerate(catalog)}
    roster = dedupe_company_employees(employees)
    added: list[dict] = []
    skipped: list[str] = []
    for emp_id in selected_ids:
        candidate = catalog_by_id.get(emp_id)
        if not candidate:
            skipped.append(str(emp_id))
            continue
        if employee_already_exists(roster, candidate):
            skipped.append(str(emp_id))
            continue
        roster.append(candidate)
        added.append(candidate)
    return dedupe_company_employees(roster), added, skipped


def company_workspace_slug(idea: str, geography: str) -> str:
    return safe_filename(f"{idea or 'business'}_{geography or 'global'}")[:96]


def company_workspace_dir(idea: str, geography: str) -> Path:
    path = APP_DIR / "business_build_outputs" / "company_memory" / company_workspace_slug(idea, geography)
    path.mkdir(parents=True, exist_ok=True)
    return path


def employee_storage_dir(employee_id: str, idea: str, geography: str) -> Path:
    path = company_workspace_dir(idea, geography) / safe_filename(employee_id or "employee")
    (path / "assets").mkdir(parents=True, exist_ok=True)
    return path


def employee_registry_path(idea: str, geography: str) -> Path:
    return company_workspace_dir(idea, geography) / "team_registry.json"


def normalize_employee(employee: dict, idx: int = 0) -> dict:
    name = str(employee.get("name") or f"Employee {idx + 1}").strip()
    title = str(employee.get("title") or employee.get("role") or "Team Member").strip()
    employee_id = str(employee.get("id") or safe_filename(f"{name}_{title}")).strip()
    return {
        "id": safe_filename(employee_id) or f"employee_{idx + 1}",
        "name": name,
        "title": title,
        "department": str(employee.get("department") or "General").strip(),
        "mission": str(employee.get("mission") or "Help build and run the business.").strip(),
        "works_on": employee.get("works_on") if isinstance(employee.get("works_on"), list) else [],
        "asset_types": employee.get("asset_types") if isinstance(employee.get("asset_types"), list) else ["Work memo"],
        "voice": str(employee.get("voice") or "clear and practical").strip(),
    }


def upgrade_company_employees(employees: list[dict]) -> list[dict]:
    """Keep existing rosters current without auto-adding missing predefined employees."""
    defaults = predefined_company_employee_catalog()
    default_by_id = {row["id"]: normalize_employee(row, idx) for idx, row in enumerate(defaults)}
    upgraded: list[dict] = []
    for idx, employee in enumerate(employees):
        employee = normalize_employee(employee, idx)
        emp_id = employee.get("id")
        default = default_by_id.get(emp_id)
        if default:
            if emp_id == "compliance_officer" and employee.get("title") in {"Compliance Officer", "Legal & Risk", ""}:
                employee = {**employee, **default}
            else:
                employee = {
                    **employee,
                    "department": employee.get("department") or default["department"],
                    "mission": employee.get("mission") or default["mission"],
                    "asset_types": list(dict.fromkeys((employee.get("asset_types") or []) + default["asset_types"])),
                    "works_on": list(dict.fromkeys((employee.get("works_on") or []) + default["works_on"])),
                    "voice": employee.get("voice") or default["voice"],
                }
        upgraded.append(employee)
    return dedupe_company_employees(upgraded)


def load_company_employees(idea: str, industry: str, geography: str) -> list[dict]:
    path = employee_registry_path(idea, geography)
    if path.exists():
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
            employees = data.get("employees", data if isinstance(data, list) else [])
            if isinstance(employees, list) and employees:
                normalized = [normalize_employee(emp, idx) for idx, emp in enumerate(employees) if isinstance(emp, dict)]
                upgraded = upgrade_company_employees(normalized)
                if upgraded != normalized:
                    save_company_employees(idea, geography, upgraded)
                return upgraded
        except Exception:
            pass
    employees: list[dict] = []
    save_company_employees(idea, geography, employees)
    return employees


def save_company_employees(idea: str, geography: str, employees: list[dict]) -> Path:
    path = employee_registry_path(idea, geography)
    employees = dedupe_company_employees(employees)
    payload = {
        "workspace": company_workspace_slug(idea, geography),
        "idea": idea,
        "geography": geography,
        "updated_at": time.strftime("%Y-%m-%d %H:%M:%S"),
        "employees": employees,
    }
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")
    return path


def append_jsonl(path: Path, row: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as f:
        f.write(json.dumps(row, ensure_ascii=False) + "\n")


def read_jsonl(path: Path, limit: int = 40) -> list[dict]:
    if not path.exists():
        return []
    rows: list[dict] = []
    try:
        with path.open("r", encoding="utf-8", errors="ignore") as f:
            tail = deque(f, maxlen=max(int(limit or 40), 1))
        for line in tail:
            if not line.strip():
                continue
            rows.append(json.loads(line))
    except Exception:
        return rows
    return rows


def employee_chat_path(employee_id: str, idea: str, geography: str) -> Path:
    return employee_storage_dir(employee_id, idea, geography) / "chat.jsonl"


def employee_memory_path(employee_id: str, idea: str, geography: str) -> Path:
    return employee_storage_dir(employee_id, idea, geography) / "memory.jsonl"


def append_employee_chat(employee: dict, idea: str, geography: str, role: str, content: str) -> None:
    append_jsonl(
        employee_chat_path(employee["id"], idea, geography),
        {
            "at": time.strftime("%Y-%m-%d %H:%M:%S"),
            "employee_id": employee["id"],
            "employee_name": employee.get("name"),
            "role": role,
            "content": content,
        },
    )


def append_employee_memory(employee: dict, idea: str, geography: str, content: str, kind: str = "work_note", artifact: str = "") -> None:
    append_jsonl(
        employee_memory_path(employee["id"], idea, geography),
        {
            "at": time.strftime("%Y-%m-%d %H:%M:%S"),
            "employee_id": employee["id"],
            "employee_name": employee.get("name"),
            "title": employee.get("title"),
            "kind": kind,
            "artifact": artifact,
            "content": clean_text(content, limit=2500),
        },
    )


def employee_memory_rows(employees: list[dict], idea: str, geography: str, per_employee: int = 8) -> list[dict]:
    rows: list[dict] = []
    for employee in employees:
        for row in read_jsonl(employee_memory_path(employee["id"], idea, geography), limit=per_employee):
            rows.append(row)
    rows.sort(key=lambda row: str(row.get("at", "")), reverse=True)
    return rows


def combined_company_memory(employees: list[dict], idea: str, geography: str, limit: int = 24) -> dict:
    rows = employee_memory_rows(employees, idea, geography, per_employee=12)[:limit]
    brand_points = []
    for row in rows:
        content = clean_text(row.get("content", ""), limit=220)
        if content:
            brand_points.append(f"{row.get('employee_name', 'Employee')}: {content}")
    return {
        "workspace": company_workspace_slug(idea, geography),
        "memory_count": len(rows),
        "latest_points": brand_points[:limit],
        "storage_dir": str(company_workspace_dir(idea, geography)),
    }


def workforce_employee_initials(employee: dict) -> str:
    words = [word for word in re.split(r"\s+", str(employee.get("name") or "").strip()) if word]
    if not words:
        return "AI"
    return "".join(word[0].upper() for word in words[:2])[:2]


def workforce_department_accent(employee: dict) -> str:
    family = employee_role_family(employee)
    return {
        "strategy": "#0b5fff",
        "marketing": "#2563eb",
        "sales": "#0f766e",
        "legal": "#7c3aed",
        "systems": "#0369a1",
        "analytics": "#047857",
        "operations": "#475569",
        "qa": "#b45309",
        "procurement": "#9333ea",
        "pr": "#be185d",
        "success": "#15803d",
        "partnerships": "#1d4ed8",
    }.get(family, "#64748b")


