def workforce_employee_card_html(employee: dict, status: str = "Available", is_active: bool = False, is_open: bool = False) -> str:
    accent = workforce_department_accent(employee)
    classes = "wf-card"
    if is_active:
        classes += " active"
    if is_open:
        classes += " open"
    status_class = "open" if is_open else ("active" if is_active else "")
    tags = "".join(
        f"<span class='wf-tag'>{html_lib.escape(str(tag), quote=True)}</span>"
        for tag in (employee.get("asset_types") or employee.get("works_on") or [])[:3]
    )
    return (
        f"<div class='{classes}'>"
        "<div class='wf-card-head'>"
        f"<div class='wf-avatar' style='background:{accent}'>{html_lib.escape(workforce_employee_initials(employee), quote=True)}</div>"
        "<div>"
        f"<div class='wf-name'>{html_lib.escape(str(employee.get('name') or 'Employee'), quote=True)}</div>"
        f"<div class='wf-role'>{html_lib.escape(str(employee.get('title') or 'Team Member'), quote=True)} | {html_lib.escape(str(employee.get('department') or 'General'), quote=True)}</div>"
        "</div>"
        "</div>"
        f"<div class='wf-status {status_class}'><span class='wf-dot'></span>{html_lib.escape(status, quote=True)}</div>"
        f"<div class='wf-card-body'>{html_lib.escape(clean_text(employee.get('mission', ''), limit=155), quote=True)}</div>"
        f"<div class='wf-tags'>{tags}</div>"
        "</div>"
    )


