def partnership_deliverable_markdown(snapshot: dict, user_message: str = "") -> str:
    rows = partnership_candidate_rows(snapshot)
    lines = [
        "## Concrete Partnership Target List",
        "I am not contacting anyone yet. This is a founder-review list: approve the partner message, referral terms, and claims before outreach.",
        "",
        "| Priority | Partner / channel | Type | Link | Why this fits | First ask | Contact path | Proof needed |",
        "|---|---|---|---|---|---|---|---|",
    ]
    for row in rows:
        lines.append(
            "| {priority} | {partner} | {type} | {url} | {why_fit} | {first_ask} | {contact_path} | {proof_needed} |".format(
                **{key: str(value).replace("|", "/") for key, value in row.items()}
            )
        )
    lines.extend([
        "",
        "### How I would use this list",
        "1. Pick 3 P1 partners only; do not blast the whole list.",
        "2. Create one co-branded diagnostic/checklist matched to the partner audience.",
        "3. Ask for feedback or one warm intro before asking for a formal referral relationship.",
        "4. Track partner source, intro count, meeting rate, qualified opportunity rate, pilot value, and implementation burden.",
        "5. Stop any partner route that produces low-fit leads or requires unapproved referral economics.",
        "",
        "### Partner Outreach Draft",
        f"Subject: Partner idea for {snapshot.get('buyer')}",
        "",
        f"Hi {{first_name}}, I am building around {snapshot.get('idea')} for {snapshot.get('buyer')} in {snapshot.get('geography')}. Your audience already deals with {snapshot.get('pain')}. I would like to create a useful diagnostic/checklist your clients can use, and if it helps, route qualified implementation work back through an approved partner model. Would it be worth a 20-minute fit check next week?",
        "",
        "Approval needed before sending: founder approval on partner fit, legal approval on referral/fee language, and proof review on any performance claims.",
    ])
    if user_message:
        lines.extend(["", "### User request I answered", clean_text(user_message, limit=500)])
    return "\n".join(lines)


def employee_specialized_deliverable_markdown(employee: dict, snapshot: dict, user_message: str = "") -> str:
    family = employee_role_family(employee)
    request = str(user_message or "").lower()
    if family == "partnerships" or any(term in request for term in ["partner", "partnership", "referral", "channel list", "ecosystem"]):
        return partnership_deliverable_markdown(snapshot, user_message)
    return ""


def format_employee_execution_markdown(employee: dict, snapshot: dict, items: list[dict], user_message: str) -> str:
    contacts = snapshot.get("attached_contacts") or []
    contact_lines = []
    for contact in contacts[:3]:
        if not isinstance(contact, dict):
            continue
        contact_lines.append(
            "- "
            + " | ".join(
                x for x in [
                    str(contact.get("name") or ""),
                    str(contact.get("title") or ""),
                    str(contact.get("company_name") or contact.get("company") or ""),
                    str(contact.get("email") or contact.get("linkedin_url") or contact.get("url") or ""),
                ]
                if x
            )
        )
    if not contact_lines:
        contact_lines = [f"- {snapshot.get('contact_status', 'No named contacts attached yet.')}"]
    lines = [
        f"I am {employee.get('name')}, {employee.get('title')}. I am using the current marketing plan, business plan, and company memory.",
        "",
        "## Current operating context",
        f"- Business: {snapshot.get('idea')} ({snapshot.get('industry')}, {snapshot.get('geography')})",
        f"- Buyer: {snapshot.get('buyer')}",
        f"- Trigger: {snapshot.get('trigger')}",
        f"- Pain: {clean_text(snapshot.get('pain', ''), limit=260)}",
        f"- WTP / pricing signal: {snapshot.get('willingness_to_pay')}",
        f"- CTA: {snapshot.get('cta')}",
        f"- Approval boundary: {snapshot.get('risk_reversal')}",
        "",
        "## Work I am executing now",
    ]
    for idx, item in enumerate(items, start=1):
        lines.extend([
            f"{idx}. **{item.get('workstream')}**",
            f"   - Output: {item.get('output')}",
            f"   - Next action: {item.get('next_action')}",
            f"   - Approval gate: {item.get('approval_gate')}",
        ])
    specialized = employee_specialized_deliverable_markdown(employee, snapshot, user_message)
    if specialized:
        lines.extend(["", specialized])
    lines.extend([
        "",
        "## Named leads or inputs I will use",
        *contact_lines,
        "",
        "## Handoff",
        "I will store this work in my employee memory and hand off blockers to the right teammate. External execution stays blocked until you explicitly approve the exact action.",
    ])
    if user_message:
        lines.extend(["", "## Your request interpreted", clean_text(user_message, limit=600)])
    if employee_role_family(employee) == "legal":
        lines.extend([
            "",
            "Legal/Risk boundary: I can draft legal/risk work product and issue lists, but jurisdiction-specific final legal advice and final contract language should be reviewed by qualified counsel.",
        ])
    return "\n".join(lines)


def _execution_owner_to_employee_id(owner: str) -> str:
    mapping = {
        "founder": "ceo_strategy",
        "ceo": "ceo_strategy",
        "sales": "sales_lead",
        "sales_lead": "sales_lead",
        "market_research": "market_research",
        "marketing": "marketing_manager",
        "marketing_manager": "marketing_manager",
        "product_builder": "product_builder",
        "systems": "automation_engineer",
        "automation_engineer": "automation_engineer",
        "compliance_officer": "compliance_officer",
        "growth_marketer": "growth_marketer",
        "operations_manager": "operations_manager",
        "finance_analyst": "finance_analyst",
        "customer_success": "customer_success",
    }
    key = str(owner or "").strip().lower().replace(" ", "_")
    return mapping.get(key, key or "ceo_strategy")


def _blueprint_tasks_for_employee(employee: dict, plan: dict) -> list[dict]:
    """Map execution blueprint tasks to a specific employee roster entry."""
    flat = plan.get("_execution_tasks_flat") if isinstance(plan.get("_execution_tasks_flat"), list) else []
    if not flat:
        return []
    emp_id = str(employee.get("id", ""))
    items: list[dict] = []
    for row in flat:
        if not isinstance(row, dict):
            continue
        owner_id = _execution_owner_to_employee_id(row.get("owner", ""))
        if owner_id != emp_id and str(row.get("owner", "")).lower() not in {emp_id, str(employee.get("title", "")).lower()}:
            continue
        items.append({
            "workstream": clean_text(str(row.get("workstream") or row.get("task") or row.get("focus") or "Execution task"), limit=80),
            "output": clean_text(str(row.get("deliverable") or row.get("task") or ""), limit=220),
            "next_action": clean_text(str(row.get("task") or row.get("focus") or ""), limit=220),
            "approval_gate": "Founder approval required before external emails, posts, purchases, hiring, or tool changes.",
            "phase": row.get("phase", ""),
            "day": row.get("day"),
            "kpi": row.get("kpi", ""),
            "source": "execution_blueprint",
        })
    return items[:12]


def build_employee_execution_system(plan: dict | None, employees: list[dict], idea: str = "", industry: str = "", geography: str = "") -> dict:
    """Assign the current plan to employees as execution-ready workstreams."""
    plan = plan if isinstance(plan, dict) else {}
    concept = plan.get("business_concept") if isinstance(plan.get("business_concept"), dict) else {}
    context = {
        "business": {
            "idea": concept.get("idea") or idea,
            "industry": concept.get("industry") or industry,
            "geography": concept.get("geography") or geography,
        },
        "business_plan": plan,
    }
    snapshot = employee_plan_snapshot(context)
    tasks_by_employee = []
    for employee in employees:
        if not isinstance(employee, dict):
            continue
        items = employee_role_execution_items(employee, snapshot)
        blueprint_items = _blueprint_tasks_for_employee(employee, plan)
        if blueprint_items:
            seen = {str(x.get("workstream")) for x in items}
            for row in blueprint_items:
                if row.get("workstream") not in seen:
                    items.insert(0, row)
                    seen.add(str(row.get("workstream")))
        tasks_by_employee.append({
            "employee_id": employee.get("id"),
            "employee_name": employee.get("name"),
            "title": employee.get("title"),
            "department": employee.get("department"),
            "role_family": employee_role_family(employee),
            "task_count": len(items),
            "tasks": items,
            "memory_storage": str(employee_storage_dir(employee.get("id", "employee"), snapshot.get("idea", idea), snapshot.get("geography", geography))),
        })
    return {
        "created_at": time.strftime("%Y-%m-%d %H:%M:%S"),
        "business": {
            "idea": snapshot.get("idea"),
            "industry": snapshot.get("industry"),
            "geography": snapshot.get("geography"),
            "buyer": snapshot.get("buyer"),
            "trigger": snapshot.get("trigger"),
            "cta": snapshot.get("cta"),
        },
        "execution_rules": [
            "Employees create internal files, briefs, dashboards, task boards, scripts, images, video storyboards, lead tables, and system specs.",
            "Employees may prepare external-action payloads, but emails, posts, purchases, hires, tool changes, payments, and customer contact require explicit approval.",
            "Every employee uses the same current marketing plan, ICP, geography, leads, financial assumptions, and combined company memory.",
            "Unsupported claims, mismatched geography, missing buyer, and missing approval are blockers.",
        ],
        "tasks_by_employee": tasks_by_employee,
        "handoff_model": "Marketing creates message and assets; Sales/CRM qualifies leads; Systems builds workflows; Legal/QA approve risks; Finance/Data score economics; Operations runs cadence; Success captures retention proof.",
    }


def deterministic_employee_reply(employee: dict, user_message: str, context: dict) -> str:
    snapshot = employee_plan_snapshot(context)
    items = employee_role_execution_items(employee, snapshot, user_message)
    return format_employee_execution_markdown(employee, snapshot, items, user_message)


def employee_suggested_work_items(employee: dict, idea: str, industry: str, geography: str, plan: dict | None) -> list[dict]:
    """Return concrete one-click work suggestions for a company employee."""
    snapshot = employee_plan_snapshot({
        "business": {"idea": idea, "industry": industry, "geography": geography},
        "business_plan": plan or {},
    })
    items = employee_role_execution_items(employee, snapshot)
    suggestions: list[dict] = []
    for idx, item in enumerate(items[:3], start=1):
        workstream = clean_text(str(item.get("workstream") or f"Task {idx}"), limit=80)
        output = clean_text(str(item.get("output") or ""), limit=220)
        next_action = clean_text(str(item.get("next_action") or ""), limit=220)
        suggestions.append({
            "title": workstream,
            "summary": output,
            "next_action": next_action,
            "asset_type": f"{workstream} work memo",
            "prompt": (
                f"Execute this employee task now.\n"
                f"Workstream: {workstream}\n"
                f"Required output: {output}\n"
                f"Next action: {next_action}\n"
                f"Make it specific to {snapshot.get('idea') or idea}, {snapshot.get('buyer')}, and {snapshot.get('geography') or geography}. "
                "Include assumptions, blockers, owner handoffs, and the founder approval gate."
            ),
        })
    if not suggestions:
        suggestions.append({
            "title": "Create first work memo",
            "summary": f"Turn this employee's role into a concrete plan for {idea}.",
            "next_action": "Create the first deliverable and save it to employee memory.",
            "asset_type": "Role work memo",
            "prompt": f"Create your first concrete work memo for {idea} in {geography}.",
        })
    return suggestions


def run_employee_work_item(
    employee: dict,
    work_item: dict,
    idea: str,
    industry: str,
    geography: str,
    plan: dict | None,
    evidence_items: list[dict] | None,
    report_context: dict | None,
    employees: list[dict],
) -> tuple[str, dict]:
    """Execute a suggested employee work item locally and store the output in chat/memory."""
    prompt = str(work_item.get("prompt") or work_item.get("next_action") or work_item.get("summary") or "")
    append_employee_chat(employee, idea, geography, "user", prompt)
    reply = employee_chat_reply(
        employee,
        prompt,
        idea,
        industry,
        geography,
        plan,
        evidence_items,
        report_context,
        employees,
        allow_llm=False,
    )
    append_employee_chat(employee, idea, geography, "assistant", reply)
    append_employee_memory(employee, idea, geography, reply, kind="suggested_work")
    asset: dict = {}
    return reply, asset


def employee_message_has_inline_approval(message: str) -> bool:
    text = str(message or "").strip().lower()
    return bool(re.search(r"\b(approve|approved|approval granted|go ahead|confirmed|yes,? do it|yes do it|please proceed)\b", text))


def strip_inline_approval(message: str) -> str:
    text = str(message or "").strip()
    text = re.sub(r"^\s*(approve|approved|approval granted|go ahead|confirmed|please proceed)\s*[:,-]?\s*", "", text, flags=re.I)
    return text.strip() or str(message or "").strip()


def employee_message_is_approval_only(message: str) -> bool:
    text = str(message or "").strip().lower()
    return text in {"approve", "approved", "go ahead", "confirmed", "yes", "yes do it", "please proceed"}


def employee_request_needs_clarification(message: str) -> bool:
    text = str(message or "").strip()
    if not text:
        return True
    lower = text.lower()
    if len(text.split()) <= 3 and not any(term in lower for term in ["list", "plan", "email", "budget", "sop", "script", "partnership", "lead", "copy"]):
        return True
    return False


def employee_clarifying_questions(employee: dict, idea: str, geography: str, request: str) -> str:
    family = employee_role_family(employee)
    question_sets = {
        "partnerships": [
            "Which partner type should I prioritize: agencies, platforms, associations, newsletters, consultants, or communities?",
            "Which geography should I use for partner discovery?",
            "Should I optimize for warm referrals, co-marketing, implementation partners, or distribution?",
        ],
        "sales": [
            "Which buyer title should I prioritize?",
            "Should the output be a lead list, email sequence, discovery script, or CRM plan?",
            "What offer or pilot price should I use?",
        ],
        "marketing": [
            "Which channel should I build for first: email, LinkedIn, community, content, ads, or partner co-marketing?",
            "Should the tone be founder-led, enterprise, technical, or direct-response?",
            "What proof asset do we already have or need to create?",
        ],
        "legal": [
            "Which country or jurisdiction should I check?",
            "Is this for outreach, privacy/data handling, contracts, claims, employment, or regulated activity?",
            "Do you want an internal issue list, checklist, or draft language for lawyer review?",
        ],
        "analytics": [
            "Which metric should I model first: CAC, payback, margin, churn, revenue, forecast, or retention?",
            "Do we have real customer, price, cost, or conversion data to use?",
            "Should I create a simple model or a scenario table?",
        ],
    }
    questions = question_sets.get(family, [
        "What exact output do you want me to create?",
        "Who is the intended audience or user of this output?",
        "Should I keep it as an internal draft or prepare it for founder approval?",
    ])
    lines = [
        f"I can do that for {idea} in {geography}, but I need one quick clarification before I create the work.",
        "",
        "Please answer these, or reply with `APPROVE:` followed by the exact task if you want me to proceed with assumptions:",
    ]
    lines.extend(f"{idx}. {question}" for idx, question in enumerate(questions, start=1))
    lines.extend(["", f"Your original request: {clean_text(request, limit=500)}"])
    return "\n".join(lines)


def employee_approval_request_message(employee: dict, idea: str, geography: str, request: str) -> str:
    return "\n".join([
        f"I can create this now as {employee.get('name')}, {employee.get('title')}.",
        "",
        "Before I do the work, approve this internal draft action in chat:",
        f"- Task: {clean_text(request, limit=700)}",
        f"- Business: {idea}",
        f"- Market: {geography}",
        "- Boundary: I will create an internal draft only. I will not email, post, contact people, buy tools, hire anyone, or change external systems.",
        "- Result: I will show the full output here in this chat and offer a Markdown download.",
        "",
        "Reply `APPROVE` to run this exact task, or rewrite the request with `APPROVE:` at the start.",
    ])


def employee_chat_reply(
    employee: dict,
    user_message: str,
    idea: str,
    industry: str,
    geography: str,
    plan: dict | None,
    evidence_items: list[dict] | None,
    report_context: dict | None,
    employees: list[dict],
    allow_llm: bool | None = None,
    fast_context: bool = False,
) -> str:
    if fast_context:
        team_memory = combined_company_memory([employee], idea, geography, limit=6)
    else:
        team_memory = combined_company_memory(employees, idea, geography)
    context = business_context_for_employee(employee, idea, industry, geography, plan, evidence_items, report_context, team_memory)
    use_llm = (
        bool(allow_llm)
        if allow_llm is not None
        else os.getenv("BUSINESS_BUILDER_LLM_EMPLOYEES", "0").strip().lower() in {"1", "true", "yes"}
    )
    if not use_llm:
        try:
            from iidatech.execution.execution_chat_bridge import try_real_execution_reply
            bridged = try_real_execution_reply(
                employee,
                user_message,
                idea=idea,
                industry=industry,
                geography=geography,
                plan=plan,
                report_context=report_context,
            )
            if bridged:
                return bridged
        except Exception:
            pass
        return deterministic_employee_reply(employee, user_message, context)
    legal_clause = ""
    if employee.get("id") == "compliance_officer":
        legal_clause = (
            "For Legal & Risk work, respond like a senior in-house counsel: identify jurisdiction, issue, rule/law category, "
            "risk level, business consequence, recommended controls, contract/privacy/compliance language to draft, and external counsel escalation. "
            "Do not claim to be a licensed attorney and do not say final legal advice is complete without jurisdiction-specific counsel review. "
        )
    prompt = (
        "You are one employee inside the user's company, not a generic chatbot. "
        "Speak in first person as that employee. Use the full business context, current plan, uploaded evidence, latest report, "
        "and combined team memory. Be specific and create work, not vague advice. "
        "If the user asks for an external action, prepare the artifact and say what approval is needed before execution.\n\n"
        f"{legal_clause}\n"
        f"Context JSON:\n{json.dumps(context, indent=2, ensure_ascii=False)[:30000]}\n\n"
        f"User message:\n{user_message}\n\n"
        "Return a useful employee response with concrete next work, assumptions, and files/assets to create when relevant."
    )
    try:
        text, _route = business_builder_text_request(
            prompt,
            f"You are {employee.get('name')}, {employee.get('title')}. Voice: {employee.get('voice')}.",
            max_tokens=1800,
            temperature=0.2,
        )
        if text.strip():
            return text.strip()
    except Exception:
        pass
    return deterministic_employee_reply(employee, user_message, context)


def ensure_employee_chat_greeting(
    employee: dict,
    idea: str,
    industry: str,
    geography: str,
    plan: dict | None,
) -> None:
    chat_path = employee_chat_path(employee["id"], idea, geography)
    if read_jsonl(chat_path, limit=1):
        return
    snapshot = employee_plan_snapshot({
        "business": {"idea": idea, "industry": industry, "geography": geography},
        "business_plan": plan or {},
    })
    suggested_items = employee_role_execution_items(employee, snapshot)[:3]
    suggested_lines = "\n".join(
        f"- {item.get('workstream')}: {item.get('next_action')}"
        for item in suggested_items
        if isinstance(item, dict)
    )
    greeting = (
        f"I am {employee.get('name')}, your {employee.get('title')}. "
        f"I am ready now with context for {snapshot.get('idea') or idea} in {snapshot.get('geography') or geography}. "
        f"My first priority is {snapshot.get('buyer')}.\n\n"
        "I can start with:\n"
        f"{suggested_lines or '- Create a concrete first work memo for this project.'}\n\n"
        "Pick one suggested task or ask me for a deliverable and I will create it locally first."
    )
    append_employee_chat(employee, idea, geography, "assistant", greeting)


def render_employee_quick_chat_panel(
    employee: dict,
    idea: str,
    industry: str,
    geography: str,
    plan: dict | None,
    evidence_items: list[dict] | None,
    report_context: dict | None,
    employees: list[dict],
) -> None:
    """Render the fastest path for employee chat without full team workspace work."""
    ensure_employee_chat_greeting(employee, idea, industry, geography, plan)
    st.markdown(f"### {employee.get('name')} - {employee.get('title')}")
    st.caption("Fast employee focus mode: chat opens first, uses local company context, and avoids slow external model calls.")
    cols = st.columns([1, 1])
    with cols[0]:
        st.caption(f"Department: {employee.get('department', 'General')}")
    with cols[1]:
        if st.button("Back to full team workspace", key=f"exit_employee_focus_{employee['id']}", width="stretch"):
            st.session_state["employee_chat_focus_mode"] = False
            st.rerun()
    st.caption(f"Employee storage: {employee_storage_dir(employee['id'], idea, geography)}")
    chat_path = employee_chat_path(employee["id"], idea, geography)
    for row in read_jsonl(chat_path, limit=12):
        role = "assistant" if row.get("role") == "assistant" else "user"
        with st.chat_message(role):
            st.write(row.get("content", ""))
    with st.form(f"quick_employee_chat_form_{employee['id']}", clear_on_submit=True):
        employee_message = st.text_area(
            f"Message {employee.get('name')}",
            value="",
            height=82,
            placeholder="Ask for a concrete deliverable: campaign, lead list criteria, proof asset, legal check, budget, SOP, or sales plan.",
        )
        send_employee_message = st.form_submit_button("Send now", type="primary", width="stretch")
    if send_employee_message and employee_message.strip():
        append_employee_chat(employee, idea, geography, "user", employee_message.strip())
        reply = employee_chat_reply(
            employee,
            employee_message.strip(),
            idea,
            industry,
            geography,
            plan,
            evidence_items,
            report_context,
            employees,
            allow_llm=False,
            fast_context=True,
        )
        append_employee_chat(employee, idea, geography, "assistant", reply)
        append_employee_memory(employee, idea, geography, reply, kind="chat_output")
        st.session_state["business_builder_team_sync_signature"] = ""
        with st.chat_message("user"):
            st.write(employee_message.strip())
        with st.chat_message("assistant"):
            st.write(reply)
        st.success("Saved to this employee's memory.")


def employee_asset_content(employee: dict, asset_type: str, instructions: str, context: dict) -> str:
    if os.getenv("BUSINESS_BUILDER_LLM_EMPLOYEES", "0").strip().lower() not in {"1", "true", "yes"}:
        snapshot = employee_plan_snapshot(context)
        items = employee_role_execution_items(employee, snapshot, f"Create asset: {asset_type}. {instructions}")
        role_work = format_employee_execution_markdown(employee, snapshot, items, instructions)
        return (
            f"# {asset_type}\n\n"
            f"Created by: {employee.get('name')} - {employee.get('title')}\n\n"
            f"## Asset objective\n{instructions or employee.get('mission')}\n\n"
            f"{role_work}\n\n"
            "## Review checklist\n"
            "- Buyer, trigger, geography, and CTA match the current business plan.\n"
            "- Any numbers, customer names, quotes, claims, or legal statements are source-backed or marked as assumptions.\n"
            "- External action remains blocked until founder approval.\n"
        )
    legal_clause = ""
    if employee.get("id") == "compliance_officer":
        legal_clause = (
            "Because this is Legal & Risk work, write it like an in-house counsel deliverable: jurisdiction assumptions, issue list, "
            "applicable laws/standards categories, risk rating, controls, draft clauses/checklists, evidence needed, and outside counsel review gates. "
            "Do not represent the output as final legal advice.\n\n"
        )
    prompt = (
        "Create a business execution asset for the selected employee. Use real context from the current business plan and team memory. "
        "Do not write generic placeholders. Include exact copy, steps, names of tools, source/assumption notes, and approval boundaries.\n\n"
        f"{legal_clause}"
        f"Employee:\n{json.dumps(employee, indent=2, ensure_ascii=False)}\n\n"
        f"Asset type: {asset_type}\nInstructions: {instructions}\n\n"
        f"Business context:\n{json.dumps(context, indent=2, ensure_ascii=False)[:30000]}\n\n"
        "Return Markdown only."
    )
    try:
        text, _route = business_builder_text_request(
            prompt,
            f"You are {employee.get('name')}, {employee.get('title')}, creating production-ready company work.",
            max_tokens=2600,
            temperature=0.2,
        )
        if text.strip():
            return text.strip()
    except Exception:
        pass
    business = context.get("business", {})
    return (
        f"# {asset_type}\n\n"
        f"Created by: {employee.get('name')} - {employee.get('title')}\n\n"
        f"Business: {business.get('idea', '')}\n"
        f"Market: {business.get('industry', '')} | {business.get('geography', '')}\n\n"
        f"## Objective\n{instructions or employee.get('mission')}\n\n"
        "## Work Output\n"
        "- Define the target buyer and trigger before execution.\n"
        "- Use the current business plan and team memory as source context.\n"
        "- Create copy/tasks/materials that are ready for founder review.\n"
        "- Block external sending, posting, buying, or hiring until explicit approval.\n\n"
        "## Next Approval\nFounder review required before external execution.\n"
    )


def write_employee_visual_mockup(asset_dir: Path, employee: dict, title: str, subtitle: str) -> Path:
    svg_path = asset_dir / "social_image_mockup.svg"
    safe_title = clean_text(title, limit=64).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    safe_subtitle = clean_text(subtitle, limit=140).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    svg = f"""<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="675" viewBox="0 0 1200 675">
  <rect width="1200" height="675" fill="#0f172a"/>
  <rect x="64" y="64" width="1072" height="547" rx="28" fill="#f8fafc"/>
  <text x="104" y="150" font-family="Arial, sans-serif" font-size="30" fill="#475569">{employee.get('department', 'Team')} asset</text>
  <text x="104" y="270" font-family="Arial, sans-serif" font-size="58" font-weight="700" fill="#111827">{safe_title}</text>
  <foreignObject x="104" y="310" width="960" height="160">
    <div xmlns="http://www.w3.org/1999/xhtml" style="font-family: Arial, sans-serif; font-size: 32px; color: #334155; line-height: 1.25;">{safe_subtitle}</div>
  </foreignObject>
  <text x="104" y="560" font-family="Arial, sans-serif" font-size="26" fill="#64748b">Created by {employee.get('name', 'Employee')} - {employee.get('title', '')}</text>
</svg>
"""
    svg_path.write_text(svg, encoding="utf-8")
    return svg_path


def write_employee_storyboard(asset_dir: Path, employee: dict, asset_content: str) -> Path:
    html_path = asset_dir / "video_storyboard.html"
    body = clean_text(asset_content, limit=6000).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    html = f"""<!doctype html>
<html><head><meta charset="utf-8"><title>Video Storyboard</title>
<style>body{{font-family:Arial,sans-serif;margin:40px;line-height:1.5;color:#111827}}.meta{{color:#64748b}}pre{{white-space:pre-wrap;background:#f8fafc;border:1px solid #e5e7eb;padding:20px;border-radius:8px}}</style>
</head><body>
<h1>Video Storyboard</h1>
<p class="meta">Created by {employee.get('name')} - {employee.get('title')}</p>
<pre>{body}</pre>
</body></html>"""
    html_path.write_text(html, encoding="utf-8")
    return html_path


def create_employee_asset(
    employee: dict,
    asset_type: str,
    instructions: str,
    idea: str,
    industry: str,
    geography: str,
    plan: dict | None,
    evidence_items: list[dict] | None,
    report_context: dict | None,
    employees: list[dict],
) -> dict:
    timestamp = time.strftime("%Y%m%d-%H%M%S")
    asset_dir = employee_storage_dir(employee["id"], idea, geography) / "assets" / f"{timestamp}_{safe_filename(asset_type)}"
    asset_dir.mkdir(parents=True, exist_ok=True)
    team_memory = combined_company_memory(employees, idea, geography)
    context = business_context_for_employee(employee, idea, industry, geography, plan, evidence_items, report_context, team_memory)
    content = employee_asset_content(employee, asset_type, instructions, context)
    md_path = asset_dir / f"{safe_filename(asset_type)}.md"
    md_path.write_text(content, encoding="utf-8")
    created = [str(md_path)]
    lower_type = asset_type.lower()
    if "image" in lower_type or "brand" in lower_type or "creative" in lower_type:
        title = (plan or {}).get("business_concept", {}).get("wedge") if isinstance((plan or {}).get("business_concept"), dict) else ""
        title = title or (idea[:64] if idea else asset_type)
        created.append(str(write_employee_visual_mockup(asset_dir, employee, title, instructions or asset_type)))
    if "video" in lower_type or "storyboard" in lower_type:
        created.append(str(write_employee_storyboard(asset_dir, employee, content)))
    append_employee_memory(employee, idea, geography, f"Created {asset_type}: {content[:1200]}", kind="asset", artifact=str(md_path))
    return {"folder": str(asset_dir), "files": created, "content": content}


def render_employee_latest_output(result: dict | None, active_employee_id: str = "") -> None:
    """Render the latest employee-created work in full inside the app."""
    if not isinstance(result, dict):
        return
    if active_employee_id and result.get("employee_id") and result.get("employee_id") != active_employee_id:
        return
    content = str(result.get("content") or "")
    asset = result.get("asset") if isinstance(result.get("asset"), dict) else {}
    with st.container(border=True):
        st.markdown("### Latest employee output")
        st.caption(
            f"Created by {result.get('employee_name', 'employee')} | "
            f"Action: {result.get('action', 'work')} | "
            f"Approval: {result.get('approval_status', 'draft approved for internal creation')}"
        )
        if content:
            st.markdown(content)
            st.info("Full result is shown above. Click the download button below to save this employee output as Markdown.")
            st.download_button(
                "Download this output as Markdown",
                data=content,
                file_name=f"{safe_filename(result.get('employee_name', 'employee'))}_{safe_filename(result.get('action', 'work'))}.md",
                mime="text/markdown",
                key=f"latest_output_markdown_{active_employee_id}_{safe_filename(result.get('action', 'work'))}",
                width="stretch",
            )
        elif asset.get("content"):
            asset_content = str(asset.get("content"))
            st.markdown(asset_content)
            st.info("Full result is shown above. Click the download button below to save this employee output as Markdown.")
            st.download_button(
                "Download this output as Markdown",
                data=asset_content,
                file_name=f"{safe_filename(result.get('employee_name', 'employee'))}_{safe_filename(result.get('action', 'work'))}.md",
                mime="text/markdown",
                key=f"latest_asset_markdown_{active_employee_id}_{safe_filename(result.get('action', 'work'))}",
                width="stretch",
            )
        else:
            st.info("The employee completed the action, but no readable content was returned.")
        if asset.get("folder"):
            st.caption(f"Saved folder: {asset.get('folder')}")
        for file_name in asset.get("files", []) if isinstance(asset.get("files"), list) else []:
            path = Path(str(file_name))
            if path.exists():
                st.download_button(
                    f"Download {path.name}",
                    data=path.read_bytes(),
                    file_name=path.name,
                    mime="text/plain" if path.suffix.lower() not in {".svg", ".html"} else ("image/svg+xml" if path.suffix.lower() == ".svg" else "text/html"),
                    key=f"latest_output_download_{active_employee_id}_{path.name}_{path.stat().st_mtime_ns}",
                    width="stretch",
                )


def sync_team_memory_into_plan(plan: dict | None, employees: list[dict], idea: str, geography: str) -> dict:
    plan = copy.deepcopy(plan or {})
    employees = upgrade_company_employees([normalize_employee(emp, idx) for idx, emp in enumerate(employees or [])])
    plan["company_team_memory"] = combined_company_memory(employees, idea, geography)
    plan["company_team"] = employees
    concept = plan.get("business_concept") if isinstance(plan.get("business_concept"), dict) else {}
    plan["employee_execution_system"] = build_employee_execution_system(
        plan,
        employees,
        concept.get("idea") or idea,
        concept.get("industry", ""),
        concept.get("geography") or geography,
    )
    return plan


def automation_workspace_dir(idea: str, geography: str) -> Path:
    path = company_workspace_dir(idea, geography) / "automations"
    path.mkdir(parents=True, exist_ok=True)
    return path


def automation_state_path(idea: str, geography: str) -> Path:
    return automation_workspace_dir(idea, geography) / "automations.json"


def automation_chat_path(idea: str, geography: str) -> Path:
    return automation_workspace_dir(idea, geography) / "automation_chat.jsonl"


def load_automation_state(idea: str, geography: str) -> dict:
    state = read_json_file(automation_state_path(idea, geography), {"automations": [], "runs": []})
    if not isinstance(state, dict):
        state = {"automations": [], "runs": []}
    state.setdefault("automations", [])
    state.setdefault("runs", [])
    return state


def save_automation_state(idea: str, geography: str, state: dict) -> None:
    state = state if isinstance(state, dict) else {"automations": [], "runs": []}
    state.setdefault("automations", [])
    state.setdefault("runs", [])
    write_json_file(automation_state_path(idea, geography), state)


def append_automation_chat(idea: str, geography: str, role: str, content: str, automation_id: str = "") -> None:
    append_jsonl(
        automation_chat_path(idea, geography),
        {
            "role": role,
            "content": clean_text(content, limit=8000),
            "automation_id": automation_id,
            "at": time.strftime("%Y-%m-%d %H:%M:%S"),
        },
    )


