def automation_business_snapshot(idea: str, industry: str, geography: str, plan: dict | None, employees: list[dict]) -> dict:
    plan = plan if isinstance(plan, dict) else {}
    concept = plan.get("business_concept") if isinstance(plan.get("business_concept"), dict) else {}
    icp = plan.get("validated_icp") if isinstance(plan.get("validated_icp"), dict) else {}
    profiles = icp.get("named_buyer_profiles") if isinstance(icp.get("named_buyer_profiles"), list) else []
    top_profile = profiles[0] if profiles and isinstance(profiles[0], dict) else {}
    marketing_pack = plan.get("marketing_work_pack") if isinstance(plan.get("marketing_work_pack"), dict) else {}
    return {
        "idea": concept.get("idea") or idea,
        "industry": concept.get("industry") or industry,
        "geography": concept.get("geography") or geography,
        "buyer": top_profile.get("named_buyer_profile") or top_profile.get("decision_maker") or "target buyer not finalized",
        "trigger": top_profile.get("buyer_trigger") or "trigger must be validated",
        "offer": top_profile.get("outreach_angle") or marketing_pack.get("positioning") or "offer must be tightened from the business plan",
        "cta": top_profile.get("call_to_action") or "book a short validation call",
        "team_memory": combined_company_memory(employees, idea, geography, limit=8),
    }


def automation_kind_from_request(request: str) -> str:
    text = str(request or "").lower()
    if any(term in text for term in ("lead", "prospect", "outreach", "email", "apollo", "hunter", "linkedin")):
        return "lead_generation"
    if any(term in text for term in ("post", "content", "instagram", "linkedin", "social", "video", "image", "ad", "campaign")):
        return "content_marketing"
    if any(term in text for term in ("crm", "follow up", "pipeline", "deal", "customer", "noco", "hubspot")):
        return "crm_follow_up"
    if any(term in text for term in ("research", "source", "trend", "competitor", "monitor", "report")):
        return "research_monitor"
    if any(term in text for term in ("call", "meeting", "calendar", "cal.com", "booking", "interview")):
        return "discovery_calls"
    return "founder_operations"


