def automation_team_coordination(request: str, employees: list[dict], snapshot: dict) -> list[dict]:
    employees = employees or []
    role_fallbacks = [
        {"name": "Marketing", "title": "Marketing Employee", "department": "Marketing"},
        {"name": "Sales", "title": "Sales Employee", "department": "Sales"},
        {"name": "Operations", "title": "Operations Employee", "department": "Operations"},
        {"name": "Legal/Risk", "title": "Legal/Risk Employee", "department": "Legal & Risk"},
    ]
    candidates = employees[:6] if employees else role_fallbacks
    notes = []
    for employee in candidates:
        dept = str(employee.get("department") or employee.get("title") or "Team")
        name = str(employee.get("name") or dept)
        lower_dept = dept.lower()
        if "sales" in lower_dept:
            decision = f"Define who to contact, why now, and what proof is needed for {snapshot.get('buyer')}."
            output = "Lead criteria, outreach draft, CRM fields, and approval gate."
        elif "marketing" in lower_dept or "growth" in lower_dept:
            decision = "Turn the business plan into clear copy, content, and offer framing."
            output = "Campaign brief, post drafts, and proof-claim checklist."
        elif "legal" in lower_dept or "risk" in lower_dept or "quality" in lower_dept:
            decision = "Block unsupported claims, risky outreach, privacy issues, and unapproved external actions."
            output = "Compliance checklist and approval wording."
        elif "operations" in lower_dept:
            decision = "Make the work repeatable and easy to run every week."
            output = "Task board, run checklist, owner map, and log structure."
        else:
            decision = "Create the artifact needed for this role and hand it to the next owner."
            output = "Role-specific work packet."
        notes.append({"Employee": name, "Role": employee.get("title", dept), "Decision": decision, "Output": output})
    return notes


def build_local_automation_spec(
    request: str,
    idea: str,
    industry: str,
    geography: str,
    plan: dict | None,
    employees: list[dict],
) -> dict:
    snapshot = automation_business_snapshot(idea, industry, geography, plan, employees)
    kind = automation_kind_from_request(request)
    name_map = {
        "lead_generation": "Lead finder and outreach-prep automation",
        "content_marketing": "Content and launch asset automation",
        "crm_follow_up": "CRM follow-up and pipeline automation",
        "research_monitor": "Research and competitor-monitor automation",
        "discovery_calls": "Discovery-call booking automation",
        "founder_operations": "Founder operating workflow automation",
    }
    step_map = {
        "lead_generation": [
            "Read ICP from the business plan.",
            "Create exact lead search queries and lead-fit rules.",
            "Save lead-review tasks in Local CRM.",
            "Draft first outreach email and approval checklist.",
            "Stop before sending emails until the founder approves.",
        ],
        "content_marketing": [
            "Read positioning and proof claims from the business plan.",
            "Draft seven short posts and one visual brief.",
            "Check each claim against available evidence.",
            "Save social-ready copy as local artifacts.",
            "Stop before publishing until the founder approves.",
        ],
        "crm_follow_up": [
            "Create local CRM fields for lead, status, next action, owner, and deadline.",
            "Create follow-up task records.",
            "Prepare handoff fields for NocoDB or HubSpot if configured.",
            "Log every action in the outbound log.",
        ],
        "research_monitor": [
            "Define competitor and trend keywords from the topic.",
            "Create a weekly source checklist.",
            "Write a decision memo template for the founder.",
            "Store all findings in the project automation folder.",
        ],
        "discovery_calls": [
            "Define the exact interview target and trigger.",
            "Create discovery questions and qualification rules.",
            "Save booking tasks locally.",
            "Prepare a Cal.com handoff if a booking link is configured.",
        ],
        "founder_operations": [
            "Break the request into repeatable steps.",
            "Assign owners by employee role.",
            "Create local files and task records.",
            "Show what needs approval before external execution.",
        ],
    }
    app_map = {
        "lead_generation": ["Local files", "Local CRM", "Apify", "Resend / SendGrid"],
        "content_marketing": ["Local files", "Ayrshare / Social", "PostHog"],
        "crm_follow_up": ["Local CRM", "NocoDB", "HubSpot CRM"],
        "research_monitor": ["Local files", "n8n"],
        "discovery_calls": ["Local CRM", "Cal.com", "Resend / SendGrid"],
        "founder_operations": ["Local files", "Local CRM", "n8n"],
    }
    automation_id = f"auto-{int(time.time() * 1000)}-{hashlib.sha1(request.encode('utf-8', errors='ignore')).hexdigest()[:8]}"
    team_notes = automation_team_coordination(request, employees, snapshot)
    spec = {
        "id": automation_id,
        "name": name_map.get(kind, "Founder automation"),
        "kind": kind,
        "request": clean_text(request, limit=2000),
        "created_at": time.strftime("%Y-%m-%d %H:%M:%S"),
        "status": "Ready to run locally",
        "business": snapshot,
        "simple_explanation": [
            "This automation creates local work first, so you can inspect it safely.",
            "It uses your project idea, business plan, and team memory.",
            "It will not email, post, scrape, or create outside records unless you open advanced tools and approve that action.",
        ],
        "team_decision": team_notes,
        "steps": step_map.get(kind, step_map["founder_operations"]),
        "apps": app_map.get(kind, ["Local files", "Local CRM"]),
        "local_outputs": [
            "Automation plan markdown",
            "Founder run checklist",
            "Local CRM task record",
            "Employee memory updates",
            "Run summary artifact",
        ],
        "approval_needed_for": [
            "Sending emails or messages",
            "Publishing social posts",
            "Running paid scrapers or lead tools",
            "Creating external CRM/NocoDB/HubSpot records",
            "Triggering n8n or third-party workflows",
        ],
    }
    spec["artifact_markdown"] = automation_spec_markdown(spec)
    return spec


def automation_spec_markdown(spec: dict) -> str:
    business = spec.get("business", {}) if isinstance(spec.get("business"), dict) else {}
    lines = [
        f"# {spec.get('name', 'Automation')}",
        "",
        "## Plain-English Summary",
        f"This automation helps with: {spec.get('request', '')}",
        f"Business: {business.get('idea', '')}",
        f"Market: {business.get('geography', '')} | Industry: {business.get('industry', '')}",
        f"Buyer: {business.get('buyer', '')}",
        f"Trigger: {business.get('trigger', '')}",
        "",
        "## What To Press",
        "1. Read this plan.",
        "2. Approve the local work.",
        "3. Read the created artifact and run log.",
        "4. Only use external send/post/app buttons after you approve the exact action.",
        "",
        "## Team Decision",
    ]
    for row in spec.get("team_decision", []):
        lines.append(f"- {row.get('Employee')}: {row.get('Decision')} Output: {row.get('Output')}")
    lines.extend(["", "## Automation Steps"])
    for idx, step in enumerate(spec.get("steps", []), start=1):
        lines.append(f"{idx}. {step}")
    lines.extend(["", "## Apps This Can Use"])
    for app in spec.get("apps", []):
        lines.append(f"- {app}")
    lines.extend(["", "## Runs Locally Now"])
    for output in spec.get("local_outputs", []):
        lines.append(f"- {output}")
    lines.extend(["", "## Needs Founder Approval Before"])
    for gate in spec.get("approval_needed_for", []):
        lines.append(f"- {gate}")
    return "\n".join(lines).strip() + "\n"


def automation_console_html(spec: dict, run: dict | None = None) -> str:
    """Build a standalone HTML console for founder review inside and outside Streamlit."""
    run = run if isinstance(run, dict) else {}
    business = spec.get("business", {}) if isinstance(spec.get("business"), dict) else {}
    steps = spec.get("steps", []) if isinstance(spec.get("steps"), list) else []
    apps = spec.get("apps", []) if isinstance(spec.get("apps"), list) else []
    gates = spec.get("approval_needed_for", []) if isinstance(spec.get("approval_needed_for"), list) else []
    files = run.get("files", []) if isinstance(run.get("files"), list) else []
    local_outputs = spec.get("local_outputs", []) if isinstance(spec.get("local_outputs"), list) else []
    title = html_lib.escape(str(spec.get("name") or "Automation"))
    request = html_lib.escape(str(spec.get("request") or ""))
    status = html_lib.escape(str(run.get("status") or spec.get("status") or "Ready"))
    run_id = html_lib.escape(str(run.get("run_id") or "not run yet"))
    created_at = html_lib.escape(str(run.get("created_at") or spec.get("created_at") or ""))

    def li(items: list, css_class: str = "") -> str:
        rows = []
        for item in items:
            text = html_lib.escape(str(item))
            rows.append(f"<li class='{css_class}'>{text}</li>")
        return "\n".join(rows) or "<li>None yet</li>"

    step_rows = []
    for idx, step in enumerate(steps, start=1):
        text = html_lib.escape(str(step))
        step_rows.append(
            f"""
            <label class="step-row">
              <input type="checkbox" data-step="{idx}">
              <span><b>Step {idx}</b><br>{text}</span>
            </label>
            """
        )
    if not step_rows:
        step_rows.append("<p class='muted'>No steps were generated yet.</p>")

    file_cards = []
    for file_path in files:
        path = Path(str(file_path))
        file_cards.append(
            f"""
            <div class="file-card">
              <div class="file-name">{html_lib.escape(path.name)}</div>
              <code>{html_lib.escape(str(file_path))}</code>
            </div>
            """
        )
    if not file_cards:
        file_cards.append("<p class='muted'>No local files yet. Approve the local work in the app to create them.</p>")

    return f"""<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{title} - Automation Console</title>
  <style>
    :root {{
      --blue: #155eef;
      --blue-dark: #123f9f;
      --ink: #102033;
      --muted: #607089;
      --line: #d9e2f1;
      --soft: #f4f8ff;
      --ok: #0f766e;
      --warn: #b45309;
      --bg: #ffffff;
    }}
    * {{ box-sizing: border-box; }}
    body {{
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--ink);
      background: linear-gradient(180deg, #f8fbff 0%, #ffffff 36%);
    }}
    .shell {{ max-width: 1120px; margin: 0 auto; padding: 28px; }}
    .hero {{
      border: 1px solid var(--line);
      border-radius: 12px;
      background: var(--bg);
      padding: 24px;
      box-shadow: 0 16px 45px rgba(21, 94, 239, 0.08);
    }}
    h1 {{ margin: 0 0 8px; font-size: 30px; letter-spacing: 0; }}
    h2 {{ margin: 0 0 12px; font-size: 18px; }}
    p {{ line-height: 1.55; }}
    .muted {{ color: var(--muted); }}
    .grid {{ display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin-top: 18px; }}
    .metric {{ border: 1px solid var(--line); background: var(--soft); border-radius: 10px; padding: 14px; }}
    .metric span {{ display: block; color: var(--muted); font-size: 12px; margin-bottom: 5px; }}
    .metric b {{ font-size: 15px; }}
    .section {{ margin-top: 18px; border: 1px solid var(--line); border-radius: 12px; background: #fff; padding: 18px; }}
    .split {{ display: grid; grid-template-columns: 1.2fr .8fr; gap: 16px; }}
    .step-row {{
      display: flex;
      gap: 12px;
      padding: 12px;
      border: 1px solid var(--line);
      border-radius: 10px;
      margin: 10px 0;
      background: #fff;
    }}
    .step-row input {{ margin-top: 3px; width: 18px; height: 18px; }}
    .step-row.done {{ border-color: rgba(15,118,110,.4); background: #f0fdfa; }}
    .tag {{
      display: inline-flex;
      align-items: center;
      gap: 6px;
      margin: 4px 6px 4px 0;
      padding: 7px 10px;
      border-radius: 999px;
      background: var(--soft);
      border: 1px solid var(--line);
      color: var(--blue-dark);
      font-weight: 600;
      font-size: 13px;
    }}
    .approval {{
      border-left: 4px solid var(--warn);
      background: #fff7ed;
      padding: 12px 14px;
      border-radius: 8px;
    }}
    .ok {{
      border-left: 4px solid var(--ok);
      background: #ecfdf5;
      padding: 12px 14px;
      border-radius: 8px;
    }}
    .file-card {{ border: 1px solid var(--line); border-radius: 10px; padding: 12px; margin: 8px 0; background: #fbfdff; }}
    .file-name {{ font-weight: 700; margin-bottom: 6px; }}
    code {{ display: block; white-space: pre-wrap; word-break: break-word; color: #1e3a8a; }}
    button {{
      border: 0;
      border-radius: 8px;
      background: var(--blue);
      color: #fff;
      padding: 10px 14px;
      font-weight: 700;
      cursor: pointer;
    }}
    button.secondary {{ background: #e8f0ff; color: var(--blue-dark); }}
    @media (max-width: 820px) {{
      .grid, .split {{ grid-template-columns: 1fr; }}
      .shell {{ padding: 16px; }}
    }}
  </style>
</head>
<body>
  <main class="shell">
    <section class="hero">
      <p class="muted">IIDATECH Automation Console</p>
      <h1>{title}</h1>
      <p>{request}</p>
      <div class="grid">
        <div class="metric"><span>Status</span><b>{status}</b></div>
        <div class="metric"><span>Run ID</span><b>{run_id}</b></div>
        <div class="metric"><span>Created</span><b>{created_at}</b></div>
        <div class="metric"><span>External actions</span><b>Blocked until approved</b></div>
      </div>
    </section>

    <section class="section split">
      <div>
        <h2>What This Automation Does</h2>
        <p><b>Business:</b> {html_lib.escape(str(business.get("idea", "")))}</p>
        <p><b>Market:</b> {html_lib.escape(str(business.get("geography", "")))} | <b>Industry:</b> {html_lib.escape(str(business.get("industry", "")))}</p>
        <p><b>Buyer:</b> {html_lib.escape(str(business.get("buyer", "")))}</p>
        <p><b>Trigger:</b> {html_lib.escape(str(business.get("trigger", "")))}</p>
      </div>
      <div>
        <h2>Apps It Can Use</h2>
        <div>{''.join(f'<span class="tag">{html_lib.escape(str(app))}</span>' for app in apps) or '<span class="tag">Local files</span>'}</div>
      </div>
    </section>

    <section class="section">
      <h2>Run Checklist</h2>
      <p class="muted">Use these checkboxes while reviewing. They are saved in this browser only and do not trigger outside actions.</p>
      {''.join(step_rows)}
      <button type="button" onclick="resetChecks()" class="secondary">Reset checklist</button>
    </section>

    <section class="section split">
      <div>
        <h2>What Was Created Locally</h2>
        <ul>{li(local_outputs)}</ul>
        <div class="ok">Local runs create files, tasks, memory updates, and run logs inside this app workspace.</div>
      </div>
      <div>
        <h2>Requires Separate Approval</h2>
        <ul>{li(gates)}</ul>
        <div class="approval">Emails, social posts, paid scrapers, webhooks, and external CRM records must show the exact payload before a separate approval.</div>
      </div>
    </section>

    <section class="section">
      <h2>Run Files</h2>
      {''.join(file_cards)}
    </section>
  </main>
  <script>
    const key = "iidatech-automation-console-{html_lib.escape(str(spec.get("id") or "automation"))}-{run_id}";
    function loadChecks() {{
      const saved = JSON.parse(localStorage.getItem(key) || "{{}}");
      document.querySelectorAll("input[type=checkbox][data-step]").forEach((box) => {{
        box.checked = !!saved[box.dataset.step];
        box.closest(".step-row").classList.toggle("done", box.checked);
        box.addEventListener("change", () => {{
          saved[box.dataset.step] = box.checked;
          localStorage.setItem(key, JSON.stringify(saved));
          box.closest(".step-row").classList.toggle("done", box.checked);
        }});
      }});
    }}
    function resetChecks() {{
      localStorage.removeItem(key);
      document.querySelectorAll("input[type=checkbox][data-step]").forEach((box) => {{
        box.checked = false;
        box.closest(".step-row").classList.remove("done");
      }});
    }}
    loadChecks();
  </script>
</body>
</html>"""


def save_automation_spec(idea: str, geography: str, spec: dict) -> dict:
    state = load_automation_state(idea, geography)
    automations = [auto for auto in state.get("automations", []) if auto.get("id") != spec.get("id")]
    automations.insert(0, spec)
    state["automations"] = automations[:50]
    save_automation_state(idea, geography, state)
    return state


def latest_run_for_automation(state: dict, automation_id: str) -> dict:
    for run in state.get("runs", []) or []:
        if run.get("automation_id") == automation_id:
            return run
    return {}


def ensure_automation_console_file(spec: dict, run: dict, idea: str, geography: str) -> Path | None:
    if not isinstance(run, dict) or not run:
        return None
    existing = str(run.get("console_html") or "").strip()
    if existing and Path(existing).exists():
        return Path(existing)
    run_files = [str(file_path) for file_path in run.get("files", []) if file_path]
    for file_path in run_files:
        if file_path.lower().endswith(".html") and Path(file_path).exists():
            run["console_html"] = file_path
            return Path(file_path)
    base_dir = None
    for file_path in run_files:
        path = Path(file_path)
        if path.parent.exists():
            base_dir = path.parent
            break
    if base_dir is None:
        run_id = str(run.get("run_id") or f"run-{int(time.time() * 1000)}")
        base_dir = automation_workspace_dir(idea, geography) / "runs" / safe_filename(run_id)
        base_dir.mkdir(parents=True, exist_ok=True)
    console_path = base_dir / "automation_console.html"
    try:
        console_path.write_text(automation_console_html(spec, run), encoding="utf-8")
    except OSError:
        return None
    run["console_html"] = str(console_path)
    if str(console_path) not in run_files:
        run.setdefault("files", []).append(str(console_path))
    state = load_automation_state(idea, geography)
    for stored_run in state.get("runs", []) or []:
        if stored_run.get("run_id") == run.get("run_id"):
            stored_run["console_html"] = str(console_path)
            stored_files = [str(file_path) for file_path in stored_run.get("files", []) if file_path]
            if str(console_path) not in stored_files:
                stored_run.setdefault("files", []).append(str(console_path))
            break
    for auto in state.get("automations", []) or []:
        if auto.get("id") == spec.get("id"):
            last_run = auto.get("last_run") if isinstance(auto.get("last_run"), dict) else {}
            if last_run.get("run_id") == run.get("run_id"):
                last_run["console_html"] = str(console_path)
                stored_files = [str(file_path) for file_path in last_run.get("files", []) if file_path]
                if str(console_path) not in stored_files:
                    last_run.setdefault("files", []).append(str(console_path))
                auto["last_run"] = last_run
            break
    save_automation_state(idea, geography, state)
    return console_path


def automation_runtime_services(spec: dict) -> list[str]:
    apps_text = " ".join(str(app) for app in spec.get("apps", [])).lower()
    kind = str(spec.get("kind", "")).lower()
    services: list[str] = []
    if "apify" in apps_text or kind == "lead_generation":
        services.append("Apify")
    if "resend" in apps_text or "sendgrid" in apps_text or kind in {"lead_generation", "discovery_calls"}:
        services.append("Resend / SendGrid")
    if "ayrshare" in apps_text or "social" in apps_text or kind == "content_marketing":
        services.append("Ayrshare / Social")
    if "nocodb" in apps_text or "crm" in apps_text:
        services.append("NocoDB")
    if "n8n" in apps_text:
        services.append("n8n")
    if "cal.com" in apps_text or kind == "discovery_calls":
        services.append("Cal.com")
    if "posthog" in apps_text:
        services.append("PostHog")
    if "documenso" in apps_text:
        services.append("Documenso")
    return unique_nonempty(services, limit=12)


def automation_runtime_connection_rows(spec: dict, runtime_inputs: dict | None = None) -> list[dict]:
    runtime_inputs = runtime_inputs if isinstance(runtime_inputs, dict) else {}
    rows: list[dict] = []
    for service in automation_runtime_services(spec):
        if service == "Apify":
            ready = bool(APIFY_TOKEN or runtime_inputs.get("APIFY_TOKEN"))
            rows.append({
                "Service": service,
                "Status": "ready" if ready else "needs API key",
                "What can run here": "Budget-capped public lead discovery after separate Apify approval.",
            })
        elif service == "Resend / SendGrid":
            resend_ready = bool((RESEND_API_KEY or runtime_inputs.get("RESEND_API_KEY")) and (RESEND_FROM_EMAIL or runtime_inputs.get("RESEND_FROM_EMAIL")))
            sendgrid_ready = bool((SENDGRID_API_KEY or runtime_inputs.get("SENDGRID_API_KEY")) and (SENDGRID_FROM_EMAIL or runtime_inputs.get("SENDGRID_FROM_EMAIL")))
            rows.append({
                "Service": service,
                "Status": "ready" if (resend_ready or sendgrid_ready) else "needs sender setup",
                "What can run here": "Drafts are prepared here; sending needs exact email review in outbound tools.",
            })
        elif service == "Ayrshare / Social":
            ready = bool(AYRSHARE_API_KEY or runtime_inputs.get("AYRSHARE_API_KEY"))
            rows.append({
                "Service": service,
                "Status": "ready" if ready else "needs API/OAuth",
                "What can run here": "Post assets are prepared here; publishing needs exact post review.",
            })
        elif service == "NocoDB":
            ready = bool(
                (NOCODB_API_TOKEN or runtime_inputs.get("NOCODB_API_TOKEN"))
                and (NOCODB_BASE_URL or runtime_inputs.get("NOCODB_BASE_URL"))
                and (NOCODB_TABLE_ID or runtime_inputs.get("NOCODB_TABLE_ID"))
            )
            rows.append({
                "Service": service,
                "Status": "ready" if ready else "needs NocoDB setup",
                "What can run here": "Local CRM runs now; external NocoDB records need payload review.",
            })
        elif service == "n8n":
            ready = bool(N8N_WEBHOOK_URL or runtime_inputs.get("N8N_WEBHOOK_URL"))
            rows.append({
                "Service": service,
                "Status": "ready" if ready else "needs webhook/OAuth",
                "What can run here": "Webhook payload is prepared; trigger needs payload review.",
            })
        elif service == "Cal.com":
            ready = bool(CALCOM_API_KEY or CALCOM_BOOKING_LINK or runtime_inputs.get("CALCOM_API_KEY") or runtime_inputs.get("CALCOM_BOOKING_LINK"))
            rows.append({
                "Service": service,
                "Status": "ready" if ready else "needs booking link/API",
                "What can run here": "Booking handoff is prepared for approval.",
            })
        elif service == "PostHog":
            ready = bool(POSTHOG_API_KEY or runtime_inputs.get("POSTHOG_API_KEY"))
            rows.append({
                "Service": service,
                "Status": "ready" if ready else "needs project key",
                "What can run here": "Analytics event plan is prepared for approval.",
            })
        elif service == "Documenso":
            ready = bool((DOCUMENSO_API_KEY or runtime_inputs.get("DOCUMENSO_API_KEY")) and (DOCUMENSO_BASE_URL or runtime_inputs.get("DOCUMENSO_BASE_URL")))
            rows.append({
                "Service": service,
                "Status": "ready" if ready else "needs API/OAuth",
                "What can run here": "Signing handoff is prepared for approval.",
            })
    if not rows:
        rows.append({
            "Service": "Local app",
            "Status": "ready",
            "What can run here": "Creates files, tasks, memory updates, and run logs.",
        })
    return rows


def collect_automation_runtime_inputs(spec: dict, automation_id: str) -> tuple[dict, dict]:
    runtime_inputs: dict = {}
    live_actions: dict = {}
    services = automation_runtime_services(spec)
    if not services:
        st.info("This automation only needs local files, Local CRM, and team memory.")
        return runtime_inputs, live_actions

    st.caption("Temporary inputs are used for this browser session only. They are not written into automation files.")
    if "Apify" in services:
        if not APIFY_TOKEN:
            runtime_inputs["APIFY_TOKEN"] = st.text_input(
                "Apify API token for this run",
                value="",
                type="password",
                key=f"runtime_apify_token_{automation_id}",
            ).strip()
        else:
            st.success("Apify key is configured in the app environment.")
        live_actions["run_apify"] = st.checkbox(
            f"Run Apify lead discovery now, capped at ${APIFY_MAX_SPEND_USD:.2f}",
            value=False,
            key=f"runtime_run_apify_{automation_id}",
            help="This is the only external action this console can run directly. It still uses the app's spend cap.",
        )
        live_actions["apify_max_leads"] = int(st.number_input(
            "Max Apify leads",
            min_value=1,
            max_value=25,
            value=10,
            step=1,
            key=f"runtime_apify_max_leads_{automation_id}",
        ))

    if "Resend / SendGrid" in services:
        if not RESEND_API_KEY and not SENDGRID_API_KEY:
            runtime_inputs["RESEND_API_KEY"] = st.text_input(
                "Resend API key for this run",
                value="",
                type="password",
                key=f"runtime_resend_key_{automation_id}",
            ).strip()
        if not RESEND_FROM_EMAIL and not SENDGRID_FROM_EMAIL:
            runtime_inputs["RESEND_FROM_EMAIL"] = st.text_input(
                "Verified sender email",
                value="",
                key=f"runtime_resend_from_{automation_id}",
                help="Required before any email can be sent. Sending still needs exact-recipient approval.",
            ).strip()
        st.caption("Email sending is not triggered from this console. It prepares the payload and points you to the approval-gated outbound tools.")

    if "Ayrshare / Social" in services:
        if not AYRSHARE_API_KEY:
            runtime_inputs["AYRSHARE_API_KEY"] = st.text_input(
                "Ayrshare API key for this run",
                value="",
                type="password",
                key=f"runtime_ayrshare_key_{automation_id}",
            ).strip()
        if not AYRSHARE_PROFILE_KEY:
            runtime_inputs["AYRSHARE_PROFILE_KEY"] = st.text_input(
                "Ayrshare profile key, optional",
                value="",
                type="password",
                key=f"runtime_ayrshare_profile_{automation_id}",
            ).strip()
        st.caption("Publishing still requires reviewing the exact post and media before send.")

    if "NocoDB" in services:
        if not NOCODB_API_TOKEN:
            runtime_inputs["NOCODB_API_TOKEN"] = st.text_input("NocoDB API token", value="", type="password", key=f"runtime_nocodb_token_{automation_id}").strip()
        if not NOCODB_BASE_URL:
            runtime_inputs["NOCODB_BASE_URL"] = st.text_input("NocoDB base URL", value="", key=f"runtime_nocodb_url_{automation_id}").strip()
        if not NOCODB_TABLE_ID:
            runtime_inputs["NOCODB_TABLE_ID"] = st.text_input("NocoDB table ID/name", value="", key=f"runtime_nocodb_table_{automation_id}").strip()

    if "n8n" in services and not N8N_WEBHOOK_URL:
        runtime_inputs["N8N_WEBHOOK_URL"] = st.text_input("n8n webhook URL", value="", type="password", key=f"runtime_n8n_url_{automation_id}").strip()
    if "Cal.com" in services and not (CALCOM_API_KEY or CALCOM_BOOKING_LINK):
        runtime_inputs["CALCOM_BOOKING_LINK"] = st.text_input("Cal.com booking link or API key", value="", key=f"runtime_calcom_{automation_id}").strip()
    if "PostHog" in services and not POSTHOG_API_KEY:
        runtime_inputs["POSTHOG_API_KEY"] = st.text_input("PostHog project API key", value="", type="password", key=f"runtime_posthog_{automation_id}").strip()
    if "Documenso" in services and not DOCUMENSO_API_KEY:
        runtime_inputs["DOCUMENSO_API_KEY"] = st.text_input("Documenso API key", value="", type="password", key=f"runtime_documenso_key_{automation_id}").strip()

    runtime_inputs = {key: value for key, value in runtime_inputs.items() if str(value or "").strip()}
    return runtime_inputs, live_actions


def render_in_app_run_timeline(spec: dict, run: dict | None, runtime_inputs: dict | None = None) -> None:
    runtime_inputs = runtime_inputs if isinstance(runtime_inputs, dict) else {}
    connection_rows = automation_runtime_connection_rows(spec, runtime_inputs)
    if run:
        events = run.get("events") if isinstance(run.get("events"), list) else []
        if not events:
            events = [
                {
                    "Stage": "Local files",
                    "Status": "done" if run.get("files") else "not found",
                    "Result": f"{len(run.get('files', []))} file paths are attached to this run.",
                },
                {
                    "Stage": "Local CRM task",
                    "Status": "done" if run.get("local_crm_saved") else "unknown",
                    "Result": run.get("local_crm_message", "This older run did not store a CRM result message."),
                },
                {
                    "Stage": "Employee/team memory",
                    "Status": "done",
                    "Result": "This older run created or referenced employee memory from the automation plan.",
                },
                {
                    "Stage": "External APIs",
                    "Status": "blocked",
                    "Result": "This older run did not store an external API execution record.",
                },
            ]
    else:
        events = [
            {"Stage": "Automation artifact", "Status": "ready", "Result": "Review the plan and approval gates."},
            {"Stage": "API readiness", "Status": "ready" if all(row.get("Status") == "ready" for row in connection_rows) else "needs setup", "Result": "Use the right column for missing keys or OAuth/API setup."},
            {"Stage": "Local execution", "Status": "waiting", "Result": "Tick approval and start local work."},
            {"Stage": "External actions", "Status": "blocked", "Result": "Nothing external runs until exact payload review."},
        ]
    done_count = sum(1 for row in events if str(row.get("Status", "")).lower() in {"done", "ready", "completed locally"})
    total_count = max(len(events), 1)
    st.progress(min(done_count / total_count, 1.0), text=f"{done_count}/{total_count} stages ready or complete")
    for row in events:
        status = str(row.get("Status", "waiting"))
        label = f"{row.get('Stage', 'Stage')} - {status}"
        with st.container(border=True):
            st.markdown(f"**{label}**")
            st.write(row.get("Result", ""))
    if run:
        st.markdown("**Result of this run**")
        result_rows = run.get("external_action_results") if isinstance(run.get("external_action_results"), list) else []
        summary_rows = [
            {"Area": "Local files", "Result": f"{len(run.get('files', []))} files created"},
            {"Area": "Local CRM", "Result": run.get("local_crm_message", "not recorded")},
            {"Area": "Employee memory", "Result": "updated for active employees"},
            {"Area": "External actions", "Result": "blocked unless separately approved"},
        ] + result_rows
        st.dataframe(summary_rows, width="stretch", hide_index=True)
    else:
        st.markdown("**What will happen next**")
        st.dataframe(connection_rows, width="stretch", hide_index=True)


def render_automation_preapproval_preview(spec: dict, runtime_inputs: dict | None = None, live_actions: dict | None = None) -> None:
    runtime_inputs = runtime_inputs if isinstance(runtime_inputs, dict) else {}
    live_actions = live_actions if isinstance(live_actions, dict) else {}
    business = spec.get("business", {}) if isinstance(spec.get("business"), dict) else {}
    apps = spec.get("apps", []) if isinstance(spec.get("apps"), list) else []
    steps = spec.get("steps", []) if isinstance(spec.get("steps"), list) else []
    is_lead_work = spec.get("kind") == "lead_generation" or "Apify" in apps
    apify_requested = bool(live_actions.get("run_apify"))
    apify_max_leads = live_actions.get("apify_max_leads", 10)

    st.markdown("**Review before approval**")
    st.info(
        "This preview shows what the automation is about to do. Local work can run after approval. "
        "Lead discovery only runs if the Apify box is ticked. Emails, posts, and external CRM writes need a second review."
    )

    action_rows = [
        {
            "Stage": "1. Local work",
            "What runs": "Create plan, checklist, run log, local CRM task, and employee memory update.",
            "Needs approval": "This page approval",
            "What you see": "Run output, files, timeline, and console inside this app.",
        },
        {
            "Stage": "2. Lead discovery",
            "What runs": "Public lead/search collection through Apify when selected.",
            "Needs approval": "Apify checkbox plus this page approval",
            "What you see": "Lead table in the Leads & emails tab before any email is sent.",
        },
        {
            "Stage": "3. Email or message send",
            "What runs": "Reviewed outbound emails only.",
            "Needs approval": "Separate draft review plus typing SEND APPROVED EMAILS",
            "What you see": "Exact recipients, subject, body, and send result table.",
        },
    ]
    st.dataframe(action_rows, width="stretch", hide_index=True)

    if is_lead_work:
        lead_brief = [
            {"Field": "Target buyer", "Current value": business.get("buyer", "not finalized")},
            {"Field": "Buyer trigger", "Current value": business.get("trigger", "not finalized")},
            {"Field": "Geography", "Current value": business.get("geography", "not finalized")},
            {"Field": "Offer angle", "Current value": business.get("offer", "not finalized")},
            {"Field": "Apify run selected", "Current value": "Yes" if apify_requested else "No"},
            {"Field": "Lead cap for this run", "Current value": apify_max_leads if apify_requested else "Not running Apify yet"},
            {"Field": "Source rule", "Current value": "Use only public profile/company data returned by the configured lead source."},
            {"Field": "Send rule", "Current value": "Do not send anything until lead table and email drafts are reviewed."},
        ]
        st.markdown("**Lead automation preview**")
        st.dataframe(lead_brief, width="stretch", hide_index=True)
        if not apify_requested:
            st.warning(
                "Apify lead discovery is not selected for this run. The app will still create the local plan and checklist, "
                "but no fresh lead names will appear until Apify discovery is approved."
            )

    with st.expander("See exact automation steps", expanded=False):
        for index, step in enumerate(steps, start=1):
            st.write(f"{index}. {step}")
        st.markdown("**Configured apps**")
        st.write(", ".join(apps) if apps else "Local app only")
        if runtime_inputs:
            st.caption("Temporary keys supplied for this run: " + ", ".join(sorted(runtime_inputs.keys())))


def automation_run_dir_from_run(run: dict) -> Path | None:
    for file_path in run.get("files", []) if isinstance(run, dict) else []:
        path = Path(str(file_path))
        if path.parent.exists():
            return path.parent
    return None


def automation_leads_from_run(run: dict) -> list[dict]:
    if not isinstance(run, dict) or not run:
        return []
    if isinstance(run.get("leads"), list):
        return [lead for lead in run.get("leads", []) if isinstance(lead, dict)]
    for file_path in run.get("files", []) or []:
        path = Path(str(file_path))
        if path.name == "apify_leads.json" and path.exists():
            payload = read_json_file(path, {})
            leads = payload.get("leads") if isinstance(payload, dict) else []
            return [lead for lead in leads if isinstance(lead, dict)]
    return []


def build_automation_email_drafts(spec: dict, leads: list[dict], limit: int = 10) -> list[dict]:
    business = spec.get("business", {}) if isinstance(spec.get("business"), dict) else {}
    offer = business.get("offer") or "a practical workflow improvement"
    trigger = business.get("trigger") or "a visible operating trigger"
    cta = business.get("cta") or "review a short workflow audit"
    drafts: list[dict] = []
    for lead in leads[:limit]:
        first_name = str(lead.get("first_name") or str(lead.get("name") or "").split(" ")[0] or "there").strip()
        company = str(lead.get("company") or lead.get("company_name") or "your team").strip()
        title = str(lead.get("title") or "operator").strip()
        email = str(lead.get("email") or "").strip()
        subject = f"Quick idea for {company}"
        body = (
            f"Hi {first_name},\n\n"
            f"I noticed {company} may fit a workflow trigger we are researching: {trigger}.\n\n"
            f"The specific idea is {offer}. For a {title}, the useful proof would be whether it saves time, reduces errors, "
            "or creates a measurable revenue/response improvement without adding another complicated tool.\n\n"
            f"Would you be open to {cta}? If useful, I can send a one-page workflow map first.\n\n"
            "Best,\n"
            "Founder"
        )
        drafts.append({
            "to": email,
            "name": lead.get("name", ""),
            "company": company,
            "title": title,
            "subject": subject,
            "body": body,
            "send_ready": "yes" if email else "missing email",
        })
    return drafts


def update_automation_run_record(idea: str, geography: str, automation_id: str, run_id: str, updates: dict) -> None:
    state = load_automation_state(idea, geography)
    for run in state.get("runs", []) or []:
        if run.get("run_id") == run_id:
            run.update(updates)
            break
    for auto in state.get("automations", []) or []:
        if auto.get("id") == automation_id:
            last_run = auto.get("last_run") if isinstance(auto.get("last_run"), dict) else {}
            if last_run.get("run_id") == run_id:
                last_run.update(updates)
                auto["last_run"] = last_run
            break
    save_automation_state(idea, geography, state)


def render_lead_email_review_stage(spec: dict, run: dict | None, idea: str, industry: str, geography: str, automation_id: str) -> None:
    if not run:
        st.info("Lead and email review appears here after the automation has a local run. Run local work first; no email will be sent.")
        return
    leads = automation_leads_from_run(run)
    st.markdown("**Lead and email review before sending**")
    if not leads:
        st.warning(
            "No leads are attached to this run yet. To collect leads, tick `Run Apify lead discovery now` in the API column, "
            "then approve work in this app. The leads will appear here before any email can be sent."
        )
        return

    lead_rows = []
    for lead in leads[:25]:
        lead_rows.append({
            "Name": lead.get("name", ""),
            "Title": lead.get("title", ""),
            "Company": lead.get("company") or lead.get("company_name") or "",
            "Email": lead.get("email", ""),
            "LinkedIn": lead.get("linkedin_url", ""),
            "Fit": lead.get("fit_score", ""),
            "Why this lead": lead.get("lead_reason", ""),
        })
    st.dataframe(lead_rows, width="stretch", hide_index=True)
    drafts = build_automation_email_drafts(spec, leads, limit=10)
    st.markdown("**Draft emails generated from these leads**")
    for idx, draft in enumerate(drafts, start=1):
        with st.expander(f"Draft {idx}: {draft.get('name') or draft.get('to') or 'lead'}", expanded=idx == 1):
            st.write(f"To: {draft.get('to') or 'missing email'}")
            st.write(f"Subject: {draft.get('subject')}")
            st.text_area("Email body", value=draft.get("body", ""), height=210, key=f"email_draft_preview_{automation_id}_{run.get('run_id')}_{idx}")

    st.info("Sending is separate from lead collection. Review every lead and draft first. The app will only send emails after the exact approval phrase is typed.")
    send_key = RESEND_API_KEY
    send_from = RESEND_FROM_EMAIL
    if not send_key:
        send_key = st.text_input("Resend API key for sending", value="", type="password", key=f"send_resend_key_{automation_id}_{run.get('run_id')}").strip()
    if not send_from:
        send_from = st.text_input("Verified sender email for sending", value="", key=f"send_resend_from_{automation_id}_{run.get('run_id')}").strip()
    reply_to = RESEND_REPLY_TO or send_from
    phrase = st.text_input(
        "Type SEND APPROVED EMAILS to send only the reviewed drafts with email addresses",
        value="",
        key=f"send_email_phrase_{automation_id}_{run.get('run_id')}",
    )
    max_send = st.number_input(
        "Maximum emails to send now",
        min_value=1,
        max_value=max(len(drafts), 1),
        value=min(len([d for d in drafts if d.get("to")]), 3) or 1,
        step=1,
        key=f"send_email_max_{automation_id}_{run.get('run_id')}",
    )
    if st.button("Send reviewed emails", type="primary", width="stretch", key=f"send_reviewed_emails_{automation_id}_{run.get('run_id')}"):
        if phrase.strip().upper() != "SEND APPROVED EMAILS":
            st.error("Emails were not sent. Type SEND APPROVED EMAILS first.")
            return
        if not send_key or not send_from:
            st.error("Emails were not sent. Resend API key and verified sender email are required.")
            return
        runtime_project_id = None
        if runtime_ensure_project is not None:
            try:
                runtime_project = runtime_ensure_project(
                    idea,
                    industry,
                    geography,
                    metadata={"source": "streamlit_email_review", "automation_id": automation_id},
                )
                runtime_project_id = runtime_project.get("id")
            except Exception:
                runtime_project_id = None
        results = []
        sent_count = 0
        for draft in drafts:
            if sent_count >= int(max_send):
                break
            to_email = str(draft.get("to") or "").strip()
            if not to_email:
                results.append({"to": "", "ok": False, "message": "Skipped: missing email", "subject": draft.get("subject")})
                continue
            if runtime_is_email_suppressed is not None:
                try:
                    if runtime_is_email_suppressed(runtime_project_id, to_email):
                        results.append({"to": to_email, "ok": False, "message": "Skipped: email is on suppression list", "subject": draft.get("subject")})
                        if runtime_record_outbound_message is not None:
                            runtime_record_outbound_message(
                                runtime_project_id,
                                "email",
                                to_email,
                                subject=draft.get("subject", ""),
                                body=draft.get("body", ""),
                                status="suppressed",
                                provider="resend",
                                error="suppression_list",
                                metadata={"automation_id": automation_id, "run_id": run.get("run_id")},
                            )
                        continue
                except Exception:
                    pass
            ok, msg = send_resend_email(send_key, send_from, to_email, draft.get("subject", ""), draft.get("body", ""), reply_to=reply_to)
            results.append({"to": to_email, "ok": ok, "message": msg, "subject": draft.get("subject")})
            append_outbound_log({"action": "automation_send_reviewed_email", "automation_id": automation_id, "run_id": run.get("run_id"), "to": to_email, "ok": ok, "message": msg})
            if runtime_record_outbound_message is not None:
                try:
                    runtime_record_outbound_message(
                        runtime_project_id,
                        "email",
                        to_email,
                        subject=draft.get("subject", ""),
                        body=draft.get("body", ""),
                        status="sent" if ok else "failed",
                        provider="resend",
                        provider_message_id=msg if ok else "",
                        error="" if ok else msg,
                        metadata={"automation_id": automation_id, "run_id": run.get("run_id"), "reply_to": reply_to},
                    )
                except Exception:
                    pass
            if runtime_record_usage is not None and runtime_project_id:
                try:
                    runtime_record_usage(
                        "resend",
                        "email_send_attempt",
                        units=1,
                        estimated_cost_usd=0,
                        project_id=runtime_project_id,
                        metadata={"automation_id": automation_id, "run_id": run.get("run_id"), "ok": ok},
                    )
                except Exception:
                    pass
            sent_count += 1
        run_dir = automation_run_dir_from_run(run)
        if run_dir:
            results_path = run_dir / "email_send_results.json"
            write_json_file(results_path, {"results": results, "sent_at": time.strftime("%Y-%m-%d %H:%M:%S")})
            files = list(run.get("files", []) or [])
            if str(results_path) not in files:
                files.append(str(results_path))
            run["files"] = files
        run.setdefault("events", []).append({
            "Stage": "Reviewed email send",
            "Status": "done",
            "Result": f"Attempted {len(results)} reviewed emails. Successful: {sum(1 for r in results if r.get('ok'))}.",
        })
        run.setdefault("external_action_results", []).append({
            "Area": "Resend email",
            "Result": f"Attempted {len(results)} reviewed emails. Successful: {sum(1 for r in results if r.get('ok'))}.",
        })
        update_automation_run_record(idea, geography, automation_id, str(run.get("run_id")), {
            "events": run.get("events", []),
            "external_action_results": run.get("external_action_results", []),
            "files": run.get("files", []),
        })
        st.success(f"Email send step completed. Successful sends: {sum(1 for r in results if r.get('ok'))}/{len(results)}")
        st.dataframe(results, width="stretch", hide_index=True)


def render_automation_artifact_panel(
    spec: dict,
    state: dict,
    idea: str,
    industry: str,
    geography: str,
    plan: dict | None,
    employees: list[dict],
) -> None:
    automation_id = str(spec.get("id", ""))
    latest_run = latest_run_for_automation(state, automation_id)
    artifact_markdown = automation_spec_markdown(spec)
    with st.container(border=True):
        st.markdown(f"### Artifact: {spec.get('name', 'Automation')}")
        status_cols = st.columns(4)
        status_cols[0].metric("Status", spec.get("status", "Ready"))
        status_cols[1].metric("Apps", len(spec.get("apps", []) or []))
        status_cols[2].metric("Steps", len(spec.get("steps", []) or []))
        status_cols[3].metric("Last run", latest_run.get("status", "not run"))
        st.caption("This is the automation artifact. Review it like a client deliverable before starting any work.")

        st.markdown("**Run this automation inside the app**")
        runner_col, api_col = st.columns([1.4, 0.9])
        with api_col:
            st.markdown("**API inputs for this automation**")
            runtime_inputs, live_actions = collect_automation_runtime_inputs(spec, automation_id)
            if runtime_inputs:
                st.caption("Temporary API inputs supplied for this run: " + ", ".join(sorted(runtime_inputs.keys())))
            st.info("External emails, posts, webhooks, and external CRM writes stay blocked until the exact payload is shown and separately approved.")
            approved = st.checkbox(
                "I reviewed this automation and approve starting the local work.",
                value=False,
                key=f"approve_local_automation_{automation_id}",
            )
            if st.button(
                "Approve and start work in this app",
                type="primary",
                width="stretch",
                disabled=not approved,
                key=f"approve_run_automation_{automation_id}",
            ):
                run = run_local_automation(
                    spec,
                    idea,
                    industry,
                    geography,
                    plan,
                    employees,
                    runtime_inputs=runtime_inputs,
                    live_actions=live_actions,
                )
                st.success(f"Automation finished inside the app. Run ID: {run['run_id']}")
                st.rerun()
        with runner_col:
            st.write("This is the live automation preview. It shows what will run, what already ran, and what is blocked.")
            render_automation_preapproval_preview(spec, runtime_inputs, live_actions)
            render_in_app_run_timeline(spec, latest_run, runtime_inputs)
            st.markdown("**After you approve, the app will:**")
            st.write("1. Create a local automation folder with the plan and JSON spec.")
            st.write("2. Create a founder checklist so the work is easy to review.")
            st.write("3. Save a Local CRM task for this automation.")
            st.write("4. Add the automation result to employee/team memory.")
            st.write("5. Show the run output, files, and visual console inside this page.")
        st.caption(
            "Before anything is sent outside the app, the exact message, lead list, post, scraper query, webhook payload, "
            "or CRM record must be shown for a separate review and approval."
        )

        preview_tab, console_tab, lead_email_tab, files_tab = st.tabs(["Artifact preview", "Automation console", "Leads & emails", "Run output"])
        with preview_tab:
            st.markdown(artifact_markdown)
            st.download_button(
                "Download this artifact",
                data=artifact_markdown,
                file_name=f"IIDATECH_Automation_{safe_filename(spec.get('name', 'automation'))}.md",
                mime="text/markdown",
                width="stretch",
                key=f"download_active_automation_{automation_id}",
            )
        with console_tab:
            if latest_run:
                console_path = ensure_automation_console_file(spec, latest_run, idea, geography)
                if console_path and console_path.exists():
                    console_html = console_path.read_text(encoding="utf-8", errors="ignore")
                    st.caption("This is the front-end automation console created by the local run. It is safe to use for review; outside actions still require separate approval.")
                    components.html(console_html, height=760, scrolling=True)
                    st.download_button(
                        "Download automation console HTML",
                        data=console_html,
                        file_name=f"IIDATECH_AutomationConsole_{safe_filename(spec.get('name', 'automation'))}.html",
                        mime="text/html",
                        width="stretch",
                        key=f"download_automation_console_{automation_id}_{latest_run.get('run_id', 'latest')}",
                    )
                else:
                    st.warning("The console could not be created for this run. Approve and start local work again to generate a fresh console.")
            else:
                st.info("Approve the local work first. The app will generate and show an HTML automation console here.")
        with lead_email_tab:
            render_lead_email_review_stage(spec, latest_run, idea, industry, geography, automation_id)
        with files_tab:
            if latest_run:
                st.success(f"Latest run: {latest_run.get('run_id')} | {latest_run.get('status')}")
                st.markdown("**Where you can see and use it**")
                st.write("1. Use the Automation console tab above for the founder-facing preview.")
                st.write("2. Use this Run output tab to inspect every generated file.")
                st.write("3. Use Recent local automation runs below to find past runs.")
                st.write("4. To run it again, tick the approval checkbox above and press Approve and start local work.")
                for file_path in latest_run.get("files", []):
                    st.code(file_path, language="text")
                    path = Path(file_path)
                    if path.exists() and path.suffix.lower() in {".md", ".txt", ".json", ".html"}:
                        with st.expander(f"Open file preview: {path.name}", expanded=path.name == "run_summary.md"):
                            content = path.read_text(encoding="utf-8", errors="ignore")
                            if path.suffix.lower() == ".json":
                                render_pretty_value(read_json_file(path, {}))
                            elif path.suffix.lower() == ".html":
                                components.html(content, height=520, scrolling=True)
                            else:
                                st.markdown(content)
            else:
                st.info("No run yet. Tick the approval checkbox above and press Approve and start local work.")


def run_local_automation(
    spec: dict,
    idea: str,
    industry: str,
    geography: str,
    plan: dict | None,
    employees: list[dict],
    runtime_inputs: dict | None = None,
    live_actions: dict | None = None,
) -> dict:
    runtime_inputs = runtime_inputs if isinstance(runtime_inputs, dict) else {}
    live_actions = live_actions if isinstance(live_actions, dict) else {}
    runtime_project = None
    runtime_project_id = None
    if runtime_ensure_project is not None:
        try:
            runtime_project = runtime_ensure_project(
                idea,
                industry,
                geography,
                metadata={"source": "streamlit_automation", "automation_id": spec.get("id", "")},
            )
            runtime_project_id = runtime_project.get("id")
        except Exception:
            runtime_project = None
            runtime_project_id = None
    run_id = f"run-{int(time.time() * 1000)}"
    run_dir = automation_workspace_dir(idea, geography) / "runs" / run_id
    run_dir.mkdir(parents=True, exist_ok=True)
    spec_path = run_dir / "automation.json"
    plan_path = run_dir / "automation_plan.md"
    checklist_path = run_dir / "founder_checklist.md"
    console_path = run_dir / "automation_console.html"
    events = [
        {"Stage": "Run folder", "Status": "done", "Result": str(run_dir)},
        {"Stage": "Automation artifact", "Status": "done", "Result": "Saved JSON spec and markdown plan."},
        {"Stage": "Founder checklist", "Status": "done", "Result": "Created a checklist for review and execution."},
    ]
    write_json_file(spec_path, spec)
    plan_path.write_text(spec.get("artifact_markdown") or automation_spec_markdown(spec), encoding="utf-8")
    checklist_lines = [
        f"# Founder Checklist: {spec.get('name', 'Automation')}",
        "",
        "- Read the automation plan.",
        "- Check the buyer, country, and offer match the current project.",
        "- Check any external action before approving it.",
        "- Save any new learning back into the team memory.",
        "",
        "## Steps",
    ]
    checklist_lines.extend([f"- {step}" for step in spec.get("steps", [])])
    checklist_path.write_text("\n".join(checklist_lines), encoding="utf-8")
    ok, crm_msg = append_local_crm_record(
        {
            "Name": spec.get("name", "Automation"),
            "Status": "Created locally",
            "Idea": idea,
            "Industry": industry,
            "Geography": geography,
            "Next Action": "Review artifact, then approve external execution only if needed.",
            "Automation ID": spec.get("id", ""),
        },
        "task",
    )
    events.append({
        "Stage": "Local CRM task",
        "Status": "done" if ok else "failed",
        "Result": crm_msg,
    })
    if runtime_create_crm_task is not None and runtime_project_id:
        try:
            runtime_create_crm_task(
                runtime_project_id,
                "automation_review",
                owner="Founder",
                status="pending",
                notes=f"Review automation artifact before external execution: {spec.get('name', 'Automation')}",
                metadata={"automation_id": spec.get("id", ""), "run_id": run_id, "run_dir": str(run_dir)},
            )
            if runtime_add_audit_event is not None:
                runtime_add_audit_event(
                    runtime_project_id,
                    "streamlit",
                    "automation.local_crm_task.created",
                    spec.get("id", ""),
                    {"run_id": run_id, "local_crm_message": crm_msg},
                )
        except Exception:
            pass
    for employee in employees[:6]:
        append_employee_memory(
            employee,
            idea,
            geography,
            f"Automation created: {spec.get('name')}. Role output needed: {employee.get('title')} should review relevant steps.",
            kind="automation_run",
            artifact=str(plan_path),
        )
    events.append({
        "Stage": "Employee/team memory",
        "Status": "done",
        "Result": f"Updated memory for {min(len(employees), 6)} employees.",
    })
    if spec.get("picked_steps"):
        try:
            from iidatech.ui.automation_builder import run_agent_queue_for_spec

            queue_logs = run_agent_queue_for_spec(spec, idea, industry, geography, report_context=None)
            events.append({
                "Stage": "Agent team queue",
                "Status": "done" if queue_logs else "skipped",
                "Result": f"Ran {len(queue_logs)} queue step(s). Check war room in automation builder.",
            })
            run_queue_note = queue_logs
        except Exception as exc:
            events.append({
                "Stage": "Agent team queue",
                "Status": "failed",
                "Result": str(exc)[:200],
            })
            run_queue_note = []
    else:
        run_queue_note = []
    run = {
        "run_id": run_id,
        "automation_id": spec.get("id"),
        "automation_name": spec.get("name"),
        "status": "completed locally",
        "created_at": time.strftime("%Y-%m-%d %H:%M:%S"),
        "files": [str(spec_path), str(plan_path), str(checklist_path)],
        "local_crm_saved": bool(ok),
        "local_crm_message": crm_msg,
        "external_actions_blocked": spec.get("approval_needed_for", []),
        "api_inputs_provided": sorted([key for key, value in runtime_inputs.items() if value]),
        "events": events,
        "external_action_results": [],
    }
    apify_token = str(runtime_inputs.get("APIFY_TOKEN") or APIFY_TOKEN or "").strip()
    if live_actions.get("run_apify"):
        if apify_token:
            max_leads = int(live_actions.get("apify_max_leads") or 10)
            found_leads, apify_meta, apify_errors = find_apify_leads(
                apify_token,
                plan or {},
                geography,
                max_charge_usd=APIFY_MAX_SPEND_USD,
                max_results=max_leads,
            )
            lead_json_path = run_dir / "apify_leads.json"
            lead_csv_path = run_dir / "apify_leads.csv"
            write_json_file(lead_json_path, {"meta": apify_meta, "leads": found_leads, "errors": apify_errors})
            if found_leads:
                fieldnames = sorted({key for lead in found_leads for key in lead.keys()})
                with lead_csv_path.open("w", newline="", encoding="utf-8") as handle:
                    writer = csv.DictWriter(handle, fieldnames=fieldnames)
                    writer.writeheader()
                    writer.writerows(found_leads)
                run["files"].append(str(lead_csv_path))
            run["leads"] = found_leads[:50]
            run["email_drafts"] = build_automation_email_drafts(spec, found_leads, limit=10)
            run["files"].append(str(lead_json_path))
            if runtime_upsert_crm_contact is not None and runtime_project_id:
                for lead in found_leads[:50]:
                    try:
                        runtime_upsert_crm_contact(
                            runtime_project_id,
                            name=str(lead.get("name") or ""),
                            email=str(lead.get("email") or ""),
                            company=str(lead.get("company") or lead.get("company_name") or ""),
                            title=str(lead.get("title") or ""),
                            source="Apify",
                            status="review_required",
                            metadata={"automation_id": spec.get("id", ""), "run_id": run_id, "lead": lead},
                        )
                    except Exception:
                        continue
            if runtime_record_usage is not None and runtime_project_id:
                try:
                    runtime_record_usage(
                        "apify",
                        "lead_discovery",
                        units=len(found_leads),
                        estimated_cost_usd=min(APIFY_MAX_SPEND_USD, APIFY_HARD_CAP_USD),
                        project_id=runtime_project_id,
                        metadata={"run_id": run_id, "status": apify_meta.get("status", "unknown")},
                    )
                except Exception:
                    pass
            apify_status = "done" if found_leads else "completed with warnings"
            apify_result = f"Apify returned {len(found_leads)} leads. Status: {apify_meta.get('status', 'unknown')}."
            if apify_errors:
                apify_result += " " + " ".join(str(err) for err in apify_errors[:2])
            run["events"].append({"Stage": "Apify lead discovery", "Status": apify_status, "Result": apify_result})
            run["external_action_results"].append({
                "Area": "Apify",
                "Result": apify_result,
            })
        else:
            message = "Skipped because no Apify token was available."
            run["events"].append({"Stage": "Apify lead discovery", "Status": "skipped", "Result": message})
            run["external_action_results"].append({"Area": "Apify", "Result": message})
    else:
        run["events"].append({
            "Stage": "External APIs",
            "Status": "blocked",
            "Result": "External sends, posts, paid discovery, webhooks, and external CRM writes were not run.",
        })
        run["external_action_results"].append({
            "Area": "External APIs",
            "Result": "Not run. Use API inputs plus explicit external approval when needed.",
        })
    if live_actions.get("run_apify") and apify_token:
        external_note = (
            "Apify lead discovery was run because it was separately approved in this console. "
            "Emails, posts, webhooks, and external CRM records were still not run."
        )
    else:
        external_note = (
            "External actions were not run. Use approval-gated advanced tools for sends, posts, "
            "paid scrapers, webhooks, or third-party records."
        )
    run_summary = (
        f"# Automation Run Summary\n\n"
        f"Automation: {run['automation_name']}\n\n"
        f"Status: {run['status']}\n\n"
        f"Local CRM: {crm_msg}\n\n"
        "## Where To See It\n\n"
        "- In this app: Automations -> choose this automation -> Automation console.\n"
        "- In this run folder: open automation_console.html.\n"
        "- In Local CRM: look for the task with this automation ID.\n"
        "- In employee memory: each active employee has a note linked to this automation plan.\n\n"
        "## What Happened\n\n"
        + "\n".join(f"- {event.get('Stage')}: {event.get('Status')} - {event.get('Result')}" for event in run.get("events", []))
        + "\n\n"
        f"{external_note}\n"
    )
    summary_path = run_dir / "run_summary.md"
    summary_path.write_text(run_summary, encoding="utf-8")
    run["files"].append(str(summary_path))
    console_path.write_text(automation_console_html(spec, run), encoding="utf-8")
    run["console_html"] = str(console_path)
    run["files"].append(str(console_path))
    state = load_automation_state(idea, geography)
    state.setdefault("runs", []).insert(0, run)
    for auto in state.get("automations", []):
        if auto.get("id") == spec.get("id"):
            auto["last_run"] = run
            auto["status"] = "Completed locally"
            break
    save_automation_state(idea, geography, state)
    append_outbound_log({"action": "run_local_automation", "automation_id": spec.get("id"), "run_id": run_id, "ok": True})
    if runtime_record_usage is not None and runtime_project_id:
        try:
            runtime_record_usage(
                "local",
                "automation_run",
                units=1,
                estimated_cost_usd=0,
                project_id=runtime_project_id,
                metadata={"automation_id": spec.get("id"), "run_id": run_id, "files": run.get("files", [])},
            )
        except Exception:
            pass
    if runtime_add_audit_event is not None and runtime_project_id:
        try:
            runtime_add_audit_event(
                runtime_project_id,
                "streamlit",
                "automation.local_run.completed",
                spec.get("id", ""),
                {"run_id": run_id, "status": run.get("status"), "files": run.get("files", [])},
            )
        except Exception:
            pass
    append_automation_chat(idea, geography, "assistant", f"Automation ran locally. Created files: {', '.join(run['files'])}", spec.get("id", ""))
    return run


def render_automations_workspace(
    idea: str,
    industry: str,
    geography: str,
    plan: dict | None,
    employees: list[dict],
    evidence_items: list[dict] | None,
    report_context: dict | None,
) -> None:
    st.markdown("### Automations")

    with st.container(border=True):
        st.markdown("**Need automations for your company?**")
