                    save_automation_spec(idea, geography, spec)
                    st.session_state["active_automation_artifact_id"] = spec["id"]
                    append_automation_chat(idea, geography, "user", suggestion["prompt"], spec["id"])
                    append_automation_chat(idea, geography, "assistant", f"I created {spec['name']}. Review the artifact, approve local work, then inspect the run output.", spec["id"])
