        st.session_state["active_automation_artifact_id"] = spec["id"]
        append_automation_chat(idea, geography, "user", automation_request.strip(), spec["id"])
        append_automation_chat(idea, geography, "assistant", f"I created {spec['name']} from the business plan and team memory. Review the artifact, approve local work, then inspect the run output.", spec["id"])
