def build_idea_intelligence_brief(
    idea: str,
    industry: str,
    geography: str,
    evidence_items: list[dict] | None,
    report_context: dict | None,
    source_records: list[dict] | None = None,
) -> dict:
    domain = classify_topic_domain(idea, industry)
    playbook = business_domain_playbook(domain, idea, industry, geography)
    evidence_text = "\n".join(clean_text(item.get("text", ""), limit=2500) for item in (evidence_items or []) if item.get("text"))
    report_bits = ""
    if isinstance(report_context, dict):
        report_bits = json.dumps(
            {
                "topic": report_context.get("topic"),
                "industry": report_context.get("industry"),
                "geography": report_context.get("geography"),
                "topic_intelligence_brief": report_context.get("topic_intelligence_brief"),
                "evidence_completeness": report_context.get("evidence_completeness"),
            },
            ensure_ascii=False,
        )
    combined = clean_text(f"{idea}\n{industry}\n{geography}\n{evidence_text[:7000]}\n{report_bits[:7000]}", limit=16000)
    terms = unique_nonempty(playbook.get("detected_terms", []) + extract_business_terms(combined, limit=18), limit=18)
    inferred_buyer = infer_target_buyer_phrase(idea, evidence_text, industry, geography)
    inferred_pain = infer_problem_phrase(idea, evidence_text, playbook)
    if inferred_buyer:
        playbook["buyer_segments"] = unique_nonempty([inferred_buyer] + [str(x) for x in playbook.get("buyer_segments", [])], limit=5)
    if inferred_pain:
        playbook["pain_domains"] = unique_nonempty([inferred_pain] + [str(x) for x in playbook.get("pain_domains", [])], limit=5)
    source_records = source_records or []
    source_names = unique_nonempty(
        [
            " - ".join(str(record.get(k, "")) for k in ("publisher", "title") if record.get(k))
            for record in source_records[:8]
        ],
        limit=8,
    )
    uploaded_summary = [
        {
            "name": item.get("name"),
            "kind": item.get("kind"),
            "text_available": bool(item.get("text")),
            "useful_extract": clean_text(item.get("text", ""), limit=400) if item.get("text") else "; ".join(item.get("notes", [])),
        }
        for item in (evidence_items or [])[:8]
    ]
    likely_customer = playbook["buyer_segments"][0]
    likely_pain = playbook["pain_domains"][0]
    market_boundary = (
        f"{idea.strip() or industry or 'The idea'} should be treated as a {playbook['category']} for "
        f"{likely_customer} in {geography or 'the selected geography'}, focused first on {likely_pain}. "
        f"Do not analyze the whole {industry or domain} market until this wedge is validated."
    )
    broadness_flags = []
    if len(str(idea or "").split()) < 5:
        broadness_flags.append("Idea text is short; outputs should stay hypothesis-gated until the founder narrows product, buyer, and price.")
    if not evidence_text and not report_context:
        broadness_flags.append("No uploaded/report evidence is available; the builder can create a starting hypothesis but not claim validation.")
    if domain == "ai_workflow_automation" and "small business" in combined.lower():
        broadness_flags.append("Small businesses is not an executable ICP; choose one vertical, tool stack, company-size band, trigger, and launch geography before outreach.")
    launch_geography = select_business_launch_geography(idea, industry, geography, domain)
    return {
        "idea": idea,
        "industry": industry,
        "geography": geography,
        "launch_geography": launch_geography,
        "classified_domain": domain,
        "detected_terms": terms,
        "market_boundary": market_boundary,
        "likely_customer": likely_customer,
        "likely_pain": likely_pain,
        "decision_makers": playbook.get("decision_makers", []),
        "observable_triggers": playbook.get("observable_triggers", []),
        "proof_metrics": playbook.get("proof_metrics", []),
        "pricing_logic": playbook.get("pricing_logic", ""),
        "capabilities_to_build": playbook.get("capabilities", []),
        "innovation_themes": playbook.get("innovation_themes", []),
        "compliance_focus": playbook.get("compliance_focus", []),
        "uploaded_evidence_summary": uploaded_summary,
        "report_context_used": bool(report_context),
        "source_signals": source_names,
        "broadness_flags": broadness_flags,
        "domain_playbook": playbook,
    }


def is_global_scope(geography: str) -> bool:
    geo = clean_text(geography or "", limit=80).lower()
    return not geo or geo in {"global", "worldwide", "international", "all countries", "multi-country"}


def select_business_launch_geography(idea: str, industry: str, geography: str, domain: str | None = None) -> dict:
    domain = domain or classify_topic_domain(idea, industry)
    text = f"{idea} {industry} {geography}".lower()
    if not is_global_scope(geography):
        return {
            "research_scope": geography,
            "execution_scope": geography,
            "sequence": [geography],
            "rule": "The selected geography is both research scope and launch scope.",
        }
    if "india" in text or "inr" in text or "rupee" in text:
        first_geo = "India"
        sequence = ["India", "GCC or Southeast Asia", "United States/UK after proof"]
    elif "europe" in text or "eu " in text or "gdpr" in text:
        first_geo = "United Kingdom or one EU country"
        sequence = ["United Kingdom or one EU country", "EU expansion country-by-country", "North America after proof"]
    elif domain == "ai_workflow_automation":
        first_geo = "United States"
        sequence = ["United States", "Canada/United Kingdom/Australia", "EU after GDPR and data-processing controls are productized"]
    else:
        first_geo = "One country selected by lead availability and regulation"
        sequence = [first_geo, "Adjacent markets with same buyer behavior", "Broader global expansion after repeatable acquisition"]
    return {
        "research_scope": geography or "Global",
        "execution_scope": first_geo,
        "sequence": sequence,
        "rule": "Global is allowed for research context, but execution must start in one beachhead geography before scaled outreach.",
    }


