def ai_workflow_icp_candidates(idea: str, industry: str, geography: str, evidence_gate: dict, playbook: dict, terms: list[str]) -> list[dict]:
    launch_geo = select_business_launch_geography(idea, industry, geography, "ai_workflow_automation")
    is_india = "india" in str(launch_geo.get("execution_scope", geography)).lower()
    validation_status = evidence_gate.get("validation_status", "hypothesis only")
    candidates = []
    scored_options = ai_workflow_vertical_options(idea, industry, geography)
    matched_options = [option for option in scored_options if int(option.get("score", 0) or 0) > 0]
    selected_options = []
    seen_verticals = set()
    source_options = matched_options or scored_options[:3]
    for option in source_options:
        variants = ai_workflow_adjacent_icp_variants(option)
        for variant in variants:
            if len(selected_options) >= 3:
                break
            if variant.get("vertical") in seen_verticals:
                continue
            selected_options.append(variant)
            seen_verticals.add(variant.get("vertical"))
        if len(selected_options) >= 3:
            break
    selected_options = selected_options or scored_options[:3]
    for idx, option in enumerate(selected_options[:3], start=1):
        wtp = option["wtp_in"] if is_india else option["wtp_us"]
        lead_filters = unique_nonempty(
            [launch_geo.get("execution_scope"), option["vertical"], option["buyer_trigger"]]
            + option.get("tool_stack_filter", [])[:4]
            + terms[:3],
            limit=10,
        )
        candidates.append({
            "rank": idx,
            "vertical": option["vertical"],
            "named_buyer_profile": option["named_buyer_profile"],
            "company_size_filter": option["company_size_filter"],
            "tool_stack_filter": option["tool_stack_filter"],
            "pain": f"{option['pain']}. This must be verified with buyer calls and workflow screenshots before scaled outreach.",
            "willingness_to_pay": wtp,
            "buyer_trigger": option["buyer_trigger"],
            "decision_maker": option["decision_maker"],
            "lead_filters": lead_filters,
            "disqualifiers": [
                "No repeated weekly workflow with measurable volume",
                "No visible SaaS/tool stack to integrate with",
                "No budget owner or owner-operated urgency",
                "Already has maintained automations with measured ROI",
            ],
            "outreach_angle": option["diagnostic_cta"],
            "diagnostic_cta": option["diagnostic_cta"],
            "evidence_status": validation_status,
            "first_validation_test": (
                f"Interview 10 {option['vertical']} prospects in {launch_geo.get('execution_scope')}; "
                "require 3 pain confirmations, 2 price confirmations, and 1 paid pilot before hiring or scaling outbound."
            ),
        })
    return candidates


def is_generic_small_business_segment(segment: str) -> bool:
    text = clean_text(segment or "", limit=120).lower()
    return text in {"small businesses", "small business", "smbs", "smes", "businesses"} or text.startswith("small businesses ")


def ai_workflow_adjacent_icp_variants(option: dict) -> list[dict]:
    """Create backup ICPs that stay inside the matched AI-workflow wedge."""
    base = copy.deepcopy(option)
    vertical = str(base.get("vertical", "")).lower()
    variants = [base]

    def make_variant(vertical_name: str, buyer: str, pain: str, trigger: str, cta: str) -> dict:
        row = copy.deepcopy(base)
        row["vertical"] = vertical_name
        row["named_buyer_profile"] = buyer
        row["pain"] = pain
        row["buyer_trigger"] = trigger
        row["diagnostic_cta"] = cta
        row["score_terms"] = list(dict.fromkeys(row.get("score_terms", []) + vertical_name.lower().split()))
        row["keywords"] = list(dict.fromkeys(row.get("keywords", []) + vertical_name.lower().split()))
        return row

    if "ecommerce" in vertical:
        variants.extend([
            make_variant(
                "ecommerce returns and support operations",
                "Shopify/WooCommerce sellers with recurring return, exchange, refund, and customer-update queues handled manually by founders or ops leads",
                "returns, refunds, exchanges, customer updates, and courier exceptions create measurable support backlog and margin leakage",
                "return volume rising, delayed refund complaints, new support hire, or visible helpdesk backlog",
                "Can I map one return-to-refund workflow and show where automation can reduce support load and refund-cycle time?",
            ),
            make_variant(
                "ecommerce inventory and catalog operations",
                "online sellers with 50-1,000 SKUs whose inventory updates, bundle changes, product data, and exception reports still live in spreadsheets",
                "inventory mismatch, catalog updates, bundle changes, and exception reporting slow down order flow and create avoidable founder oversight",
                "SKU growth, frequent stockouts, new marketplace/channel launch, or hiring for ecommerce operations",
                "Can I audit one SKU/order exception path and show which handoffs can be automated with approval gates?",
            ),
        ])
    elif "agency" in vertical or "consulting" in vertical:
        variants.extend([
            make_variant(
                "agency client-reporting operations",
                "agency or consulting teams with 5-50 active clients that manually assemble weekly or monthly reports from multiple tools",
                "manual report assembly, quality checks, commentary writing, and client follow-up consume non-billable senior hours",
                "new client cohort, missed report cadence, account-manager overload, or hiring for client success",
                "Can I map one monthly report workflow and show the hours that can be removed without lowering client quality?",
            ),
            make_variant(
                "agency onboarding and proposal operations",
                "professional-service teams that repeat intake, proposal, onboarding, kickoff, and task-routing workflows for every new client",
                "proposal assembly, intake summaries, kickoff packs, and task routing delay delivery and create inconsistent client starts",
                "increase in inbound leads, repeated proposal delays, new account-manager hire, or client onboarding backlog",
                "Can I convert one proposal-to-kickoff workflow into an auditable automation map before you commit to a pilot?",
            ),
        ])
    elif "appointment" in vertical:
        variants.extend([
            make_variant(
                "appointment intake and follow-up operations",
                "appointment-heavy local operators with inbound inquiries, reminders, document collection, and front-desk follow-up still handled manually",
                "slow response, reminder gaps, missing intake documents, and manual follow-up reduce booked appointments and staff capacity",
                "rising inbound inquiries, missed-call complaints, no-show problem, new location, or front-desk hiring pressure",
                "Can I review one inquiry-to-booking path and show where response time or no-shows can be reduced?",
            ),
            make_variant(
                "high-ticket local service admin operations",
                "local service businesses with high-value bookings where customer intake, eligibility checks, reminders, and post-service follow-up affect revenue",
                "manual intake and post-service communication create lost bookings, lower show rates, and avoidable admin work",
                "new marketing campaign, booking growth, poor follow-up visibility, or overloaded office manager",
                "Can I map the first 24 hours after an inquiry and identify which handoffs should be automated first?",
            ),
        ])
    elif "real-estate" in vertical or "property" in vertical:
        variants.extend([
            make_variant(
                "real-estate lead response operations",
                "broker teams with inbound buyer/seller leads, showing coordination, and transaction follow-up handled across CRM, messages, and spreadsheets",
                "lead response delays, showing coordination, document chasing, and status updates create lost deals and coordinator workload",
                "new listing volume, missed lead response, hiring transaction coordinator, or growth in managed units",
                "Can I map your lead-to-showing path and identify where the first response gap is costing deals?",
            ),
            make_variant(
                "property management tenant and owner operations",
                "property managers handling tenant requests, owner updates, documents, maintenance coordination, and recurring reports manually",
                "tenant/owner updates, maintenance coordination, document chasing, and report assembly create avoidable admin load",
                "growth in managed units, maintenance backlog, owner-report complaints, or hiring for operations",
                "Can I audit one tenant-request workflow and show where approval-gated automation can reduce admin work?",
            ),
        ])
    return variants[:3]


def narrow_small_business_segments(domain: str, industry: str) -> list[str]:
    if domain == "finance":
        return [
            "B2B service firms with 5-50 employees, recurring unpaid invoices, and 30-90 day customer payment terms",
            "small exporters, wholesalers, or distributors with repeat buyers and invoice-backed working-capital gaps",
            "contractors, agencies, or suppliers with signed invoices but cash-flow pressure before customer payment",
        ]
    if domain == "cybersecurity":
        return [
            "regulated professional-services firms with 10-75 employees using Microsoft 365 or Google Workspace and cyber-insurance pressure",
            "healthcare clinics, dental groups, or accounting firms with customer data, compliance exposure, and no internal security team",
            "local manufacturers or logistics operators with endpoint, email, and vendor-access risk but no full-time security owner",
        ]
    return [
        f"{industry or 'target'} firms with 10-75 employees, a visible budget owner, and one measurable recurring pain",
        f"owner-operated {industry or 'target'} businesses with recent growth, manual handoffs, and existing software spend",
        f"specialized {industry or 'target'} operators with a trigger that can be found in public lead data",
    ]


def default_company_size_filter(domain: str, small_business_topic: bool) -> str:
    if not small_business_topic:
        return "Select a narrow company-size band before scaled outreach."
    if domain == "finance":
        return "5-50 employees, recurring B2B invoices, visible receivables/working-capital need, budget owner involved."
    if domain == "cybersecurity":
        return "10-75 employees, sensitive data or compliance exposure, Microsoft 365/Google Workspace footprint, no internal security team."
    return "10-75 employees, owner/operator decision maker, visible trigger, existing software or service spend."


def default_tool_stack_filter(domain: str, idea: str, industry: str) -> list[str]:
    text = f"{idea} {industry}".lower()
    if domain == "finance":
        return ["QuickBooks/Tally/Zoho Books", "GST or sales invoices", "bank statements", "B2B customer contracts", "payment follow-up spreadsheet/CRM"]
    if domain == "cybersecurity":
        return ["Microsoft 365/Google Workspace", "endpoint antivirus/EDR", "email security", "password manager/MFA", "cyber insurance or compliance checklist"]
    if "ecommerce" in text or "retail" in text:
        return ["Shopify/WooCommerce", "payments", "CRM/email", "inventory/order system"]
    return ["CRM/spreadsheet", "email/calendar", "accounting or operations software", "manual reporting workflow"]


def refine_buyer_segment_for_gtm(segment: str, idea: str, industry: str, geography: str, domain: str) -> str:
    """Turn short category labels into an outreach-ready buyer wedge."""
    base = clean_text(segment, limit=180)
    text = f"{idea} {industry} {base}".lower()
    rules = [
        (
            ("fleet", "logistics", "truck"),
            f"truck and EV fleet operators in {geography} with 25-250 vehicles, recurring downtime, fuel or maintenance cost pressure, and an operations head owning uptime KPIs",
        ),
        (
            ("merchant payments", "independent retailers", "retailer payments"),
            f"independent retailers in {geography} with 1-10 stores, daily card or wallet transaction volume, reconciliation pain, and an owner/operator controlling payment decisions",
        ),
        (
            ("battery energy storage", "commercial buildings", "c&i solar", "energy storage"),
            f"commercial building owners and facility managers in {geography} running high-load sites with demand-charge exposure, backup-power risk, and authority over energy projects",
        ),
        (
            ("textile", "wastewater", "effluent"),
            f"textile dyeing and processing factories in {geography} with recurring effluent-treatment cost, discharge-compliance exposure, and an owner or EHS head controlling plant upgrades",
        ),
        (
            ("remote patient monitoring", "cardiology"),
            f"independent cardiology practices and outpatient heart clinics in {geography} with chronic patient panels, reimbursement/admin pressure, and a practice administrator budget owner",
        ),
        (
            ("vocational", "tutoring", "upskilling"),
            f"vocational training institutes and employers in {geography} serving job-seeking learners with completion risk, placement targets, and a training director budget owner",
        ),
        (
            ("private schools", "school management", "k-12"),
            f"private K-12 school chains in {geography} with 500+ students, fee-collection/admin workload, parent communication pressure, and a principal or owner budget owner",
        ),
        (
            ("industrial robotics", "robotics integrator"),
            f"mid-market manufacturers in {geography} with repetitive labor-constrained production cells, 50-500 employees, plant manager ownership, and capex budget for automation",
        ),
        (
            ("smart factory", "automotive suppliers", "predictive maintenance"),
            f"automotive and industrial suppliers in {geography} with OEE pressure, machine downtime, quality reporting needs, and a plant operations owner",
        ),
        (
            ("carbon accounting", "csrd", "exporters"),
            f"export manufacturers in {geography} selling to regulated buyers with emissions-documentation requests, audit exposure, and a CFO or compliance owner",
        ),
        (
            ("hotel revenue", "independent hotels"),
            f"independent hotels in {geography} with 20-120 rooms, OTA dependency, RevPAR pressure, and a general manager or owner making pricing decisions",
        ),
        (
            ("construction", "contractor"),
            f"specialty contractors in {geography} running 5-50 active jobs per year, change-order leakage, job-costing pain, and an owner or project director budget owner",
        ),
        (
            ("water utility", "utility analytics"),
            f"mid-sized water utilities in {geography} with leakage, billing, asset-maintenance, or regulatory reporting pressure and an operations or finance owner",
        ),
        (
            ("creator", "streaming", "gaming"),
            f"creator-led media businesses in {geography} with recurring audience monetization pressure, platform-dependence risk, and a founder or partnerships owner",
        ),
    ]
    for keywords, refined in rules:
        if any(keyword in text for keyword in keywords):
            return refined
    vague = ["specific style community", "early adopters", "target", "operators", "firms", "buyers"]
    if len(base.split()) < 8 or any(base.lower() == item or base.lower().endswith(f" {item}") for item in vague):
        return f"{base or industry or 'target buyers'} in {geography} with 10-250 employees or equivalent demand volume, a named budget owner, existing category spend, and one measurable weekly pain"
    return base


def default_icp_candidates(idea: str, industry: str, geography: str, evidence_gate: dict) -> list[dict]:
    domain = classify_topic_domain(idea, industry)
    small_business_topic = any(term in f"{idea} {industry}".lower() for term in ["small business", "small businesses", "smb", "smes", "sme "])
    is_india = "india" in str(geography).lower()
    currency_band = (
        "Set one INR pilot price and one recurring price after 10 buyer calls; do not use a wide unvalidated range."
        if is_india
        else "Set one USD pilot price and one recurring price after 10 buyer calls; do not use a wide unvalidated range."
    )
    validation_status = evidence_gate.get("validation_status", "hypothesis only")
    intelligence = evidence_gate.get("idea_intelligence") if isinstance(evidence_gate, dict) else {}
    playbook = (intelligence or {}).get("domain_playbook") or business_domain_playbook(domain, idea, industry, geography)
    buyer_segments = unique_nonempty([str(x) for x in playbook.get("buyer_segments", [])], limit=4)
    pain_domains = unique_nonempty([str(x) for x in playbook.get("pain_domains", [])], limit=4)
    triggers = unique_nonempty([str(x) for x in playbook.get("observable_triggers", [])], limit=5)
    decision_makers = unique_nonempty([str(x) for x in playbook.get("decision_makers", [])], limit=4)
    terms = unique_nonempty([str(x) for x in (intelligence or {}).get("detected_terms", [])], limit=8)
    pricing = playbook.get("pricing_logic", "")
    if domain == "ai_workflow_automation":
        return ai_workflow_icp_candidates(idea, industry, geography, evidence_gate, playbook, terms)
    if small_business_topic and any(is_generic_small_business_segment(segment) for segment in buyer_segments[:2]):
        buyer_segments = unique_nonempty(
            narrow_small_business_segments(domain, industry)
            + [segment for segment in buyer_segments if not is_generic_small_business_segment(segment)],
            limit=4,
        )
    candidates = []
    for idx, segment in enumerate(buyer_segments[:3], start=1):
        segment = refine_buyer_segment_for_gtm(segment, idea, industry, geography, domain)
        pain = pain_domains[(idx - 1) % len(pain_domains)] if pain_domains else "costly unmet need"
        short_pain = clean_text(str(pain).split(";")[0], limit=110)
        trigger = triggers[(idx - 1) % len(triggers)] if triggers else "visible urgency or recent change"
        decision = ", ".join(decision_makers[:3]) or "Founder/operator"
        wtp = currency_band
        if domain in {"fashion", "consumer"}:
            wtp = "Validate by price-band test, preorder, gross-margin target, and comparable products"
        elif domain in {"agriculture", "water_environment"}:
            wtp = "Validate by pilot economics, project margin, transaction margin, or contract value"
        elif domain in {"healthcare", "finance"}:
            wtp = "Validate by ROI, compliance value, recovered revenue, or budget-owner confirmation"
        lead_filters = unique_nonempty([geography, industry, segment, trigger] + terms[:4], limit=8)
        candidates.append({
            "rank": idx,
            "vertical": clean_text(segment, limit=90),
            "named_buyer_profile": f"{segment} where {short_pain} is a budget-owned buying pain",
            "company_size_filter": default_company_size_filter(domain, small_business_topic),
            "tool_stack_filter": default_tool_stack_filter(domain, idea, industry),
            "pain": f"{pain} creates measurable cost, delay, churn, compliance exposure, or missed revenue for this specific segment.",
            "willingness_to_pay": wtp,
            "buyer_trigger": trigger,
            "decision_maker": decision,
            "lead_filters": lead_filters,
            "diagnostic_cta": f"Should I send a 5-question diagnostic to quantify {short_pain} against {', '.join(playbook.get('proof_metrics', [])[:2]) or 'the buyer-owned metric'}?",
            "outreach_angle": f"Use {idea or industry} to improve {pain} and prove it with {', '.join(playbook.get('proof_metrics', [])[:3]) or 'a measurable business metric'}.",
            "evidence_status": validation_status,
            "first_validation_test": f"Interview 10 {segment} prospects in {geography}; require 3 to confirm {pain} and 2 to confirm budget or purchase intent.",
        })
    return candidates[:3]


def build_validated_icp_block(idea: str, industry: str, geography: str, evidence_items: list[dict], report_context: dict | None) -> dict:
    evidence_gate = collect_business_icp_evidence(idea, industry, geography, evidence_items, report_context)
    candidates = default_icp_candidates(idea, industry, geography, evidence_gate)
    idea_intelligence = evidence_gate.get("idea_intelligence", {})
    domain = classify_topic_domain(idea, industry)
    if domain == "ai_workflow_automation" and candidates and isinstance(idea_intelligence, dict):
        playbook = copy.deepcopy(idea_intelligence.get("domain_playbook") or {})
        playbook["buyer_segments"] = unique_nonempty(
            [str(candidate.get("named_buyer_profile", "")) for candidate in candidates if isinstance(candidate, dict)],
            limit=3,
        )
        playbook["pain_domains"] = unique_nonempty(
            [str(candidate.get("pain", "")) for candidate in candidates if isinstance(candidate, dict)],
            limit=3,
        )
        idea_intelligence = {
            **idea_intelligence,
            "likely_customer": playbook["buyer_segments"][0] if playbook["buyer_segments"] else idea_intelligence.get("likely_customer", ""),
            "likely_pain": playbook["pain_domains"][0] if playbook["pain_domains"] else idea_intelligence.get("likely_pain", ""),
            "domain_playbook": playbook,
        }
        evidence_gate = {**evidence_gate, "idea_intelligence": idea_intelligence}
    return {
        "status": evidence_gate["validation_status"],
        "risk": "High if scaled outreach starts before the named buyer profile is validated.",
        "why_this_exists": "Prevents generic outreach and prevents the strategy agent from depending on report evidence that does not exist for the selected geography.",
        "idea_intelligence": idea_intelligence,
        "market_boundary": idea_intelligence.get("market_boundary", ""),
        "evidence_gate": evidence_gate,
        "named_buyer_profiles": candidates,
        "do_not_execute_until": [
            "At least one named buyer profile is selected.",
            "Minimum 10 buyer interviews or 3 direct local evidence records support the profile.",
            "Willingness-to-pay is confirmed by at least 2 paid pilots, LOIs, or strong verbal budget confirmations.",
            "Buyer trigger can be detected through Apollo/Hunter/manual lead filters before outbound.",
        ],
    }


