def build_evidence_interpretation(
    idea: str,
    industry: str,
    geography: str,
    evidence_items: list[dict] | None,
    report_context: dict | None,
    top_icp: dict | None = None,
) -> dict:
    top_icp = top_icp or {}
    evidence_items = evidence_items or []
    topic_terms = unique_nonempty(extract_business_terms(f"{idea} {industry} {geography}", limit=18), limit=18)
    buyer_terms = unique_nonempty(extract_business_terms(json.dumps(top_icp, ensure_ascii=False), limit=12), limit=12)
    rows = []
    for item in evidence_items[:12]:
        text = clean_text(item.get("text", ""), limit=6000)
        haystack = f"{item.get('name', '')} {item.get('kind', '')} {text}".lower()
        topic_hits = [term for term in topic_terms if term.lower() in haystack]
        buyer_hits = [term for term in buyer_terms if term.lower() in haystack]
        relevance = min(10, 2 + len(topic_hits) * 2 + len(buyer_hits))
        rows.append({
            "source": item.get("name", "uploaded evidence"),
            "kind": item.get("kind"),
            "text_extracted": bool(text),
            "relevance_score_10": relevance if text else 3,
            "matched_topic_terms": topic_hits[:8],
            "matched_buyer_terms": buyer_hits[:6],
            "what_it_changes": (
                "Use this as direct evidence for ICP, pain, pricing, compliance, objections, or MVP scope."
                if text and relevance >= 6
                else "Keep as weak context only; it needs better OCR/transcript/detail before it can drive the plan."
            ),
            "extract": text[:650] if text else "No extractable text. Add OCR, transcript, or notes before treating it as evidence.",
        })
    report_used = {}
    if isinstance(report_context, dict) and report_context:
        report_text = json.dumps(
            {
                "topic": report_context.get("topic"),
                "industry": report_context.get("industry"),
                "geography": report_context.get("geography"),
                "topic_intelligence_brief": report_context.get("topic_intelligence_brief"),
                "evidence_completeness": report_context.get("evidence_completeness"),
            },
            ensure_ascii=False,
        ).lower()
        report_used = {
            "topic": report_context.get("topic"),
            "industry": report_context.get("industry"),
            "geography": report_context.get("geography"),
            "matched_terms": [term for term in topic_terms if term.lower() in report_text][:10],
            "use_rule": "Use only claims matching the current idea, industry, and launch geography; mismatched report claims remain background context.",
        }
    return {
        "status": "uploaded evidence interpreted" if rows else "no uploaded evidence; plan is hypothesis-gated",
        "topic_terms_checked": topic_terms,
        "buyer_terms_checked": buyer_terms,
        "items": rows,
        "latest_report_context": report_used or {"status": "no matching generated report supplied"},
        "evidence_decision_rule": "A claim can enter the plan only if it matches topic, buyer, geography, and source context; otherwise it becomes an assumption to verify in discovery.",
        "minimum_next_evidence": [
            "10-15 buyer conversation notes",
            "3-5 buyer-approved proof metrics",
            "1 LOI, verbal budget commitment, or paid pilot signal before building",
            "minimum compliance map for the first pilot geography",
        ],
    }


