def business_plan_to_markdown(plan: dict) -> str:
    lines = ["# Agentic Business Build Plan", ""]
    for key, value in plan.items():
        if key.startswith("_"):
            continue
        lines.append(f"## {humanize_label(key)}")
        lines.append("```json")
        lines.append(json.dumps(value, indent=2, ensure_ascii=False))
        lines.append("```")
        lines.append("")
    return "\n".join(lines)


def founder_plan_budget_allocation(domain: str) -> list[dict]:
    """Budget structure adapted from the uploaded IIDATECH action-plan template."""
    if domain == "ai_workflow_automation":
        rows = [
            ("Product, Technology & Automation", 25, "High", ["MVP workflow build", "cloud/API/tool usage", "security and backup", "technical QA"]),
            ("Founder Sales & Marketing", 22, "High", ["landing page", "outbound tools", "proof assets", "niche content", "CRM setup"]),
            ("Delivery & Operations", 20, "High", ["implementation labor", "SOPs", "customer support", "pilot delivery"]),
            ("Market Research & Validation", 13, "High", ["buyer interviews", "competitor/pricing checks", "survey incentives", "proof metric tracking"]),
            ("Legal, Compliance & Risk", 8, "Medium", ["contracts", "privacy policy", "data processing review", "claims review"]),
            ("Contingency Reserve", 12, "Medium", ["tool overruns", "extra implementation hours", "failed experiments", "pivot reserve"]),
        ]
    elif domain in {"consumer_product", "fashion", "retail"}:
        rows = [
            ("Inventory, Samples & Production", 30, "High", ["samples", "first production run", "packaging", "quality checks"]),
            ("Marketing & Sales", 20, "High", ["creative assets", "creator seeding", "website", "paid test budget", "email/SMS"]),
            ("Operations & Fulfillment", 18, "High", ["fulfillment setup", "returns process", "warehousing", "shipping materials"]),
            ("Market Research & Customer Testing", 10, "High", ["customer interviews", "price tests", "competitor/SKU audit", "surveys"]),
            ("Legal & Compliance", 7, "Medium", ["entity setup", "GST/tax", "trademark", "product safety review"]),
            ("Contingency Reserve", 15, "Medium", ["stockouts", "defects", "returns spike", "supplier delays"]),
        ]
    else:
        rows = [
            ("Personnel & Operations", 25, "High", ["founder/operator time", "contractors", "admin", "customer delivery"]),
            ("Infrastructure & Equipment", 20, "High", ["tools", "workspace", "equipment", "workflow systems"]),
            ("Marketing & Sales", 18, "High", ["website", "outreach", "content", "CRM", "sales collateral"]),
            ("Technology & Software", 15, "Medium", ["software subscriptions", "analytics", "security", "automation"]),
            ("Legal & Compliance", 8, "Medium", ["entity setup", "contracts", "licenses", "insurance", "privacy"]),
            ("Market Validation", 7, "High", ["interviews", "surveys", "competitor checks", "pilot measurement"]),
            ("Contingency Reserve", 7, "Medium", ["unexpected costs", "failed experiments", "pivot reserve"]),
        ]
    return [
        {"category": category, "allocation_pct": pct, "priority": priority, "line_items": items}
        for category, pct, priority, items in rows
    ]


