def create_nocodb_record(api_token: str, base_url: str, table_id: str, fields: dict) -> tuple[bool, str]:
    if not api_token:
        return False, "NocoDB API token missing."
    if not base_url or not table_id:
        return False, "NocoDB base URL and table ID/name are required."
    if not isinstance(fields, dict) or not fields:
        return False, "NocoDB fields are required."
    clean_fields = {str(key): value for key, value in fields.items() if str(key).strip()}
    if not clean_fields:
        return False, "NocoDB fields are required."
    if dummy_execution_enabled(api_token, base_url, table_id):
        return dummy_success("NocoDB", f"Would create record in {table_id}.")
    try:
        base = base_url.rstrip("/")
        if base.endswith("/records"):
            endpoint = base
        else:
            endpoint = f"{base}/api/v2/tables/{quote(table_id.strip(), safe='')}/records"
        resp = requests.post(
            endpoint,
            headers={"xc-token": api_token, "Content-Type": "application/json"},
            json=clean_fields,
            timeout=45,
        )
        if 200 <= resp.status_code < 300:
            data = resp.json() if resp.content else {}
            record_id = data.get("Id") or data.get("id") or data.get("ncRecordId") or "accepted"
            return True, f"NocoDB record created: {record_id}"
        return False, f"NocoDB HTTP {resp.status_code}: {resp.text[:240]}"
    except Exception as e:
        return False, str(e)


def create_notion_page(
    api_key: str,
    database_id: str,
    title_property: str,
    title: str,
    properties: dict | None = None,
) -> tuple[bool, str]:
    if not api_key:
        return False, "Notion API key missing."
    if not database_id:
        return False, "Notion database ID is required."
    title_property = title_property.strip() or "Name"
    title = clean_text(title, limit=220)
    if not title:
        return False, "Notion page title is required."
    notion_properties = {
        title_property: {"title": [{"text": {"content": title}}]},
    }
    for key, value in (properties or {}).items():
        key = str(key).strip()
        if not key or key == title_property:
            continue
        text_value = clean_text(value if isinstance(value, str) else json.dumps(value, ensure_ascii=False), limit=1800)
        notion_properties[key] = {"rich_text": [{"text": {"content": text_value}}]}
    if dummy_execution_enabled(api_key, database_id):
        return dummy_success("Notion", f"Would create page {title}.")
    try:
        resp = requests.post(
            "https://api.notion.com/v1/pages",
            headers={
                "Authorization": f"Bearer {api_key}",
                "Content-Type": "application/json",
                "Notion-Version": "2022-06-28",
            },
            json={"parent": {"database_id": database_id}, "properties": notion_properties},
            timeout=45,
        )
        if 200 <= resp.status_code < 300:
            data = resp.json() if resp.content else {}
            return True, f"Notion page created: {data.get('id', title)}"
        return False, f"Notion HTTP {resp.status_code}: {resp.text[:240]}"
    except Exception as e:
        return False, str(e)


