def capture_posthog_event(api_key: str, host: str, distinct_id: str, event_name: str, properties: dict | None = None) -> tuple[bool, str]:
    if not api_key:
        return False, "PostHog project API key missing."
    host = (host or POSTHOG_HOST or "https://app.posthog.com").rstrip("/")
