def append_outbound_log(row: dict) -> Path:
    log_dir = APP_DIR / "business_build_outputs" / "outbound_logs"
    log_dir.mkdir(parents=True, exist_ok=True)
    log_path = log_dir / "outbound_actions.jsonl"
    row = {**row, "logged_at": time.strftime("%Y-%m-%d %H:%M:%S")}
    with log_path.open("a", encoding="utf-8") as f:
        f.write(json.dumps(row, ensure_ascii=False) + "\n")
    return log_path


def append_local_crm_record(fields: dict, record_type: str = "lead") -> tuple[bool, str]:
    if not isinstance(fields, dict) or not fields:
        return False, "Local CRM fields are required."
    clean_fields = {str(key).strip(): value for key, value in fields.items() if str(key).strip()}
    if not clean_fields:
        return False, "Local CRM fields are required."
    crm_dir = APP_DIR / "business_build_outputs" / "local_crm"
    crm_dir.mkdir(parents=True, exist_ok=True)
    clean_type = re.sub(r"[^a-z0-9_]+", "_", str(record_type or "lead").lower()).strip("_") or "lead"
    record_id = f"local-{clean_type}-{int(time.time() * 1000)}"
    row = {
        "id": record_id,
        "record_type": clean_type,
        "fields": clean_fields,
        "created_at": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    log_path = crm_dir / f"{clean_type}_records.jsonl"
    with log_path.open("a", encoding="utf-8") as f:
        f.write(json.dumps(row, ensure_ascii=False) + "\n")
    append_outbound_log({"action": "create_local_crm_record", "record_type": clean_type, "record_id": record_id})
    return True, f"Local CRM record saved: {record_id}"


def is_ai_workflow_topic(topic: str, industry: str) -> bool:
    haystack = f"{topic} {industry}".lower()
    ai_signal = topic_text_has_any(
        haystack,
        (
            "ai",
            "artificial intelligence",
            "agentic",
            "ai agent",
            "agents",
            "llm",
            "copilot",
            "rpa",
            "zapier",
            "make.com",
            "n8n",
            "uipath",
        ),
    )
    crm_workflow_signal = topic_text_has_any(
        haystack,
        (
            "crm automation",
            "sales automation",
            "customer relationship management automation",
            "sales workflow",
            "revops",
            "revenue operations",
        ),
    )
    workflow_signal = topic_text_has_any(
        haystack,
        (
            "workflow",
            "automation",
            "automate",
            "orchestration",
            "operations platform",
            "delivery operations",
            "small business",
            "small businesses",
            "smb",
            "sme",
        ),
    )
    return (ai_signal and workflow_signal) or crm_workflow_signal


def healthcare_wedge(topic: str, industry: str) -> str:
    haystack = f"{topic} {industry}".lower()
    if any(term in haystack for term in ("registry", "quality reporting", "nhsn", "clinical registry", "compliance reporting", "measure reporting")):
        return "clinical_registry_compliance"
    if any(term in haystack for term in ("diagnostic", "diagnostics", "lab ", "laboratory", "clia", "clfs", "ivd", "pathology")):
        return "diagnostic_lab_billing"
    if any(term in haystack for term in ("hospital", "health system", "cfo", "denial", "denials", "appeal", "prior authorization", "revenue cycle", "rcm")):
        return "hospital_revenue_cycle"
    if any(term in haystack for term in ("medical billing", "coding", "payer portal", "claim", "claims", "practice management")):
        return "physician_practice_billing"
    if any(term in haystack for term in ("samd", "clinical decision support", "medical device", "fda", "mdr", "cdsco", "triage", "diagnosis", "treatment")):
        return "regulated_clinical_software"
    return "healthcare_general"


def topic_text_has_term(text: str, term: str) -> bool:
    low = str(text or "").lower()
    needle = str(term or "").lower().strip()
    if not needle:
        return False
    if " " in needle or "_" in needle or "/" in needle or "-" in needle or "." in needle:
        return needle in low
    return re.search(rf"(?<![a-z0-9]){re.escape(needle)}(?![a-z0-9])", low) is not None


def topic_text_has_any(text: str, terms: tuple[str, ...]) -> bool:
    return any(topic_text_has_term(text, term) for term in terms)


