def score_beauty_vs_agriculture(haystack: str) -> tuple[int, int]:
    low = str(haystack or "").lower()
    beauty = sum(1 for term in BEAUTY_CONSUMER_KEYWORDS if term in low)
    agriculture = sum(1 for term in AGRICULTURE_STRICT_KEYWORDS if term in low)
    if "organic" in low and any(term in low for term in ("skincare", "cosmetic", "beauty", "serum", "moisturizer", "d2c", "dtc", "brand")):
        beauty += 2
    if "organic" in low and any(term in low for term in ("farm", "farming", "crop", "agriculture", "produce", "cultivation")):
        agriculture += 2
    return beauty, agriculture


def resolve_beauty_consumer_domain(haystack: str) -> str | None:
    beauty, agriculture = score_beauty_vs_agriculture(haystack)
    if beauty >= 2 and beauty > agriculture:
        return "ecommerce_retail"
    if beauty >= 2 and beauty == agriculture:
        return "ecommerce_retail"
    return None


def record_host_is_trusted_research(url: str, publisher: str = "") -> bool:
    host = urlparse(str(url or "")).netloc.lower().replace("www.", "")
    blob = f"{host} {publisher}".lower()
    return any(domain in blob for domain in TRUSTED_RESEARCH_DOMAINS)


def record_has_named_saas_competitor(record: dict) -> bool:
    haystack = record_text_blob(record).lower()
    company = str(record.get("company") or record.get("entity_name") or "").lower()
    return any(name.lower() in haystack or name.lower() in company for name in KNOWN_SAAS_COMPETITOR_NAMES)


def record_has_named_automotive_competitor(record: dict) -> bool:
    haystack = record_text_blob(record).lower()
    company = str(record.get("company") or record.get("entity_name") or "").lower()
    return any(name.lower() in haystack or name.lower() in company for name in KNOWN_AUTOMOTIVE_COMPETITOR_NAMES)


