def resolve_commercial_route(topic: str, industry: str, country: str = "") -> dict:
    """Deterministic commercial domain router.

    Runs BEFORE classify_topic_domain.  Returns a hard routing dict;
    caller must use the domain when ``confidence >= 0.75``.
    """
    h = f"{topic} {industry} {country}".lower()

    def _any(*terms: str) -> bool:
        return any(t in h for t in terms)

    # ── AI customer support + ecommerce (highest-priority combo) ────────────
    ecomm = _any("ecommerce", "e-commerce", "shopify", "online store", "woocommerce",
                 "magento", "d2c", "dtc", "online retail", "online shop")
    support = _any("support", "helpdesk", "help desk", "ticketing", "chat support",
                   "customer service", "gorgias", "zendesk", "intercom",
                   "forethought", "ada ai", "support automation")
    if ecomm and support:
        return {"domain": "ai_support_ecommerce", "competitor_template": "ai_support_ecommerce",
                "pricing_template": "ai_support_ecommerce",
                "tam_template": "store_count_x_support_spend", "confidence": 0.92}
    if _any("ai support automation", "ai customer support", "ai helpdesk",
            "ai support", "ai customer service", "ai ticketing",
            "support ai", "automated support"):
        conf = 0.84 if _any("ecommerce", "store", "shopify", "retail") else 0.76
        return {"domain": "ai_support_ecommerce", "competitor_template": "ai_support_ecommerce",
                "pricing_template": "ai_support_ecommerce",
                "tam_template": "store_count_x_support_spend", "confidence": conf}

    # ── Dental SaaS ─────────────────────────────────────────────────────────
    if _any("dental", "dentist", "dentistry", "orthodontic", "orthodontist",
            "dental clinic", "dental practice", "dental office"):
        return {"domain": "dental_saas", "competitor_template": "dental_saas",
                "pricing_template": "dental_saas",
                "tam_template": "clinic_count_x_annual_software_spend", "confidence": 0.90}

    # ── Clinic / practice workflow SaaS (non-dental, non-hospital) ──────────
    clinic_signal = _any("clinic", "appointment scheduling", "practice management",
                         "medical workflow", "patient scheduling", "doctor scheduling",
                         "outpatient", "specialty clinic", "veterinary clinic")
    software_signal = _any("automation", "software", "saas", "platform", "app",
                            "system", "workflow", "scheduling")
    if clinic_signal and software_signal:
        return {"domain": "clinic_workflow", "competitor_template": "clinic_workflow",
                "pricing_template": "clinic_workflow",
                "tam_template": "clinic_count_x_annual_software_spend", "confidence": 0.78}

    # ── CRM / RevOps ─────────────────────────────────────────────────────────
    if _any("crm", "sales pipeline", "lead management",
            "customer relationship management", "sales automation"):
        return {"domain": "crm_automation", "competitor_template": "crm_automation",
                "pricing_template": "crm_automation",
                "tam_template": "smb_count_x_software_spend", "confidence": 0.85}

    beauty_score, ag_score = score_beauty_vs_agriculture(h)
    if beauty_score >= 2 and beauty_score >= ag_score:
        from iidatech.routing.domain_router import should_block_domain
        blocked, _ = should_block_domain(topic, "ecommerce_retail", industry)
        if not blocked:
            return {"domain": "ecommerce_retail", "competitor_template": "ecommerce_retail",
                    "pricing_template": "ecommerce_retail",
                    "tam_template": "consumer_brand_count_x_aov", "confidence": 0.86}

    return {"domain": "", "competitor_template": "", "pricing_template": "",
            "tam_template": "", "confidence": 0.0}


def classify_topic_domain(topic: str, industry: str) -> str:
    from iidatech.routing.domain_router import route_domain, should_block_domain

    # Weighted ontology router — festive/event/decor niches before legacy bleed.
    scored = route_domain(topic, industry)
    if scored.get("selected_domain"):
        return str(scored["selected_domain"])

    # Commercial router takes priority — prevents niche topics from falling
    # into generic healthcare / ai_workflow_automation buckets.
    _route = resolve_commercial_route(topic, industry)
    if _route["confidence"] >= 0.75:
        blocked, _ = should_block_domain(topic, _route["domain"], industry)
        if not blocked:
            return _route["domain"]

    haystack = f"{topic} {industry}".lower()
    industry_text = industry.lower()
    crm_terms = (
        "crm", "customer relationship management", "sales automation",
        "lead management", "pipeline management", "sales funnel",
        "customer support automation", "hubspot", "salesforce", "zoho crm",
        "freshsales", "pipedrive",
    )
    revops_terms = (
        "revops", "revenue operations", "sales ops", "sales enablement",
        "outbound automation", "lead enrichment", "sales workflow",
    )
    b2b_saas_terms = (
        "saas", "subscription software", "workflow software", "business software",
        "enterprise software", "cloud software", "automation platform",
    )
    if topic_text_has_any(haystack, crm_terms) and topic_text_has_any(
        haystack,
        ("automation", "automate", "workflow", "smb", "sme", "small business", "software", "platform", "saas"),
    ):
        return "crm_automation"
    if topic_text_has_any(haystack, revops_terms):
        return "revops_sales_automation"
    if topic_text_has_any(haystack, b2b_saas_terms):
        return "b2b_saas"
    if topic_text_has_any(haystack, ("heat pump", "heat pumps", "building electrification", "nuclear", "smr", "small modular reactor", "advanced reactor")):
        return "energy"
    if topic_text_has_any(haystack, ("carbon removal", "biochar", "battery recycling", "black mass", "circular minerals")):
        return "climate"
    if topic_text_has_any(haystack, ("vertical farming", "controlled environment agriculture", "precision fermentation", "alternative protein", "cultivated food")):
        return "agriculture"
    if topic_text_has_any(haystack, ("glp-1", "glp1", "obesity", "metabolic health", "longevity", "preventive health", "femtech", "fertility", "women's health", "synthetic biology", "biomanufacturing", "medspa", "medical aesthetics")):
        return "healthcare"
    if topic_text_has_any(haystack, ("ai governance", "model risk", "modelops", "ai assurance", "llm security", "prompt injection", "ai red team", "ai red-teaming")):
        return "cybersecurity"
    if topic_text_has_any(haystack, ("developer tools", "coding agent", "code assistant", "vector database", "rag platform", "data infrastructure", "embedding pipeline")):
        return "ai_workflow_automation"
    if topic_text_has_any(haystack, ("post-quantum cryptography", "post quantum cryptography", "quantum-safe", "quantum safe", "pqc")) or (
        topic_text_has_any(haystack, ("post-quantum", "post quantum", "quantum")) and
        topic_text_has_any(haystack, ("bank", "security", "cyber", "cryptography", "encryption", "compliance", "risk"))
    ):
        return "cybersecurity"
    if topic_text_has_any(haystack, ("quantum", "post-quantum", "quantum computing", "quantum sensing")):
        return "semiconductors"
    if topic_text_has_any(haystack, ("spatial computing", "ar/vr", "ar vr", "immersive training", "xr training")):
        return "media"
    if topic_text_has_any(haystack, ("embedded finance", "banking-as-a-service", "baas", "payments infrastructure")):
        return "finance"
    if topic_text_has_any(haystack, ("industrial iot", "digital twin", "digital twins", "asset monitoring")):
        return "manufacturing"
    if topic_text_has_any(haystack, ("sports betting", "fantasy sports", "integrity monitoring", "odds")):
        return "sports"
    if topic_text_has_any(haystack, ("water treatment", "wastewater", "desalination", "water purification", "effluent", "sewage", "filtration")):
        return "water_environment"
    if topic_text_has_any(
        haystack,
        (
            "law firm",
            "law firms",
            "lawyer",
            "lawyers",
            "legal technology",
            "legal tech",
            "contract operations",
            "contract review",
            "legal services",
            "professional indemnity",
            "startup client agreements",
        ),
    ):
        return "compliance"
    if is_ai_workflow_topic(topic, industry):
        return "ai_workflow_automation"
    if topic_text_has_any(industry_text, ("automotive", "mobility", "electric vehicle", "vehicle", "ev", "adas")):
        return "automotive"
    if topic_text_has_any(haystack, EXTENDED_DOMAIN_TERMS["aerospace_defense"]):
        return "aerospace_defense"
    if topic_text_has_any(haystack, EXTENDED_DOMAIN_TERMS["sports"]):
        return "sports"
    if topic_text_has_any(
        haystack,
        (
            "senior care",
            "elder care",
            "eldercare",
            "home health",
            "home-visit care",
            "home visit care",
            "caregiver",
            "care coordination",
            "mental health",
            "behavioral health",
            "clinic",
            "dental",
            "pharma",
            "pharmaceutical",
            "cold-chain",
            "cold chain",
        ),
    ):
        return "healthcare"
    if topic_text_has_any(haystack, EXTENDED_DOMAIN_TERMS["education"]):
        return "education"
    if topic_text_has_any(haystack, ("pet care", "pet products", "pet food", "veterinary", "grooming", "pet subscription")):
        return "consumer"
    if topic_text_has_any(haystack, EXTENDED_DOMAIN_TERMS["hospitality"]):
        return "hospitality"
    if topic_text_has_any(haystack, ("health", "healthcare", "medical", "pharma", "clinical", "hospital", "disease", "clinic", "dermatology", "patient", "payer", "provider", "diagnostic", "eldercare", "elder care", "home health")):
        return "healthcare"
    if topic_text_has_any(haystack, ("finance", "financial", "bank", "banking", "insurance", "insurtech", "fintech", "credit", "payments", "invoice financing", "lending", "loan", "underwriting", "accounting", "bookkeeping", "tax", "payroll", "cfo services")):
        return "finance"
    if topic_text_has_any(haystack, ("energy", "solar", "wind", "battery", "oil", "gas", "grid", "storage", "renewable", "power")):
        return "energy"
    if any(term in haystack for term in FASHION_TERMS):
        return "fashion"
    if topic_text_has_any(haystack, EXTENDED_DOMAIN_TERMS["climate"]):
        return "climate"
    beauty_domain = resolve_beauty_consumer_domain(haystack)
    if beauty_domain:
        blocked, _ = should_block_domain(topic, beauty_domain, industry)
        if not blocked:
            return beauty_domain
    if any(term in haystack for term in AGRICULTURE_TERMS):
        if "organic" in haystack and beauty_domain is None:
            _beauty, _ag = score_beauty_vs_agriculture(haystack)
            if _beauty >= _ag:
                blocked, _ = should_block_domain(topic, "ecommerce_retail", industry)
                if not blocked:
                    return "ecommerce_retail"
        blocked, _ = should_block_domain(topic, "agriculture", industry)
        if not blocked:
            return "agriculture"
    if topic_text_has_any(haystack, ("water", "wastewater", "effluent", "sewage", "desalination")):
        return "water_environment"
    if topic_text_has_any(haystack, EXTENDED_DOMAIN_TERMS["semiconductors"]):
        return "semiconductors"
    if topic_text_has_any(haystack, EXTENDED_DOMAIN_TERMS["mining"]):
        return "mining"
    for domain, terms in EXTENDED_DOMAIN_TERMS.items():
        if topic_text_has_any(haystack, terms):
            return domain
    return "general_market"


def narrow_topic_scope(topic: str, industry: str, target: str) -> str:
    domain = classify_topic_domain(topic, industry)
    text = topic.lower()
    if domain == "agriculture":
        if any(x in text for x in ("export", "apeda", "organic", "rice", "mango", "spice", "processed food")):
            return "agri-export value chain: production base, procurement, certification, processing, logistics, buyers, and export channels"
        if any(x in text for x in ("farmer", "credit", "nabard", "fpo", "rural")):
            return "farmer/FPO enablement: credit, input access, advisory, procurement, market linkage, and working capital"
        if any(x in text for x in ("tech", "ai", "platform", "app", "digital")):
            return "agritech platform: farmer acquisition, advisory/workflow, data rails, procurement partners, and monetization"
        return "one agriculture value chain in the selected geography, with farmer economics, distribution, procurement, and buyer demand separated"
    if domain == "fashion":
        if any(x in text for x in ("luxury", "premium", "designer", "jewelry", "watch")):
            return "one luxury or premium category, with customer segment, channel, price band, brand positioning, and competitor set separated"
        if any(x in text for x in ("resale", "secondhand", "thrift", "circular", "sustainable")):
            return "one circular/resale fashion model, with supply acquisition, authentication, take rate, logistics, and repeat buyer behavior separated"
        if any(x in text for x in ("d2c", "ecommerce", "brand", "online")):
            return "one D2C fashion category and customer segment, with CAC, gross margin, returns, inventory, and channel mix separated"
        return "one apparel/textile/fashion category, price band, region, and channel; do not analyze the whole fashion industry as one market"
    if domain == "ai_workflow_automation":
        return "one SMB workflow wedge, not the entire AI software market"
    if domain in {"crm_automation", "b2b_saas", "revops_sales_automation"}:
        if any(x in text for x in ("lead", "lead management", "lead generation")):
            return "one CRM buyer segment focused on lead management and pipeline automation: buyer size, workflow, pricing, named vendors, and adoption signals; separate SMB from mid-market"
        if any(x in text for x in ("revops", "revenue operations", "sales ops", "sales enablement")):
            return "one RevOps/sales-ops workflow wedge: buyer title, tool stack, automation depth, vendor pricing, and switching friction; separate outbound, enrichment, and pipeline tools"
        return "one CRM/sales-automation buyer segment: define SMB vs mid-market, lead lifecycle stage, pricing model, named competitors (Salesforce, HubSpot, Zoho, Freshsales, Pipedrive), and monetization wedge"
    if domain == "water_environment":
        return "one water or wastewater use case, customer/plant type, geography, treatment technology, and regulatory driver"
    if domain == "healthcare":
        wedge = healthcare_wedge(topic, industry)
        wedge_scopes = {
            "hospital_revenue_cycle": "hospital revenue-cycle wedge: claims denial, prior authorization, appeals, coding, documentation, payer communication, or AR workflow; do not combine with clinical registries or diagnostic labs",
            "physician_practice_billing": "physician-practice billing wedge: specialty, payer mix, claim volume, denial workflow, payer portals, coding staff, and PM/EHR integration",
            "clinical_registry_compliance": "clinical registry/compliance wedge: NHSN/quality registry reporting workflow, facility denominator, reporting burden, validation, penalties/incentives, and compliance buyer",
            "diagnostic_lab_billing": "diagnostic-lab billing wedge: CLIA/CLFS/CPT/test-menu reimbursement, sample volume, payer mix, lab operations, and quality/compliance requirements",
            "regulated_clinical_software": "regulated clinical software wedge: SaMD/CDS risk classification, clinical evidence, QMS, regulator pathway, reimbursement, and capital burn",
            "healthcare_general": "one healthcare buyer and one reimbursed/admin/clinical workflow; do not analyze hospital RCM, labs, registries, and SaMD as one TAM",
        }
        return wedge_scopes.get(wedge, wedge_scopes["healthcare_general"])
    return f"one buyer segment and one monetization wedge inside {industry or 'the selected industry'} for {target}"


def source_pack_text(topic: str, industry: str, country: str | None = None) -> str:
    domain = classify_topic_domain(topic, industry)
    controlled_pack = source_text_for_domain(domain) if source_text_for_domain is not None else ""
    country_fact_pack = country_specific_fact_pack(country, domain) if country else ""

    if country:
        # Country mode is a hard evidence boundary: use only country-local fact packs
        # here. Regional/global curated packs are intentionally skipped and can only
        # appear later as visibly labelled proxy evidence if a section asks for it.
        return country_fact_pack

    if domain == "agriculture":
        blocks = []
        for item in AGRICULTURE_SOURCE_PACK:
            blocks.append(
                "[VERIFIED | AGRICULTURE | confidence 90%]\n"
                f"Title: {item['title']}\n"
                f"Summary: {' '.join(item['facts'])}\n"
                f"Source: {item['url']}"
            )
        curated = "CURATED AGRICULTURE / AGRIBUSINESS SOURCE PACK:\n" + "\n\n".join(blocks)
        return "\n\n".join(part for part in (controlled_pack, curated) if part)

    if domain == "fashion":
        blocks = []
        for item in FASHION_SOURCE_PACK:
            blocks.append(
                "[VERIFIED | FASHION | confidence 85%]\n"
                f"Title: {item['title']}\n"
                f"Summary: {' '.join(item['facts'])}\n"
                f"Source: {item['url']}"
            )
        curated = "CURATED FASHION / APPAREL SOURCE PACK:\n" + "\n\n".join(blocks)
        return "\n\n".join(part for part in (controlled_pack, curated) if part)

    if domain in {"crm_automation", "b2b_saas", "revops_sales_automation"}:
        crm_blocks = [
            "[VERIFIED | CRM VENDOR | confidence 90%]\nTitle: HubSpot CRM pricing and SMB adoption\nSummary: HubSpot offers a freemium CRM with paid tiers (Starter ~$15/seat/month, Professional ~$450/month, Enterprise ~$1,500/month). Over 200,000 SMB customers as of 2024. Key SMB entry point is free CRM plus paid Marketing/Sales Hub. Sources: HubSpot investor relations, pricing page, G2 reviews.\nSource: https://www.hubspot.com/pricing",
            "[VERIFIED | CRM VENDOR | confidence 90%]\nTitle: Salesforce SMB and mid-market CRM pricing\nSummary: Salesforce Starter Suite ~$25/user/month; Professional ~$80/user/month; Enterprise ~$165/user/month. SMB penetration via Salesforce Essentials and Starter. Revenue >$34B FY2024. Sources: Salesforce 10-K, pricing page, G2/Capterra reviews.\nSource: https://www.salesforce.com/pricing",
            "[VERIFIED | CRM VENDOR | confidence 85%]\nTitle: Zoho CRM SMB pricing and market position\nSummary: Zoho CRM Standard ~$14/user/month; Professional ~$23/user/month; Enterprise ~$40/user/month. Claimed 250,000+ businesses globally. Strong SMB traction in emerging markets. Sources: Zoho pricing page, G2 category data.\nSource: https://www.zoho.com/crm/zohocrm-pricing.html",
            "[VERIFIED | CRM VENDOR | confidence 85%]\nTitle: Pipedrive and Freshsales SMB CRM pricing\nSummary: Pipedrive Essential ~$15/user/month; Advanced ~$29/user/month; Professional ~$59/user/month. Freshsales Growth ~$15/user/month; Pro ~$39/user/month. Both targeting SMB sales teams with pipeline-centric UX. Sources: vendor pricing pages, G2 SMB category.\nSource: https://www.pipedrive.com/en/plans",
            "[CONTEXT | REVIEW PLATFORM | confidence 75%]\nTitle: G2 and Capterra CRM category benchmarks\nSummary: G2 CRM category has 900+ products; Salesforce, HubSpot, Zoho, Pipedrive, and Freshsales dominate SMB reviews. Average SMB NPS and ease-of-use scores available per vendor. Review counts indicate relative market penetration. Sources: G2.com CRM grid, Capterra CRM category.\nSource: https://www.g2.com/categories/crm",
            "[CONTEXT | ANALYST | confidence 70%]\nTitle: SaaS CRM market sizing and CAGR benchmarks\nSummary: Global CRM market estimated $65-$100B range (varies by scope: sales CRM vs all customer management). SMB segment ~20-30% of total. CAGR estimates 10-14% through 2028. Use bottom-up SMB count x ARPU as primary sizing method; treat analyst TAM figures as context only without source. Sources: Gartner, IDC, Forrester notes (verify exact scope before citing).\nSource: https://www.gartner.com/en/information-technology/insights/crm-strategy",
            "[CONTEXT | MARKET SIZING MODEL | confidence 60%]\nTitle: Bottom-up SMB CRM sizing model\nSummary: Illustrative model: 30M software-mature global SMBs x 15% CRM adoption x $300 ARPU = $1.35B base SMB CRM ARR; scaling to 25% adoption at $400 ARPU = $3B. Mid-market adds another layer. These are methodology assumptions; validate with vendor revenue splits and buyer surveys before citing.\nSource: IIDATECH internal bottom-up model",
        ]
        curated = "CURATED CRM / B2B SAAS SOURCE PACK:\n" + "\n\n".join(crm_blocks)
        return "\n\n".join(part for part in (country_fact_pack, controlled_pack, curated) if part)

    if domain != "ai_workflow_automation":
        return "\n\n".join(part for part in (country_fact_pack, controlled_pack) if part)

    blocks = []
    for item in AI_AUTOMATION_SOURCE_PACK:
        blocks.append(
            "[VERIFIED | CURATED | confidence 95%]\n"
            f"Title: {item['title']}\n"
            f"Summary: {' '.join(item['facts'])}\n"
            f"Source: {item['url']}"
        )
    blocks.append(
        "[MODEL | IIDATECH SIZING ASSUMPTIONS | confidence 60%]\n"
        "Title: Bottom-up SMB AI workflow automation sizing model\n"
        "Summary: Illustrative SMB spend model for missing market-size datasets: annual contract value "
        "bands of $600, $2,400, and $6,000 per business; base reachable universe of 30 million software-mature "
        "SMBs globally; final base-case TAM of $72 billion equals 30 million businesses times $2,400 ACV. "
        "SAM of $22 billion equals 30% of TAM; SOM range of $220 million to $660 million equals 1% to 3% of SAM. "
        "Regional base model: U.S. $20 billion, Europe $15 billion, APAC $25 billion, Rest of world $12 billion. "
        "Adoption curve model for the 30 million reachable universe: 3% adoption in 2026, 6% in 2027, 10% in 2028, "
        "15% in 2029, 21% in 2030, and 27% in 2031. Churn stress case uses 30% annual churn, reducing first-year "
        "retained ARR from $72 billion to $50.4 billion. Workflow usage bands: 50, 500, 1,000, and 10,000 AI-assisted "
        "runs per month. These are methodology assumptions, not external market estimates.\n"
        "Source: IIDATECH internal bottom-up model"
    )
    curated = "CURATED AI WORKFLOW AUTOMATION SOURCE PACK:\n" + "\n\n".join(blocks)
    return "\n\n".join(part for part in (country_fact_pack, controlled_pack, curated) if part)


def country_specific_fact_pack(country: str | None, domain: str) -> str:
    """Hard-code only externally traceable country facts; use as citations, not metadata."""
    if not country or domain != "ai_workflow_automation":
        return ""
    country_l = country.strip().lower()
    if country_l != "united kingdom":
        return ""
    facts = [
        {
            "title": "DBT Business population estimates for the UK and regions 2025",
            "summary": (
                "The UK had 5.64 million private-sector businesses at the start of 2025; small businesses "
                "with 0-49 employees were 99.2% of the private-sector business population. Use this as the "
                "upper UK SMB universe before filtering for software maturity, recurring digital workflows, "
                "and willingness to pay."
            ),
            "url": "https://www.gov.uk/government/statistics/business-population-estimates-2025/business-population-estimates-for-the-uk-and-regions-2025-statistical-release",
        },
        {
            "title": "ONS Business demography, UK: 2024",
            "summary": (
                "ONS reported approximately 2.9 million active UK businesses in 2024, down by about 11,000 "
                "from 2023. Use this as the registered/active-business denominator, not as the full private-sector "
                "SMB universe."
            ),
            "url": "https://www.ons.gov.uk/businessindustryandtrade/business/activitysizeandlocation/bulletins/businessdemography/latest",
        },
        {
            "title": "ONS UK business; activity, size and location: 2025",
            "summary": (
                "ONS reported 2.73 million UK VAT/PAYE-registered businesses as of March 2025 and 3.2 million "
                "local units. Professional, scientific and technical activities accounted for the largest share "
                "of registered businesses at 15.3%, making it a priority segment for UK B2B workflow automation."
            ),
            "url": "https://www.ons.gov.uk/businessindustryandtrade/business/activitysizeandlocation/bulletins/ukbusinessactivitysizeandlocation/latest",
        },
        {
            "title": "FCA data and publications",
            "summary": (
                "FCA datasets and publications are relevant only for regulated financial-services workflows. "
                "For general AI workflow SaaS, FCA data is a compliance context, not a source for total SMB TAM."
            ),
            "url": "https://www.fca.org.uk/data",
        },
    ]
    blocks = []
    for item in facts:
        blocks.append(
            "[VERIFIED | UK AI WORKFLOW COUNTRY FACT | confidence 90%]\n"
            f"Title: {item['title']}\n"
            f"Summary: {item['summary']}\n"
            f"Source: {item['url']}"
        )
    return "UK-SPECIFIC AI WORKFLOW EVIDENCE PACK:\n" + "\n\n".join(blocks)


def relevant_to_ai_workflow(text: str) -> bool:
    low = text.lower()
    return any(term in low for term in AI_AUTOMATION_TERMS)


def relevant_to_agriculture(text: str) -> bool:
    low = text.lower()
    return any(term in low for term in AGRICULTURE_TERMS) or any(
        term in low for term in ("ministry of agriculture", "apeda", "nabard", "icar", "faostat", "agmarknet")
    )


def relevant_to_fashion(text: str) -> bool:
    low = text.lower()
    return any(term in low for term in FASHION_TERMS) or any(term in low for term in FASHION_SOURCE_TERMS)


def relevant_to_water_environment(text: str) -> bool:
    low = text.lower()
    return any(term in low for term in ("water", "wastewater", "effluent", "sewage", "desalination", "filtration", "pollution control", "treatment plant"))


def contains_domain_term(text: str, term: str) -> bool:
    low = str(text or "").lower()
    needle = str(term or "").lower().strip()
    if not needle:
        return False
    if " " in needle or "_" in needle or "/" in needle or "-" in needle:
        return needle in low
    return re.search(rf"(?<![a-z0-9]){re.escape(needle)}(?![a-z0-9])", low) is not None


