def record_domain_confidence(record: dict, domain: str, topic: str = "", industry: str = "") -> float:
    if domain == "general_market":
        return 1.0
    haystack = record_text_blob(record).lower()
    tags = " ".join(str(t).lower() for t in record.get("topic_tags", []))
    family = str(record.get("source_family", "")).lower()
    if is_metadata_only_evidence(record):
        return 0.0
    if family in DOMAIN_BLOCKED_SOURCE_FAMILIES.get(domain, set()):
        return 0.0
    crm_positive_terms = (
        "crm", "customer relationship management", "sales automation",
        "lead management", "pipeline management", "sales funnel",
        "customer support automation", "hubspot", "salesforce", "zoho crm",
        "freshsales", "pipedrive", "revops", "revenue operations",
        "sales ops", "sales enablement", "outbound automation", "lead enrichment",
        "sales workflow", "smb", "small business", "saas", "subscription software",
        "workflow software", "business software", "enterprise software",
        "cloud software", "automation platform",
    )
    positives = DOMAIN_POSITIVE_TERMS.get(domain, crm_positive_terms if domain in {"crm_automation", "b2b_saas", "revops_sales_automation"} else ())
    positive_hits = [term for term in positives if contains_domain_term(haystack, term) or contains_domain_term(tags, term)]
    forbidden_hits = [term for term in DOMAIN_FORBIDDEN_TERMS.get(domain, ()) if contains_domain_term(haystack, term)]
    core_terms = DOMAIN_CORE_SIGNAL_TERMS.get(domain, ())
    has_core_signal = any(contains_domain_term(haystack, term) or contains_domain_term(tags, term) for term in core_terms)
    if domain in {"crm_automation", "b2b_saas", "revops_sales_automation"} and family == "academic_research":
        explicit_crm_related = any(
            contains_domain_term(haystack, term) or contains_domain_term(tags, term)
            for term in crm_positive_terms[:19]
        )
        if not explicit_crm_related:
            return 0.0
    if domain == "ai_workflow_automation":
        if forbidden_hits and not has_core_signal:
            return 0.0
        if family == "official_survey" and not has_core_signal:
            return 0.0
    if forbidden_hits and len(positive_hits) < 2 and family not in DOMAIN_STRONG_SOURCE_FAMILIES.get(domain, set()):
        return 0.0

    score = min(0.85, 0.16 * len(set(positive_hits)))
    if domain in tags or domain in haystack:
        score = max(score, 0.55)
    if family in DOMAIN_STRONG_SOURCE_FAMILIES.get(domain, set()):
        score += 0.35
    if record_matches_topic_tokens(record, topic, industry):
        score += 0.15
    neutral_official_tags = (
        "country_denominator", "macro_baseline", "business_formation",
        "digital_readiness", "market_sizing", "official_statistics",
    )
    if (
        family in {"government_data", "official_financial_data", "official_survey"}
        and any(tag in tags or tag in haystack for tag in neutral_official_tags)
        and not forbidden_hits
    ):
        score = max(score, 0.42)
    if forbidden_hits:
        score -= 0.35
    return max(0.0, min(1.0, score))


try:
    from iidatech.validation.relevance_gate import register_domain_helpers

    register_domain_helpers(classify_topic_domain, record_domain_confidence)
except Exception:
    pass


def record_matches_topic_tokens(record: dict, topic: str, industry: str) -> bool:
    tokens = relevant_topic_tokens(topic, industry, "")
    if not tokens:
        return False
    haystack = record_text_blob(record).lower()
    return any(token in haystack for token in tokens)


def record_matches_domain(record: dict, domain: str) -> bool:
    haystack = " ".join(
        str(record.get(field, ""))
        for field in ("title", "publisher", "source_family", "geography", "metric_name", "topic_tags", "text")
    ).lower()
    if domain == "agriculture":
        return any(term in haystack for term in AGRICULTURE_TERMS) or any(
            term in haystack for term in ("apeda", "nabard", "agmarknet", "ministry_agriculture", "icar", "faostat")
        )
    if domain == "fashion":
        return any(term in haystack for term in FASHION_TERMS) or any(term in haystack for term in FASHION_SOURCE_TERMS)
    if domain == "ai_workflow_automation":
        return relevant_to_ai_workflow(haystack) or "ai_workflow_automation" in haystack
    if domain == "healthcare":
        return record_domain_confidence(record, domain) >= 0.25
    if domain == "finance":
        return record_domain_confidence(record, domain) >= 0.25
    if domain == "energy":
        return any(term in haystack for term in ("energy", "grid", "solar", "wind", "battery", "iea", "eia"))
    if domain == "water_environment":
        return relevant_to_water_environment(haystack)
    if domain in DOMAIN_POSITIVE_TERMS:
        return any(contains_domain_term(haystack, term) for term in DOMAIN_POSITIVE_TERMS.get(domain, ()))
    return True


def record_text_blob(record: dict) -> str:
    return " ".join(
        str(record.get(field, ""))
        for field in ("title", "publisher", "source_family", "geography", "metric_name", "metric_value", "unit", "topic_tags", "text")
    )


def is_metadata_only_evidence(record: dict) -> bool:
    family = str(record.get("source_family", "")).lower()
    if family in {
        "country_industry_pack",
        "country_pack_official_profile",
        "country_databank_source",
        "country_industry_policy_route",
        "country_industry_financial_route",
        "country_news_route",
        "global_master_source_route",
        "global_master_regulator_route",
        "global_master_url_health",
        "ai_saas_funding_gap",
        "statista_public_metadata",
        "government_context",
    }:
        return True
    if strict_is_metadata_or_route is not None:
        try:
            if strict_is_metadata_or_route(record):
                return True
        except Exception:
            pass
    blob = record_text_blob(record).lower()
    return any(
        phrase in blob
        for phrase in (
            "metadata only",
            "transcript unavailable",
            "episode notes only",
            "needs ocr/transcription",
        )
    )


def is_verified_existing_survey_record(record: dict) -> bool:
    family = str(record.get("source_family", "")).lower()
    if is_metadata_only_evidence(record):
        return False
    if family in {"official_survey", "healthcare_primary_survey"}:
        return True
    if family == "government_data":
        blob = record_text_blob(record).lower()
        return any(term in blob for term in ("survey", "btos", "business trends and outlook", "respondents", "responses"))
    return False


def topic_match_detail(record: dict, topic: str, industry: str, target: str) -> dict:
    haystack = record_text_blob(record).lower()
    tokens = relevant_topic_tokens(topic, industry, target)
    matched = sorted({token for token in tokens if token and token in haystack})
    score = min(1.0, len(matched) / max(4, min(10, len(tokens) or 1)))
    domain = classify_topic_domain(topic, industry)
    try:
        from iidatech.validation.relevance_gate import is_record_relevant_to_report

        report_relevant, report_relevance_reason = is_record_relevant_to_report(
            record, topic, industry, domain
        )
    except Exception:
        report_relevant, report_relevance_reason = True, "gate_unavailable"
    return {
        "score": round(score, 2),
        "matched_terms": matched[:12],
        "token_count": len(tokens),
        "report_relevant": report_relevant,
        "report_relevance_reason": report_relevance_reason,
    }


@st.cache_data(show_spinner=False, ttl=60)
def load_market_dataset_records(
    limit: int | None = None,
    *,
    topic: str = "",
    industry: str = "",
) -> list[dict]:
    limit = int(limit or MARKET_RECORD_LIMIT)
    records = []
    seen_ids: set[str] = set()

    def add_record(record: dict) -> bool:
        if not isinstance(record, dict):
            return False
        rid = str(record.get("id") or "").strip()
        if not rid:
            rid = hashlib.sha1(json.dumps(record, sort_keys=True, default=str).encode("utf-8", errors="ignore")).hexdigest()[:18]
            record["id"] = rid
        if rid in seen_ids:
            return False
        seen_ids.add(rid)
        records.append(record)
        return True

    if load_financial_market_records is not None:
        try:
            for record in load_financial_market_records(limit=min(1200, limit)):
                add_record(record)
                if len(records) >= limit:
                    return _filter_loader_records_by_report_gate(records, topic, industry)
        except Exception:
            pass

    paths = []
    if PRIMARY_INTERVIEW_JSONL_PATH.exists():
        paths.append(PRIMARY_INTERVIEW_JSONL_PATH)
    if FINANCIAL_EVIDENCE_JSONL_PATH.exists():
        paths.append(FINANCIAL_EVIDENCE_JSONL_PATH)
    if LEARNED_TOPIC_JSONL_PATH is not None and LEARNED_TOPIC_JSONL_PATH.exists():
        paths.append(LEARNED_TOPIC_JSONL_PATH)
    if MARKET_JSONL_PATH is not None and MARKET_JSONL_PATH.exists():
        paths.append(MARKET_JSONL_PATH)
    for path in paths:
        try:
            source_lines = path.read_text(encoding="utf-8-sig", errors="ignore").splitlines()
        except Exception:
            continue
        for line in source_lines:
            clean_line = line.strip().lstrip("\ufeff")
            if not clean_line:
                continue
            try:
                row = json.loads(clean_line)
            except Exception:
                continue
            if path == LEARNED_TOPIC_JSONL_PATH:
                try:
                    from iidatech.validation.competitor_relevance import should_index_learned_competitor_record

                    if not should_index_learned_competitor_record(row):
                        continue
                except Exception:
                    pass
            if not add_record(row):
                continue
            if len(records) >= limit:
                return _filter_loader_records_by_report_gate(records, topic, industry)
    return _filter_loader_records_by_report_gate(records, topic, industry)


def _filter_loader_records_by_report_gate(
    records: list[dict],
    topic: str = "",
    industry: str = "",
) -> list[dict]:
    if not str(topic or "").strip():
        return records
    try:
        from iidatech.validation.relevance_gate import is_record_relevant_to_report

        domain = classify_topic_domain(topic, industry)
        return [
            record
            for record in records
            if isinstance(record, dict)
            and is_record_relevant_to_report(record, topic, industry, domain)[0]
        ]
    except Exception:
        return records


def append_primary_interview_record(
    topic_text: str,
    industry_text: str,
    geography_text: str,
    respondent_role: str,
    company_context: str,
    notes: str,
) -> Path:
    PRIMARY_INTERVIEW_JSONL_PATH.parent.mkdir(parents=True, exist_ok=True)
    stamp = datetime.utcnow().isoformat() + "Z"
    compact_notes = re.sub(r"\s+", " ", notes.strip())[:3000]
    record = {
        "id": "primary_"
        + hashlib.sha1(
            (topic_text + geography_text + respondent_role + compact_notes + stamp).encode("utf-8", errors="ignore")
        ).hexdigest()[:16],
        "source_family": "primary_interview",
        "publisher": "User-provided primary interview",
        "title": f"Completed buyer/operator interview: {respondent_role.strip() or 'respondent'}",
        "url": "internal://primary-interviews/user-provided",
        "retrieved_at": stamp,
        "geography": geography_text.strip() or "Configurable",
        "year": stamp[:4],
        "metric_name": "Completed primary interview",
        "metric_value": "1 completed interview note",
        "unit": "interview",
        "topic_tags": [
            "primary_interview",
            "primary_research",
            "interview",
            "buyer_behavior",
            "go_to_market",
            "retention",
            classify_topic_domain(topic_text, industry_text),
        ],
        "text": (
            f"Completed primary interview for topic '{topic_text}' in {geography_text}. "
            f"Respondent role: {respondent_role}. Company/context: {company_context}. "
            f"Notes: {compact_notes}"
        ),
        "confidence": 0.92,
    }
    with PRIMARY_INTERVIEW_JSONL_PATH.open("a", encoding="utf-8") as f:
        f.write(json.dumps(record, ensure_ascii=False) + "\n")
    return PRIMARY_INTERVIEW_JSONL_PATH


def append_uploaded_buyer_evidence_records(
    topic_text: str,
    industry_text: str,
    geography_text: str,
    uploaded_name: str,
    raw_bytes: bytes,
) -> tuple[Path, int]:
    PRIMARY_INTERVIEW_JSONL_PATH.parent.mkdir(parents=True, exist_ok=True)
    stamp = datetime.utcnow().isoformat() + "Z"
    decoded = raw_bytes.decode("utf-8-sig", errors="ignore")
    extension = Path(uploaded_name or "").suffix.lower()
    rows: list[dict] = []
    if extension == ".csv":
        rows = [dict(row) for row in csv.DictReader(io.StringIO(decoded)) if any((v or "").strip() for v in row.values())]
    elif extension == ".jsonl":
        for line in decoded.splitlines():
            if not line.strip():
                continue
            try:
                obj = json.loads(line)
                rows.append(obj if isinstance(obj, dict) else {"text": str(obj)})
            except Exception:
                rows.append({"text": line})
    elif extension == ".json":
        try:
            parsed = json.loads(decoded)
            if isinstance(parsed, list):
                rows = [item if isinstance(item, dict) else {"text": str(item)} for item in parsed]
            elif isinstance(parsed, dict):
                inner = parsed.get("records") or parsed.get("responses") or parsed.get("interviews") or parsed.get("surveys")
                if isinstance(inner, list):
                    rows = [item if isinstance(item, dict) else {"text": str(item)} for item in inner]
                else:
                    rows = [parsed]
            else:
                rows = [{"text": str(parsed)}]
        except Exception:
            rows = [{"text": decoded}]
    else:
        chunks = [part.strip() for part in re.split(r"\n\s*\n", decoded) if part.strip()]
        rows = [{"text": chunk} for chunk in chunks[:80]]

    domain = classify_topic_domain(topic_text, industry_text)

    def first_value(row: dict, *keys: str) -> str:
        lower_map = {str(k).strip().lower(): v for k, v in row.items()}
        for key in keys:
            if key in row and str(row.get(key, "")).strip():
                return str(row.get(key, "")).strip()
            low_key = key.lower()
            if low_key in lower_map and str(lower_map.get(low_key, "")).strip():
                return str(lower_map.get(low_key, "")).strip()
        return ""

    records = []
    for idx, row in enumerate(rows[:500], start=1):
        if not isinstance(row, dict):
            row = {"text": str(row)}
        source_url = first_value(row, "source_url", "url", "link", "source")
        publisher = first_value(row, "publisher", "source_name", "platform", "channel", "organization")
        respondent = first_value(row, "respondent", "respondent_role", "role", "buyer_type", "persona")
        sample_size = first_value(row, "sample_size", "n", "respondents", "survey_n")
        quote = first_value(row, "quote", "excerpt", "as_quoted", "verbatim")
        finding = first_value(row, "finding", "notes", "response", "text", "summary", "insight")
        if not (quote or finding):
            continue
        row_text = re.sub(r"\s+", " ", f"{quote} {finding}".strip())[:4000]
        is_survey = bool(sample_size) or any(word in f"{publisher} {finding}".lower() for word in ("survey", "poll", "respondents", "sample"))
        source_family = "user_uploaded_survey" if is_survey else "user_uploaded_interview"
        record = {
            "id": "uploaded_buyer_"
            + hashlib.sha1((uploaded_name + str(idx) + row_text + stamp).encode("utf-8", errors="ignore")).hexdigest()[:16],
            "source_family": source_family,
            "publisher": publisher or ("User-uploaded survey" if is_survey else "User-uploaded buyer/operator evidence"),
            "title": first_value(row, "title", "survey_name", "interview_title")
            or f"{'Survey' if is_survey else 'Interview'} evidence from {uploaded_name}",
            "url": source_url or f"internal://uploaded-buyer-evidence/{safe_filename(uploaded_name)}",
            "retrieved_at": stamp,
            "geography": first_value(row, "geography", "country", "region", "market") or geography_text.strip() or "Configurable",
            "year": first_value(row, "year", "date", "period")[:4] or stamp[:4],
            "metric_name": "Uploaded buyer/survey evidence",
            "metric_value": sample_size or "qualitative source",
            "unit": "responses" if is_survey else "interview note",
            "topic_tags": [
                "primary_research",
                "buyer_behavior",
                "go_to_market",
                "survey" if is_survey else "interview",
                "retention",
                "pricing",
                domain,
            ],
            "text": (
                f"Uploaded evidence for topic '{topic_text}' in {geography_text}. "
                f"Respondent/source: {respondent or publisher or 'not specified'}. "
                f"Sample size: {sample_size or 'not specified'}. "
                f"Quote/excerpt/finding: {row_text}"
            ),
            "confidence": 0.82 if source_url and is_survey else 0.74 if source_url else 0.64,
            "upload_file": uploaded_name,
            "verification_note": (
                "User-uploaded survey with source context; verify sample, geography, period, and methodology before hard claims."
                if is_survey
                else "User-uploaded buyer/operator evidence; use for qualitative pain, workflow, pricing, and objection signals."
            ),
        }
        records.append(record)

    if records:
        with PRIMARY_INTERVIEW_JSONL_PATH.open("a", encoding="utf-8") as f:
            for record in records:
                f.write(json.dumps(record, ensure_ascii=False) + "\n")
    return PRIMARY_INTERVIEW_JSONL_PATH, len(records)


def append_financial_evidence_record(
    topic_text: str,
    industry_text: str,
    geography_text: str,
    source_family: str,
    publisher: str,
    metric_name: str,
    metric_value: str,
    period: str,
    source_url: str,
    notes: str,
) -> Path:
    FINANCIAL_EVIDENCE_JSONL_PATH.parent.mkdir(parents=True, exist_ok=True)
    stamp = datetime.utcnow().isoformat() + "Z"
    cleaned_family = source_family if source_family in {
        "company_filings",
        "funding_data",
        "valuation_data",
        "company_reports",
        "analyst_report",
        "earnings_transcript",
        "pricing_reference",
        "implementation_benchmark",
        "procurement_cycle_evidence",
    } else "company_reports"
    compact_notes = re.sub(r"\s+", " ", notes.strip())[:3000]
    record = {
        "id": "financial_"
        + hashlib.sha1(
            (
                topic_text
                + geography_text
                + cleaned_family
                + publisher
                + metric_name
                + metric_value
                + period
                + source_url
                + stamp
            ).encode("utf-8", errors="ignore")
        ).hexdigest()[:16],
        "source_family": cleaned_family,
        "publisher": publisher.strip() or "User-provided financial source",
        "title": f"{metric_name.strip() or 'Financial evidence'} - {period.strip() or stamp[:4]}",
        "url": source_url.strip() or "internal://financial-evidence/user-provided",
        "retrieved_at": stamp,
        "geography": geography_text.strip() or "Configurable",
        "year": (period.strip() or stamp[:4])[:4],
        "metric_name": metric_name.strip() or "Financial metric",
        "metric_value": metric_value.strip() or "not specified",
        "unit": "",
        "topic_tags": [
            "financial_evidence",
            "funding",
            "valuation",
            "comparable_company",
            "unit_economics",
            "revenue",
            "market_sizing",
            classify_topic_domain(topic_text, industry_text),
        ],
        "text": (
            f"Financial/comparable evidence for topic '{topic_text}' in {geography_text}. "
            f"Publisher/company: {publisher}. Metric: {metric_name} = {metric_value}. "
            f"Period/source date: {period}. Notes: {compact_notes}"
        ),
        "confidence": 0.9 if cleaned_family in {"company_filings", "valuation_data", "funding_data"} else 0.78,
    }
    with FINANCIAL_EVIDENCE_JSONL_PATH.open("a", encoding="utf-8") as f:
        f.write(json.dumps(record, ensure_ascii=False) + "\n")
    if upsert_financial_record is not None:
        try:
            upsert_financial_record(record, topic=topic_text, industry=industry_text)
            if write_financial_store_summary is not None:
                write_financial_store_summary()
        except Exception:
            pass
    return FINANCIAL_EVIDENCE_JSONL_PATH


def append_manual_diligence_evidence_record(
    topic_text: str,
    industry_text: str,
    geography_text: str,
    evidence_type: str,
    publisher: str,
    title: str,
    metric_name: str,
    metric_value: str,
    source_url: str,
    notes: str,
) -> Path:
    if LearnedRecord is None or append_learned_records is None or LEARNED_TOPIC_JSONL_PATH is None:
        raise RuntimeError("Learned evidence store is unavailable.")
    stamp = datetime.utcnow().isoformat() + "Z"
    evidence_type_clean = re.sub(r"[^a-z0-9_]+", "_", evidence_type.lower()).strip("_")
    source_family_by_type = {
        "buyer_interview_or_proxy_survey": "user_uploaded_interview",
        "supplier_quote_or_input_cost": "pricing_reference",
        "pricing_page_or_package_benchmark": "pricing_reference",
        "transaction_tender_or_booking_evidence": "procurement_data",
        "competitor_operator_benchmark": "local_operator_listing",
    }
    claim_type_by_type = {
        "buyer_interview_or_proxy_survey": "buyer_voice",
        "supplier_quote_or_input_cost": "pricing",
        "pricing_page_or_package_benchmark": "pricing",
        "transaction_tender_or_booking_evidence": "procurement_demand",
        "competitor_operator_benchmark": "competitor",
    }
    allowed_use_by_type = {
        "buyer_interview_or_proxy_survey": "Use for buyer pain, workflow, objections, willingness-to-pay, and GTM hypotheses; do not use alone for TAM or revenue proof.",
        "supplier_quote_or_input_cost": "Use for unit-cost and COGS modeling when SKU/package, unit, currency, geography, source date, and supplier are cited.",
        "pricing_page_or_package_benchmark": "Use for bottom-up pricing and package benchmarking when offer scope, unit, currency, geography, and source date are cited.",
        "transaction_tender_or_booking_evidence": "Use as demand evidence; distinguish open tender/listing from awarded spend or completed bookings.",
        "competitor_operator_benchmark": "Use for named competitor/operator mapping, positioning, price comparison, and substitute analysis; do not infer market share alone.",
    }
    source_family = source_family_by_type.get(evidence_type_clean, "pricing_reference")
    claim_type = claim_type_by_type.get(evidence_type_clean, "context")
    compact_notes = re.sub(r"\s+", " ", notes.strip())[:3500]
    record = LearnedRecord(
        id="manual_diligence_"
        + hashlib.sha1(
            (
                topic_text
                + geography_text
                + evidence_type_clean
                + publisher
                + title
                + metric_name
                + metric_value
                + source_url
                + compact_notes
                + stamp
            ).encode("utf-8", errors="ignore")
        ).hexdigest()[:16],
        source_family=source_family,
        publisher=publisher.strip() or "User-provided diligence source",
        title=title.strip() or humanize_label(evidence_type_clean),
        url=source_url.strip() or f"internal://manual-diligence/{evidence_type_clean}",
        retrieved_at=stamp,
        geography=geography_text.strip() or "Configurable",
        year=stamp[:4],
        metric_name=metric_name.strip() or humanize_label(evidence_type_clean),
        metric_value=metric_value.strip() or "qualitative evidence",
        unit="source",
        topic_tags=[
            "manual_diligence_evidence",
            evidence_type_clean,
            claim_type,
            classify_topic_domain(topic_text, industry_text),
        ],
        text=(
            f"Manual funding diligence evidence for topic '{topic_text}' in {geography_text}. "
            f"Evidence type: {humanize_label(evidence_type_clean)}. "
            f"Publisher/source: {publisher}. Title: {title}. Metric: {metric_name} = {metric_value}. "
            f"Notes/excerpt/derivation: {compact_notes}"
        ),
        confidence=0.86 if source_url.strip() else 0.7,
        country=geography_text.strip(),
        industry=industry_text.strip(),
        claim_type=claim_type,
        evidence_tier="user_supplied_source_backed" if source_url.strip() else "user_supplied_needs_source_check",
        allowed_use=allowed_use_by_type.get(evidence_type_clean, "Use only with visible source and section-specific verification."),
    )
    append_learned_records([record])
    return LEARNED_TOPIC_JSONL_PATH


@st.cache_data(show_spinner=False, ttl=60)
def market_dataset_summary() -> dict:
    if MARKET_SUMMARY_PATH is None or not MARKET_SUMMARY_PATH.exists():
        return {}
    try:
        summary = json.loads(MARKET_SUMMARY_PATH.read_text(encoding="utf-8", errors="ignore"))
        if financial_store_summary is not None:
            try:
                summary["financial_sqlite_store"] = financial_store_summary()
            except Exception:
                pass
        for user_path in (PRIMARY_INTERVIEW_JSONL_PATH, FINANCIAL_EVIDENCE_JSONL_PATH):
            if not user_path.exists():
                continue
            user_records = []
            for line in user_path.read_text(encoding="utf-8", errors="ignore").splitlines():
                if not line.strip():
                    continue
                try:
                    user_records.append(json.loads(line))
                except Exception:
                    continue
            if user_records:
                summary["record_count"] = int(summary.get("record_count", 0) or 0) + len(user_records)
                by_family = summary.setdefault("by_source_family", {})
                for record in user_records:
                    family = str(record.get("source_family", "user_evidence"))
                    by_family[family] = int(by_family.get(family, 0) or 0) + 1
        if learned_topic_summary is not None:
            learned_summary = learned_topic_summary() or {}
            learned_count = int(learned_summary.get("record_count", 0) or 0)
            if learned_count:
                summary["record_count"] = int(summary.get("record_count", 0) or 0) + learned_count
                summary["learned_topic_research"] = learned_summary
                by_family = summary.setdefault("by_source_family", {})
                for family, count in (learned_summary.get("by_source_family", {}) or {}).items():
                    by_family[family] = int(by_family.get(family, 0) or 0) + int(count or 0)
        if FINANCIAL_MODEL_BANK_SUMMARY_PATH is not None and FINANCIAL_MODEL_BANK_SUMMARY_PATH.exists():
            model_summary = json.loads(FINANCIAL_MODEL_BANK_SUMMARY_PATH.read_text(encoding="utf-8", errors="ignore"))
            model_count = int(model_summary.get("record_count", 0) or 0)
            if model_count:
                summary["record_count"] = int(summary.get("record_count", 0) or 0) + model_count
                by_family = summary.setdefault("by_source_family", {})
                by_family["iidatech_2026_financial_model_bank"] = int(by_family.get("iidatech_2026_financial_model_bank", 0) or 0) + model_count
        return summary
    except Exception:
        return {}


