def active_pack_for_industry_domain(industry: str, domain: str, topic: str = "") -> dict:
    if not INDUSTRY_PACK_CATALOG:
        return {}
    industry_l = str(industry or "").strip().lower()
    topic_l = str(topic or "").strip().lower()
    query_blob = f"{topic_l} {industry_l}".strip()
    domain_l = str(domain or "").strip().lower()
    active = [row for row in INDUSTRY_PACK_CATALOG if row.get("status") == "active"]
    for row in active:
        if str(row.get("industry", "")).strip().lower() == industry_l:
            return row
    for row in active:
        if str(row.get("pack_id", "")).strip().lower() == industry_l:
            return row
    scored: list[tuple[int, dict]] = []
    query_terms = {term for term in re.split(r"[^a-z0-9]+", query_blob) if len(term) >= 3}
    for row in active:
        if str(row.get("domain", "")).strip().lower() != domain_l:
            continue
        pack_blob = " ".join(
            str(row.get(field, ""))
            for field in ("pack_id", "industry", "test_prompt")
        ).lower()
        pack_terms = {term for term in re.split(r"[^a-z0-9]+", pack_blob) if len(term) >= 3}
        score = len(query_terms.intersection(pack_terms))
        if score:
            scored.append((score, row))
    if scored:
        return sorted(scored, key=lambda item: item[0], reverse=True)[0][1]
    for row in active:
        if str(row.get("domain", "")).strip().lower() == domain_l:
            return row
    return {}


@st.cache_data(show_spinner=False, ttl=60)
def load_country_dataset_records(limit: int | None = None) -> list[dict]:
    limit = int(limit or COUNTRY_RECORD_LIMIT)
    if COUNTRY_JSONL_PATH is None or not COUNTRY_JSONL_PATH.exists():
        return []
    records: list[dict] = []
    try:
        source_lines = COUNTRY_JSONL_PATH.read_text(encoding="utf-8-sig", errors="ignore").splitlines()
        for line in source_lines:
            clean_line = line.strip().lstrip("\ufeff")
            if not clean_line:
                continue
            try:
                records.append(json.loads(clean_line))
            except Exception:
                continue
            if len(records) >= limit:
                break
    except Exception:
        return []
    return records


@st.cache_data(show_spinner=False, ttl=60)
def load_user_added_records(limit: int = 2000) -> list[dict]:
    records: list[dict] = []
    for path in (PRIMARY_INTERVIEW_JSONL_PATH, FINANCIAL_EVIDENCE_JSONL_PATH):
        if not path.exists():
            continue
        try:
            for line in path.read_text(encoding="utf-8", errors="ignore").splitlines():
                if not line.strip():
                    continue
                records.append(json.loads(line))
                if len(records) >= limit:
                    return records
        except Exception:
            continue
    return records


def is_country_specific_target(target: str) -> bool:
    if country_options is None:
        return False
    return target.strip().lower() in {country.lower() for country in country_options()}


def load_financial_model_bank_records() -> list[dict]:
    """Load stored 2026 estimated TAM/SAM/SOM and operating-model records."""
    if load_2026_financial_model_bank is None:
        return []
    try:
        return load_2026_financial_model_bank()
    except Exception:
        return []


def synthetic_hard_isolation_enabled() -> bool:
    return os.getenv("IIDATECH_SYNTHETIC_HARD_ISOLATION", "1") == "1"


def _is_synthetic_record(record: dict) -> bool:
    return (
        record.get("evidence_namespace") == "synthetic_model"
        or record.get("source_type") == "synthetic_model"
        or "financial_model_bank" in str(record.get("source_file", "")).lower()
        or str(record.get("url", "")).startswith("internal://")
    )


def load_real_evidence_records_for_target(target: str) -> list[dict]:
    user_records = load_user_added_records()
    if is_country_specific_target(target):
        return load_country_dataset_records() + load_market_dataset_records() + user_records
    return load_market_dataset_records() + user_records


def load_synthetic_planning_records_for_target(_target: str) -> list[dict]:
    return load_financial_model_bank_records()


def load_records_for_target(target: str, *, topic: str = "", industry: str = "") -> list[dict]:
    if synthetic_hard_isolation_enabled():
        records = load_real_evidence_records_for_target(target)
        return _filter_loader_records_by_report_gate(records, topic, industry)
    model_bank_records = load_financial_model_bank_records()
    user_records = load_user_added_records()
    if is_country_specific_target(target):
        records = load_country_dataset_records() + load_market_dataset_records(topic=topic, industry=industry) + model_bank_records + user_records
    else:
        records = load_market_dataset_records(topic=topic, industry=industry) + model_bank_records + user_records
    return _filter_loader_records_by_report_gate(records, topic, industry)


