def target_record_filter(records: list[dict], target: str) -> list[dict]:
    if not is_country_specific_target(target):
        return records
    target_l = target.strip().lower()
    filtered = []
    for record in records:
        geography = str(record.get("geography", "")).lower()
        family = str(record.get("source_family", "")).lower()
        if target_l in geography:
            filtered.append(record)
            continue
        if (geography in {"global", "world", "worldwide", "configurable"} or "global" in geography) and family in BENCHMARK_PROXY_FAMILIES:
            proxy = dict(record)
            proxy["proxy_geography_for"] = target
            filtered.append(proxy)
    return filtered


