def source_readiness_has_number(record: dict) -> bool:
    surface = " ".join(
        str(record.get(field, ""))
        for field in ("metric_name", "metric_value", "unit", "title", "text")
    )
    return bool(re.search(r"\d", surface))


def source_readiness_is_internal_or_synthetic(record: dict) -> bool:
    family = str(record.get("source_family", "")).lower()
    url = str(record.get("url", "")).lower()
    return family in SOURCE_READINESS_INTERNAL_FAMILIES or url.startswith("internal://")


def source_readiness_is_generic_country_denominator(record: dict) -> bool:
    family = str(record.get("source_family", "")).lower()
    if family in {"country_denominator", "macro_baseline", "business_formation", "government_context"}:
        return True
    surface = " ".join(
        str(record.get(field, "")).lower()
        for field in ("title", "metric_name", "unit", "topic_tags")
    )
    return any(term in surface for term in SOURCE_READINESS_GENERIC_COUNTRY_METRICS)


def source_readiness_target_is_global(target: str) -> bool:
    return str(target or "").strip().lower() in {"global", "world", "worldwide", "international"}


def source_readiness_region_member_countries(target: str) -> set[str]:
    target_l = str(target or "").strip().lower()
    direct = set()
    if COUNTRY_CATALOG is not None:
        try:
            direct = {
                str(row.get("country", ""))
                for row in COUNTRY_CATALOG
                if str(row.get("region", "")).strip().lower() == target_l
            }
        except Exception:
            direct = set()
    aliases = {
        "asean": {"Singapore", "Malaysia", "Indonesia", "Thailand", "Vietnam", "Philippines"},
        "south asia": {"India"},
        "gcc": {"Saudi Arabia", "United Arab Emirates", "Qatar", "Kuwait"},
        "middle east": {"Saudi Arabia", "United Arab Emirates", "Qatar", "Kuwait", "Israel", "Turkey"},
        "latin america": {"Brazil", "Mexico", "Argentina", "Chile", "Colombia"},
        "south america": {"Brazil", "Argentina", "Chile", "Colombia"},
        "north america": {"United States", "Canada", "Mexico"},
        "africa": {"South Africa", "Nigeria", "Kenya", "Egypt"},
        "africa / middle east": {"South Africa", "Nigeria", "Kenya", "Egypt", "Saudi Arabia", "United Arab Emirates", "Qatar", "Kuwait", "Israel", "Turkey"},
        "middle east / europe": {"Saudi Arabia", "United Arab Emirates", "Qatar", "Kuwait", "Israel", "Turkey"},
        "asia-pacific": {"Australia", "New Zealand", "Japan", "China", "Singapore", "Malaysia", "Indonesia", "Thailand", "Vietnam", "Philippines", "South Korea", "Taiwan", "India"},
        "europe": {"United Kingdom", "Germany", "France", "Ireland", "Netherlands", "Spain", "Italy", "Sweden", "Poland"},
        "european union": {"Germany", "France", "Ireland", "Netherlands", "Spain", "Italy", "Sweden", "Poland"},
    }
    return direct | aliases.get(target_l, set())


def source_readiness_record_matches_target_scope(record: dict, target: str) -> bool:
    if record.get("proxy_geography_for"):
        return False
    target_l = str(target or "").strip().lower()
    geo = str(record.get("geography", "")).lower()
    if not target_l:
        return False
    if is_country_specific_target(target):
        return target_l in geo
    if source_readiness_target_is_global(target):
        return geo in {"global", "world", "worldwide", "international"} or "global" in geo or "worldwide" in geo
    members = {country.lower() for country in source_readiness_region_member_countries(target)}
    return target_l in geo or any(country in geo for country in members)


def source_readiness_is_qualitative(record: dict) -> bool:
    if is_metadata_only_evidence(record) or source_readiness_is_internal_or_synthetic(record):
        return False
    if is_verified_existing_survey_record(record):
        return True
    roles = {str(role).lower() for role in (record.get("roles", []) or [])}
    if roles.intersection({"buyer_or_practitioner_voice", "verified_survey", "competitor_signal", "operator_signal"}):
        return True
    family = str(record.get("source_family", "")).lower()
    unit = str(record.get("unit", "")).lower()
    if unit in {"buyer_pain", "buyer_voice"} or str(record.get("record_type", "")).lower() == "buyer_pain":
        return True
    if family in {"buyer_signal"}:
        return True
    if family in SOURCE_READINESS_QUALITATIVE_FAMILIES:
        return True
    tags = " ".join(str(tag).lower() for tag in record.get("topic_tags", []))
    return family in {"implementation_benchmark", "industry_trend_data", "analyst_report"} and any(
        tag in tags for tag in ("survey", "published_voice", "buyer_behavior", "operator", "practitioner", "retention", "churn")
    )


SOURCE_READINESS_STOP_TOPIC_TERMS = {
    "business", "service", "services", "market", "markets", "india", "indian", "global",
    "local", "premium", "luxury", "small", "large", "new", "online", "platform",
}


def source_readiness_topic_terms(topic: str, industry: str = "") -> list[str]:
    surface = f"{topic} {industry}".lower()
    return [
        token for token in re.findall(r"[a-z0-9][a-z0-9&+.-]{2,}", surface)
        if len(token) >= 4 and token not in SOURCE_READINESS_STOP_TOPIC_TERMS
    ]


def source_readiness_topic_match_count(record: dict, topic: str, industry: str = "") -> int:
    haystack = record_text_blob(record).lower()
    return sum(1 for term in source_readiness_topic_terms(topic, industry) if term in haystack)


def source_readiness_has_commercial_topic_fit(record: dict, topic: str, industry: str = "", minimum: int = 2) -> bool:
    topic_terms = source_readiness_topic_terms(topic, industry)
    if not topic_terms:
        return True
    return source_readiness_topic_match_count(record, topic, industry) >= min(minimum, max(1, len(topic_terms)))


def source_readiness_is_strict_buyer_validation_record(record: dict, topic: str, industry: str, target: str, domain: str) -> bool:
    if (
        is_metadata_only_evidence(record)
        or source_readiness_is_internal_or_synthetic(record)
        or source_readiness_is_generic_country_denominator(record)
        or not source_readiness_record_matches_target_scope(record, target)
        or record_domain_confidence(record, domain, topic, industry) < 0.50
        or not source_readiness_has_commercial_topic_fit(record, topic, industry, minimum=2)
    ):
        return False
    family = str(record.get("source_family", "")).lower()
    strict_family = family in {
        "official_survey",
        "primary_interview",
        "reddit_practitioner",
        "youtube_transcript",
        "podcast_interview",
        "user_uploaded_survey",
        "user_uploaded_interview",
    }
    haystack = record_text_blob(record).lower()
    explicit_validation = any(term in haystack for term in (
        "buyer interview", "operator interview", "customer survey", "dealer survey",
        "distributor call", "respondents", "survey of", "interviewed", "transcript",
        "willingness to pay", "purchase decision", "procurement interview",
    ))
    buyer_context = any(term in haystack for term in (
        "buyer", "customer", "operator", "planner", "venue", "dealer", "distributor",
        "school", "mall", "rwa", "community", "founder", "practitioner", "merchant",
        "procurement", "tenant", "user",
    ))
    if family == "academic_research" and not (explicit_validation and buyer_context):
        return False
    return (strict_family or explicit_validation) and buyer_context


def source_readiness_is_direct_pricing_record(record: dict, topic: str, industry: str, target: str, domain: str) -> bool:
    if (
        is_metadata_only_evidence(record)
        or source_readiness_is_internal_or_synthetic(record)
        or source_readiness_is_generic_country_denominator(record)
        or not source_readiness_record_matches_target_scope(record, target)
        or record_domain_confidence(record, domain, topic, industry) < 0.45
        or not source_readiness_has_commercial_topic_fit(record, topic, industry, minimum=1)
    ):
        if record_trace_enabled():
            trace_record_stage(record, stage="source_readiness_is_direct_pricing_record", accepted=False, rejection_reason="base_gate_failed")
        return False
    family = str(record.get("source_family", "")).lower()
    record_type = str(record.get("record_type") or record.get("claim_type") or "").lower()
    trusted = record_host_is_trusted_research(str(record.get("url", "")), str(record.get("publisher", "")))
    quality_floor = 30 if trusted and family in {"vendor_pricing", "market_reviews", "review_platform", "marketplace_pricing", "app_marketplace", "pricing_reference"} else 40
    quality = int(record.get("quality_score", record.get("confidence", 0) or 0) or 0)
    if quality and quality < quality_floor and family not in {"vendor_pricing", "pricing_reference", "marketplace_pricing", "app_marketplace"}:
        if record_trace_enabled():
            trace_record_stage(record, stage="source_readiness_is_direct_pricing_record", accepted=False, rejection_reason="quality_below_threshold", quality_score=quality)
        return False
    if family in {
        "pricing_reference",
        "marketplace_pricing",
        "app_marketplace",
        "local_operator_listing",
        "procurement_data",
        "procurement_cycle_evidence",
        "company_reports",
        "company_filings",
        "industry_pack_cost",
        "industry_pack_company",
        "vendor_pricing",
        "market_reviews",
        "review_platform",
        "competitor_intelligence",
    } or record_type == "pricing":
        haystack = record_text_blob(record).lower()
        has_price_signal = any(term in haystack for term in (
            "price", "pricing", "fee", "fees", "inr", "rs.", "rs ", "₹", "$", "cost",
            "package", "rental", "quote", "rate", "margin", "gross margin", "per month", "per user",
            "starting at", "/month", "/mo", "monthly",
        )) or bool(record.get("monthly_price") or record.get("annual_price") or record.get("price_value"))
        if has_price_signal:
            if record_trace_enabled():
                trace_record_stage(record, stage="source_readiness_is_direct_pricing_record", accepted=True, detected_record_type="pricing")
            return True
    if record_trace_enabled():
        trace_record_stage(record, stage="source_readiness_is_direct_pricing_record", accepted=False, rejection_reason="pricing_regex_miss")
    return False


def source_readiness_is_named_competitor_record(record: dict, topic: str, industry: str, target: str, domain: str) -> bool:
    if (
        is_metadata_only_evidence(record)
        or source_readiness_is_internal_or_synthetic(record)
        or source_readiness_is_generic_country_denominator(record)
        or not source_readiness_record_matches_target_scope(record, target)
        or record_domain_confidence(record, domain, topic, industry) < 0.45
        or not source_readiness_has_commercial_topic_fit(record, topic, industry, minimum=1)
    ):
        if record_trace_enabled():
            trace_record_stage(record, stage="source_readiness_is_named_competitor_record", accepted=False, rejection_reason="base_gate_failed")
        return False
    family = str(record.get("source_family", "")).lower()
    record_type = str(record.get("record_type") or record.get("claim_type") or "").lower()
    haystack = record_text_blob(record).lower()
    generic_publishers = ("world bank", "unesco", "coursera", "duolingo", "unilever", "amazon.com", "walmart")
    if any(publisher in haystack for publisher in generic_publishers) and source_readiness_topic_match_count(record, topic, industry) < 3:
        if record_trace_enabled():
            trace_record_stage(record, stage="source_readiness_is_named_competitor_record", accepted=False, rejection_reason="topic_mismatch")
        return False
    if domain in _SAAS_GATE_DOMAINS and (
        record_type == "competitor"
        or family in {"competitor_intelligence", "vendor_pricing", "market_reviews", "review_platform", "app_marketplace", "pricing_reference"}
    ) and record_has_named_saas_competitor(record):
        if record_trace_enabled():
            trace_record_stage(record, stage="source_readiness_is_named_competitor_record", accepted=True, detected_record_type="competitor")
        return True
    if domain in {"automotive", "automotive_retail"} and (
        record_type == "competitor"
        or family in {"competitor_intelligence", "local_operator_listing", "review_platform", "market_reviews"}
    ) and record_has_named_automotive_competitor(record):
        if record_trace_enabled():
            trace_record_stage(record, stage="source_readiness_is_named_competitor_record", accepted=True, detected_record_type="competitor")
        return True
    if family in {
        "local_operator_listing",
        "pricing_reference",
        "marketplace_pricing",
        "app_marketplace",
        "review_platform",
        "company_reports",
        "company_filings",
        "industry_pack_company",
        "industry_pack_analyst",
        "funding_data",
        "competitor_intelligence",
        "vendor_pricing",
        "market_reviews",
    } or record_type == "competitor":
        if str(record.get("company") or record.get("entity_name") or "").strip():
            if record_trace_enabled():
                trace_record_stage(record, stage="source_readiness_is_named_competitor_record", accepted=True, detected_record_type="competitor")
            return True
        if any(term in haystack for term in (
            "operator", "vendor", "directory", "listing", "reviews", "rating", "competitor",
            "price", "package", "booking", "decorator", "planner", "supplier", "marketplace",
            "company", "startup", "agency", "provider", "crm", "software", "dealer", "garage", "service center",
        )):
            if record_trace_enabled():
                trace_record_stage(record, stage="source_readiness_is_named_competitor_record", accepted=True, detected_record_type="competitor")
            return True
    if record_trace_enabled():
        trace_record_stage(record, stage="source_readiness_is_named_competitor_record", accepted=False, rejection_reason="competitor_name_missing")
    return False


_SAAS_GATE_DOMAINS = frozenset({
    "crm_automation", "b2b_saas", "revops_sales_automation",
    "ai_workflow_automation", "ai_support_ecommerce", "cybersecurity",
})
_ECOMMERCE_GATE_DOMAINS = frozenset({"ecommerce_retail", "consumer", "fashion"})
_PHYSICAL_GATE_DOMAINS = frozenset({
    "manufacturing", "fashion", "agriculture", "energy", "water_environment",
    "logistics", "automotive", "climate", "hospitality", "consumer",
})
_HEALTHCARE_GATE_DOMAINS = frozenset({
    "healthcare", "dental_saas", "clinic_workflow", "healthcare_admin",
})


def get_industry_gate_profile(domain: str) -> dict:
    """Industry-adaptive strict gate requirements (verification stays on; rules adapt)."""
    domain = (domain or "general_market").lower()
    if domain in _SAAS_GATE_DOMAINS:
        return {
            "profile_id": "saas_software",
            "competitor_requires_location": False,
            "competitor_requires_pricing": True,
            "competitor_requires_reviews_or_usage": True,
            "competitor_requires_product_proof": True,
            "competitor_requires_supplier_quotes": False,
            "competitor_requires_unit_economics": False,
            "competitor_minimum": 3,
            "competitor_gate_label": (
                "3-5 named software competitors with pricing evidence plus reviews, "
                "customer usage, or product/platform proof"
            ),
            "regulatory_min_count": 0,
            "pricing_unit_cost_minimum": 1,
        }
    if domain in _ECOMMERCE_GATE_DOMAINS:
        return {
            "profile_id": "ecommerce_retail",
            "competitor_requires_location": False,
            "competitor_requires_pricing": True,
            "competitor_requires_reviews_or_usage": True,
            "competitor_requires_product_proof": False,
            "competitor_requires_supplier_quotes": False,
            "competitor_requires_unit_economics": False,
            "competitor_minimum": 3,
            "competitor_gate_label": (
                "3-5 named D2C/retail competitors with marketplace or brand pricing plus review signals"
            ),
            "regulatory_min_count": 1,
            "pricing_unit_cost_minimum": 2,
        }
    if domain in _PHYSICAL_GATE_DOMAINS:
        return {
            "profile_id": "physical_product",
            "competitor_requires_location": True,
            "competitor_requires_pricing": True,
            "competitor_requires_reviews_or_usage": True,
            "competitor_requires_product_proof": False,
            "competitor_requires_supplier_quotes": True,
            "competitor_requires_unit_economics": True,
            "competitor_minimum": 3,
            "competitor_gate_label": (
                "3-5 named operators with pricing, location, and supplier/unit-economics signals"
            ),
            "regulatory_min_count": 1,
            "pricing_unit_cost_minimum": 2,
        }
    if domain in _HEALTHCARE_GATE_DOMAINS:
        return {
            "profile_id": "healthcare_regulated",
            "competitor_requires_location": True,
            "competitor_requires_pricing": True,
            "competitor_requires_reviews_or_usage": True,
            "competitor_requires_product_proof": False,
            "competitor_requires_supplier_quotes": False,
            "competitor_requires_unit_economics": False,
            "competitor_minimum": 3,
            "competitor_gate_label": (
                "3-5 named healthcare competitors/operators with pricing, evidence signal, "
                "and regulatory/compliance context where applicable"
            ),
            "regulatory_min_count": 2,
            "pricing_unit_cost_minimum": 2,
        }
    return {
        "profile_id": "general",
        "competitor_requires_location": True,
        "competitor_requires_pricing": True,
        "competitor_requires_reviews_or_usage": True,
        "competitor_requires_product_proof": False,
        "competitor_requires_supplier_quotes": False,
        "competitor_requires_unit_economics": False,
        "competitor_minimum": 3,
        "competitor_gate_label": (
            "3-5 named competitors/operators with pricing, review/listing, and geography fit"
        ),
        "regulatory_min_count": 1,
        "pricing_unit_cost_minimum": 2,
    }


def source_readiness_is_competitor_proof_record(record: dict, topic: str, industry: str, target: str, domain: str) -> bool:
    """Competitor evidence strong enough for market-ready benchmarking (industry-aware)."""
    if not source_readiness_is_named_competitor_record(record, topic, industry, target, domain):
        return False
    profile = get_industry_gate_profile(domain)
    haystack = record_text_blob(record).lower()
    has_pricing = any(term in haystack for term in (
        "price", "pricing", "fee", "fees", "rate", "package", "ticket", "quote", "tariff",
        "subscription", "per seat", "per user", "pricing page",
        "₹", "rs.", "inr", "$", "usd", "eur", "gbp",
    ))
    has_review_or_listing = any(term in haystack for term in (
        "review", "reviews", "rating", "ratings", "stars", "listing", "directory",
        "followers", "instagram", "google maps", "justdial", "indiamart", "capterra", "g2",
        "trustpilot", "customer", "customers", "users", "install", "downloads",
    ))
    has_product_proof = any(term in haystack for term in (
        "product", "platform", "software", "saas", "app", "integration", "api",
        "website", "features", "marketplace", "chrome extension", "shopify",
    ))
    has_location = any(term in haystack for term in (
        "location", "address", "city", "branch", "store", "office", "near", "area",
        str(target or "").strip().lower(),
    )) or str(record.get("geography", "")).strip().lower() not in {"", "global", "unknown"}
    has_supplier = any(term in haystack for term in (
        "supplier", "suppliers", "moq", "manufacturing", "logistics", "freight",
        "procurement", "vendor quote", "unit cost", "cogs", "bill of materials",
    ))
    if profile["profile_id"] == "saas_software":
        pricing_ok = has_pricing or has_product_proof or not profile["competitor_requires_pricing"]
        signal_ok = has_review_or_listing or has_product_proof or record_has_named_saas_competitor(record)
        return pricing_ok and signal_ok
    if profile["profile_id"] == "physical_product" and domain in {"automotive", "automotive_retail"}:
        return (has_pricing or has_review_or_listing) and (has_location or has_review_or_listing or record_has_named_automotive_competitor(record))
    if profile["profile_id"] == "physical_product":
        unit_ok = has_supplier or has_pricing
        if profile["competitor_requires_supplier_quotes"] and not has_supplier:
            unit_ok = has_pricing and has_review_or_listing
        return has_pricing and has_review_or_listing and has_location and unit_ok
    if profile["profile_id"] == "healthcare_regulated":
        return has_pricing and (has_review_or_listing or has_product_proof)
    if profile["competitor_requires_location"]:
        return has_pricing and has_review_or_listing and has_location
    return has_pricing and (has_review_or_listing or has_product_proof)


def source_readiness_is_regulatory_compliance_record(record: dict, topic: str, industry: str, target: str, domain: str) -> bool:
    if (
        is_metadata_only_evidence(record)
        or source_readiness_is_internal_or_synthetic(record)
        or not source_readiness_record_matches_target_scope(record, target)
        or record_domain_confidence(record, domain, topic, industry) < 0.38
    ):
        return False
    family = str(record.get("source_family", "")).lower()
    haystack = record_text_blob(record).lower()
    if family in {
        "industry_pack_regulation",
        "healthcare_regulatory_source",
        "state_industry_department",
        "compliance_case_study",
    }:
        return True
    return any(term in haystack for term in (
        "regulation", "regulator", "law", "legal", "compliance", "license", "licence",
        "permit", "certification", "standard", "approval", "tax", "registration",
        "gdpr", "hipaa", "fda", "mdr", "cdsco", "rbi", "sebi", "gst", "msme",
    ))


def source_readiness_is_financial_comp_record(record: dict, topic: str, industry: str, target: str, domain: str) -> bool:
    if (
        is_metadata_only_evidence(record)
        or source_readiness_is_internal_or_synthetic(record)
        or source_readiness_is_generic_country_denominator(record)
        or not source_readiness_record_matches_target_scope(record, target)
        or record_domain_confidence(record, domain, topic, industry) < 0.50
        or not source_readiness_has_number(record)
    ):
        return False
    family = str(record.get("source_family", "")).lower()
    haystack = record_text_blob(record).lower()
    return family in SOURCE_READINESS_FINANCIAL_FAMILIES and any(term in haystack for term in (
        "revenue", "arr", "ebitda", "margin", "gross margin", "market cap", "enterprise value",
        "valuation", "multiple", "ev/revenue", "ev/ebitda", "funding", "round", "acquisition",
        "pricing", "fee", "cost", "public company", "annual report", "filing",
    ))


def source_readiness_is_traceable_numeric_record(record: dict) -> bool:
    if not source_readiness_has_number(record):
        return False
    if is_metadata_only_evidence(record) or source_readiness_is_internal_or_synthetic(record):
        return False
    url = str(record.get("url", "") or "").strip()
    if not url or url.startswith("internal://"):
        return False
    has_source_name = bool(str(record.get("publisher", "") or record.get("title", "")).strip())
    has_metric = bool(str(record.get("metric_name", "") or record.get("metric_value", "")).strip())
    return has_source_name and has_metric


def gate_row(label: str, current: int | float, required: int | float, passed: bool | None = None, partial: bool | None = None, why: str = "") -> dict:
    if passed is None:
        passed = current >= required
    if partial is None:
        partial = bool(current) and not passed
    status = "pass" if passed else "partial" if partial else "fail"
    return {
        "label": label,
        "status": status,
        "current": current,
        "required": required,
        "why_it_matters": why,
    }


def build_markets_report_gate_status(
    record_counts: dict,
    target: str = "",
    scope_mode: str = "",
    readiness_status: str = "",
    missing: list[str] | None = None,
    domain: str = "",
) -> dict:
    """Strict market-report gates. Claude can fill analysis, but only evidence can pass gates."""
    profile = get_industry_gate_profile(domain)
    counts = record_counts or {}
    competitor_proof = int(counts.get("competitor_pricing_review_location_records", 0) or 0)
    named_competitors = int(counts.get("named_competitor_operator_records", 0) or 0)
    buyer = int(counts.get("strict_buyer_validation_records", 0) or 0)
    pricing = int(counts.get("direct_pricing_unit_cost_records", 0) or 0)
    numeric = int(counts.get("numeric_input_records", 0) or 0)
    traceable_numeric = int(counts.get("traceable_numeric_records", 0) or 0)
    financial_comps = int(counts.get("financial_comps_benchmarks_records", 0) or 0)
    legal = int(counts.get("country_specific_legal_compliance_records", 0) or 0)
    scope_sources = int(counts.get("target_scope_domain_records", 0) or counts.get("country_local_domain_records", 0) or 0)
    source_ledger_rows = int(counts.get("source_ledger_traceable_rows", traceable_numeric) or 0)
    competitor_min = int(profile.get("competitor_minimum", 3) or 3)
    regulatory_min = int(profile.get("regulatory_min_count", 1) or 0)
    pricing_min = int(profile.get("pricing_unit_cost_minimum", 2) or 2)

    competitor_current = max(competitor_proof, named_competitors if competitor_proof else 0)
    competitor_label = profile.get("competitor_gate_label") or (
        "3-5 named competitors/operators with pricing, review/listing, and location evidence"
    )
    gates = {
        "named_competitors_with_pricing_reviews_locations": gate_row(
            competitor_label,
            competitor_current,
            competitor_min,
            passed=competitor_proof >= competitor_min,
            partial=named_competitors >= competitor_min,
            why=(
                "Competitive benchmarking needs industry-appropriate competitor proof "
                f"({profile.get('profile_id', 'general')})."
            ),
        ),
        "verified_buyer_or_practitioner_evidence": gate_row(
            "Verified local buyer/practitioner/survey evidence",
            buyer,
            2,
            why="Demand, willingness-to-pay, churn, and GTM claims need buyer/operator proof.",
        ),
        "bottom_up_tam_sam_som_inputs": gate_row(
            "Bottom-up TAM/SAM/SOM inputs with source-backed buyer count, pricing, frequency/adoption, and penetration",
            min(numeric, traceable_numeric, pricing + buyer),
            5,
            passed=numeric >= 5 and traceable_numeric >= 5 and pricing >= pricing_min and buyer >= 2,
            partial=numeric >= 3 and pricing >= 1,
            why="Market size cannot use broad top-down denominators as proof.",
        ),
        "financial_comps_or_benchmarks": gate_row(
            "Real financial comps or public/private benchmarks",
            financial_comps,
            1,
            why="Funding, valuation, and revenue projections need filings, market data, funding rounds, pricing pages, or benchmark reports.",
        ),
        "country_specific_legal_compliance": gate_row(
            "Country-specific legal/compliance evidence",
            legal,
            regulatory_min,
            passed=legal >= regulatory_min if regulatory_min > 0 else True,
            partial=legal >= max(1, regulatory_min // 2) if regulatory_min > 0 else legal >= 0,
            why=(
                "Regulated sectors need legal/compliance proof; SaaS may defer until launch geography is regulated."
                if profile.get("profile_id") == "saas_software"
                else "Loan, visa, launch, and regulated-industry claims need country-specific rules and certification/licensing context."
            ),
        ),
        "traceable_source_ledger": gate_row(
            "Source ledger with every number traceable",
            source_ledger_rows,
            8,
            passed=source_ledger_rows >= 8 and traceable_numeric >= 5 and scope_sources >= 3,
            partial=source_ledger_rows >= 4 or traceable_numeric >= 3,
            why="Every hard number must map to a URL/source, metric, unit, and allowed-use rule.",
        ),
    }
    if profile.get("profile_id") == "saas_software" and regulatory_min == 0:
        gates["country_specific_legal_compliance"]["status"] = "pass"
        gates["country_specific_legal_compliance"]["note"] = "Not required for SaaS/software gate profile unless regulated sub-sector."
    failed = [key for key, row in gates.items() if row["status"] != "pass"]
    all_passed = not failed
    score_cap = 10.0 if all_passed else 7.0
    return {
        "standard": "MarketsandMarkets-style strict evidence gates (industry-adaptive)",
        "industry_gate_profile": profile.get("profile_id", "general"),
        "target": target,
        "scope_mode": scope_mode,
        "source_readiness_status": readiness_status,
        "all_gates_passed": all_passed,
        "score_cap_10": score_cap,
        "score_cap_rule": "No report or section score may be shown above 7/10 unless every strict gate passes.",
        "gates": gates,
        "failed_gates": failed,
        "missing_before_score_above_7": [gates[key]["label"] for key in failed],
        "source_missing_items": missing or [],
        "claude_fill_policy": (
            "If the databank/scrapers do not contain enough evidence, Claude may write analyst sections using "
            "labeled ESTIMATED, PROXY, SYNTHETIC MODEL, or VALIDATION REQUIRED content, but Claude output "
            "does not count as VERIFIED evidence and cannot make a failed gate pass."
        ),
    }


def source_readiness_is_country_local_domain_record(
    record: dict,
    target: str,
    domain: str,
    topic: str,
    industry: str,
) -> bool:
    target_l = target.strip().lower()
    if not target_l or target_l not in str(record.get("geography", "")).lower():
        return False
    if record.get("proxy_geography_for"):
        return False
    if is_metadata_only_evidence(record):
        return False
    if source_readiness_is_internal_or_synthetic(record):
        return False
    if source_readiness_is_generic_country_denominator(record):
        return False
    return record_domain_confidence(record, domain, topic, industry) >= 0.50


def assess_source_readiness(
    topic: str,
    industry: str,
    target: str,
    selected_sections: list[dict] | None = None,
) -> dict:
    """Preflight source coverage before generation so weak topics do not become fake reports."""
    domain = classify_topic_domain(topic, industry)
    gate_profile = get_industry_gate_profile(domain)
    market_niche = identify_market_niche(topic, industry, target)
    raw_records = target_record_filter(load_records_for_target(target), target)
    infrastructure_records = [
        record for record in raw_records
        if is_metadata_only_evidence(record)
    ]
    usable_records = [
        record for record in raw_records
        if not is_metadata_only_evidence(record)
    ]
    min_domain_confidence = 0.38 if domain != "general_market" else 0.0
    domain_records = [
        record for record in usable_records
        if record_domain_confidence(record, domain, topic, industry) >= min_domain_confidence
    ]
    section_titles = [section.get("title", "") for section in (selected_sections or []) if section.get("title")]
    if not section_titles:
        section_titles = ["Executive Summary", "Market Size & Valuation", "Competitive Landscape", "Pricing Analysis"]

    direct_records = []
    proxy_records = []
    context_records = []
    for record in domain_records:
        best_decision = "exclude"
        best_score = 0.0
        best_niche_decision = "exclude"
        for section_title in section_titles[:8]:
            precision = source_precision_check(record, domain, section_title, topic, industry, target)
            score = float(precision.get("score", 0.0) or 0.0)
            best_niche_decision = str(precision.get("evidence_tier", best_niche_decision))
            if score > best_score:
                best_score = score
                best_decision = str(precision.get("decision", "exclude"))
            if precision.get("decision") == "direct":
                best_decision = "direct"
                best_score = max(best_score, score)
                break
        if best_decision == "direct":
            direct_records.append(record)
        elif best_decision == "proxy":
            proxy_records.append(record)
        elif best_niche_decision == "Proxy":
            context_records.append(record)

    official_records = [
        record for record in (direct_records + context_records)
        if str(record.get("source_family", "")).lower() in SOURCE_READINESS_OFFICIAL_FAMILIES
    ]
    financial_records = [
        record for record in direct_records
        if str(record.get("source_family", "")).lower() in SOURCE_READINESS_FINANCIAL_FAMILIES
    ]
    numeric_records = [
        record for record in direct_records
        if source_readiness_has_number(record)
        and not source_readiness_is_internal_or_synthetic(record)
    ]
    qualitative_records = [
        record for record in direct_records
        if source_readiness_is_qualitative(record)
    ]
    strict_buyer_validation_records = [
        record for record in direct_records
        if source_readiness_is_strict_buyer_validation_record(record, topic, industry, target, domain)
    ]
    direct_pricing_records = [
        record for record in direct_records
        if source_readiness_is_direct_pricing_record(record, topic, industry, target, domain)
    ]
    named_competitor_records = [
        record for record in direct_records
        if source_readiness_is_named_competitor_record(record, topic, industry, target, domain)
    ]
    competitor_proof_records = [
        record for record in direct_records
        if source_readiness_is_competitor_proof_record(record, topic, industry, target, domain)
    ]
    regulatory_compliance_records = [
        record for record in direct_records
        if source_readiness_is_regulatory_compliance_record(record, topic, industry, target, domain)
    ]
    financial_comp_records = [
        record for record in direct_records
        if source_readiness_is_financial_comp_record(record, topic, industry, target, domain)
    ]
    traceable_numeric_records = [
        record for record in direct_records
        if source_readiness_is_traceable_numeric_record(record)
    ]
    commercial_topic_fit_records = [
        record for record in direct_records
        if source_readiness_has_commercial_topic_fit(record, topic, industry, minimum=2)
        and not source_readiness_is_internal_or_synthetic(record)
        and not source_readiness_is_generic_country_denominator(record)
    ]
    commercial_topic_fit_ratio = len(commercial_topic_fit_records) / max(len(direct_records), 1)
    country_mode = is_country_specific_target(target)
    global_mode = source_readiness_target_is_global(target)
    scope_mode = "country" if country_mode else ("global" if global_mode else "region")
    local_micro_market_mode = bool(market_niche.get("buyer_terms")) and not country_mode and not global_mode
    required_official_records = 1 if local_micro_market_mode else 4
    country_local_domain_records = [
        record for record in direct_records
        if source_readiness_is_country_local_domain_record(record, target, domain, topic, industry)
    ] if country_mode else []
    country_local_qualitative = [
        record for record in qualitative_records
        if target.strip().lower() in str(record.get("geography", "")).lower()
        and not record.get("proxy_geography_for")
    ] if country_mode else []
    target_scope_domain_records = [
        record for record in direct_records
        if source_readiness_record_matches_target_scope(record, target)
        and not source_readiness_is_internal_or_synthetic(record)
        and not source_readiness_is_generic_country_denominator(record)
        and record_domain_confidence(record, domain, topic, industry) >= 0.50
    ]
    target_scope_qualitative = [
        record for record in qualitative_records
        if source_readiness_record_matches_target_scope(record, target)
    ]

    missing = []
    if domain == "general_market":
        missing.append("domain-specific routing for this topic/industry")
    if len(direct_records) < 3:
        missing.append(f"exact niche direct evidence rows: {len(direct_records)}/3")
    if len(direct_records) + len(proxy_records) < 8:
        missing.append(f"exact niche direct/proxy evidence rows: {len(direct_records) + len(proxy_records)}/8")
    if len(domain_records) < 10:
        missing.append(f"domain-matched source records before niche filter: {len(domain_records)}/10")
    if len(direct_records) < 8:
        missing.append(f"direct eligible evidence records: {len(direct_records)}/8")
    if len(official_records) < required_official_records:
        missing.append(f"official/company/filing sources: {len(official_records)}/{required_official_records}")
    if len(financial_records) < 2:
        missing.append(f"financial/pricing/valuation benchmarks: {len(financial_records)}/2")
    if len(numeric_records) < 5:
        missing.append(f"numeric source-backed inputs: {len(numeric_records)}/5")
    if len(qualitative_records) < 2:
        missing.append(f"published survey/practitioner/buyer evidence: {len(qualitative_records)}/2")
    if len(strict_buyer_validation_records) < 2:
        missing.append(f"strict topic-matched buyer/practitioner validation: {len(strict_buyer_validation_records)}/2")
    if len(direct_pricing_records) < 2:
        missing.append(f"direct topic-matched pricing/unit-cost evidence: {len(direct_pricing_records)}/2")
    if len(named_competitor_records) < 3:
        missing.append(f"named topic-matched competitor/operator evidence: {len(named_competitor_records)}/3")
    if len(competitor_proof_records) < 3:
        gate_label = gate_profile.get("competitor_gate_label", "competitor proof")
        missing.append(f"{gate_label}: {len(competitor_proof_records)}/3")
    if len(financial_comp_records) < 1:
        missing.append(f"real financial comps or public/private benchmarks: {len(financial_comp_records)}/1")
    regulatory_min = int(gate_profile.get("regulatory_min_count", 1) or 0)
    if regulatory_min > 0 and len(regulatory_compliance_records) < regulatory_min:
        missing.append(f"country/scope legal-compliance evidence: {len(regulatory_compliance_records)}/{regulatory_min}")
    if len(traceable_numeric_records) < 5:
        missing.append(f"traceable numeric source-ledger rows: {len(traceable_numeric_records)}/5")
    if commercial_topic_fit_ratio < 0.35:
        missing.append(f"direct evidence topic-fit ratio: {commercial_topic_fit_ratio:.2f}/0.35")
    if country_mode and len(country_local_domain_records) < 3:
        missing.append(f"country-local domain sources for {target}: {len(country_local_domain_records)}/3")
    if country_mode and len(country_local_qualitative) < 1:
        missing.append(f"country-local buyer/practitioner/survey signal for {target}: {len(country_local_qualitative)}/1")
    if not country_mode and len(target_scope_domain_records) < 5:
        missing.append(f"{scope_mode}-scope domain sources for {target}: {len(target_scope_domain_records)}/5")
    if not country_mode and len(target_scope_qualitative) < 3:
        missing.append(f"{scope_mode}-scope buyer/practitioner/survey signal for {target}: {len(target_scope_qualitative)}/3")

    score = 0
    if domain != "general_market":
        score += 10
    score += min(32, len(direct_records) * 4)
    score += min(14, len(proxy_records) * 2)
    score += min(12, len(official_records) * 3)
    score += min(12, len(financial_records) * 6)
    score += min(10, len(numeric_records) * 2)
    score += min(4, len(qualitative_records) * 2)
    score += min(8, len(strict_buyer_validation_records) * 4)
    score += min(8, len(direct_pricing_records) * 4)
    score += min(6, len(named_competitor_records) * 2)
    if country_mode:
        score += min(18, len(country_local_domain_records) * 6)
        score += min(5, len(country_local_qualitative) * 5)
        score = min(score, 100)
    else:
        score += min(18, len(target_scope_domain_records) * 4)
        score += min(5, len(target_scope_qualitative) * 2)
        score = min(score, 100)

    hard_blocking_gap = (
        len(domain_records) == 0
        or len(direct_records) == 0
        or (
            country_mode
            and len(country_local_domain_records) == 0
            and len(proxy_records) < 3
        )
    )
    severe_gap = (
        hard_blocking_gap
        or len(domain_records) < 3
        or len(direct_records) < 2
        or len(strict_buyer_validation_records) == 0
        or len(direct_pricing_records) == 0
        or len(named_competitor_records) == 0
        or (domain == "general_market" and len(direct_records) < 3)
    )
    status = "ready"
    if hard_blocking_gap:
        status = "collect_sources_first"
    elif severe_gap or missing:
        status = "limited"
    if status == "collect_sources_first":
        if len(direct_records) == 0:
            score = min(score, 19)
        else:
            score = min(score, 39)
    elif status == "limited":
        score = min(score, 84)
    if len(strict_buyer_validation_records) == 0:
        score = min(score, 58)
    elif len(strict_buyer_validation_records) < 2:
        score = min(score, 66)
    if len(direct_pricing_records) < 2:
        score = min(score, 64)
    if len(named_competitor_records) < 3:
        score = min(score, 64)
    if len(competitor_proof_records) < 3:
        score = min(score, 62)
    if len(financial_comp_records) < 1:
        score = min(score, 66)
    if regulatory_min > 0 and len(regulatory_compliance_records) < regulatory_min:
        score = min(score, 70)
    if len(traceable_numeric_records) < 5:
        score = min(score, 68)
    if commercial_topic_fit_ratio < 0.35:
        score = min(score, 62)

    matrix_row = {}
    pack_row = active_pack_for_industry_domain(industry, domain, topic)
    if pack_row:
        matrix_row = evidence_quality_matrix_lookup().get((pack_row.get("pack_id", ""), target.strip().lower()), {}) or {}
        matrix_status = str(matrix_row.get("readiness_status", "")).strip()
        matrix_gap = str(matrix_row.get("gap_summary", "")).strip()
        if matrix_status == "source_collection_required":
            if status == "collect_sources_first":
                score = min(score, 19 if len(direct_records) == 0 else 39)
            else:
                status = "limited"
                score = min(score, 84)
            if matrix_gap:
                missing.append(f"evidence quality matrix: {matrix_gap}")
        elif matrix_status == "limited_scaffold" and status == "ready":
            status = "limited"
            score = min(score, 84)
            if matrix_gap:
                missing.append(f"evidence quality matrix: {matrix_gap}")

    buyer_terms_required = bool((market_niche or {}).get("buyer_terms"))
    if buyer_terms_required and len(qualitative_records) == 0:
        if "buyer/operator/survey evidence matched to the exact niche: 0/1" not in missing:
            missing.append("buyer/operator/survey evidence matched to the exact niche: 0/1")
        if status == "ready":
            status = "limited"
        if status == "limited":
            score = min(score, 49)

    infrastructure_score = min(
        100,
        len(infrastructure_records) * 3
        + (20 if matrix_row else 0)
        + (15 if pack_row else 0)
    )
    collection_queries = [
        f"{target} {industry} {topic} official statistics regulator dataset 2026",
        f"{target} {industry} {topic} company filings annual report pricing benchmark",
        f"{target} {industry} {topic} adoption survey buyer interview practitioner forum",
        f"{target} {industry} {topic} funding rounds valuation comparable companies",
        f"{target} {industry} {topic} regulation certification compliance costs",
    ]
    record_counts = {
        "loaded_records": len(raw_records),
        "infrastructure_route_records": len(infrastructure_records),
        "usable_records": len(usable_records),
        "domain_matched_records": len(domain_records),
        "direct_records": len(direct_records),
        "proxy_records": len(proxy_records),
        "context_only_records": len(context_records),
        "official_company_filing_records": len(official_records),
        "financial_pricing_valuation_records": len(financial_records),
        "numeric_input_records": len(numeric_records),
        "survey_practitioner_buyer_records": len(qualitative_records),
        "strict_buyer_validation_records": len(strict_buyer_validation_records),
        "direct_pricing_unit_cost_records": len(direct_pricing_records),
        "named_competitor_operator_records": len(named_competitor_records),
        "competitor_pricing_review_location_records": len(competitor_proof_records),
        "financial_comps_benchmarks_records": len(financial_comp_records),
        "country_specific_legal_compliance_records": len(regulatory_compliance_records),
        "traceable_numeric_records": len(traceable_numeric_records),
        "source_ledger_traceable_rows": len(traceable_numeric_records),
        "commercial_topic_fit_records": len(commercial_topic_fit_records),
        "commercial_topic_fit_ratio": round(commercial_topic_fit_ratio, 2),
        "country_local_domain_records": len(country_local_domain_records),
        "country_local_buyer_signal_records": len(country_local_qualitative),
        "target_scope_domain_records": len(target_scope_domain_records),
        "target_scope_buyer_signal_records": len(target_scope_qualitative),
    }
    markets_report_gate = build_markets_report_gate_status(
        record_counts,
        target=target,
        scope_mode=scope_mode,
        readiness_status=status,
        missing=missing,
        domain=domain,
    )
    if not markets_report_gate.get("all_gates_passed"):
        score = min(score, int(markets_report_gate.get("score_cap_10", 7.0) * 10))
        if status == "ready":
            status = "limited"
    markets_report_gate["source_readiness_status"] = status

    competitor_intel_gate = (
        competitor_intelligence_gate(record_counts)
        if competitor_intelligence_gate is not None
        else {"passed": True, "score_cap_10": 10.0}
    )
    if not competitor_intel_gate.get("passed"):
        score = min(score, int(competitor_intel_gate.get("score_cap_10", 6.5) * 10))
        if status == "ready":
            status = "limited"
        for reason in competitor_intel_gate.get("failed_reasons", []) or []:
            label = f"competitor intelligence gate: {reason}"
            if label not in missing:
                missing.append(label)

    if build_industry_queries is not None:
        industry_plan = build_industry_queries(topic, domain, target, industry=industry)
        for bucket in ("competitor_queries", "pricing_queries", "buyer_queries"):
            collection_queries.extend(industry_plan.get(bucket, [])[:2])
        collection_queries = list(dict.fromkeys(collection_queries))[:12]

    return {
        "status": status,
        "score": int(round(score)),
        "evidence_score": int(round(score)),
        "infrastructure_score": int(round(infrastructure_score)),
        "domain": domain,
        "industry_gate_profile": gate_profile.get("profile_id", "general"),
        "market_niche": market_niche,
        "target_is_country": country_mode,
        "scope_mode": scope_mode,
        "quality_matrix_status": matrix_row.get("readiness_status", ""),
        "quality_matrix_pack": pack_row.get("pack_id", "") if pack_row else "",
        "record_counts": record_counts,
        "markets_report_gate": markets_report_gate,
        "competitor_intelligence_gate": competitor_intel_gate,
        "missing": missing,
        "collection_queries": collection_queries,
        "message": (
            "This topic/industry is not yet supported with enough verified local sources. "
            "Please wait about 10 minutes while official sources, filings, pricing data, surveys, "
            "practitioner evidence, and regulatory records are collected before generating a funding-ready report."
        ),
    }


def auto_harvest_source_gaps(
    topic: str,
    industry: str,
    target: str,
    selected_sections: list[dict] | None,
    readiness: dict,
    max_records: int = 24,
    search_api_keys: dict[str, str] | None = None,
    search_api_budgets: dict[str, dict] | None = None,
) -> dict:
    """Run on-demand credible-source discovery when the current evidence is weak."""
    if harvest_on_demand_topic is None:
        return {"attempted": False, "reason": "on-demand research module unavailable"}
    status = str(readiness.get("status", "limited"))
    score = int(readiness.get("score", 0) or 0)
    if status == "ready" and score >= 85:
        return {"attempted": False, "reason": "source readiness already sufficient"}

    domain = readiness.get("domain") or classify_topic_domain(topic, industry)
    country_domains_for_run: list[str] = []
    if is_country_specific_target(target) and country_source_domains is not None:
        try:
            country_domains_for_run = country_source_domains(target) or []
        except Exception:
            country_domains_for_run = []
    if not country_domains_for_run and country_grounding_profile is not None and is_country_specific_target(target):
        try:
            profile = country_grounding_profile(target) or {}
            country_domains_for_run = profile.get("domains", []) or []
        except Exception:
            country_domains_for_run = []

    try:
        result = harvest_on_demand_topic(
            topic=topic,
            industry=industry,
            target=target,
            domain=domain,
            country_domains=country_domains_for_run,
            max_records=int(max_records),
            missing=readiness.get("missing", []) or [],
            extra_queries=readiness.get("collection_queries", []) or [],
            search_api_keys=search_api_keys or {},
            search_api_budgets=search_api_budgets or LIVE_RESEARCH_API_BUDGETS,
        )
    except Exception as exc:
        return {"attempted": True, "error": str(exc), "added_count": 0}

    try:
        st.cache_data.clear()
    except Exception:
        pass
    updated_readiness = assess_source_readiness(topic, industry, target, selected_sections)
    result["updated_readiness"] = updated_readiness
    return result


def render_source_readiness_preflight(readiness: dict) -> None:
    status = readiness.get("status", "limited")
    if status == "collect_sources_first":
        st.error(readiness.get("message", "Source collection is required before report generation."))
    elif status == "limited":
        st.warning(
            "Source coverage is partial. The report will proceed with clearly labeled estimates where evidence is thin."
        )
    else:
        st.success("Evidence preflight passed. Report generation can proceed.")
    if client_report_mode():
        return
    counts = readiness.get("record_counts", {}) or {}
    summary_rows = [
        {"Check": key.replace("_", " ").title(), "Count": value}
        for key, value in counts.items()
    ]
    st.caption(
        f"Evidence readiness: {readiness.get('evidence_score', readiness.get('score', 0))}/100 | "
        f"Infrastructure readiness: {readiness.get('infrastructure_score', 0)}/100 | "
        f"Domain: {readiness.get('domain', 'unknown')} | "
        f"Scope gate: {readiness.get('scope_mode', 'unknown')} | "
        f"Evidence matrix: {readiness.get('quality_matrix_status') or 'not indexed'}"
    )
    with st.expander("Source readiness details", expanded=status != "ready"):
        market_niche = readiness.get("market_niche", {}) or {}
        if market_niche:
            st.markdown("**Exact market niche gate**")
            st.write(market_niche.get("exact_market_niche", ""))
            st.caption(market_niche.get("source_acceptance_rule", ""))
        if summary_rows:
            st.table(summary_rows)
        markets_gate = readiness.get("markets_report_gate", {}) or {}
        gate_rows = [
            {
                "Gate": row.get("label", key),
                "Status": str(row.get("status", "")).upper(),
                "Current": row.get("current", ""),
                "Required": row.get("required", ""),
            }
            for key, row in (markets_gate.get("gates", {}) or {}).items()
            if isinstance(row, dict)
        ]
        if gate_rows:
            st.markdown("**Strict report gates**")
            st.caption(markets_gate.get("score_cap_rule", "No score above 7/10 unless all strict gates pass."))
            st.table(gate_rows)
        missing = readiness.get("missing", []) or []
        if missing:
            st.markdown("**Missing before funding-ready use**")
            for item in missing:
                st.markdown(f"- {item}")
        queries = readiness.get("collection_queries", []) or []
        if queries:
            st.markdown("**10-minute source collection queue**")
            for query in queries:
                st.markdown(f"- `{query}`")


def render_auto_research_findings(harvest_result: dict) -> None:
    """Show exactly what the app searched and which credible records passed gates."""
    if not harvest_result or not harvest_result.get("attempted"):
        return
    queries = harvest_result.get("searched_queries", []) or []
    candidates = harvest_result.get("candidate_records", []) or []
    provider_diagnostics = harvest_result.get("provider_diagnostics", []) or []
    diligence_coverage = harvest_result.get("diligence_evidence_coverage", {}) or {}
    with st.expander("Auto-research searches and accepted sources", expanded=True):
        if provider_diagnostics:
            st.markdown("**Live retrieval diagnostics**")
            bank_trace = harvest_result.get("evidence_bank_trace") or {}
            if bank_trace:
                st.markdown("**IIDATECH evidence bank trace**")
                st.json({
                    "bank_hits": bank_trace.get("bank_hits", 0),
                    "benchmark_hits": bank_trace.get("benchmark_hits", 0),
                    "serp_competitor_hits": bank_trace.get("serp_competitor_hits", 0),
                    "new_competitors_discovered": bank_trace.get("new_competitors_discovered", 0),
                    "exact_search_hits": bank_trace.get("exact_search_hits", 0),
                    "exa_hits": bank_trace.get("exa_hits", 0),
                    "tavily_hits": bank_trace.get("tavily_hits", 0),
                })
            st.dataframe(
                [
                    {
                        "Provider": row.get("provider", ""),
                        "Configured": "yes" if row.get("configured") else "no",
                        "Attempted": "yes" if row.get("attempted") else "no",
                        "Working": (
                            "yes"
                            if row.get("configured")
                            and row.get("attempted")
                            and not row.get("errors")
                            and int(row.get("returned", 0) or 0) > 0
                            else "no"
                        ),
                        "Query cap": str(row.get("budget_max_queries", "")),
                        "Results/query cap": str(row.get("budget_results_per_query", "")),
                        "Page extract cap": str(row.get("budget_max_page_extracts", "")),
                        "Returned": str(row.get("returned", 0)),
                        "Accepted": str(row.get("accepted", 0)),
                        "Error": "; ".join(row.get("errors", [])[:2]) if isinstance(row.get("errors"), list) else row.get("error", ""),
                    }
                    for row in provider_diagnostics
                ],
                width="stretch",
                hide_index=True,
            )
            failed = [
                row for row in provider_diagnostics
                if row.get("configured") and (row.get("errors") or (row.get("attempted") and int(row.get("returned", 0) or 0) == 0))
            ]
            if failed:
                st.warning(
                    "One or more configured retrieval providers did not return usable results. "
                    "Generation will stay blocked if direct evidence remains zero."
                )
        configured_live = harvest_result.get("configured_live_providers", []) or []
        if not configured_live:
            st.warning(
                "No Tavily, Exa, or Firecrawl key is configured for live retrieval. "
                "The app used free/public fallback search only, which may be too weak for niche market reports."
            )
        if diligence_coverage:
            st.markdown("**Funding diligence evidence coverage**")
            st.dataframe(
                [
                    {
                        "Evidence type": row.get("label", humanize_label(intent)),
                        "Accepted records": row.get("accepted_records", 0),
                        "Queries queued": row.get("query_count", 0),
                        "Allowed use": row.get("allowed_use", ""),
                    }
                    for intent, row in diligence_coverage.items()
                ],
                width="stretch",
                hide_index=True,
            )
        if queries:
            st.markdown("**Searches run for the missing evidence gates**")
            st.table([
                {
                    "Gap": str(row.get("gap", ""))[:140],
                    "Intent": str(row.get("intent", ""))[:90],
                    "Query": str(row.get("query", ""))[:260],
                }
                for row in queries[:18]
            ])
            if len(queries) > 18:
                st.caption(f"{len(queries) - 18} additional searches were queued and de-duplicated.")
        else:
            st.caption("No source-search queries were generated.")

        if candidates:
            st.markdown("**Credible sources found and stored for this topic**")
            st.dataframe(
                [
                    {
                        "Status": row.get("Status", ""),
                        "Family": row.get("Source family", ""),
                        "Publisher": row.get("Publisher", ""),
                        "Title": row.get("Title", ""),
                        "Geography": row.get("Geography", ""),
                        "Year": row.get("Year", ""),
                        "Metric": row.get("Metric", ""),
                        "Accepted because": row.get("Value / why accepted", ""),
                        "Confidence": row.get("Confidence", ""),
                        "URL": row.get("URL", ""),
                    }
                    for row in candidates[:16]
                ],
                width="stretch",
                hide_index=True,
            )
            st.caption(
                "These records passed the allowlisted-source and topic-relevance gates. "
                "Funding-grade use still depends on whether the source contains direct local figures, not only a credible article or paper."
            )
        else:
            st.warning(
                "The app searched the missing evidence gates, but no credible allowlisted sources passed the topic and domain filters. "
                "The report should remain blocked until official data, filings, pricing references, surveys, or practitioner sources are added."
            )


def evidence_label_for_diligence_record(
    record: dict,
    topic: str,
    industry: str,
    target: str,
) -> str:
    """Topic-aware evidence label for financial / funding diligence tables."""
    domain = classify_topic_domain(topic, industry)
    try:
        from iidatech.validation.relevance_gate import is_record_relevant_to_report

        ok, reason = is_record_relevant_to_report(record, topic, industry, domain)
        if not ok and "automotive" in reason:
            return "WITHHELD / CROSS-DOMAIN CONTAMINATION"
        if not ok:
            return "WITHHELD / OFF-TOPIC EVIDENCE"
    except Exception:
        pass
    label = evidence_label_for_record(record, topic=topic, industry=industry, target=target)
    match = topic_match_detail(record, topic, industry, target)
    if not match.get("report_relevant", True):
        return "WITHHELD / OFF-TOPIC EVIDENCE"
    if match["score"] < 0.35 and str(label).upper().startswith("VERIFIED"):
        return "ESTIMATED / TOPIC PROXY"
    return label


def evidence_label_for_record(
    record: dict,
    topic: str = "",
    industry: str = "",
    target: str = "",
) -> str:
    if str(topic or "").strip():
        try:
            from iidatech.validation.relevance_gate import is_record_relevant_to_report

            domain = classify_topic_domain(topic, industry)
            if not is_record_relevant_to_report(record, topic, industry, domain)[0]:
                return "WITHHELD / OFF-TOPIC EVIDENCE"
        except Exception:
            pass
    family = str(record.get("source_family", "")).lower()
    if family == "iidatech_2026_financial_model_bank":
        return "ESTIMATED MODEL / NOT VERIFIED HARD FIGURE"
    if family == "user_uploaded_survey":
        return "USER-UPLOADED SURVEY / NEEDS SOURCE CHECK"
    if family == "user_uploaded_interview":
        return "USER-UPLOADED BUYER NOTE / QUALITATIVE"
    if str(record.get("url", "")).startswith("internal://"):
        return "SYNTHETIC MODEL / NOT VERIFIED"
    if family in {
        "country_databank_source",
        "country_industry_policy_route",
        "country_industry_financial_route",
        "country_news_route",
        "country_industry_pack",
        "country_pack_official_profile",
        "global_master_source_route",
        "global_master_regulator_route",
        "global_master_url_health",
        "ai_saas_funding_gap",
        "statista_public_metadata",
        "government_context",
    }:
        return "VERIFIED SOURCE ROUTE / NOT A CLAIM"
    if source_verification_status is not None:
        try:
            return source_verification_status(record).get("label") or "ESTIMATED / THIRD-PARTY BENCHMARK"
        except Exception:
            pass
    if record.get("proxy_geography_for"):
        return "ESTIMATED / PROXY BENCHMARK"
    if family in {
        "government_data", "official_financial_data", "official_health_data",
        "healthcare_regulatory_source", "company_filings", "bank_website_registry",
    }:
        return "VERIFIED"
    if family in {"official_survey", "healthcare_primary_survey"}:
        return "VERIFIED SURVEY"
    if family == "academic_research":
        return "ACADEMIC / RESEARCH EVIDENCE"
    if family == "primary_interview":
        return "USER-SUPPLIED PRIMARY NOTE"
    if family in {"financial_market_data"}:
        return "ESTIMATED / MARKET DATA SNAPSHOT"
    if family in {"reddit_practitioner", "youtube_transcript", "podcast_interview"}:
        return "PUBLISHED PRACTITIONER / SURVEY SIGNAL"
    if family in {
        "analyst_report", "company_reports", "funding_data", "valuation_data",
        "magazine_article", "earnings_transcript", "pricing_reference",
        "implementation_benchmark", "procurement_cycle_evidence",
        "industry_pack_government", "industry_pack_regulation",
        "industry_pack_analyst", "industry_pack_company", "industry_pack_vendor",
        "macro_trend_data", "industry_trend_data", "public_web", "developer_ecosystem",
    }:
        return "ESTIMATED / THIRD-PARTY BENCHMARK"
    if family in {"industry_pack_benchmark", "industry_pack_cost"} or str(record.get("url", "")).startswith("internal://benchmarks"):
        return "SYNTHETIC MODEL"
    if family in {"primary_research_plan", "industry_pack_primary_research"}:
        return "FIELDWORK PLAN / NOT EVIDENCE"
    if family in {"book_reference", "community_forum", "blog_article"}:
        return "ESTIMATED / QUALITATIVE CONTEXT"
    return "ESTIMATED / THIRD-PARTY BENCHMARK"


CLAIM_TYPE_CANONICAL = {
    "tam": "market_denominator",
    "sam": "market_denominator",
    "som": "market_denominator",
    "market_size": "market_denominator",
    "market sizing": "market_denominator",
    "company_filings": "revenue",
    "valuation": "valuation_multiple",
    "multiple": "valuation_multiple",
    "compliance": "regulation",
    "digital_behavior": "buyer_voice",
    "patent_data": "technical_trend",
    "academic_research": "technical_trend",
}


def canonical_claim_type(value: str) -> str:
    claim = str(value or "").strip().lower().replace(" ", "_").replace("-", "_")
    return CLAIM_TYPE_CANONICAL.get(claim, claim or "context")


def infer_record_claim_type(record: dict) -> str:
    explicit = canonical_claim_type(str(record.get("claim_type", "")))
    if explicit and explicit != "context":
        return explicit
    tags = {canonical_claim_type(str(tag)) for tag in (record.get("topic_tags") or [])}
    preferred = [
        "market_denominator", "pricing", "revenue", "margin", "funding_round",
        "valuation_multiple", "competitor", "regulation", "certification_cost",
        "procurement_demand", "buyer_voice", "technical_trend",
    ]
    for claim in preferred:
        if claim in tags:
            return claim
    family = str(record.get("source_family", "") or "").lower()
    metric_surface = " ".join(
        str(record.get(field, ""))
        for field in ("title", "publisher", "metric_name", "metric_value", "unit", "text")
    ).lower()
    if any(term in metric_surface for term in ("price", "pricing", "fee", "rate card", "tariff", "per user", "per seat", "per month", "package")):
        return "pricing"
    if any(term in metric_surface for term in ("gross margin", "operating margin", "ebitda margin", "cogs", "cost structure")):
        return "margin"
    if any(term in metric_surface for term in ("funding", "round", "investor", "seed", "series a", "venture")):
        return "funding_round"
    if any(term in metric_surface for term in ("market cap", "enterprise value", "ev/", "multiple", "valuation")):
        return "valuation_multiple"
    if any(term in metric_surface for term in ("regulation", "law", "standard", "certification", "permit", "license", "approval")):
        return "regulation"
    if any(term in metric_surface for term in ("review", "reddit", "transcript", "survey", "interview", "podcast", "buyer", "customer voice")):
        return "buyer_voice"
    if any(term in metric_surface for term in ("patent", "paper", "research", "technical", "r&d", "innovation")):
        return "technical_trend"
    return CLAIM_TYPE_BY_SOURCE_FAMILY.get(family, "context")


def inferred_evidence_tier(record: dict) -> str:
    existing = str(record.get("evidence_tier", "") or "").strip()
    if existing:
        return existing
    label = evidence_label_for_record(record)
    label_l = label.lower()
    if "verified source route" in label_l:
        return "source_route_only"
    if label_l.startswith("verified"):
        return "verified"
    if "published practitioner" in label_l:
        return "published_practitioner_signal"
    if "synthetic" in label_l or "internal" in label_l:
        return "synthetic_model"
    if "proxy" in label_l:
        return "proxy"
    if "qualitative" in label_l:
        return "qualitative_context"
    return "estimated_benchmark"


def inferred_allowed_use(record: dict, claim_type: str | None = None) -> str:
    existing = str(record.get("allowed_use", "") or "").strip()
    if existing:
        return existing
    claim = canonical_claim_type(claim_type or infer_record_claim_type(record))
    family = str(record.get("source_family", "") or "").lower()
    if is_metadata_only_evidence(record):
        return "Source discovery route only; not evidence for final claims."
    if claim == "market_denominator":
        return "Denominator/context input; final TAM/SAM/SOM still requires buyer count, pricing, frequency, adoption, and capture formula."
    if claim == "pricing":
        return "Pricing input after vendor/listing/SKU/date/currency/unit are cited."
    if claim == "revenue":
        return "Company revenue or financial benchmark after company, period, segment, and source are cited."
    if claim == "valuation_multiple":
        return "Comparable valuation/multiple benchmark after company/sample, date, stage, geography, and basis are cited."
    if claim == "funding_round":
        return "Funding signal after company, round, date, amount, investors, and source basis are cited."
    if claim == "procurement_demand":
        return "Procurement demand signal; distinguish open tender from awarded spend."
    if claim in {"regulation", "certification_cost"}:
        return "Compliance/regulatory input after jurisdiction, rule, authority, cost/timeline, and date are cited."
    if claim == "buyer_voice" or family in {"reddit_practitioner", "youtube_transcript", "podcast_interview", "community_forum", "trade_forum", "review_platform"}:
        return "Published practitioner or survey signal only; supports pain, objections, and workflow, not hard TAM/revenue."
    if claim == "technical_trend":
        return "Technical trend input; supports innovation/defensibility, not market revenue by itself."
    return "Context input; final claims require section-specific source and formula checks."


def normalize_evidence_record_schema(record: dict, target: str = "", industry: str = "") -> dict:
    """Return a retrieval record with the funding-ready evidence schema populated."""
    row = dict(record or {})
    geography = str(row.get("geography", "") or "")
    target_clean = str(target or "").strip()
    country = str(row.get("country", "") or "").strip()
    region = str(row.get("region", "") or "").strip()
    if not country and target_clean and is_country_specific_target(target_clean) and target_clean.lower() in geography.lower():
        country = target_clean
    elif not country and geography and geography.lower() not in {"global", "world", "worldwide", "international", "configurable"}:
        country = geography
    if not region and target_clean and not is_country_specific_target(target_clean):
        region = target_clean
    claim_type = infer_record_claim_type(row)
    row.update({
        "record_schema_version": row.get("record_schema_version") or "funding_ready_evidence_v2",
        "country": country,
        "region": region,
        "industry": str(row.get("industry") or industry or "").strip(),
        "claim_type": claim_type,
        "evidence_tier": inferred_evidence_tier(row),
        "allowed_use": inferred_allowed_use(row, claim_type),
    })
    return row


def section_claim_type_preferences(section_title: str) -> set[str]:
    return {
        canonical_claim_type(claim)
        for claim in SECTION_CLAIM_TYPE_PREFERENCES.get(str(section_title or ""), set())
        if canonical_claim_type(claim)
    }


def claim_type_matches_section(record: dict, section_title: str) -> bool:
    preferred = section_claim_type_preferences(section_title)
    if not preferred:
        return True
    return canonical_claim_type(record.get("claim_type", "")) in preferred


LOCAL_MARKET_TERMS = {
    "goa", "mumbai", "delhi", "bengaluru", "bangalore", "pune", "hyderabad", "chennai",
    "kolkata", "jaipur", "ahmedabad", "kochi", "gurugram", "gurgaon", "noida",
    "dubai", "abu dhabi", "singapore", "london", "new york", "san francisco",
}

BUYER_SIGNAL_TERMS = {
    "kids": {"kids", "children", "child", "family", "families", "parents", "parent", "school", "student", "students"},
    "smb": {"smb", "small business", "small businesses", "microbusiness", "owner", "operator", "merchant", "msme", "sme"},
    "healthcare_admin": {"hospital", "clinic", "practice", "cfo", "rcm", "billing", "claims", "payer", "provider"},
    "farmer": {"farmer", "fpo", "grower", "dealer", "mandi", "procurement", "rural"},
}


def identify_market_niche(topic: str, industry: str, target: str) -> dict:
    domain = classify_topic_domain(topic, industry)
    surface = f"{topic} {industry} {target}".lower()
    buyer_terms: set[str] = set()
    for _label, terms in BUYER_SIGNAL_TERMS.items():
        if any(term in surface for term in terms):
            buyer_terms.update(terms)
    if not buyer_terms and domain == "education":
        buyer_terms.update(BUYER_SIGNAL_TERMS["kids"])
    local_terms = {term for term in LOCAL_MARKET_TERMS if term in surface}
    category_terms = relevant_topic_tokens(topic, industry, target)
    generic_remove = {
        "market", "industry", "business", "service", "services", "report", "analysis",
        "global", "india", "united", "states", "country", "regional", "international",
        "year", "years", "old", "age", "ages",
    }
    category_terms = {term for term in category_terms if term not in generic_remove}
    if domain in DOMAIN_POSITIVE_TERMS:
        category_terms.update(str(term).lower() for term in DOMAIN_POSITIVE_TERMS.get(domain, ())[:12])
    if "workshop" in surface or "workshops" in surface:
        category_terms.update({"workshop", "workshops", "experiential", "activity", "activities"})
    if "tourism" in surface or "tourist" in surface or "goa" in surface:
        category_terms.update({"tourism", "tourist", "families", "children", "activity"})
    exact_market = " x ".join(part for part in [
        target.strip() or "selected geography",
        narrow_topic_scope(topic, industry, target),
        "buyer: " + ", ".join(sorted(list(buyer_terms))[:5]) if buyer_terms else "buyer: inferred from topic",
    ] if part)
    return {
        "domain": domain,
        "geography": target,
        "local_terms": sorted(local_terms),
        "category_terms": sorted(category_terms)[:32],
        "buyer_terms": sorted(buyer_terms)[:24],
        "exact_market_niche": exact_market,
        "source_acceptance_rule": (
            "Accept evidence only when it matches geography, category/use case, and buyer. "
            "Macro national or infrastructure records are context only unless the section explicitly needs denominators."
        ),
    }


def local_niche_needs_operator_evidence(topic: str, industry: str, target: str) -> bool:
    """Detect local service niches where real operators/prices matter more than macro context."""
    surface = f"{topic} {industry} {target}".lower()
    target_l = str(target or "").strip().lower()
    non_global_target = bool(target_l) and target_l not in {
        "global", "world", "worldwide", "international"
    }
    buyer_terms = {
        "kids", "children", "child", "parents", "families", "student", "students",
        "smb", "small business", "farmer", "hospital", "clinic", "buyer", "customer",
    }
    service_terms = {
        "workshop", "workshops", "camp", "class", "classes", "activity", "activities",
        "booking", "pricing", "fees", "operator", "centre", "center", "studio", "academy",
        "course", "program", "subscription", "agency", "clinic", "practice",
    }
    return (
        non_global_target
        and any(term in surface for term in buyer_terms)
        and any(term in surface for term in service_terms)
    )


def record_market_niche_match(record: dict, niche: dict, target: str, topic: str, industry: str) -> dict:
    haystack = record_text_blob(record).lower()
    geo = str(record.get("geography", "") or "").lower()
    family = str(record.get("source_family", "") or "").lower()
    target_l = str(target or "").strip().lower()
    local_terms = [term for term in niche.get("local_terms", []) if term]
    category_terms = [term for term in niche.get("category_terms", []) if len(str(term)) >= 3]
    buyer_terms = [term for term in niche.get("buyer_terms", []) if len(str(term)) >= 3]

    if is_metadata_only_evidence(record):
        return {"decision": "exclude", "tier": "Hypothesis", "score": 0.0, "reason": "route/metadata/infrastructure row, not evidence"}

    if not target_l:
        geo_match = True
    else:
        geo_match = False
    target_is_global = target_l in {"global", "world", "worldwide", "international"}
    if target_is_global:
        geo_match = "global" in geo or geo in {"world", "worldwide", "international", "global"}
    elif target_l:
        geo_match = bool(target_l and (target_l in geo or target_l in haystack))
    if local_terms:
        local_match = any(term in haystack or term in geo for term in local_terms)
        geo_match = bool(geo_match or local_match)
    else:
        local_match = True

    region_member_match = False
    if not geo_match and not target_is_global and not is_country_specific_target(target):
        members = {country.lower() for country in source_readiness_region_member_countries(target)}
        region_member_match = any(country in geo for country in members)
    proxy_geo = bool(record.get("proxy_geography_for")) or geo in {"global", "world", "worldwide", "international", "configurable"} or "global" in geo

    matched_category = sorted({term for term in category_terms if contains_domain_term(haystack, str(term))})[:10]
    matched_buyer = sorted({term for term in buyer_terms if contains_domain_term(haystack, str(term))})[:10]
    category_ok = bool(matched_category) or record_domain_confidence(record, niche.get("domain", ""), topic, industry) >= 0.55
    buyer_required = bool(buyer_terms)
    buyer_ok = not buyer_required or bool(matched_buyer)
    generic_denominator = source_readiness_is_generic_country_denominator(record)

    if geo_match and category_ok and buyer_ok and not generic_denominator:
        return {
            "decision": "direct",
            "tier": "Verified" if evidence_label_for_record(record).startswith("VERIFIED") else "Derived",
            "score": 1.0,
            "reason": "matches geography, category, and buyer",
            "matched_category_terms": matched_category,
            "matched_buyer_terms": matched_buyer,
        }
    if (geo_match or region_member_match) and category_ok and not generic_denominator:
        return {
            "decision": "context" if buyer_required and not buyer_ok else "direct",
            "tier": "Proxy" if buyer_required and not buyer_ok else ("Verified" if evidence_label_for_record(record).startswith("VERIFIED") else "Derived"),
            "score": 0.42 if buyer_required and not buyer_ok else 0.78,
            "reason": "matches geography/category but not buyer; context only" if buyer_required and not buyer_ok else "matches geography/category; buyer fit is inferred or weaker",
            "matched_category_terms": matched_category,
            "matched_buyer_terms": matched_buyer,
        }
    if category_ok and proxy_geo and not generic_denominator:
        return {
            "decision": "proxy",
            "tier": "Proxy",
            "score": 0.52,
            "reason": "category matches but geography is proxy/global/comparable",
            "matched_category_terms": matched_category,
            "matched_buyer_terms": matched_buyer,
        }
    if generic_denominator and (geo_match or region_member_match):
        return {
            "decision": "context",
            "tier": "Proxy",
            "score": 0.32,
            "reason": "macro denominator; context only, not evidence for the niche",
            "matched_category_terms": matched_category,
            "matched_buyer_terms": matched_buyer,
        }
    return {
        "decision": "exclude",
        "tier": "Hypothesis",
        "score": 0.0,
        "reason": "does not match geography x category x buyer",
        "matched_category_terms": matched_category,
        "matched_buyer_terms": matched_buyer,
    }


def bottom_up_sizing_rule_for_niche(topic: str, industry: str, target: str) -> dict:
    niche = identify_market_niche(topic, industry, target)
    surface = f"{topic} {industry} {target}".lower()
    inputs = [
        "addressable buyer count",
        "average ticket price or annual contract value",
        "purchase frequency or usage volume",
        "realistic penetration/capture rate",
    ]
    if "goa" in surface and any(term in surface for term in ("kids", "children", "workshop", "camp", "activity")):
        inputs = [
            "Goa annual tourist families with children",
            "Goa resident families in relevant catchment areas",
            "average workshop ticket price from named Goa/Indian city operators",
            "purchase frequency per child/family per season",
            "realistic penetration rate after competitor capacity and seasonality",
        ]
    return {
        "formula": "TAM = addressable buyer count x average ticket price x purchase frequency x realistic penetration rate",
        "required_inputs": inputs,
        "forbidden_method": "Never use top-down percentage of a broad market as the final TAM/SAM/SOM.",
        "source_tier_rule": "Show each input as Verified, Derived, Proxy, or Hypothesis before computing the figure.",
        "niche": niche.get("exact_market_niche", ""),
    }


def regional_subsection_rule(topic: str, industry: str, target: str) -> dict:
    surface = f"{topic} {industry} {target}".lower()
    if "goa" in surface:
        return {
            "scope": "city/state micro-market",
            "replace_global_regions_with": ["North Goa tourist belt", "South Goa tourist belt", "Panjim/Porvorim resident catchment", "Margao/Vasco resident catchment", "seasonal resort/event channels"],
            "rule": "Do not use North America/Europe/APAC sections for this city/state topic.",
        }
    if is_country_specific_target(target):
        if target.strip().lower() == "india":
            regions = ["North India", "West India", "South India", "East/Northeast India", "priority state/city clusters named by evidence"]
        else:
            regions = ["capital/major metro", "secondary cities", "tourism/commercial clusters", "regulatory/procurement regions", "underserved whitespace clusters"]
        return {
            "scope": "country sub-national",
            "replace_global_regions_with": regions,
            "rule": "For country-scoped reports, use state/city-level or sub-national breakdowns, not global regional headings.",
        }
    return {
        "scope": "regional/global",
        "replace_global_regions_with": ["North America", "Europe", "Asia-Pacific", "Latin America", "Middle East & Africa"],
        "rule": "Global regional headings are allowed only for global or multi-region scope.",
    }


def named_competitor_discovery_gate(
    topic: str,
    industry: str,
    target: str,
    records: list[dict],
    domain: str = "",
) -> dict:
    niche = identify_market_niche(topic, industry, target)
    profile = get_industry_gate_profile(domain or classify_topic_domain(topic, industry))
    candidate_rows = []
    seen = set()
    company_pattern = re.compile(r"\b[A-Z][A-Za-z0-9&'.-]+(?:\s+[A-Z][A-Za-z0-9&'.-]+){0,4}\b")
    for record in records:
        match = record_market_niche_match(record, niche, target, topic, industry)
        if match["decision"] not in {"direct", "proxy"}:
            continue
        surface = " ".join(str(record.get(field, "")) for field in ("publisher", "title", "text"))
        names = [name.strip(" .,-") for name in company_pattern.findall(surface)]
        for name in names[:4]:
            low = name.lower()
            if low in seen or low in {"global", "india", "united states", "market", "source", "verified"}:
                continue
            seen.add(low)
            candidate_rows.append({
                "name": name,
                "location": record.get("geography", target) if profile.get("competitor_requires_location") else "n/a (software)",
                "price_point": record.get("metric_value", "") if "price" in record_text_blob(record).lower() else "not found",
                "evidence_signal": record.get("title", ""),
                "source": record.get("url", ""),
                "competition_type": "direct/operator" if match["decision"] == "direct" else "proxy/substitute",
                "gap_filled": profile.get(
                    "competitor_gate_label",
                    "pricing, review/listing, press, source mention, or operator evidence must be verified before strategy use",
                ),
            })
            break
        if len(candidate_rows) >= 8:
            break
    minimum_label = profile.get(
        "competitor_gate_label",
        "3 named competitors/substitutes with name, location, price point, and one evidence signal",
    )
    return {
        "status": "pass" if len(candidate_rows) >= int(profile.get("competitor_minimum", 3) or 3) else "hypothesis_grade",
        "industry_gate_profile": profile.get("profile_id", "general"),
        "minimum_required": minimum_label,
        "named_competitor_count": len(candidate_rows),
        "competitors": candidate_rows[:8],
        "if_below_three": "Do not write a final competitive landscape; show named gaps and classify the section as hypothesis-grade.",
        "competition_types_to_map": ["direct competitor", "substitute", "incumbent/manual process", "agency/service provider", "non-consumption"],
    }


def section_funding_readiness_gate(section_title: str) -> dict:
    return {
        "required_questions": [
            "What is the specific claim?",
            "What is the source and evidence tier?",
            "What would change this estimate or conclusion?",
            "What decision does a founder or investor make from it?",
        ],
        "completion_rule": (
            "If any question is unanswered, mark the section incomplete, list the missing data, and state where to find it."
        ),
        "section": section_title,
    }


def source_precision_check(record: dict, domain: str, section_title: str, topic: str = "", industry: str = "", target: str = "") -> dict:
    """Score whether a record belongs in this domain/section before retrieval."""
    record = normalize_evidence_record_schema(record, target=target, industry=industry)
    niche = identify_market_niche(topic, industry, target)
    niche_match = record_market_niche_match(record, niche, target, topic, industry)
    if domain == "general_market":
        if niche_match["decision"] == "exclude":
            return {
                "decision": "exclude",
                "score": 0.0,
                "reason": niche_match["reason"],
                "evidence_tier": "Hypothesis",
                "matched_category_terms": niche_match.get("matched_category_terms", []),
                "matched_buyer_terms": niche_match.get("matched_buyer_terms", []),
            }
        return {
            "decision": niche_match["decision"],
            "score": max(0.45, niche_match["score"]),
            "reason": "general-market mode with niche gate",
            "evidence_tier": niche_match["tier"],
            "matched_category_terms": niche_match.get("matched_category_terms", []),
            "matched_buyer_terms": niche_match.get("matched_buyer_terms", []),
        }
    family = str(record.get("source_family", "")).lower()
    claim_type = canonical_claim_type(record.get("claim_type", ""))
    preferred_claims = section_claim_type_preferences(section_title)
    if family == "statista_public_metadata":
        return {
            "decision": "context",
            "score": min(0.22, float(niche_match.get("score", 0.0) or 0.0)),
            "reason": (
                "Statista public metadata is a cross-check/source-discovery route only; "
                "use licensed/exported Statista data or the original cited source before hard claims"
            ),
            "evidence_tier": "Proxy",
            "matched_category_terms": niche_match.get("matched_category_terms", []),
            "matched_buyer_terms": niche_match.get("matched_buyer_terms", []),
        }
    if niche_match["decision"] == "exclude":
        return {
            "decision": "exclude",
            "score": 0.0,
            "reason": f"niche gate failed: {niche_match.get('reason')}",
            "evidence_tier": "Hypothesis",
            "matched_category_terms": niche_match.get("matched_category_terms", []),
            "matched_buyer_terms": niche_match.get("matched_buyer_terms", []),
        }
    if family == "iidatech_2026_financial_model_bank":
        return {
            "decision": "model",
            "score": min(0.72, float(niche_match.get("score", 0.0) or 0.0)),
            "reason": f"stored 2026 planning model; hypothesis only; niche gate: {niche_match.get('decision')} - {niche_match.get('reason')}",
            "evidence_tier": "Hypothesis",
            "matched_category_terms": niche_match.get("matched_category_terms", []),
            "matched_buyer_terms": niche_match.get("matched_buyer_terms", []),
        }
    local_niche_requires_buyer = bool(niche.get("buyer_terms")) and not str(target or "").strip().lower() in {
        "", "global", "world", "worldwide", "international"
    }
    broad_context_families = {
        "government_data", "government_context", "academic_research", "statista_public_metadata",
        "macro_trend_data", "industry_trend_data", "public_web",
    }
    direct_local_evidence_families = {
        "local_operator_listing", "pricing_reference", "official_survey", "magazine_article",
        "blog_article", "reddit_practitioner", "youtube_transcript", "podcast_interview",
        "user_uploaded_interview", "user_uploaded_survey", "company_reports", "company_filings",
        "industry_pack_vendor",
    }
    section_allows_official_denominators = section_title in {
        "Market Size & Valuation", "Regional Analysis", "Regulatory Environment",
        "Market Forecast (2026-2031)", "Financial Forecasting Basis",
    }
    if (
        local_niche_requires_buyer
        and niche_match.get("decision") == "direct"
        and family in broad_context_families
        and family not in direct_local_evidence_families
    ):
        niche_match = dict(niche_match)
        if section_allows_official_denominators and family in {"government_data", "official_survey"}:
            niche_match["decision"] = "context"
            niche_match["tier"] = "Proxy"
            niche_match["score"] = min(float(niche_match.get("score", 0.0) or 0.0), 0.38)
            niche_match["reason"] = (
                f"{niche_match.get('reason')}; official/broad record can support denominators or policy context, "
                "but not direct local buyer/operator evidence"
            )
        else:
            return {
                "decision": "exclude",
                "score": 0.0,
                "reason": (
                    "local niche requires operator, pricing, buyer/survey, or trade evidence; "
                    f"{family} is context-only for this section"
                ),
                "evidence_tier": "Hypothesis",
                "matched_category_terms": niche_match.get("matched_category_terms", []),
                "matched_buyer_terms": niche_match.get("matched_buyer_terms", []),
            }
    if preferred_claims and claim_type not in preferred_claims:
        denominator_claim = claim_type == "market_denominator" or source_readiness_is_generic_country_denominator(record)
        if denominator_claim and section_title not in {
            "Executive Summary",
            "Market Size & Valuation",
            "Historical Market Data",
            "Regional Analysis",
            "Market Forecast (2026-2031)",
            "Financial Forecasting Basis",
            "Appendix & Methodology",
            "Cited Market Intelligence Ledger",
        }:
            return {
                "decision": "exclude",
                "score": 0.0,
                "reason": f"claim type {claim_type} is context-only for {section_title}",
                "evidence_tier": "Proxy",
                "matched_category_terms": niche_match.get("matched_category_terms", []),
                "matched_buyer_terms": niche_match.get("matched_buyer_terms", []),
            }
    route = DOMAIN_SOURCE_ROUTING.get(domain, {})
    haystack = record_text_blob(record).lower()
    tags = " ".join(str(tag).lower() for tag in record.get("topic_tags", []))
    preferred = set(route.get("preferred_families", set())) or {
        "government_data", "company_filings", "company_reports", "analyst_report",
        "industry_pack_government", "industry_pack_regulation", "industry_pack_analyst",
        "industry_pack_company", "industry_pack_vendor", "official_survey",
        "pricing_reference", "implementation_benchmark", "procurement_cycle_evidence",
        "magazine_article", "blog_article", "reddit_practitioner", "youtube_transcript",
        "podcast_interview", "user_uploaded_interview", "user_uploaded_survey",
        "academic_research", "iidatech_2026_financial_model_bank",
        "local_operator_listing",
    }
    specialized_terms = tuple(route.get("specialized_terms", ())) or tuple(DOMAIN_POSITIVE_TERMS.get(domain, ()))
    blocked_terms = tuple(route.get("blocked_terms", ())) + tuple(DOMAIN_FORBIDDEN_TERMS.get(domain, ()))
    domain_hits = [term for term in specialized_terms if contains_domain_term(haystack, term) or contains_domain_term(tags, term)]
    blocked_hits = [term for term in blocked_terms if contains_domain_term(haystack, term)]
    section_terms = DOMAIN_ROUTING_SECTION_TERMS.get(section_title, ())
    section_hits = [term for term in section_terms if contains_domain_term(haystack, term)]
    confidence = record_domain_confidence(record, domain, topic, industry)

    if family in DOMAIN_BLOCKED_SOURCE_FAMILIES.get(domain, set()):
        return {
            "decision": "exclude",
            "score": 0.0,
            "reason": f"blocked source family for {domain}: {family}",
            "evidence_tier": "Hypothesis",
            "matched_category_terms": niche_match.get("matched_category_terms", []),
            "matched_buyer_terms": niche_match.get("matched_buyer_terms", []),
        }
    if blocked_hits and len(domain_hits) < 2 and confidence < 0.55:
        return {
            "decision": "exclude",
            "score": 0.0,
            "reason": f"wrong-domain terms detected: {', '.join(blocked_hits[:3])}",
            "evidence_tier": "Hypothesis",
            "matched_category_terms": niche_match.get("matched_category_terms", []),
            "matched_buyer_terms": niche_match.get("matched_buyer_terms", []),
        }

    score = confidence * 0.55
    if preferred_claims and claim_type in preferred_claims:
        score += 0.14
    elif preferred_claims:
        score -= 0.12
    if family in preferred:
        score += 0.2
    if family == "academic_research":
        score += 0.08
    if domain_hits:
        score += min(0.18, 0.035 * len(set(domain_hits)))
    if section_hits:
        score += min(0.12, 0.04 * len(set(section_hits)))
    if family in {"government_data", "official_survey", "official_financial_data", "official_health_data"} and section_title in {
        "Market Size & Valuation", "Regional Analysis", "Consumer Behavior", "Financial Forecasting Basis", "Market Forecast (2026-2031)"
    }:
        score += 0.08
        if confidence >= 0.38:
            score = max(score, 0.5)
    if record.get("proxy_geography_for"):
        score -= 0.08

    score = max(0.0, min(1.0, score))
    if niche_match["decision"] == "context":
        score = min(score, 0.35)
    elif niche_match["decision"] == "proxy":
        score = min(score + 0.05, 0.69)
    elif niche_match["decision"] == "direct":
        score += 0.08

    score = max(0.0, min(1.0, score))
    tag_blob = " ".join(str(tag).lower() for tag in record.get("topic_tags", []))
    structured_direct = (
        "structured_extraction" in tag_blob
        and confidence >= 0.38
        and niche_match["decision"] in {"direct", "proxy"}
        and family in {"pricing_reference", "competitor_intelligence", "review_platform", "buyer_signal"}
    )
    if structured_direct:
        score = max(score, 0.78)
        decision = "direct"
    elif score >= 0.72 and niche_match["decision"] == "direct":
        decision = "direct"
    elif score >= 0.46 and niche_match["decision"] in {"direct", "proxy"}:
        decision = "proxy"
    else:
        decision = "exclude"
    reason_bits = []
    if family in preferred:
        reason_bits.append(f"preferred source family: {family}")
    if domain_hits:
        reason_bits.append("domain terms: " + ", ".join(domain_hits[:5]))
    if section_hits:
        reason_bits.append("section terms: " + ", ".join(section_hits[:4]))
    if not reason_bits:
        reason_bits.append("weak domain/section fit")
    reason_bits.append(f"niche gate: {niche_match.get('decision')} - {niche_match.get('reason')}")
    if record_trace_enabled():
        trace_record_stage(
            record,
            stage="source_precision_check",
            accepted=decision in {"direct", "proxy", "context", "model"},
            rejection_reason="" if decision != "exclude" else "; ".join(reason_bits),
            quality_score=round(score * 100, 1),
            detected_record_type=str(claim_type or record.get("record_type") or ""),
        )
    return {
        "decision": decision,
        "score": round(score, 2),
        "reason": "; ".join(reason_bits),
        "evidence_tier": niche_match.get("tier", "Hypothesis"),
        "matched_category_terms": niche_match.get("matched_category_terms", []),
        "matched_buyer_terms": niche_match.get("matched_buyer_terms", []),
    }


def compact_evidence_record_score(record: dict, section_title: str, topic: str, industry: str, target: str) -> float:
    record = normalize_evidence_record_schema(record, target=target, industry=industry)
    roles = set(record.get("roles", []) or [])
    family = str(record.get("source_family", "") or "").lower()
    access_class = source_access_class_for_record(record)
    haystack = " ".join(
        str(record.get(field, ""))
        for field in ("title", "publisher", "metric_name", "metric_value", "unit", "compact_fact", "source_family")
    ).lower()
    query_terms = {
        token
        for token in re.findall(r"[a-z0-9]+", f"{topic} {industry} {target} {section_title}".lower())
        if len(token) > 3
    }
    preferred_tags = SECTION_EVIDENCE_TAGS.get(section_title, []) + DOMAIN_EVIDENCE_TAGS.get(classify_topic_domain(topic, industry), [])
    score = float(record.get("quality_score", 0) or 0)
    if claim_type_matches_section(record, section_title):
        score += 10
    elif source_readiness_is_generic_country_denominator(record):
        score -= 18
    if access_class == "free_public_or_open" and not is_metadata_only_evidence(record):
        score += 6
    elif access_class in {"public_metadata_cross_check", "source_route_only"}:
        score -= 45
    elif access_class == "paid_or_limited":
        score -= 8
    if family == "statista_public_metadata":
        score -= 35
    score += 18 if record.get("quality_grade") == "A" else 8 if record.get("quality_grade") == "B" else 0
    score += 12 if record.get("is_hard_numeric_candidate") or record.get("can_support_hard_numeric_claim") else 0
    score += sum(2 for term in query_terms if term in haystack)
    score += sum(4 for tag in preferred_tags if str(tag).lower() in haystack)
    section_role_map = {
        "Market Size & Valuation": {"denominator", "pricing_or_value", "financial_benchmark", "numeric_input"},
        "Pricing Analysis": {"pricing", "pricing_or_value", "cost_or_margin", "financial_benchmark"},
        "Consumer Behavior": {"buyer_or_practitioner_voice", "verified_survey", "serviceability_or_adoption", "capture_or_penetration"},
        "Regulatory Environment": {"regulatory_or_compliance", "official_source", "cost_or_margin"},
        "Financial Forecasting Basis": {"pricing_or_value", "cost_or_margin", "retention_or_churn", "financial_benchmark", "numeric_input"},
        "Market Forecast (2026-2031)": {"serviceability_or_adoption", "capture_or_penetration", "retention_or_churn", "denominator"},
        "Go-To-Market Playbook": {"buyer_or_practitioner_voice", "capture_or_penetration", "verified_survey", "pricing"},
    }
    score += 10 * len(roles.intersection(section_role_map.get(section_title, set())))
    if str(record.get("geography", "")).strip().lower() == str(target or "").strip().lower():
        score += 10
    return score


def fetch_compact_retrieval_context(topic: str, industry: str, target: str, section: dict, max_records: int | None = None) -> str:
    lookup = compact_retrieval_pack_lookup()
    if not lookup:
        return ""
    domain = classify_topic_domain(topic, industry)
    pack = active_pack_for_industry_domain(industry, domain, topic)
    pack_id = str(pack.get("pack_id", "")).strip()
    if not pack_id:
        return ""
    target_key = str(target or "").strip().lower()
    pack_row = lookup.get((pack_id, target_key)) or lookup.get((pack_id, "global"))
    if not pack_row:
        return ""
    section_title = str(section.get("title", "Executive Summary"))
    section_records = (pack_row.get("section_records") or {}).get(section_title) or pack_row.get("general_records") or []
    if not section_records:
        return ""
    limit = max(4, min(int(max_records or COMPACT_EVIDENCE_MAX_RECORDS), COMPACT_EVIDENCE_MAX_RECORDS))
    selected = sorted(
        section_records,
        key=lambda row: compact_evidence_record_score(row, section_title, topic, industry, target),
        reverse=True,
    )[:limit]
    if not selected:
        return ""
    blocks = []
    seen = set()
    for record in selected:
        record = normalize_evidence_record_schema(record, target=target, industry=industry)
        url = str(record.get("url", "")).strip()
        key = url or str(record.get("record_id", ""))
        if key and key in seen:
            continue
        seen.add(key)
        fact = clean_text(str(record.get("compact_fact", "")), limit=COMPACT_EVIDENCE_FACT_CHARS)
        metric = " ".join(
            part for part in (
                str(record.get("metric_name", "")).strip(),
                "=" if record.get("metric_value") else "",
                str(record.get("metric_value", "")).strip(),
                str(record.get("unit", "")).strip(),
            )
            if part
        )
        blocks.append(
            f"[COMPACT DATASET | {str(record.get('source_family', 'source')).upper()} | "
            f"{record.get('evidence_label', 'EVIDENCE')} | quality {record.get('quality_grade', '?')} "
            f"{record.get('quality_score', 'n/a')}/100]\n"
            f"Title: {record.get('title', 'Untitled')}\n"
            f"Publisher: {record.get('publisher', 'unknown')} | Geography: {record.get('geography', 'unknown')} | Year: {record.get('year', '')}\n"
            f"Claim type: {record.get('claim_type', 'context')} | Evidence tier: {record.get('evidence_tier', '')}\n"
            f"Allowed use: {record.get('allowed_use', '')}\n"
            f"Roles: {', '.join(record.get('roles', [])[:8])}\n"
            f"Metric: {metric}\n"
            f"Fact: {fact}\n"
            f"Source: {url}"
        )
    if not blocks:
        return ""
    return (
        "COMPACT VERIFIED EVIDENCE PACK "
        "(token-minimized; full records remain in the evidence index and source datasets):\n"
        + "\n\n".join(blocks)
    )


def _score_market_record_for_section(
    record: dict,
    *,
    topic: str,
    industry: str,
    target: str,
    section: dict,
    domain: str,
    query_terms: set[str],
    preferred_tags: list,
    preferred_claims: set[str],
    quality_lookup: dict,
    min_domain_confidence: float,
    exact_local_or_operator_niche: bool,
    market_niche: dict,
    country_mode: bool,
    target_l: str,
) -> tuple[float, dict, dict] | None:
    record = normalize_evidence_record_schema(record, target=target, industry=industry)
    quality_row = quality_lookup.get(str(record.get("id", "")).strip()) if quality_lookup else None
    if quality_row and (quality_row.get("is_route_only") or quality_row.get("is_synthetic")):
        return None
    if quality_row and domain != "general_market" and domain not in (quality_row.get("domains") or []):
        return None
    if is_metadata_only_evidence(record):
        return None
    domain_confidence = record_domain_confidence(record, domain, topic, industry)
    if domain != "general_market" and domain_confidence < min_domain_confidence:
        return None
    source_precision = source_precision_check(record, domain, section["title"], topic, industry, target)
    if source_precision["decision"] == "exclude":
        return None
    generic_denominator = source_readiness_is_generic_country_denominator(record)
    claim_type = canonical_claim_type(record.get("claim_type", ""))
    record_tags = [str(t).lower() for t in record.get("topic_tags", [])]
    haystack = " ".join(
        str(record.get(field, ""))
        for field in ("title", "publisher", "source_family", "geography", "metric_name", "topic_tags", "text")
    ).lower()
    record_geography = str(record.get("geography", "")).lower()
    family = str(record.get("source_family", "source"))
    access_class = source_access_class_for_record(record)
    section_title_for_score = str(section.get("title", ""))
    if exact_local_or_operator_niche and generic_denominator and section_title_for_score in {
        "Competitive Landscape",
        "Key Player Profiles",
        "Market Share Analysis",
        "Pricing Analysis",
        "Consumer Behavior",
        "Go-To-Market Playbook",
        "Founder Build Plan",
        "Operating Model & Hiring Plan",
    }:
        return None
    score = float(sum(1 for term in query_terms if len(term) > 2 and term in haystack))
    score += sum(3 for tag in preferred_tags if tag.lower() in record_tags or tag.lower() in haystack)
    if preferred_claims and claim_type in preferred_claims:
        score += 14
    elif preferred_claims and generic_denominator:
        score -= 18
    elif preferred_claims and claim_type not in {"context", ""}:
        score -= 6
    score += float(source_precision.get("score", 0.0)) * 6
    if exact_local_or_operator_niche:
        niche_match = record_market_niche_match(record, market_niche, target, topic, industry)
        local_direct_families = {
            "pricing_reference", "local_operator_listing", "magazine_article", "blog_article",
            "company_reports", "company_filings", "industry_pack_vendor", "official_survey",
            "government_data", "user_uploaded_interview", "user_uploaded_survey",
            "reddit_practitioner", "youtube_transcript", "podcast_interview",
        }
        if niche_match.get("decision") == "direct":
            score += 34
            if family in local_direct_families:
                score += 16
        elif niche_match.get("decision") in {"proxy", "context"}:
            score -= 22
        else:
            score -= 35
        if generic_denominator:
            score -= 28
        if str(target or "").strip().lower() in haystack or str(target or "").strip().lower() in record_geography:
            score += 10
        if record_geography in {"global", "world", "worldwide", "international", "configurable"} or "global" in record_geography:
            score -= 18
    if domain == "ai_workflow_automation" and any(tag in haystack for tag in ("workflow", "automation", "smb", "ai", "pricing", "governance", "adoption", "digital")):
        score += 4
    if domain == "agriculture" and any(tag in haystack for tag in ("agriculture", "agri", "farmer", "apeda", "nabard", "fao", "rural", "export", "crop", "procurement")):
        score += 4
    if domain == "fashion" and any(tag in haystack for tag in ("fashion", "apparel", "clothing", "textile", "luxury", "comtrade", "census", "otexa", "inditex", "h&m")):
        score += 4
    if section["title"].lower().split()[0] in haystack:
        score += 2
    score += domain_confidence * 8
    if access_class == "free_public_or_open":
        score += 5
    elif access_class == "paid_or_limited":
        score -= 5
    elif access_class in {"public_metadata_cross_check", "source_route_only"}:
        score -= 35
    if quality_row:
        quality_score = int(quality_row.get("quality_score", 0) or 0)
        quality_grade = str(quality_row.get("quality_grade", "D"))
        score += min(12, quality_score / 8)
        if quality_grade == "A":
            score += 5
        elif quality_grade == "B":
            score += 2
        elif quality_grade == "D":
            score -= 10
        if target_l in {str(country).lower() for country in quality_row.get("countries", [])}:
            score += 4
        if target_l in {str(region).lower() for region in quality_row.get("regions", [])}:
            score += 3
    score *= SOURCE_FAMILY_WEIGHTS.get(record.get("source_family", ""), 1.0)
    if country_mode and target_l in str(record.get("geography", "")).lower() and not record.get("proxy_geography_for"):
        score += 5
        metric = str(record.get("metric_name", "")).lower()
        section_title = str(section.get("title", ""))
        if section_title in {"Consumer Behavior", "Market Trends", "Market Forecast (2026-2031)"} and any(
            term in metric for term in ("internet", "broadband", "mobile")
        ):
            score += 7
        if section_title in {"Market Size & Valuation", "Financial Forecasting Basis", "Pricing Analysis"} and any(
            term in metric for term in ("gdp", "business", "population")
        ):
            score += 0 if exact_local_or_operator_niche else 5
        if section_title in {"Go-To-Market Playbook", "Executive Summary"} and any(
            term in metric for term in ("internet", "business", "broadband")
        ):
            score += 0 if exact_local_or_operator_niche else 5
    elif record.get("proxy_geography_for"):
        score *= 0.75
    try:
        age = max(0, 2026 - int(str(record.get("year", "2022"))[:4]))
        score += max(0, 2 - age * 0.35)
    except Exception:
        pass
    if score <= 0:
        return None
    return score, record, source_precision


def _select_scored_market_records(
    scored: list[tuple[float, dict, dict]],
    *,
    section: dict,
    max_records: int,
    exact_local_or_operator_niche: bool,
    quality_lookup: dict,
) -> tuple[list[dict], dict, dict]:
    selected: list[dict] = []
    publisher_counts: dict = {}
    family_counts: dict = {}
    context_denominator_count = 0
    max_context_denominator = max(1, int(max_records * 0.15))
    metadata_only_families = {"country_industry_pack", "country_pack_official_profile"}
    selected_quality: dict = {}
    selected_precision: dict = {}
    if section["title"] == "Regulatory Environment":
        for _, record, _source_precision in sorted(scored, key=lambda item: item[0], reverse=True):
            publisher = record.get("publisher", "unknown")
            family = record.get("source_family", "source")
            haystack = " ".join(
                str(record.get(field, ""))
                for field in ("title", "publisher", "source_family", "geography", "metric_name", "topic_tags", "text")
            ).lower()
            if is_metadata_only_evidence(record) or str(record.get("url", "")).startswith("internal://"):
                continue
            if not (
                family in {"industry_pack_regulation", "healthcare_regulatory_source", "compliance_case_study"}
                or "regulat" in haystack
                or "certification" in haystack
                or "compliance" in haystack
            ):
                continue
            if publisher_counts.get(publisher, 0) >= 2:
                continue
            if family_counts.get(family, 0) >= 5:
                continue
            selected.append(record)
            selected_quality[record.get("id") or record.get("title")] = quality_lookup.get(str(record.get("id", "")).strip()) if quality_lookup else None
            publisher_counts[publisher] = publisher_counts.get(publisher, 0) + 1
            family_counts[family] = family_counts.get(family, 0) + 1
            if len(selected) >= min(max_records, 5):
                break
    for _, record, source_precision in sorted(scored, key=lambda item: item[0], reverse=True):
        publisher = record.get("publisher", "unknown")
        family = record.get("source_family", "source")
        if any((record.get("id") or record.get("title")) == (existing.get("id") or existing.get("title")) for existing in selected):
            continue
        if is_metadata_only_evidence(record):
            continue
        if family in metadata_only_families:
            continue
        generic_denominator = source_readiness_is_generic_country_denominator(record)
        if exact_local_or_operator_niche and generic_denominator:
            if context_denominator_count >= max_context_denominator:
                continue
        if publisher_counts.get(publisher, 0) >= 3:
            continue
        if family_counts.get(family, 0) >= 6:
            continue
        selected.append(record)
        if exact_local_or_operator_niche and generic_denominator:
            context_denominator_count += 1
        selected_precision[record.get("id") or record.get("title")] = source_precision
        selected_quality[record.get("id") or record.get("title")] = quality_lookup.get(str(record.get("id", "")).strip()) if quality_lookup else None
        publisher_counts[publisher] = publisher_counts.get(publisher, 0) + 1
        family_counts[family] = family_counts.get(family, 0) + 1
        if len(selected) >= max_records:
            break
    return selected, selected_precision, selected_quality


def _format_local_market_dataset_blocks(
    selected: list[dict],
    *,
    section: dict,
    domain: str,
    topic: str,
    industry: str,
    target: str,
    country_mode: bool,
    selected_precision: dict,
    selected_quality: dict,
) -> str:
    blocks = []
    for record in selected:
        evidence_label = evidence_label_for_record(record)
        access_class = source_access_class_for_record(record)
        source_precision = selected_precision.get(record.get("id") or record.get("title")) or source_precision_check(
            record, domain, section["title"], topic, industry, target
        )
        proof_role = "CONTEXT ONLY" if source_readiness_is_generic_country_denominator(record) or source_precision.get("decision") == "context" else "CLAIM EVIDENCE"
        quality_row = selected_quality.get(record.get("id") or record.get("title")) or {}
        quality_note = (
            f"Evidence quality: {quality_row.get('quality_grade', 'unindexed')} "
            f"({quality_row.get('quality_score', 'n/a')}/100; {quality_row.get('quality_reason', '')})\n"
            if quality_row
            else "Evidence quality: unindexed current-session record\n"
        )
        proxy_note = (
            f"Proxy geography: {record.get('proxy_geography_for')} (use as ESTIMATED proxy, not local proof)\n"
            if record.get("proxy_geography_for")
            else ""
        )
        blocks.append(
            f"[DATASET | {record.get('source_family', 'source').upper()} | {evidence_label} | "
            f"{proof_role} | "
            f"source route {source_precision.get('decision', 'unknown').upper()} | "
            f"precision {float(source_precision.get('score', 0)):.0%} | confidence {float(record.get('confidence', 0.7)):.0%}]\n"
            f"Title: {record.get('title', 'Untitled')}\n"
            f"Publisher: {record.get('publisher', 'unknown')} | Geography: {record.get('geography', 'unknown')} | Year: {record.get('year', '')}\n"
            f"Claim type: {record.get('claim_type', 'context')} | Evidence tier: {record.get('evidence_tier', '')}\n"
            f"Access policy: {access_class}\n"
            f"Allowed use: {record.get('allowed_use', '')}\n"
            f"{proxy_note}"
            f"{quality_note}"
            f"Evidence label: {evidence_label}\n"
            f"Domain/source route: {source_precision.get('decision', 'unknown')} - {source_precision.get('reason', '')}\n"
            f"Metric: {record.get('metric_name', '')} = {record.get('metric_value', '')} {record.get('unit', '')}\n"
            f"Summary: {record.get('text', '')[:900]}\n"
            f"Source: {record.get('url', '')}"
        )
    header = "COUNTRY-SPECIFIC LOCAL MARKET DATASETS" if country_mode else "LOCAL MARKET DATASETS"
    return f"{header}:\n" + "\n\n".join(blocks)


def _hydrate_vector_evidence_record(
    index_row: dict,
    raw_records_by_id: dict[str, dict],
    *,
    target: str,
    industry: str,
) -> dict:
    record_id = str(index_row.get("record_id") or index_row.get("id") or "").strip()
    raw = raw_records_by_id.get(record_id)
    if raw:
        merged = dict(raw)
        for key, value in index_row.items():
            if key.startswith("_"):
                merged[key] = value
            elif value not in (None, "") and key not in merged:
                merged[key] = value
        if not merged.get("id"):
            merged["id"] = record_id
        return merged
    fallback = {
        "id": record_id,
        "title": index_row.get("title", ""),
        "publisher": index_row.get("publisher", ""),
        "source_family": index_row.get("source_family", ""),
        "geography": index_row.get("geography", ""),
        "year": index_row.get("year", ""),
        "metric_name": index_row.get("metric_name", ""),
        "metric_value": index_row.get("metric_value", ""),
        "unit": index_row.get("unit", ""),
        "url": index_row.get("url", ""),
        "text": index_row.get("vector_text", ""),
        "topic_tags": index_row.get("topic_tags", []),
        "claim_type": index_row.get("claim_type", "context"),
        "confidence": index_row.get("confidence", 0.7),
    }
    for key, value in index_row.items():
        if key.startswith("_"):
            fallback[key] = value
    return normalize_evidence_record_schema(fallback, target=target, industry=industry)


def _try_vector_evidence_retrieval(
    topic: str,
    industry: str,
    target: str,
    section: dict,
    *,
    max_records: int,
    market_niche: dict,
    exact_local_or_operator_niche: bool,
    country_mode: bool,
) -> str | None:
    if not (
        ENABLE_EVIDENCE_VECTOR_RETRIEVAL
        and build_evidence_retrieval_query is not None
        and query_evidence_bank is not None
        and evidence_vector_index_ready is not None
        and evidence_vector_index_ready()
    ):
        return None

    section_title = str(section.get("title", ""))
    domain = classify_topic_domain(topic, industry)
    retrieval_family = section_retrieval_family(section_title) if section_retrieval_family else "general"
    query = build_evidence_retrieval_query(topic, industry, target, section_title)
    t0 = time.perf_counter()
    candidates, qmeta = query_evidence_bank(
        query,
        top_k=EVIDENCE_VECTOR_TOP_K,
        target=target,
        domain=domain,
        timeout_ms=VECTOR_QUERY_TIMEOUT_MS,
    )
    debug_mode = bool(globals().get("show_debug_data") or IIDATECH_RETRIEVAL_DEBUG)

    def _log_event(path_taken: str, fallback_reason: str | None, selected_count: int = 0) -> None:
        if RetrievalEvent is None or log_evidence_retrieval_event is None:
            return
        log_evidence_retrieval_event(
            RetrievalEvent(
                section_title=section_title,
                retrieval_family=retrieval_family,
                topic=topic,
                industry=industry,
                target=target,
                path_taken=path_taken,
                fallback_reason=fallback_reason,
                query_text=query,
                top_k_requested=EVIDENCE_VECTOR_TOP_K,
                vector_candidates=int(qmeta.get("vector_candidates", 0) or 0),
                after_hydrate=int(qmeta.get("after_hydrate", 0) or 0),
                selected_count=selected_count,
                max_records=max_records,
                vector_weight=VECTOR_RERANK_VECTOR_WEIGHT,
                business_weight=VECTOR_RERANK_BUSINESS_WEIGHT,
                timed_out=bool(qmeta.get("timed_out")),
                error=qmeta.get("error"),
                timing_ms=qmeta.get("timing_ms", {}),
                chroma_path=str(qmeta.get("chroma_path", "")),
                feature_flags={
                    "vector_retrieval_enabled": True,
                    "compact_short_circuit_skipped": selected_count >= EVIDENCE_VECTOR_MIN_SELECTED,
                },
                index=qmeta.get("index", {}),
            ),
            debug=debug_mode,
        )

    if qmeta.get("timed_out") or qmeta.get("error"):
        _log_event("vector_error", str(qmeta.get("error")))
        return None
    if not candidates:
        _log_event("vector_insufficient", "no_candidates")
        return None

    raw_records_by_id = {
        str(record.get("id", "")).strip(): record
        for record in target_record_filter(load_records_for_target(target), target)
        if str(record.get("id", "")).strip()
    }
    quality_lookup = evidence_quality_lookup()
    query_terms = set(re.findall(r"[a-z0-9]+", f"{topic} {industry} {target} {section_title}".lower()))
    preferred_tags = SECTION_EVIDENCE_TAGS.get(section_title, []) + DOMAIN_EVIDENCE_TAGS.get(domain, [])
    preferred_claims = section_claim_type_preferences(section_title)
    min_domain_confidence = 0.38 if domain != "general_market" else 0.0
    target_l = target.lower()

    scored_business: list[tuple[float, dict, dict, float]] = []
    for index_row in candidates:
        record = _hydrate_vector_evidence_record(
            index_row,
            raw_records_by_id,
            target=target,
            industry=industry,
        )
        result = _score_market_record_for_section(
            record,
            topic=topic,
            industry=industry,
            target=target,
            section=section,
            domain=domain,
            query_terms=query_terms,
            preferred_tags=preferred_tags,
            preferred_claims=preferred_claims,
            quality_lookup=quality_lookup,
            min_domain_confidence=min_domain_confidence,
            exact_local_or_operator_niche=exact_local_or_operator_niche,
            market_niche=market_niche,
            country_mode=country_mode,
            target_l=target_l,
        )
        if not result:
            continue
        business_score, normalized_record, source_precision = result
        vector_sim = float(index_row.get("_vector_similarity", 0.0) or 0.0)
        scored_business.append((business_score, normalized_record, source_precision, vector_sim))

    if not scored_business:
        _log_event("vector_insufficient", "precision_exclude")
        return None

    max_business = max(item[0] for item in scored_business) or 1.0
    fused_scored = [
        (
            (VECTOR_RERANK_VECTOR_WEIGHT * vector_sim)
            + (VECTOR_RERANK_BUSINESS_WEIGHT * (business_score / max_business)),
            record,
            source_precision,
        )
        for business_score, record, source_precision, vector_sim in scored_business
    ]
    selected, selected_precision, selected_quality = _select_scored_market_records(
        fused_scored,
        section=section,
        max_records=max_records,
        exact_local_or_operator_niche=exact_local_or_operator_niche,
        quality_lookup=quality_lookup,
    )
    if len(selected) < EVIDENCE_VECTOR_MIN_SELECTED:
        _log_event("vector_insufficient", "candidates_below_min", selected_count=len(selected))
        return None

    _log_event("vector_primary", None, selected_count=len(selected))
    qmeta.setdefault("timing_ms", {})
    qmeta["timing_ms"]["rerank_total"] = round((time.perf_counter() - t0) * 1000, 2)
    return _format_local_market_dataset_blocks(
        selected,
        section=section,
        domain=domain,
        topic=topic,
        industry=industry,
        target=target,
        country_mode=country_mode,
        selected_precision=selected_precision,
        selected_quality=selected_quality,
    )


def fetch_market_dataset_context(topic: str, industry: str, target: str, section: dict, max_records: int = 18) -> str:
    market_niche = identify_market_niche(topic, industry, target)
    exact_local_or_operator_niche = bool(market_niche.get("local_terms")) or local_niche_needs_operator_evidence(topic, industry, target)
    country_mode = is_country_specific_target(target)

    vector_context = _try_vector_evidence_retrieval(
        topic,
        industry,
        target,
        section,
        max_records=max_records,
        market_niche=market_niche,
        exact_local_or_operator_niche=exact_local_or_operator_niche,
        country_mode=country_mode,
    )
    if vector_context:
        return vector_context

    compact_context = fetch_compact_retrieval_context(topic, industry, target, section, max_records=max_records)
    if compact_context and not exact_local_or_operator_niche:
        return compact_context

    records = load_records_for_target(target, topic=topic, industry=industry)
    if not records:
        return "[Country-specific market datasets: not built yet]" if country_mode else "[Local market datasets: not built yet]"
    if synthetic_hard_isolation_enabled():
        records = [r for r in records if not _is_synthetic_record(r)]

    query_terms = set(re.findall(r"[a-z0-9]+", f"{topic} {industry} {target} {section['title']}".lower()))
    domain = classify_topic_domain(topic, industry)
    records = target_record_filter(records, target)
    quality_lookup = evidence_quality_lookup()
    min_domain_confidence = 0.38 if domain != "general_market" else 0.0
    domain_records = [
        record for record in records
        if record_domain_confidence(record, domain, topic, industry) >= min_domain_confidence
    ]
    if domain != "general_market" and len(domain_records) >= 4:
        records = domain_records
    preferred_tags = SECTION_EVIDENCE_TAGS.get(section["title"], []) + DOMAIN_EVIDENCE_TAGS.get(domain, [])
    preferred_claims = section_claim_type_preferences(section["title"])
    target_l = target.lower()
    scored = []
    for record in records:
        result = _score_market_record_for_section(
            record,
            topic=topic,
            industry=industry,
            target=target,
            section=section,
            domain=domain,
            query_terms=query_terms,
            preferred_tags=preferred_tags,
            preferred_claims=preferred_claims,
            quality_lookup=quality_lookup,
            min_domain_confidence=min_domain_confidence,
            exact_local_or_operator_niche=exact_local_or_operator_niche,
            market_niche=market_niche,
            country_mode=country_mode,
            target_l=target_l,
        )
        if result:
            scored.append(result)

    selected, selected_precision, selected_quality = _select_scored_market_records(
        scored,
        section=section,
        max_records=max_records,
        exact_local_or_operator_niche=exact_local_or_operator_niche,
        quality_lookup=quality_lookup,
    )
    if not selected:
        return (
            "[Country-specific market datasets: no direct evidence records matched this topic and section. "
            "Routing metadata was excluded as evidence.]"
            if country_mode
            else "[Local market datasets: no direct evidence records matched this topic and section.]"
        )

    return _format_local_market_dataset_blocks(
        selected,
        section=section,
        domain=domain,
        topic=topic,
        industry=industry,
        target=target,
        country_mode=country_mode,
        selected_precision=selected_precision,
        selected_quality=selected_quality,
    )


def select_market_records(topic: str, industry: str, target: str, section_title: str, max_records: int = 16) -> list[dict]:
    _pool_size = max(30, max_records * 2)
    section = {"title": section_title}
    context = fetch_market_dataset_context(topic, industry, target, section, max_records=_pool_size)
    _base = load_records_for_target(target, topic=topic, industry=industry)
    if synthetic_hard_isolation_enabled():
        _base = [r for r in _base if not _is_synthetic_record(r)]
    records = target_record_filter(_base, target)
    titles = [clean_text(title, limit=240) for title in re.findall(r"Title:\s*(.+)", context)]
    title_rank = {title: idx for idx, title in enumerate(titles)}
    selected = [
        r for r in records
        if clean_text(str(r.get("title", "")), limit=240) in title_rank
    ]
    selected = sorted(
        selected,
        key=lambda r: title_rank.get(clean_text(str(r.get("title", "")), limit=240), 9999),
    )
    if len(selected) < 8:
        domain = classify_topic_domain(topic, industry)
        min_conf = 0.38 if domain != "general_market" else 0.0
        topic_tokens = relevant_topic_tokens(topic, industry, target)
        already_ids = {id(r) for r in selected}
        scored = []
        for r in records:
            if id(r) in already_ids:
                continue
            if is_metadata_only_evidence(r):
                continue
            conf = record_domain_confidence(r, domain, topic, industry)
            if conf < min_conf:
                continue
            token_hits = sum(1 for t in topic_tokens if t in record_text_blob(r).lower())
            scored.append((conf + 0.05 * min(token_hits, 10), r))
        scored.sort(key=lambda x: x[0], reverse=True)
        selected = selected + [r for _, r in scored[: max(_pool_size - len(selected), 0)]]
    selected = _filter_records_by_diligence_relevance(
        selected,
        topic=topic,
        industry=industry,
        target=target,
        domain=classify_topic_domain(topic, industry),
        min_topic_match=0.15,
    )
    return selected[:max_records]


def _filter_records_by_diligence_relevance(
    records: list[dict],
    *,
    topic: str,
    industry: str,
    target: str,
    domain: str | None = None,
    min_topic_match: float = 0.20,
) -> list[dict]:
    """Unified cross-domain relevance gate for ledgers, sections, and pricing packs."""
    _ = min_topic_match  # canonical gate uses domain confidence, not token overlap score
    domain_key = domain or classify_topic_domain(topic, industry)
    try:
        from iidatech.validation.relevance_gate import is_record_relevant_to_report

        return [
            record
            for record in records
            if isinstance(record, dict)
            and is_record_relevant_to_report(record, topic, industry, domain_key)[0]
        ]
    except Exception:
        return [r for r in records if isinstance(r, dict)]


