def section_specialist_profile(section_title: str) -> tuple[str, str]:
    return SECTION_SPECIALIST_PROFILES.get(
        section_title,
        ("Business Research Specialist", "turn the section evidence into decision-grade business implications"),
    )


def _record_year_value(record: dict) -> int:
    match = re.search(r"20\d\d|19\d\d", str(record.get("year", "") or record.get("retrieved_at", "")))
    return int(match.group(0)) if match else 0


def _record_source_anchor(record: dict) -> str:
    title = clean_text(record.get("title") or "Untitled source", limit=92)
    publisher = clean_text(record.get("publisher") or record.get("source_family") or "source", limit=48)
    year = str(record.get("year") or "").strip()
    label = evidence_label_for_record(record) if isinstance(record, dict) else "SOURCE"
    metric = clean_text(
        " ".join(
            str(x or "")
            for x in (record.get("metric_name"), record.get("metric_value"), record.get("unit"))
        ),
        limit=90,
    )
    year_part = f", {year}" if year else ""
    metric_part = f" ({metric})" if metric.strip() else ""
    return f"{label}: {publisher}{year_part} - {title}{metric_part}"


def _source_connection_summary(records: list[dict]) -> str:
    families = {str(r.get("source_family", "")).lower() for r in records}
    has_official = bool(families & {"government_data", "official_survey", "official_financial_data", "company_filings"})
    has_market = bool(families & {"pricing_reference", "financial_market_data", "valuation_data", "funding_data", "company_reports"})
    has_voice = bool(families & {"reddit_practitioner", "youtube_transcript", "podcast_interview", "official_survey", "user_uploaded_survey", "user_uploaded_interview"})
    has_policy = any("regulat" in str(r.get("topic_tags", "")).lower() or "compliance" in str(r.get("topic_tags", "")).lower() for r in records)
    parts = []
    if has_official:
        parts.append("official denominators")
    if has_market:
        parts.append("pricing/financial/comparable evidence")
    if has_voice:
        parts.append("buyer or practitioner voice")
    if has_policy:
        parts.append("policy or regulatory evidence")
    return ", ".join(parts) if parts else "available source routes and proxy records only"


def business_specialist_addendum_lines(
    topic: str,
    industry: str,
    target: str,
    sec: dict,
    market_model: dict,
    diligence_pack: dict,
) -> list[str]:
    section_title = sec.get("title", "")
    specialist, mandate = section_specialist_profile(section_title)
    domain = classify_topic_domain(topic, industry)
    records = select_market_records(topic, industry, target, section_title, max_records=10)
    if not records and section_title != "Topic Intelligence Brief":
        records = select_market_records(topic, industry, target, "Topic Intelligence Brief", max_records=6)
    anchors = [_record_source_anchor(record) for record in records[:4]]
    direct_records = [
        record for record in records
        if evidence_label_for_record(record).startswith("VERIFIED")
    ]
    years = [_record_year_value(record) for record in records]
    latest_year = max([year for year in years if year], default=0)
    source_connection = _source_connection_summary(records)
    readiness = (diligence_pack.get("source_readiness_preflight", {}) or {}) if isinstance(diligence_pack, dict) else {}
    readiness_status = readiness.get("status") or readiness.get("quality_matrix_status") or "not indexed"
    score = readiness.get("score") or readiness.get("score_10") or "n/a"
    model_basis = "Use the stored quantitative model only as VERIFIED when its source gates pass; otherwise label it ESTIMATED or SYNTHETIC MODEL."
    if section_title in {"Market Size & Valuation", "Future Outlook & Forecast", "Startup Budget & Revenue Model", "Digital Behavior, Retention & Unit Economics"}:
        model_basis = "Use bottom-up math: buyer count x adoption/filter x price x retention/capacity; show each input source before TAM/SAM/SOM or revenue."
    elif section_title in {"Pricing Analysis", "Comparables, Multiples & Valuation Support"}:
        model_basis = "Use pricing pages, filings, market values, and denominators on the same date; otherwise show a valuation framework, not a hard multiple."
    elif section_title in {"Regulatory Environment", "Certification, Compliance & Launch Timeline"}:
        model_basis = "Use country law, regulator, standards, and certification records as launch gates with time/cost ranges only when directly sourced."
    elif section_title in {"Consumer Behavior", "Primary Research, Surveys & Interview Findings"}:
        model_basis = "Use surveys, transcripts, Reddit/podcast practitioner signals, and uploaded calls as buyer-language evidence, not hard market-size proof."
    anchor_text = "; ".join(anchors) if anchors else "No direct source selected for this section yet; use the source collection backlog before external use."
    latest_text = (
        f"Latest selected-source year is {latest_year}; do not imply a newer figure unless a 2026 record is selected."
        if latest_year and latest_year < 2026
        else "Selected evidence includes 2026/current-source routing or current records where available."
    )
    direct_text = (
        f"{len(direct_records)} selected records are direct/verified enough to support factual claims."
        if direct_records
        else "No selected direct hard-figure record was found; numeric claims must stay estimated or methodological."
    )
    return [
        f"1. Specialist: {specialist} - mandate is to {mandate}.",
        f"2. Scope lock: this line interprets '{section_title}' only for '{topic}' in {target}, within the {domain} evidence route.",
        f"3. Source anchors: {anchor_text}",
        f"4. Evidence connection: current section evidence links {source_connection}; weak links should become the next scrape or upload target.",
        f"5. Geography check: use {target}-specific records first; global or regional evidence is proxy context unless explicitly country-local.",
        f"6. Figure discipline: {model_basis}",
        f"7. 2026 freshness check: {latest_text}",
        f"8. Verification status: source readiness is {readiness_status} with score {score}; {direct_text}",
        f"9. Business implication: this section should change a buyer, product, GTM, hiring, compliance, pricing, or funding decision, not just describe the market.",
        "10. Analyst next step: replace the weakest proxy with one official/local source, one competitor/pricing source, and one buyer/practitioner signal before calling the section funding-ready.",
    ]


def append_business_specialist_addendum(
    output: str,
    topic: str,
    industry: str,
    target: str,
    sec: dict,
    market_model: dict,
    diligence_pack: dict,
) -> str:
    """Add a ten-line specialist readout without changing existing section keys."""
    addendum_key = "Business Research Specialist Addendum - 10 Lines"
    lines = business_specialist_addendum_lines(topic, industry, target, sec, market_model, diligence_pack)
    cleaned = re.sub(r"^```(?:json)?\s*|\s*```$", "", str(output or "").strip(), flags=re.MULTILINE)
    try:
        data = json.loads(cleaned)
        if isinstance(data, dict):
            if addendum_key not in data:
                data[addendum_key] = lines
            return json.dumps(data, ensure_ascii=False)
    except Exception:
        pass
    if addendum_key in cleaned:
        return cleaned
    return cleaned + "\n\n### " + addendum_key + "\n" + "\n".join(f"- {line}" for line in lines)


