            {"segment": "SMB-focused CRM", "competitor_archetypes": "HubSpot CRM, Zoho CRM, Freshsales, Pipedrive", "benchmark_metrics": "freemium conversion rate, ARPU, seat price/month, SMB review scores, time-to-value", "source_need": "vendor pricing pages, G2 SMB category, Capterra, earnings calls (HubSpot public)"},
