            {"segment": "RevOps / sales intelligence tools", "competitor_archetypes": "Outreach, Salesloft, Apollo, Clay, ZoomInfo", "benchmark_metrics": "seat price, contact enrichment cost, outbound volume, sequence open rates", "source_need": "pricing pages, G2 reviews, customer call notes"},
            {"segment": "Substitutes", "competitor_archetypes": "Spreadsheets, email folders, manual follow-up, generic task managers", "benchmark_metrics": "switching cost, time lost per rep, error rate, deal loss from no follow-up", "source_need": "buyer interviews and workflow observation"},
