            {"segment": "Technology suppliers", "competitor_archetypes": "membrane, filtration, biological treatment, ZLD, sludge-treatment suppliers", "benchmark_metrics": "recovery rate, energy use, chemical cost, fouling/maintenance, warranty", "source_need": "technical datasheets, pilot data, operator calls"},
