    return {**common, "domain": domain, "interview_plan": plans.get(domain, [
        {"respondent": "target buyers", "sample": "20-30", "questions": "pain, current alternative, budget, decision process, willingness to pay", "decision_use": "demand and pricing"},
        {"respondent": "competitors/channel partners", "sample": "8-12", "questions": "pricing, margins, sales cycle, objections", "decision_use": "competitive and GTM validation"},
        {"respondent": "operators/experts", "sample": "5-8", "questions": "cost stack, delivery risk, regulatory/technical barriers", "decision_use": "operational feasibility"},
    ])}


