def _build_tam_sam_som_provenance(calc: dict) -> list:
    """Build provenance claims for TAM, SAM, SOM from a calculation dict."""
    if not (build_formula_claim and compute_derived_confidence):
        return []
    base_confidence = 0.6
    tam_inputs = {
        "gdp_current_usd": calc.get("gdp_current_usd"),
        "industry_spend_share_of_gdp": calc.get("industry_spend_share_of_gdp_assumption"),
        "topic_wedge_share": calc.get("topic_wedge_share_assumption"),
        "digital_readiness_factor": calc.get("digital_readiness_factor"),
    }
    tam_conf = compute_derived_confidence([base_confidence], "tam_bottom_up")
    tam_claim = build_formula_claim(
        metric_name="TAM 2026",
        value=calc.get("tam_2026"),
        unit="USD",
        derived_from_claim_ids=[],
        formula_expression=calc.get("tam_formula", "GDP x industry_spend_share x topic_wedge_share x digital_readiness_factor"),
        formula_inputs=tam_inputs,
        formula_type="tam_bottom_up",
        confidence=tam_conf,
    )
    sam_inputs = {
        "tam_2026": calc.get("tam_2026"),
        "sam_share_assumption": calc.get("sam_share_assumption"),
    }
    sam_conf = compute_derived_confidence([tam_conf], "sam_filter")
    sam_claim = build_formula_claim(
        metric_name="SAM 2026",
        value=calc.get("sam_2026"),
        unit="USD",
        derived_from_claim_ids=[tam_claim["id"]],
        formula_expression=calc.get("sam_formula", "TAM x sam_share_assumption"),
        formula_inputs=sam_inputs,
        formula_type="sam_filter",
        confidence=sam_conf,
    )
    som_inputs = {
        "sam_2026": calc.get("sam_2026"),
        "som_capture_share_assumption": calc.get("som_capture_share_assumption"),
    }
    som_conf = compute_derived_confidence([sam_conf], "som_capture")
    som_claim = build_formula_claim(
        metric_name="SOM 2026",
        value=calc.get("som_2026"),
        unit="USD",
        derived_from_claim_ids=[sam_claim["id"]],
        formula_expression=calc.get("som_formula", "SAM x som_capture_share_assumption"),
        formula_inputs=som_inputs,
        formula_type="som_capture",
        confidence=som_conf,
    )
    return [tam_claim, sam_claim, som_claim]


def build_bottom_up_market_calculation(topic: str, industry: str, target: str, model: dict) -> dict:
    domain = classify_topic_domain(topic, industry)
    stored_model = stored_2026_financial_model(topic, industry, target)
    if stored_model:
        calc = stored_model.get("calculation", {}) or {}
        def short_usd(value) -> str:
            try:
                value = float(value)
            except Exception:
                return "n/a"
            if abs(value) >= 1_000_000_000:
                return f"${value / 1_000_000_000:.2f}B"
            if abs(value) >= 1_000_000:
                return f"${value / 1_000_000:.1f}M"
            if abs(value) >= 1_000:
                return f"${value / 1_000:.1f}K"
            return f"${value:,.0f}"

        base_tam = float(calc.get("tam_2026") or 0)
        base_sam = float(calc.get("sam_2026") or 0)
        base_som = float(calc.get("som_2026") or 0)
        # Zero-guard: GDP formula produced $0 — never show zero to end-users.
        if base_tam <= 0 or base_sam <= 0:
            _is_india = "india" in (target or "").lower()
            _clinic_domains = {"dental_saas", "clinic_workflow", "healthcare"}
            if domain in _clinic_domains:
                if _is_india:
                    tam_r, sam_r, som_r, cagr_r = "$50M–$250M", "$12M–$70M", "$1M–$10M", "10–18%"
                else:
                    tam_r, sam_r, som_r, cagr_r = "$500M–$2B", "$100M–$600M", "$5M–$60M", "9–15%"
            else:
                _fb = _TAM_FALLBACK_RANGES.get(domain)
                if not _fb:
                    _fb = ("$100M–$1B", "$20M–$250M", "$2M–$25M", "10–20%")
                tam_r, sam_r, som_r, cagr_r = _fb
            _lbl = "[ESTIMATED RANGE — LOW CONFIDENCE — NOT INVESTOR CITABLE]"
            return {
                "status": "template_estimated; GDP model produced zero — template range substituted",
                "formula": "buyer/clinic count x annual software spend (template heuristic)",
                "current_outputs": {
                    "Base TAM": f"{_lbl} {tam_r}",
                    "SAM": f"{_lbl} {sam_r}",
                    "SOM": f"{_lbl} {som_r}",
                    "Forecast CAGR": f"{_lbl} {cagr_r}",
                },
                "estimation_basis": (
                    f"GDP multiplier model returned $0 for domain '{domain}' / geography '{target}'. "
                    "Template range shown for directional use only. "
                    "Must be replaced with verified buyer-count, ACV, and adoption evidence."
                ),
                "not_investor_citable": True,
                "citation_allowed": False,
                "validation_needed": ["verified buyer/clinic count", "sourced ACV", "geography boundary", "adoption evidence"],
            }
        scenario_rows = []
        for scenario, factor, logic in [
            ("Bear", 0.65, "slower adoption, weaker serviceability, longer sales cycles, higher churn/support burden"),
            ("Base", 1.00, "stored 2026 planning model with current denominator and domain assumptions"),
            ("Bull", 1.45, "faster adoption, stronger pricing, higher capture, better retention and operating leverage"),
        ]:
            scenario_rows.append({
                "scenario": scenario,
                "tam": f"ESTIMATED {short_usd(base_tam * factor)}",
                "sam": f"ESTIMATED {short_usd(base_sam * factor)}",
                "som": f"ESTIMATED {short_usd(base_som * factor)}",
                "assumption_change": logic,
                "verification_status": "SYNTHETIC MODEL until denominator, price/value, adoption, capture, retention, and cost inputs pass source checks",
            })
        return {
            "status": "estimated_2026_model_available",
            "evidence_label": stored_model.get("evidence_label"),
            "formula": calc.get("tam_formula", "GDP x industry spend share x topic wedge share x digital readiness factor"),
            "current_outputs": {
                "Base TAM": f"ESTIMATED {calc.get('tam_2026_fmt', 'n/a')}",
                "SAM": f"ESTIMATED {calc.get('sam_2026_fmt', 'n/a')}",
                "SOM": f"ESTIMATED {calc.get('som_2026_fmt', 'n/a')}",
                "Forecast CAGR": f"ESTIMATED {float(calc.get('forecast_cagr_2026_2031_assumption', 0) or 0):.1%}",
            },
            "calculation_inputs": {
                "gdp_current_usd": calc.get("gdp_current_usd"),
                "population": calc.get("population"),
                "gdp_per_capita_current_usd": calc.get("gdp_per_capita_current_usd"),
                "internet_users_pct": calc.get("internet_users_pct"),
                "digital_readiness_factor": calc.get("digital_readiness_factor"),
                "industry_spend_share_of_gdp_assumption": calc.get("industry_spend_share_of_gdp_assumption"),
                "topic_wedge_share_assumption": calc.get("topic_wedge_share_assumption"),
                "sam_share_assumption": calc.get("sam_share_assumption"),
                "som_capture_share_assumption": calc.get("som_capture_share_assumption"),
            },
            "scenario_assumption_rows": scenario_rows,
            "assumption_table": [
                {"input": "Denominator", "value": calc.get("gdp_current_usd"), "source_or_basis": "World Bank/source rows where available; not a buyer-count substitute"},
                {"input": "Industry spend share", "value": calc.get("industry_spend_share_of_gdp_assumption"), "source_or_basis": "IIDATECH domain assumption; validate with local filings, spend surveys, and comps"},
                {"input": "Topic wedge share", "value": calc.get("topic_wedge_share_assumption"), "source_or_basis": "IIDATECH topic-wedge assumption; validate against segment-specific source records"},
                {"input": "Serviceable share", "value": calc.get("sam_share_assumption"), "source_or_basis": "planning assumption; validate channel/geography/product boundary"},
                {"input": "Obtainable capture", "value": calc.get("som_capture_share_assumption"), "source_or_basis": "planning assumption; validate sales capacity, churn, competitors, and implementation throughput"},
                {"input": "CAGR", "value": calc.get("forecast_cagr_2026_2031_assumption"), "source_or_basis": "scenario assumption; not verified market CAGR"},
            ],
            "source_rows": stored_model.get("source_rows", []),
            "allowed_output": "Show as ESTIMATED, not VERIFIED, unless the strict 10-check gate passes every hard-figure input.",
            "verification_rule": "Every financial figure must show its formula and source rows. Verified and estimated figures are displayed separately.",
            "evidence_namespace": "SYNTHETIC MODEL",
            "citation_allowed": False,
            "not_investor_citable": True,
            "provenance_claims": _build_tam_sam_som_provenance(calc) if build_formula_claim else [],
        }
    if model.get("dashboard_mode") == "bottom_up_tam":
        _fb = _TAM_FALLBACK_RANGES.get(domain)
        if _fb:
            tam_r, sam_r, som_r, cagr_r = _fb
            return {
                "status": "template_estimated; replace with verified buyer-count and ACV inputs before investor use",
                "formula": "reachable buyers x annual software spend (template heuristic)",
                "current_outputs": {
                    "Base TAM": f"[ESTIMATED RANGE — LOW CONFIDENCE] {tam_r}",
                    "SAM": f"[ESTIMATED RANGE — LOW CONFIDENCE] {sam_r}",
                    "SOM": f"[ESTIMATED RANGE — LOW CONFIDENCE] {som_r}",
                    "Forecast CAGR": f"[ESTIMATED RANGE — LOW CONFIDENCE] {cagr_r}",
                },
                "estimation_basis": (
                    f"Template heuristics for domain '{domain}'. "
                    "Must be replaced with verified denominator (buyer count), "
                    "sourced ACV/pricing, and adoption evidence before investor use."
                ),
                "validation_needed": [
                    "verified buyer-count denominator",
                    "sourced ACV or annual software spend",
                    "adoption/churn evidence by segment",
                    "serviceable geography boundary",
                    "channel and capture evidence",
                ],
                "scenario_assumption_rows": [
                    {"scenario": "Bear", "assumption_change": "lower reachable-account count, lower ACV, higher churn", "output_rule": "use low end of estimated range"},
                    {"scenario": "Base", "assumption_change": "midpoint of template range; replace with source-backed inputs", "output_rule": "show as ESTIMATED until verified"},
                    {"scenario": "Bull", "assumption_change": "higher adoption, stronger pricing power, faster category growth", "output_rule": "use high end of estimated range"},
                ],
                "allowed_output": "Template range shown transparently; not a verified figure.",
            }
        return {
            "status": "strict_source_gated; model outputs are hidden until the 10-check verification gate passes",
            "formula": "reachable software-mature SMBs x ACV",
            "current_outputs": {
                "Base TAM": "WITHHELD until denominator, ACV/price, and adoption/serviceability inputs pass strict verification",
                "SAM": "WITHHELD until the TAM gate and serviceable-market boundary pass strict verification",
                "SOM": "WITHHELD until capture/channel and retention/churn inputs pass strict verification",
                "Forecast CAGR": "WITHHELD until baseline, adoption, price, churn, and cost inputs pass strict verification",
            },
            "validation_needed": ["regional SMB universe", "workflow-specific ACV", "adoption/churn by customer segment", "capture/channel evidence", "cost and margin evidence"],
            "scenario_assumption_rows": [
                {"scenario": "Bear", "assumption_change": "lower reachable-account count, lower ACV, higher churn/support cost", "output_rule": "show formula and missing inputs"},
                {"scenario": "Base", "assumption_change": "validated buyer segment, sourced price/value, realistic capture", "output_rule": "show estimate only after inputs are labeled"},
                {"scenario": "Bull", "assumption_change": "strong adoption and retention with sales/implementation capacity proven", "output_rule": "show as upside sensitivity, not verified forecast"},
            ],
            "allowed_output": "formula, missing-input table, and verified source rows only until every input passes the strict verification gate",
        }
    formulas = {
        "fashion": "reachable buyers x purchase frequency x AOV, cross-checked against retail/trade/company data",
        "agriculture": "production or procured volume x realized price/take rate, cross-checked against official production/trade/procurement data",
        "water_environment": "eligible facilities x flow volume (m3/day) x capex per m3/day plus O&M revenue, cross-checked against permits/tenders/vendor quotes",
        "finance": "eligible customers or transaction volume x take rate/spread, net of losses/funding/compliance cost",
        "healthcare": "separate wedge formulas: hospital RCM = eligible hospitals x net patient revenue affected x denial/recovery opportunity x vendor take/ACV; practice billing = practices x claims/month x fee/claim or billing fee %; clinical registry = reporting facilities x annual software/service fee; diagnostic lab = tests x reimbursed price x billing/recovery fee; regulated SaMD = cleared/approved addressable sites x license/usage price",
        "energy": "eligible capacity/load x utilization x tariff/savings share, adjusted for capex, financing, degradation, and policy",
    }
    return {
        "status": "source_gated",
        "formula": formulas.get(domain, "eligible customers/units x price x frequency, adjusted for channel and cost-to-serve"),
        "required_inputs": [row.get("required_data") for row in model.get("formula_rows", []) if row.get("required_data")],
        "scenario_assumption_rows": [
            {"scenario": "Bear", "must_vary": "denominator, adoption, price, gross margin, churn/retention, compliance delay"},
            {"scenario": "Base", "must_vary": "source-backed denominator, realistic serviceability, priced package, measured cost-to-serve"},
            {"scenario": "Bull", "must_vary": "higher adoption/capture, expansion revenue, stronger retention, operating leverage"},
        ],
        "allowed_output": "calculation structure and assumption table until source-matched inputs are available",
        "do_not_do": "Do not import generic global market numbers into this topic without source and scope match.",
    }


