def build_recent_funding_rounds(topic: str, industry: str, target: str) -> dict:
    domain = classify_topic_domain(topic, industry)
    from iidatech.validation.relevance_gate import is_record_relevant_to_report

    records = []
    for r in target_record_filter(load_records_for_target(target, topic=topic, industry=industry), target):
        if not is_record_relevant_to_report(r, topic, industry, domain)[0]:
            continue
        tag_blob = " ".join(str(x) for x in r.get("topic_tags", [])).lower()
        family = str(r.get("source_family", "")).lower()
        has_funding_signal = any(
            tag in tag_blob for tag in ("funding", "investment", "mna")
        ) or family in {"funding_data", "valuation_data"}
        if not has_funding_signal:
            continue
        records.append(r)
    records = sorted(
        records,
        key=lambda r: topic_match_detail(r, topic, industry, target).get("score", 0),
        reverse=True,
    )
    rounds = []
    for record in records[:12]:
        rounds.append({
            "company_or_segment": record.get("publisher", ""),
            "round_or_event": record.get("title", ""),
            "amount_or_metric": record.get("metric_value", ""),
            "evidence_label": evidence_label_for_diligence_record(record, topic, industry, target),
            "year": record.get("year", ""),
            "source": record.get("url", ""),
            "relevance": "Use only if the funded company/segment matches the topic; otherwise treat as investor-trend context.",
        })
    return {
        "domain": domain,
        "rounds": rounds,
        "source_rule": "Funding rounds must include company, date/year, amount when available, investor/source URL, and relevance to the selected market segment.",
        "gap_if_empty": "If no recent matching rounds are found, report this as a source gap and use investor thesis mapping instead of inventing rounds.",
    }


def build_comparable_company_multiples(topic: str, industry: str, target: str) -> dict:
    domain = classify_topic_domain(topic, industry)
    methods = {
        "fashion": "EV/sales, gross-margin quality, inventory turns, full-price sell-through, and brand durability; separate luxury, fast fashion, resale, and D2C.",
        "agriculture": "EV/EBITDA or EV/gross profit adjusted for working-capital intensity, commodity exposure, procurement reliability, and buyer concentration.",
        "ai_workflow_automation": "ARR multiple by growth, NRR/GRR, gross margin after model/API costs, CAC payback, retention, and workflow criticality.",
        "finance": "P/B, P/E, EV/revenue, take-rate/gross-profit multiple, adjusted for credit losses, funding cost, compliance, and capital intensity.",
        "healthcare": "EV/revenue or EV/EBITDA by provider/software/service mix, reimbursement exposure, clinical risk, and payer/provider retention.",
        "energy": "EV/EBITDA, EV/MW, project IRR, contracted revenue multiple, adjusted for offtake, leverage, capacity factor, and policy risk.",
        "water_environment": "EV/EBITDA or project gross-profit multiple; for technology vendors use installed base, recurring O&M, consumables, compliance criticality, and warranty risk.",
    }
    return {
        "domain": domain,
        "multiple_method": methods.get(domain, "Use EV/revenue, EV/EBITDA, gross-profit multiple, or ARR multiple depending on business model."),
        "required_public_comps": ["ticker/company", "segment fit", "latest revenue", "gross margin", "growth", "EV/market cap", "debt/cash", "source date"],
        "source_rule": "Do not show a numerical multiple unless market cap/EV and financials are sourced on the same date. Otherwise show the comparable-company framework only.",
    }


