def build_survey_interview_findings(topic: str, industry: str, target: str) -> dict:
    domain = classify_topic_domain(topic, industry)
    min_domain_confidence = 0.38 if domain != "general_market" else 0.0
    raw_records = [
        r for r in target_record_filter(load_records_for_target(target), target)
        if not is_metadata_only_evidence(r)
        if record_domain_confidence(r, domain, topic, industry) >= min_domain_confidence
        and (
            r.get("source_family") in {
                "reddit_practitioner", "youtube_transcript", "podcast_interview",
                "official_survey", "healthcare_primary_survey", "book_reference",
                "primary_interview", "user_uploaded_interview", "user_uploaded_survey",
            }
            or is_verified_existing_survey_record(r)
        )
    ]
    scored_records = []
    for record in raw_records:
        detail = topic_match_detail(record, topic, industry, target)
        if detail["score"] >= 0.25:
            scored_records.append((detail["score"], record, detail))
    scored_records = sorted(scored_records, key=lambda item: item[0], reverse=True)[:12]
    findings = []
    for score, record, detail in scored_records:
        publisher = record.get("publisher", "")
        title = record.get("title", "")
        text = str(record.get("text", ""))
        quote = text[:320]
        low = text.lower()
        decoded = []
        for label, terms in {
            "buyer pain": ("pain", "problem", "manual", "time", "friction", "give a shit", "workflow"),
            "pricing/WTP signal": ("price", "pricing", "$", "pay", "budget", "cost"),
            "adoption barrier": ("hard", "difficult", "security", "trust", "reliable", "integration", "setup"),
            "retention/usage": ("repeat", "churn", "retention", "daily", "weekly", "usage", "stick"),
            "competitive preference": ("zapier", "make", "n8n", "competitor", "alternative", "better"),
            "financial access / credit": ("credit", "loan", "lending", "underbanked", "unbanked", "account", "financial inclusion"),
            "banking compliance / risk": ("bank", "fdic", "ffiec", "capital", "fraud", "risk", "compliance", "regulator"),
            "RCM denial pain": ("denial", "denials", "appeal", "claim", "claims", "revenue cycle", "payer"),
            "prior authorization friction": ("prior authorization", "authorization", "medical necessity", "payer portal", "portal"),
            "diagnostic lab reimbursement": ("clfs", "clia", "laboratory", "diagnostic", "cpt", "test"),
            "regulatory pathway risk": ("fda", "samd", "510(k)", "mdr", "ivdr", "cdsco", "medical device"),
        }.items():
            if domain != "finance" and label in {"financial access / credit", "banking compliance / risk"}:
                continue
            if domain != "healthcare" and label in {"RCM denial pain", "prior authorization friction", "diagnostic lab reimbursement", "regulatory pathway risk"}:
                continue
            if any(term in low for term in terms):
                decoded.append(label)
        family = record.get("source_family")
        if is_verified_existing_survey_record(record) and family == "government_data":
            verification = "verified government survey or official adoption dataset; usable when geography, sample, and period match"
        elif family == "official_survey":
            verification = "official survey; usable for sampled behavior/adoption/access when sample, geography, and period match"
        elif family == "healthcare_primary_survey":
            verification = "healthcare primary survey; usable for buyer pain/workflow evidence with sponsor/sample limits disclosed"
        elif family == "user_uploaded_survey":
            verification = "user-uploaded survey; usable when sample, geography, date, and source URL/method are disclosed"
        elif family in {"primary_interview", "user_uploaded_interview"}:
            verification = "buyer/operator evidence uploaded to the app; qualitative only unless tied to a verifiable source, sample, and date"
        elif family == "book_reference":
            verification = "book/framework reference only; not current data and do not quote without a provided excerpt/page"
        elif family == "podcast_interview":
            verification = "podcast interview/episode proxy; qualitative only unless transcript cites primary data"
        else:
            verification = "topic-matched Reddit/YouTube practitioner signal; qualitative only and not valid for hard market sizing"
        findings.append({
            "source": publisher,
            "title": title,
            "url": record.get("url", ""),
            "as_quoted_by": f"{publisher} / {title}",
            "excerpt": quote,
            "topic_match": score,
            "matched_terms": ", ".join(detail["matched_terms"]),
            "decoded_signal": ", ".join(decoded) or "general qualitative signal",
            "source_family": family,
            "verification_status": verification,
        })
    proxy_count = len(findings)
    if proxy_count >= 8:
        quality = "medium qualitative proxy"
    elif proxy_count >= 3:
        quality = "low-to-medium qualitative proxy"
    else:
        quality = "low; show data gap"
    return {
        "domain": domain,
        "findings": findings,
        "source_filter": "Topic-matched official surveys, government survey/adoption datasets, uploaded buyer/survey evidence, verified transcript/excerpt records, Reddit practitioner posts, and book/framework references are included. Healthcare surveys are used only for healthcare topics. Metadata-only video/podcast records are excluded.",
        "proxy_count": proxy_count,
        "data_quality": quality,
        "primary_research_status": "Completed interviews/surveys are used only when manually pasted or uploaded with source context. Official surveys are sampled evidence; Reddit/YouTube/podcast evidence is decoded as proxy voice-of-customer only.",
        "use_rule": "Quote as 'as quoted by <source>'. Use for buyer language, pains, adoption barriers, and hypotheses. Never use social/video/podcast/book evidence as hard market sizing, revenue, churn, or valuation proof unless it cites a verified primary dataset.",
    }


