def _report_record_type(record: dict) -> str:
    record_type = str(record.get("record_type") or record.get("claim_type") or "").lower()
    unit = str(record.get("unit") or "").lower()
    family = str(record.get("source_family") or "").lower()
    if record_type in {"competitor", "pricing", "buyer_pain", "buyer_voice"}:
        return record_type
    if unit == "competitor" or "competitor" in str(record.get("metric_name", "")).lower():
        return "competitor"
    if unit == "pricing" or family in {"pricing_reference", "vendor_pricing", "marketplace_pricing"}:
        return "pricing"
    if unit == "buyer_pain" or family in {"buyer_signal", "review_platform", "reddit_practitioner"}:
        return "buyer_pain"
    if record_has_named_saas_competitor(record) or record_has_named_automotive_competitor(record):
        return "competitor"
    return record_type or "context"


def compute_topic_similarity(record: dict, topic: str, industry: str = "", target: str = "", domain: str = "") -> float:
    domain = domain or classify_topic_domain(topic, industry)
    haystack = record_text_blob(record).lower()
    tags = " ".join(str(t).lower() for t in record.get("topic_tags", []))
    topic_terms = relevant_topic_tokens(topic, industry, target)
    topic_hits = sum(1 for term in topic_terms if term in haystack or term in tags)
    domain_conf = record_domain_confidence(record, domain, topic, industry)
    leak_terms = REPORT_DOMAIN_LEAK_TERMS.get(domain, ())
    leak_hits = sum(1 for term in leak_terms if term in haystack)
    score = domain_conf * 0.50 + min(topic_hits, 10) * 0.05
    if domain in tags or domain in haystack:
        score += 0.12
    if "structured_extraction" in tags:
        score += 0.08
    if leak_hits >= 2 and topic_hits < 2:
        return 0.0
    if leak_hits >= 1 and topic_hits == 0 and domain_conf < 0.55:
        return max(0.0, score - 0.45)
    if domain != "general_market" and domain_conf < 0.30:
        return max(0.0, score - 0.35)
    target_l = str(target or "").strip().lower()
    geo = str(record.get("geography") or "").lower()
    if target_l in {"global", "world", "worldwide", "international", ""}:
        pass
    elif is_country_specific_target(target) and target_l not in geo and "global" not in geo:
        score -= 0.22
    return max(0.0, min(1.0, round(score, 3)))


def _report_geography_ok(record: dict, target: str) -> bool:
    return source_readiness_record_matches_target_scope(record, target)


def _report_direct_evidence_tier_boost(record: dict) -> float:
    record_type = _report_record_type(record)
    family = str(record.get("source_family") or "").lower()
    haystack = record_text_blob(record).lower()
    if record_type in {"pricing", "competitor", "buyer_pain"}:
        return 0.34
    if record_has_named_saas_competitor(record) or record_has_named_automotive_competitor(record):
        return 0.32
    if family in DIRECT_PROOF_FAMILIES:
        if record_type == "pricing" or any(t in haystack for t in ("pricing", "price", "per month", "per user", "rs.", "inr", "$")):
            return 0.30
        if record_type == "competitor" or record_has_named_saas_competitor(record) or record_has_named_automotive_competitor(record):
            return 0.28
        if record_type == "buyer_pain" or any(t in haystack for t in ("too expensive", "poor support", "complaint", "review")):
            return 0.22
        return 0.16
    if family in GENERIC_ANALYST_FAMILIES:
        if not any(t in haystack for t in ("pricing", "competitor", "review", "buyer", "survey")):
            return -0.28
        return -0.12
    if family in {"iidatech_2026_financial_model_bank", "industry_pack_benchmark"}:
        return -0.20
    return 0.0


def _report_section_type_boost(record: dict, section_title: str) -> float:
    priorities = SECTION_RECORD_TYPE_PRIORITY.get(section_title, {})
    return float(priorities.get(_report_record_type(record), 0.0))


def score_report_evidence_record(
    record: dict,
    topic: str,
    industry: str,
    target: str,
    section_title: str,
    *,
    domain: str = "",
) -> tuple[float, str]:
    domain = domain or classify_topic_domain(topic, industry)
    topic_sim = compute_topic_similarity(record, topic, industry, target, domain)
    if topic_sim < REPORT_TOPIC_SIMILARITY_FLOOR:
        return topic_sim, "low_topic_similarity"
    if is_metadata_only_evidence(record) or source_readiness_is_internal_or_synthetic(record):
        return 0.0, "synthetic_penalty"
    if not _report_geography_ok(record, target):
        return max(0.0, topic_sim - 0.40), "geography_mismatch"
    precision = source_precision_check(record, domain, section_title, topic, industry, target)
    if precision.get("decision") == "exclude":
        return max(0.0, topic_sim - 0.35), "section_irrelevant"
    quality = float(record.get("quality_score") or record.get("confidence") or 0) / 100.0 if float(record.get("quality_score") or record.get("confidence") or 0) > 1 else float(record.get("quality_score") or record.get("confidence") or 0.5)
    score = topic_sim * 0.42 + float(precision.get("score") or 0.0) * 0.28 + quality * 0.10
    score += _report_direct_evidence_tier_boost(record)
    score += _report_section_type_boost(record, section_title)
    if str(record.get("source_family") or "").lower() == "competitor_intelligence":
        score += 0.18
    elif float(record.get("confidence") or 0) >= 0.95:
        score += 0.10
    if source_readiness_is_generic_country_denominator(record):
        score -= 0.35
    if str(record.get("publisher") or "").lower() in {"industry_landscape_seed"} and "landscape_seed" not in " ".join(str(t) for t in record.get("topic_tags", [])):
        score -= 0.05
    reason = ""
    if score < REPORT_TOPIC_SIMILARITY_FLOOR:
        reason = "low_signal"
    return round(max(0.0, min(1.25, score)), 3), reason


def rank_report_evidence_records(
    records: list[dict],
    topic: str,
    industry: str,
    target: str,
    section_title: str,
    *,
    max_records: int = 12,
    domain: str = "",
) -> list[dict]:
    domain = domain or classify_topic_domain(topic, industry)
    scored: list[tuple[float, dict, str]] = []
    candidates: list[dict] = []
    for record in records:
        if not isinstance(record, dict):
            continue
        row = dict(record)
        row["_selection_topic"] = topic
        score, rejection = score_report_evidence_record(row, topic, industry, target, section_title, domain=domain)
        row["_selection_relevance_score"] = score
        rank_score = score
        try:
            from iidatech.retrieval.source_trust import annotate_truth_fields, data_truth_layer_enabled, truth_augmented_rank_score
            if data_truth_layer_enabled():
                row = annotate_truth_fields(row)
                rank_score = truth_augmented_rank_score(row, score)
                row["_selection_truth_augmented_score"] = rank_score
        except Exception:
            pass
        row["_selection_record_type"] = _report_record_type(row)
        row["_selection_rejection_reason"] = rejection if score < REPORT_TOPIC_SIMILARITY_FLOOR else ""
        if score >= REPORT_TOPIC_SIMILARITY_FLOOR and not rejection:
            try:
                from iidatech.validation.source_validator import validate_record_for_claim
                claim = _report_record_type(row)
                if claim in {"pricing", "competitor", "buyer_pain"}:
                    tier_check = validate_record_for_claim(row, claim if claim != "buyer_pain" else "general")
                    if not tier_check.get("allowed"):
                        row["_selection_rejection_reason"] = tier_check.get("reason") or "tier_blocked"
                        rejection = row["_selection_rejection_reason"]
            except Exception:
                pass
        candidates.append(row)
        if score >= REPORT_TOPIC_SIMILARITY_FLOOR and not rejection:
            scored.append((rank_score, row, ""))
        else:
            row["_selection_rejection_reason"] = rejection or "low_topic_similarity"
    scored.sort(key=lambda item: item[0], reverse=True)
    quotas = {
        "crm_automation": {"competitor": 4, "pricing": 3, "buyer_pain": 3},
        "b2b_saas": {"competitor": 4, "pricing": 3, "buyer_pain": 3},
        "revops_sales_automation": {"competitor": 4, "pricing": 3, "buyer_pain": 3},
        "automotive": {"competitor": 3, "pricing": 3, "buyer_pain": 2},
        "automotive_retail": {"competitor": 3, "pricing": 3, "buyer_pain": 2},
        "ecommerce_retail": {"competitor": 3, "pricing": 3, "buyer_pain": 3},
        "consumer": {"competitor": 3, "pricing": 3, "buyer_pain": 3},
    }
    quota = quotas.get(domain, {"competitor": 2, "pricing": 2, "buyer_pain": 2})
    buckets: dict[str, list[dict]] = {key: [] for key in quota}
    overflow: list[tuple[float, dict]] = []
    for score, row, _reason in scored:
        record_type = _report_record_type(row)
        if record_type in buckets and len(buckets[record_type]) < quota[record_type]:
            buckets[record_type].append(row)
        else:
            overflow.append((score, row))
    selected: list[dict] = []
    for record_type in ("competitor", "pricing", "buyer_pain"):
        selected.extend(buckets.get(record_type, []))
    for score, row in sorted(overflow, key=lambda item: item[0], reverse=True):
        if len(selected) >= max_records:
            break
        selected.append(row)
    seen: set[str] = set()
    deduped_selected: list[dict] = []
    for row in selected:
        dedupe_key = "|".join([
            str(row.get("url") or ""),
            str(row.get("title") or "")[:80].lower(),
            _report_record_type(row),
        ])
        if dedupe_key in seen:
            row["_selection_rejection_reason"] = "duplicate"
            continue
        seen.add(dedupe_key)
        deduped_selected.append(row)
    try:
        from iidatech.retrieval.evidence_cluster import cluster_evidence_records
        selected = cluster_evidence_records(deduped_selected, max_items=max_records)
    except Exception:
        selected = deduped_selected[:max_records]
    emit_report_selection_trace(section_title, candidates, selected)
    return selected


def assert_report_evidence_quality(records: list[dict], topic: str, industry: str, target: str, domain: str) -> list[str]:
    warnings: list[str] = []
    domain = domain or classify_topic_domain(topic, industry)

    def _count(record_type: str) -> int:
        return sum(1 for r in records if _report_record_type(r) == record_type)

    def _named_competitors() -> int:
        count = 0
        for r in records:
            if _report_record_type(r) == "competitor":
                count += 1
            elif record_has_named_saas_competitor(r) or record_has_named_automotive_competitor(r):
                count += 1
        return count

    if domain in {"crm_automation", "b2b_saas", "revops_sales_automation", "ai_workflow_automation"}:
        if _named_competitors() < 3:
            warnings.append("quality_assertion: CRM/SaaS selected evidence has fewer than 3 named competitor rows")
        if _count("pricing") < 2:
            warnings.append("quality_assertion: CRM/SaaS selected evidence has fewer than 2 pricing rows")
        if _count("buyer_pain") < 2:
            warnings.append("quality_assertion: CRM/SaaS selected evidence has fewer than 2 buyer pain rows")
    elif domain in {"automotive", "automotive_retail"}:
        if _named_competitors() < 2:
            warnings.append("quality_assertion: automotive selected evidence has fewer than 2 competitor rows")
        if _count("pricing") < 2:
            warnings.append("quality_assertion: automotive selected evidence has fewer than 2 pricing rows")
    elif domain in {"ecommerce_retail", "consumer", "fashion"}:
        if _named_competitors() < 2:
            warnings.append("quality_assertion: ecommerce selected evidence has fewer than 2 competitor rows")
        if _count("buyer_pain") < 2:
            warnings.append("quality_assertion: ecommerce selected evidence has fewer than 2 buyer pain rows")
    if report_selection_trace_enabled():
        for warning in warnings:
            log = __import__("logging").getLogger("iidatech.report_selection")
            log.warning(warning)
    return warnings


def select_report_evidence_pool(
    records: list[dict],
    topic: str,
    industry: str,
    target: str,
    *,
    section_title: str = "Competitive Landscape",
    limit: int = 24,
) -> list[dict]:
    return rank_report_evidence_records(
        records,
        topic,
        industry,
        target,
        section_title,
        max_records=limit,
    )


def source_relevance_table(records: list[dict], topic: str, industry: str, target: str, section_title: str) -> list[dict]:
    domain = classify_topic_domain(topic, industry)
    market_niche = identify_market_niche(topic, industry, target)
    min_domain_confidence = 0.38 if domain != "general_market" else 0.0
    target_l = (target or "").lower()
    topic_terms = relevant_topic_tokens(topic, industry, target)
    ranked_records = rank_report_evidence_records(
        records,
        topic,
        industry,
        target,
        section_title,
        max_records=12,
        domain=domain,
    )
    out = []
    for record in ranked_records:
        geo = str(record.get("geography", "unknown"))
        family = str(record.get("source_family", "source"))
        title = str(record.get("title", "Untitled"))
        geo_l = geo.lower()
        target_is_global = target_l in {"global", "worldwide", "international", ""}
        direct_geo_match = target_is_global or (target_l and target_l in geo_l)
        proxy_geo_match = geo_l in {"global", "configurable"} or "global" in geo_l
        domain_confidence = record_domain_confidence(record, domain, topic, industry)
        domain_match = domain_confidence >= min_domain_confidence
        precision = source_precision_check(record, domain, section_title, topic, industry, target)
        niche_match = record_market_niche_match(record, market_niche, target, topic, industry)
        if precision.get("decision") == "exclude":
            use = "exclude: source/domain route failed"
        elif niche_match.get("decision") == "direct" and direct_geo_match and domain_match and precision.get("decision") == "direct":
            use = "direct evidence"
        elif niche_match.get("decision") == "proxy" or (domain_match and proxy_geo_match):
            use = "domain proxy; explain geography limitation"
        elif niche_match.get("decision") == "context":
            use = "context only; do not use as claim evidence"
        elif domain_match:
            use = "domain evidence; verify geography fit"
        else:
            use = "exclude unless explicitly relevant"
        haystack = " ".join(str(record.get(field, "")) for field in ("title", "publisher", "metric_name", "metric_value", "text")).lower()
        matched_terms = sorted(t for t in topic_terms if t in haystack)[:8]
        extracted_numbers = re.findall(
            r"\$?\d+(?:\.\d+)?\s*(?:percent|percentage points|CAGR|customers|users|households|stores|"
            r"million|billion|bn|%|m(?=\W|$)|b(?=\W|$)|k(?=\W|$))",
            haystack,
            flags=re.IGNORECASE,
        )[:8]
        out.append({
            "title": title,
            "publisher": record.get("publisher", ""),
            "source_family": family,
            "evidence_label": evidence_label_for_record(record),
            "domain_confidence": round(domain_confidence, 2),
            "geography": geo,
            "metric": f"{record.get('metric_name', '')}: {record.get('metric_value', '')}".strip(": "),
            "url": record.get("url", ""),
            "section_use": use,
            "source_route": precision.get("decision", ""),
            "source_precision": precision.get("score", 0),
            "route_reason": precision.get("reason", ""),
            "evidence_tier": niche_match.get("tier", precision.get("evidence_tier", "Hypothesis")),
            "market_niche_decision": niche_match.get("decision", ""),
            "market_niche_reason": niche_match.get("reason", ""),
            "matched_category_terms": niche_match.get("matched_category_terms", matched_terms),
            "matched_buyer_terms": niche_match.get("matched_buyer_terms", []),
            "section": section_title,
            "matched_topic_terms": matched_terms,
            "extracted_numeric_claims": extracted_numbers,
        })
    return out


def build_section_relevance_contract(
    topic: str,
    industry: str,
    target: str,
    horizon: str,
    section: dict,
    market_model: dict,
    diligence_pack: dict,
) -> dict:
    domain = classify_topic_domain(topic, industry)
    records = select_market_records(topic, industry, target, section["title"], max_records=48)
    records = rank_report_evidence_records(records, topic, industry, target, section["title"], max_records=30, domain=domain)
    # When the local dataset is thin (common in dev / first-run), promote PR3-A
    # structured web records into the candidate pool so that source_relevance_table
    # produces a populated eligible_source_table instead of an empty list.
    if len(records) < 5:
        web_candidates = get_recent_structured_web_records(topic)
        if web_candidates:
            existing_ids = {str(r.get("record_id") or r.get("id") or id(r)) for r in records}
            for wr in web_candidates:
                wid = str(wr.get("record_id") or wr.get("id") or id(wr))
                if wid not in existing_ids:
                    records.append(wr)
                    existing_ids.add(wid)
    market_niche = identify_market_niche(topic, industry, target)
    competitor_gate = named_competitor_discovery_gate(topic, industry, target, records, domain=domain)
    return {
        "topic": topic,
        "domain": domain,
        "target_geography": target,
        "horizon": horizon,
        "exact_market_niche_gate": market_niche,
        "narrow_scope": narrow_topic_scope(topic, industry, target),
        "section": section["title"],
        "section_must_answer": SECTION_RELEVANCE_RULES.get(section["title"], "answer this section using topic-specific evidence, sources, calculations, and limitations"),
        "required_subsections": section.get("sub", []),
        "regional_subsection_rule": regional_subsection_rule(topic, industry, target) if section["title"] == "Regional Analysis" else {},
        "strict_evidence_tiers": {
            "Verified": "direct source with URL, date/period, geography, category/buyer fit, and figure where relevant",
            "Derived": "calculated from two or more verified inputs; formula must be shown",
            "Proxy": "comparable market/source used as stand-in; assumption and discount must be stated",
            "Hypothesis": "founder/model assumption that must be validated before funding use",
        },
        "tam_sam_som_bottom_up_rule": bottom_up_sizing_rule_for_niche(topic, industry, target) if section["title"] in {"Market Size & Valuation", "Market Forecast (2026-2031)", "Financial Forecasting Basis", "Startup Budget & Revenue Model"} else {},
        "section_completion_gate": section_funding_readiness_gate(section["title"]),
        "markets_report_gate": diligence_pack.get("markets_report_gate", {}),
        "eligible_source_table": source_relevance_table(records, topic, industry, target, section["title"]),
        "competitor_discovery_gate": competitor_gate if "Compet" in section["title"] or section["title"] in {"Key Player Profiles", "Market Share Analysis"} else {},
        "competitive_segments": diligence_pack.get("competitive_benchmark", []) if "Compet" in section["title"] or section["title"] in {"Key Player Profiles", "Market Share Analysis"} else [],
        "operational_financial_model": diligence_pack.get("operational_financial_model", {}) if section["title"] in {"Startup Budget & Revenue Model", "Operating Model & Hiring Plan", "Financial Forecasting Basis", "Valuation Support", "Market Forecast (2026-2031)"} else {},
        "bottom_up_calculation": diligence_pack.get("bottom_up_market_calculation", {}) if section["title"] in {"Market Size & Valuation", "Market Forecast (2026-2031)", "Financial Forecasting Basis", "Valuation Support"} else {},
        "figure_validation_pack": diligence_pack.get("figure_validation_pack", {}) if section["title"] in {"Executive Summary", "Market Size & Valuation", "Market Share Analysis", "Pricing Analysis", "Investment & Funding Activity", "Valuation Support", "Financial Forecasting Basis", "Market Forecast (2026-2031)", "Appendix & Methodology"} else {},
        "financial_validation_pack": diligence_pack.get("financial_validation_pack", {}) if section["title"] in {"Investment & Funding Activity", "Valuation Support", "Financial Forecasting Basis", "Market Size & Valuation", "Key Player Profiles", "M&A Activity"} else {},
        "strict_verification_pack": diligence_pack.get("strict_verification_pack", {}) if section["title"] in {"Executive Summary", "Market Size & Valuation", "Market Share Analysis", "Pricing Analysis", "Investment & Funding Activity", "Valuation Support", "Financial Forecasting Basis", "Market Forecast (2026-2031)", "Appendix & Methodology", "Regulatory Environment"} else {},
        "funding_readiness_pack": diligence_pack.get("funding_readiness_pack", {}) if section["title"] in {"Executive Summary", "Market Size & Valuation", "Investment Diligence Gate", "Investment & Funding Activity", "Valuation Support", "Financial Forecasting Basis", "Market Forecast (2026-2031)", "Startup Budget & Revenue Model", "Go-To-Market Playbook", "Appendix & Methodology"} else {},
        "pricing_intelligence_pack": diligence_pack.get("pricing_intelligence_pack", {}) if section["title"] in {"Pricing Analysis", "Startup Budget & Revenue Model", "Operating Model & Hiring Plan", "Competitive Benchmarking", "Go-To-Market Playbook", "Valuation Support", "Financial Forecasting Basis"} else {},
        "primary_research_plan": {},
        "regional_depth_plan": diligence_pack.get("regional_depth_plan", {}) if section["title"] == "Regional Analysis" or target.lower() not in {"global", "worldwide", "international"} else {},
        "funding_rounds": diligence_pack.get("recent_funding_rounds", {}) if section["title"] in {"Investment & Funding Activity", "Executive Summary", "Valuation Support"} else {},
        "comparable_company_multiples": diligence_pack.get("comparable_company_multiples", {}) if section["title"] in {"Valuation Support", "Market Size & Valuation", "Investment & Funding Activity"} else {},
        "investor_thesis_map": diligence_pack.get("investor_thesis_map", {}) if section["title"] in {"Executive Summary", "Investment & Funding Activity", "Strategic Recommendations", "Valuation Support"} else {},
        "country_law_standards": diligence_pack.get("country_law_standards", {}) if section["title"] in {"Regulatory Environment", "Regional Analysis", "Investment Diligence Gate"} else {},
        "certification_timeline_costs": diligence_pack.get("certification_timeline_costs", {}) if section["title"] in {"Regulatory Environment", "Startup Budget & Revenue Model", "Ground-Up Execution Roadmap"} else {},
        "compliance_case_studies": diligence_pack.get("compliance_case_studies", {}) if section["title"] in {"Regulatory Environment", "Restraints & Challenges", "Investment Diligence Gate"} else {},
        "survey_interview_findings": diligence_pack.get("survey_interview_findings", {}) if section["title"] in {"Consumer Behavior", "Go-To-Market Playbook", "Growth Drivers", "Opportunities & White Spaces", "Investment Diligence Gate", "Appendix & Methodology"} else {},
        "trend_and_technology_evidence": diligence_pack.get("trend_and_technology_evidence", {}) if section["title"] in {"Market Trends", "Technology Landscape", "Growth Drivers", "Opportunities & White Spaces"} else {},
        "scenario_forecast_pack": diligence_pack.get("scenario_forecast_pack", {}) if section["title"] in {"Market Forecast (2026-2031)", "Financial Forecasting Basis", "Market Size & Valuation"} else {},
        "digital_behavior_retention": diligence_pack.get("digital_behavior_retention", {}) if section["title"] in {"Consumer Behavior", "Financial Forecasting Basis", "Market Forecast (2026-2031)", "Pricing Analysis"} else {},
        "built_in_info_rule": "Use built-in model assumptions only if they appear in the quantitative model or diligence pack and are relevant to this domain/geography; otherwise mark them as assumptions or omit them.",
    }


def stored_2026_financial_model(topic: str, industry: str, target: str) -> dict:
    if get_financial_model_record is None:
        return {}
    try:
        return get_financial_model_record(topic, industry, target) or {}
    except Exception:
        return {}


def apply_estimated_2026_display(strict_pack: dict, stored_model: dict) -> dict:
    """Keep strict verification labels but show estimated figures instead of withholding."""
    if not strict_pack or not stored_model or headline_from_model_record is None:
        return strict_pack or {}
    pack = copy.deepcopy(strict_pack)
    estimate_headline = headline_from_model_record(stored_model) or {}
    if not estimate_headline:
        return pack
    existing = pack.get("headline_display", {}) or {}
    gates = pack.get("claim_gates", {}) or {}

    def verified(label: str) -> bool:
        return str((gates.get(label, {}) or {}).get("status", "")).lower() == "verified"

    pack["headline_display"] = {
        "base_tam": existing.get("base_tam") if verified("TAM") else estimate_headline.get("tam_base_fmt"),
        "tam_range": existing.get("tam_range") if verified("TAM") else estimate_headline.get("tam_range"),
        "sam": existing.get("sam") if verified("SAM") else estimate_headline.get("sam_fmt"),
        "som_range": existing.get("som_range") if verified("SOM") else estimate_headline.get("som_range"),
        "forecast_cagr": (
            existing.get("forecast_cagr")
            if str((gates.get("Financial figures", {}) or {}).get("status", "")).lower() == "verified"
            else estimate_headline.get("forecast_cagr_2026_2031_fmt")
        ),
    }
    for gate_name in ("TAM", "SAM", "SOM", "Financial figures"):
        gate = gates.get(gate_name)
        if isinstance(gate, dict) and str(gate.get("status", "")).lower() != "verified":
            if gate_name == "TAM":
                gate["estimated_output"] = estimate_headline.get("tam_base_fmt")
            elif gate_name == "SAM":
                gate["estimated_output"] = estimate_headline.get("sam_fmt")
            elif gate_name == "SOM":
                gate["estimated_output"] = estimate_headline.get("som_range")
            else:
                gate["estimated_output"] = estimate_headline.get("forecast_cagr_2026_2031_fmt")
            gate["status"] = "estimated"
            gate["rule"] = (
                gate.get("rule", "") +
                " The report may show the stored 2026 estimate if it is labeled ESTIMATED and the formula/source rows are shown."
            ).strip()
    pack["claim_gates"] = gates
    pack.setdefault("display_rules", {})
    pack["display_rules"]["show_tam_sam_som_as_estimated"] = True
    pack["display_rules"]["show_model_scenarios_as_final"] = False
    pack["display_rules"]["estimated_model_rule"] = (
        "Do not hide financial figures. Show VERIFIED where the 10-check gate passes; otherwise show ESTIMATED with formula, assumptions, and source rows."
    )
    pack["estimated_2026_model"] = {
        "id": stored_model.get("id"),
        "evidence_label": stored_model.get("evidence_label"),
        "calculation": stored_model.get("calculation", {}),
        "source_rows": stored_model.get("source_rows", []),
    }
    pack["summary"] = (
        str(pack.get("summary", "")).rstrip()
        + " Estimated 2026 model outputs are displayed with labels when strict hard-figure verification is incomplete."
    )
    return pack


def build_diligence_pack(
    topic: str,
    industry: str,
    target: str,
    model: dict,
    completeness: dict,
    *,
    harvest_serp: dict | None = None,
) -> dict:
    report_phase("Diligence pack: citation ledger")
    ledger = build_citation_ledger(topic, industry, target)
    published_voice_count = sum(
        1 for item in ledger
        if item.get("source_family") in {"official_survey", "healthcare_primary_survey", "reddit_practitioner", "youtube_transcript", "podcast_interview"}
    )
    a_grade = sum(1 for item in ledger if item["grade"] == "A")
    readiness_score = min(100, completeness.get("score", 0) + a_grade * 2 + min(10, published_voice_count))
    if readiness_score >= 85 and published_voice_count >= 6:
        readiness = "market-intelligence grade with investment-grade path"
    elif readiness_score >= 65:
        readiness = "cited market-intelligence grade, not full investment diligence"
    else:
        readiness = "research scaffold; stronger survey/practitioner evidence required"
    report_phase("Diligence pack: core modules")
    model_bank_record = stored_2026_financial_model(topic, industry, target)
    pack = {
        "readiness": {
            "score": readiness_score,
            "classification": readiness,
            "investment_grade_warning": "Do not use as valuation or investment committee basis until survey/practitioner evidence, competitor benchmarking, and company financials are verified.",
        },
        "citation_ledger": ledger,
        "competitive_benchmark": build_competitive_benchmark(topic, industry),
        "valuation_support": build_valuation_support(topic, industry, model),
        "financial_forecast_basis": build_financial_forecast_basis(topic, industry, model),
        "primary_research_plan": build_primary_research_plan(topic, industry, target),
        "operational_financial_model": build_operational_financial_model(topic, industry, target, model),
        "bottom_up_market_calculation": build_bottom_up_market_calculation(topic, industry, target, model),
        "stored_2026_financial_model": model_bank_record,
        "figure_validation_pack": build_figure_validation_pack(topic, industry, target, model),
        "financial_validation_pack": build_financial_validation_pack(topic, industry, target),
        "regional_depth_plan": build_regional_depth_plan(topic, industry, target),
        "recent_funding_rounds": build_recent_funding_rounds(topic, industry, target),
        "comparable_company_multiples": build_comparable_company_multiples(topic, industry, target),
        "pricing_intelligence_pack": build_pricing_intelligence_pack(topic, industry, target),
        "investor_thesis_map": build_investor_thesis_map(topic, industry, target),
        "country_law_standards": build_country_law_standards_map(topic, industry, target),
        "certification_timeline_costs": build_certification_timeline_costs(topic, industry, target),
        "compliance_case_studies": build_compliance_case_studies(topic, industry, target),
        "survey_interview_findings": build_survey_interview_findings(topic, industry, target),
        "trend_and_technology_evidence": build_trend_and_technology_evidence(topic, industry, target),
        "scenario_forecast_pack": build_scenario_forecast_pack(topic, industry, target, model),
        "digital_behavior_retention": build_digital_behavior_retention_pack(topic, industry, target),
    }
    if build_strict_verification_pack is not None:
        try:
            report_phase("Diligence pack: strict verification")
            strict_domain = classify_topic_domain(topic, industry)
            strict_min_confidence = 0.38 if strict_domain != "general_market" else 0.0
            strict_records = []
            try:
                from iidatech.validation.competitor_relevance import financial_diligence_record_relevant_for_topic
            except Exception:
                financial_diligence_record_relevant_for_topic = None  # type: ignore[assignment,misc]
            for r in target_record_filter(load_records_for_target(target), target):
                if is_metadata_only_evidence(r):
                    continue
                if record_domain_confidence(r, strict_domain, topic, industry) < strict_min_confidence:
                    continue
                if financial_diligence_record_relevant_for_topic is not None:
                    match = topic_match_detail(r, topic, industry, target)
                    ok, _reason = financial_diligence_record_relevant_for_topic(
                        r,
                        topic=topic,
                        industry=industry,
                        domain=strict_domain,
                        topic_match_score=float(match.get("score", 0) or 0),
                        min_topic_match=0.20,
                    )
                    if not ok:
                        continue
                strict_records.append(r)
            pack["strict_verification_pack"] = build_strict_verification_pack(
                topic,
                industry,
                target,
                model=model,
                diligence_pack=pack,
                records=strict_records,
                domain_override=strict_domain,
            )
        except Exception as exc:
            pack["strict_verification_pack"] = {
                "mode": "strict_verified_only",
                "summary": f"Strict verification layer failed to build: {exc}",
                "claim_gates": {},
                "display_rules": {"show_tam_sam_som_as_verified": False},
            }
    else:
        pack["strict_verification_pack"] = {
            "mode": "strict_verified_only",
            "summary": "Strict verification layer is not loaded.",
            "claim_gates": {},
            "display_rules": {"show_tam_sam_som_as_verified": False},
        }
    pack["strict_verification_pack"] = apply_estimated_2026_display(pack.get("strict_verification_pack", {}), model_bank_record)
    report_phase("Diligence pack: funding readiness")
    strict_display_rules = pack.get("strict_verification_pack", {}).get("display_rules", {}) or {}
    if not (
        strict_display_rules.get("show_tam_sam_som_as_verified")
        or strict_display_rules.get("show_tam_sam_som_as_estimated")
    ):
        scenario_pack = pack.get("scenario_forecast_pack", {}) or {}
        if model.get("dashboard_mode") == "bottom_up_tam":
            scenario_pack["scenario_rows"] = [
                {
                    "scenario": row.get("scenario", "Scenario"),
                    "model_output": "WITHHELD",
                    "logic": row.get("logic", ""),
                    "source_status": "Synthetic scenario output hidden until strict TAM/SAM/SOM gates pass.",
                }
                for row in model.get("scenario_rows", [])
            ]
            scenario_pack["forecast_rows"] = []
            scenario_pack["rule"] = "Scenario and forecast numbers are hidden until strict verification passes; show missing inputs and formulas only."
            pack["scenario_forecast_pack"] = scenario_pack
    pack["funding_readiness_pack"] = build_funding_readiness_pack(topic, industry, target, model, pack)
    report_phase("Diligence pack: live competitor discovery")
    try:
        from iidatech.services.serp_payload_bridge import enrich_diligence_pack_live_competitors

        pack = enrich_diligence_pack_live_competitors(
            pack,
            topic=topic,
            industry=industry,
            geography=target,
            domain=classify_topic_domain(topic, industry),
            serp_block=harvest_serp,
        )
    except Exception as exc:
        pack.setdefault("competitor_intelligence_pack", {"competitors": [], "error": str(exc)[:200]})
    report_phase("Diligence pack: complete")
    return pack


def strict_sanitize_market_model(model: dict, strict_pack: dict | None = None) -> dict:
    """Remove synthetic numeric outputs from model payloads when strict gates fail."""
    strict_pack = strict_pack or {}
    display_rules = strict_pack.get("display_rules", {}) or {}
    if display_rules.get("show_tam_sam_som_as_verified"):
        return copy.deepcopy(model)
    if display_rules.get("show_tam_sam_som_as_estimated"):
        sanitized = copy.deepcopy(model)
        headline_display = strict_pack.get("headline_display", {}) or {}
        if headline_display:
            sanitized["headline"] = {
                "tam_base": (model.get("headline", {}) or {}).get("tam_base"),
                "tam_base_fmt": headline_display.get("base_tam", (model.get("headline", {}) or {}).get("tam_base_fmt", "ESTIMATED")),
                "tam_range": headline_display.get("tam_range", (model.get("headline", {}) or {}).get("tam_range", "ESTIMATED")),
                "sam": (model.get("headline", {}) or {}).get("sam"),
                "sam_fmt": headline_display.get("sam", (model.get("headline", {}) or {}).get("sam_fmt", "ESTIMATED")),
                "som_range": headline_display.get("som_range", (model.get("headline", {}) or {}).get("som_range", "ESTIMATED")),
                "forecast_cagr_2026_2031": (model.get("headline", {}) or {}).get("forecast_cagr_2026_2031"),
                "forecast_cagr_2026_2031_fmt": headline_display.get("forecast_cagr", (model.get("headline", {}) or {}).get("forecast_cagr_2026_2031_fmt", "ESTIMATED")),
            }
        return sanitized

    sanitized = copy.deepcopy(model)
    headline_display = strict_pack.get("headline_display", {}) or {}
    sanitized["headline"] = {
        "tam_base": None,
        "tam_base_fmt": headline_display.get("base_tam", "WITHHELD - strict verification gate not passed"),
        "tam_range": headline_display.get("tam_range", "WITHHELD - strict verification gate not passed"),
        "sam": None,
        "sam_fmt": headline_display.get("sam", "WITHHELD - strict verification gate not passed"),
        "som_range": headline_display.get("som_range", "WITHHELD - strict verification gate not passed"),
        "forecast_cagr_2026_2031": None,
        "forecast_cagr_2026_2031_fmt": headline_display.get("forecast_cagr", "WITHHELD - strict verification gate not passed"),
    }
    if sanitized.get("dashboard_mode") == "bottom_up_tam":
        sanitized["scenario_rows"] = [
            {
                "scenario": row.get("scenario", "Scenario"),
                "model_output": "WITHHELD",
                "logic": row.get("logic", ""),
                "source_status": "Synthetic model output hidden until TAM/SAM/SOM gates pass all 10 checks.",
            }
            for row in sanitized.get("scenario_rows", [])
        ]
        sanitized["forecast_rows"] = []
        sanitized["sensitivity_rows"] = []
        sanitized["regional_rows"] = []
        sanitized["vendor_capture_rows"] = []
        sanitized["workload_rows"] = []
        sanitized["assumptions"] = {
            key: "WITHHELD until verified source input is available"
            for key in (sanitized.get("assumptions", {}) or {}).keys()
        }
    return sanitized


def build_investment_scorecard(evidence_rows, report_context) -> dict:
    """Deterministic bottom-up scorecard for investment/build decisions."""
    evidence_rows = list(evidence_rows or [])
    report_context = report_context or {}
    diligence = report_context.get("diligence_pack", {}) or {}
    if not isinstance(diligence, dict):
        diligence = {}
    model = report_context.get("quantitative_model", {}) or {}
    if not isinstance(model, dict):
        model = {}

    for key in (
        "citation_ledger", "competitive_benchmark", "pricing_intelligence_pack",
        "survey_interview_findings", "trend_and_technology_evidence",
        "figure_validation_pack", "funding_readiness_pack",
    ):
        value = diligence.get(key)
        if isinstance(value, list):
            evidence_rows.extend(row for row in value if isinstance(row, dict))
        elif isinstance(value, dict):
            for nested in value.values():
                if isinstance(nested, list):
                    evidence_rows.extend(row for row in nested if isinstance(row, dict))
                elif isinstance(nested, dict):
                    evidence_rows.append(nested)

    def clamp(value: float) -> float:
        return round(max(0.0, min(10.0, value)), 1)

    def number_from(value) -> float:
        if isinstance(value, (int, float)):
            return float(value)
        text = str(value or "")
        match = re.search(r"(\d+(?:,\d{3})*(?:\.\d+)?)(?:\s*([KMBT%])(?![A-Za-z]))?", text, re.I)
        if not match:
            return 0.0
        num = float(match.group(1).replace(",", ""))
        return num * {"K": 1e3, "M": 1e6, "B": 1e9, "T": 1e12}.get((match.group(2) or "").upper(), 1.0)

    headline = model.get("headline", {}) or {}
    bottom_up_raw = diligence.get("bottom_up_market_calculation", {}) or {}
    bottom_up = bottom_up_raw if isinstance(bottom_up_raw, dict) else {}
    current_outputs = bottom_up.get("current_outputs", {}) or {}
    tam = max(
        number_from(headline.get("tam_base")),
        number_from(headline.get("tam_base_fmt")),
        number_from(current_outputs.get("Base TAM")),
    )
    cagr_raw = number_from(headline.get("forecast_cagr_2026_2031"))
    cagr = max(
        cagr_raw * (100 if 0 < cagr_raw <= 1 else 1),
        number_from(headline.get("forecast_cagr_2026_2031_fmt")),
        number_from(current_outputs.get("Forecast CAGR")),
    )

    texts = " ".join(str(row) for row in evidence_rows).lower()
    pricing_rows = [r for r in evidence_rows if str(r.get("record_type") or r.get("claim_type") or r.get("source_family", "")).lower() in {"pricing", "vendor_pricing", "pricing_reference"} or "pricing" in str(r).lower()]
    competitor_rows = [r for r in evidence_rows if str(r.get("record_type") or r.get("claim_type", "")).lower() == "competitor" or r.get("competitor_archetypes")]
    pain_rows = [r for r in evidence_rows if str(r.get("record_type") or r.get("claim_type") or r.get("source_family", "")).lower() in {"buyer_pain", "buyer_voice", "buyer_signal"} or any(term in str(r).lower() for term in ("complain", "pain", "friction", "limitation", "poor"))]

    tam_score = 3.0 if tam >= 1e9 else 2.2 if tam >= 1e8 else 1.3 if tam >= 1e7 else 0.4
    cagr_score = 2.0 if cagr >= 20 else 1.4 if cagr >= 12 else 0.8 if cagr >= 6 else 0.2
    trend_score = min(2.0, sum(1 for t in ("growth", "adoption", "demand", "tailwind", "expanding") if t in texts) * 0.45)
    market_attractiveness = clamp(3.0 + tam_score + cagr_score + trend_score)

    incumbent_hits = sum(1 for n in ("salesforce", "microsoft", "hubspot", "zendesk", "intercom", "zoho") if n in texts)
    friction_hits = sum(1 for t in ("switching", "integration", "migration", "incumbent", "lock-in", "locked in") if t in texts)
    competition_intensity = clamp(2.5 + min(3.0, len(competitor_rows) * 0.6) + min(2.2, incumbent_hits * 0.45) + min(2.0, friction_hits * 0.45))

    prices = [number_from(r.get("monthly_price") or r.get("annual_price") or r.get("amount_or_metric") or r.get("text")) for r in pricing_rows]
    prices = [p for p in prices if p > 0]
    price_power = 2.4 if any(p >= 100 for p in prices) else 1.8 if any(p >= 20 for p in prices) else 0.8 if prices else 0.0
    monetization_strength = clamp(3.2 + min(2.4, len(pricing_rows) * 0.55) + price_power + (1.2 if any(t in texts for t in ("acv", "gross margin", "seat", "subscription", "enterprise")) else 0.0))

    high_pain = sum(1 for r in pain_rows if str(r.get("severity", "")).lower() == "high")
    pain_terms = sum(1 for t in ("automation limits", "poor reporting", "bad integrations", "slow workflows", "hallucinations", "weak escalation") if t in texts)
    buyer_pain_severity = clamp(3.0 + min(3.0, len(pain_rows) * 0.7) + min(2.0, high_pain * 0.8) + min(2.0, pain_terms * 0.45))

    cited_rows = sum(1 for r in evidence_rows if r.get("citation_allowed") is True or r.get("grade") in {"A", "B"})
    quality_rows = sum(1 for r in evidence_rows if str(r.get("quality_grade") or r.get("grade", "")).upper() in {"A", "B"})
    strict_pack_raw = diligence.get("strict_verification_pack", {}) or {}
    strict_pack = strict_pack_raw if isinstance(strict_pack_raw, dict) else {}
    display_rules_raw = strict_pack.get("display_rules", {}) or {}
    display_rules = display_rules_raw if isinstance(display_rules_raw, dict) else {}
    tam_verified = bool(display_rules.get("show_tam_sam_som_as_verified"))
    confidence_score = clamp(2.2 + min(2.5, len(evidence_rows) / 12) + min(2.0, cited_rows / 5) + min(1.4, quality_rows / 5) + (1.2 if pricing_rows else 0.0) + (0.7 if tam_verified else -0.5))

    return {
        "market_attractiveness": market_attractiveness,
        "competition_intensity": competition_intensity,
        "monetization_strength": monetization_strength,
        "buyer_pain_severity": buyer_pain_severity,
        "confidence_score": confidence_score,
        "evidence_counts": {
            "total_rows": len(evidence_rows),
            "pricing_rows": len(pricing_rows),
            "competitor_rows": len(competitor_rows),
            "buyer_pain_rows": len(pain_rows),
            "citable_or_b_grade_rows": cited_rows,
        },
    }


def build_investment_verdict(scorecard) -> dict:
    if not isinstance(scorecard, dict):
        scorecard = {}
    market = float(scorecard.get("market_attractiveness", 0) or 0)
    competition = float(scorecard.get("competition_intensity", 0) or 0)
    monetization = float(scorecard.get("monetization_strength", 0) or 0)
    pain = float(scorecard.get("buyer_pain_severity", 0) or 0)
    confidence = float(scorecard.get("confidence_score", 0) or 0)
    investment_score = round((market * 0.24) + ((10 - competition) * 0.12) + (monetization * 0.24) + (pain * 0.22) + (confidence * 0.18), 1)
    if investment_score >= 8.0 and market >= 7 and pain >= 7 and monetization >= 7 and competition <= 6.5 and confidence >= 6:
        verdict = "STRONG_YES"
    elif investment_score >= 6.7 and market >= 6 and pain >= 6 and monetization >= 5.8 and confidence >= 5:
        verdict = "CONDITIONAL_YES"
    elif investment_score >= 4.8 and confidence >= 3.8:
        verdict = "MAYBE"
    else:
        verdict = "NO"
    rationale, risks = [], []
    if market >= 7:
        rationale.append("strong market attractiveness")
    if pain >= 7:
        rationale.append("strong buyer pain")
    if monetization >= 7:
        rationale.append("good pricing power")
    if competition <= 6:
        rationale.append("manageable competition")
    if confidence >= 7:
        rationale.append("credible evidence base")
    if competition >= 7:
        risks.append("high incumbent strength")
    if confidence < 6:
        risks.append("weak or incomplete evidence confidence")
    if monetization < 6:
        risks.append("pricing power not proven")
    if pain < 6:
        risks.append("buyer urgency not proven")
    if market < 6:
        risks.append("market scale or growth not strong enough")
    return {
        "verdict": verdict,
        "investment_score": investment_score,
        "scorecard": scorecard,
        "rationale": rationale or ["mixed but usable investment signals"],
        "risks": risks or ["execution and evidence quality still require diligence"],
    }


def build_claude_analyst_packet(report_payload) -> dict:
    """Aggregate already-computed evidence for Claude's final analyst reasoning."""
    report_payload = report_payload or {}
    diligence = report_payload.get("diligence_pack", {}) or {}
    if not isinstance(diligence, dict):
        diligence = {}
    investment = report_payload.get("investment_decision", {}) or {}
    if not isinstance(investment, dict):
        investment = {}
    bottom_up = report_payload.get("bottom_up_market_model", {}) or {}
    if not isinstance(bottom_up, dict):
        bottom_up = {}
    citation_ledger_raw = diligence.get("citation_ledger", []) or []
    if isinstance(citation_ledger_raw, dict):
        citation_sources = _list(citation_ledger_raw.get("sources"))[:30]
    elif isinstance(citation_ledger_raw, list):
        citation_sources = citation_ledger_raw[:30]
    else:
        citation_sources = []

    def _list(value):
        return value if isinstance(value, list) else []

    def _collect_buyer_pain() -> list[dict]:
        rows = []
        for value in diligence.values():
            if isinstance(value, list):
                candidates = value
            elif isinstance(value, dict):
                candidates = []
                for nested in value.values():
                    if isinstance(nested, list):
                        candidates.extend(nested)
                    elif isinstance(nested, dict):
                        candidates.append(nested)
            else:
                continue
            for row in candidates:
                marker = str(
                    row.get("record_type") or row.get("claim_type") or row.get("source_family") or row
                ).lower() if isinstance(row, dict) else str(row).lower()
                if any(t in marker for t in ("buyer_pain", "buyer_signal", "complaint", "friction", "workflow pain")):
                    rows.append(row)
        return rows[:20]

    pricing_pack = diligence.get("pricing_intelligence_pack", {}) or {}
    if not isinstance(pricing_pack, dict):
        pricing_pack = {}
    sam_som_raw = bottom_up.get("sam_som", {}) or {}
    sam_som = sam_som_raw if isinstance(sam_som_raw, dict) else {}
    bottom_up_calc_raw = diligence.get("bottom_up_market_calculation", {}) or {}
    bottom_up_calc = bottom_up_calc_raw if isinstance(bottom_up_calc_raw, dict) else {}
    return {
        "topic": report_payload.get("topic", ""),
        "industry": report_payload.get("industry", ""),
        "country": report_payload.get("geography", ""),
        "competitors": _list(diligence.get("competitive_benchmark"))[:20],
        "pricing": _list(pricing_pack.get("pricing_rows"))[:20],
        "buyer_pain": _collect_buyer_pain(),
        "tam_model": {
            "bottom_up_market_calculation": bottom_up_calc,
            "bottom_up_market_model": bottom_up,
        },
        "sam_model": sam_som.get("sam"),
        "som_model": sam_som,
        "source_table": citation_sources,
        "investment_scorecard": investment.get("scorecard", {}),
        "heuristic_verdict": {
            "verdict": investment.get("verdict"),
            "investment_score": investment.get("investment_score"),
            "rationale": investment.get("rationale", []),
            "risks": investment.get("risks", []),
        },
    }


def build_claude_analyst_prompt(packet) -> str:
    return (
        "Analyze this IIDATECH analyst packet and return valid JSON only.\n\n"
        "Role: You are a senior market analyst combining a McKinsey strategy partner, "
        "SaaS investor, and VC diligence expert.\n\n"
        "Tasks: analyze evidence, reason about competition correctly, identify risks, "
        "identify moats, and produce a funding-grade conclusion.\n\n"
        "Critical rules:\n"
        "- High competition does NOT automatically mean a bad market; it may prove demand.\n"
        "- Do not score mechanically; reason from the evidence packet.\n"
        "- Do NOT invent numbers. Use ONLY supplied packet numbers.\n"
        "- If evidence is weak, say so explicitly.\n"
        "- Return exactly these keys: executive_summary, market_verdict, why_now, "
        "major_risks, moats, investor_take, confidence.\n"
        "- market_verdict must be one of STRONG YES, CONDITIONAL YES, MAYBE, NO.\n"
        "- confidence must be 0-10.\n\n"
        f"PACKET:\n{json.dumps(packet, ensure_ascii=False, default=str)[:28000]}"
    )


def run_claude_analyst(packet):
    if str(os.getenv("IIDATECH_CLAUDE_ANALYST_MODE", "1")).strip().lower() in {"0", "false", "off", "no"}:
        return None
    if not cloud_llm_configured():
        return None
    system = (
        "You are IIDATECH's final Claude analyst layer. Return strict JSON only. "
        "Do not fabricate numbers or sources."
    )
    try:
        text, model = anthropic_text_request(
            build_claude_analyst_prompt(packet),
            system,
            candidates=ANTHROPIC_MODEL_CANDIDATES,
            max_tokens=1600,
            temperature=0.15,
        )
        parsed = json.loads(extract_json_object(text))
        if not isinstance(parsed, dict):
            return None
        verdict = str(parsed.get("market_verdict", "MAYBE")).upper().replace(" ", "_")
        if verdict not in {"STRONG_YES", "CONDITIONAL_YES", "MAYBE", "NO"}:
            verdict = "MAYBE"
        confidence = max(0.0, min(10.0, float(parsed.get("confidence", 0) or 0)))
        return {
            "verdict": verdict,
            "investment_score": round(confidence, 1),
            "scorecard": packet.get("investment_scorecard", {}),
            "rationale": parsed.get("why_now", []) or [parsed.get("executive_summary", "")],
            "risks": parsed.get("major_risks", []) or ["Evidence gaps remain."],
            "executive_summary": parsed.get("executive_summary", ""),
            "market_verdict": parsed.get("market_verdict", verdict.replace("_", " ")),
            "why_now": parsed.get("why_now", []),
            "major_risks": parsed.get("major_risks", []),
            "moats": parsed.get("moats", []),
            "investor_take": parsed.get("investor_take", ""),
            "confidence": round(confidence, 1),
            "analyst_mode": "claude",
            "analyst_model": model,
        }
    except Exception as exc:
        return {"_claude_analyst_error": str(exc)[:240]}


