def build_evidence_summary_for_boardroom(report_payload: dict) -> dict:
    report_payload = report_payload or {}
    diligence = report_payload.get("diligence_pack", {}) or {}
    if not isinstance(diligence, dict):
        diligence = {}
    bottom_up = report_payload.get("bottom_up_market_model", {}) or {}
    if not isinstance(bottom_up, dict):
        bottom_up = {}
    readiness = report_payload.get("evidence_completeness", {}) or {}
    sections = report_payload.get("sections", {}) or {}
    if not isinstance(sections, dict):
        sections = {}
    pricing_pack = diligence.get("pricing_intelligence_pack")
    pricing_pack = pricing_pack if isinstance(pricing_pack, dict) else {}
    markets_gate = diligence.get("markets_report_gate")
    markets_gate = markets_gate if isinstance(markets_gate, dict) else {}
    section_summaries = []
    for sec_id, raw in list(sections.items())[:12]:
        snippet = str(raw or "")[:1200]
        try:
            parsed = json.loads(re.sub(r"^```(?:json)?\s*|\s*```$", "", snippet.strip(), flags=re.MULTILINE))
            if isinstance(parsed, dict):
                snippet = str(parsed.get("summary") or parsed.get("Executive takeaway") or parsed.get("Market thesis") or snippet)[:900]
        except Exception:
            pass
        section_summaries.append({"section_id": sec_id, "summary": snippet})
    truth_quality = {}
    competitor_intelligence = {}
    try:
        from iidatech.retrieval.source_trust import summarize_truth_quality
        from iidatech.services.competitor_intelligence import build_competitor_intelligence
        ledger_records = diligence.get("citation_ledger") or []
        if isinstance(ledger_records, dict):
            ledger_records = ledger_records.get("sources") or []
        evidence_records = list(ledger_records) if isinstance(ledger_records, list) else []
        truth_quality = summarize_truth_quality(evidence_records)
        competitor_intelligence = build_competitor_intelligence(evidence_records, diligence_pack=diligence)
    except Exception:
        pass
    return {
        "topic": report_payload.get("topic", ""),
        "industry": report_payload.get("industry", ""),
        "geography": report_payload.get("geography", ""),
        "competitors": (diligence.get("competitive_benchmark") or [])[:15],
        "pricing": (pricing_pack.get("pricing_rows") or [])[:12],
        "buyer_signals": (diligence.get("buyer_pain_signals") or diligence.get("buyer_validation") or [])[:12],
        "tam_model": bottom_up.get("tam_result", {}) or diligence.get("bottom_up_market_calculation", {}),
        "sam_som": bottom_up.get("sam_som", {}),
        "evidence_completeness": readiness,
        "markets_gate_profile": markets_gate.get("industry_gate_profile", ""),
        "section_summaries": section_summaries,
        "truth_quality": truth_quality,
        "competitor_intelligence": competitor_intelligence,
    }


def normalize_boardroom_strategist_output(raw: dict) -> dict:
    raw = raw or {}
    verdict = str(raw.get("investment_verdict", "MAYBE")).upper().replace(" ", "_")
    if verdict not in {"STRONG_YES", "CONDITIONAL_YES", "MAYBE", "NO", "BUILD", "AVOID"}:
        verdict = "MAYBE"
    build_or_avoid = str(raw.get("build_or_avoid", "")).strip().lower()
    if build_or_avoid not in {"build", "avoid", "pilot", "wait"}:
        build_or_avoid = "pilot" if verdict in {"STRONG_YES", "CONDITIONAL_YES"} else "wait"
    conviction = max(0.0, min(10.0, float(raw.get("conviction_score", raw.get("confidence", 0)) or 0)))

    def _list(key: str) -> list:
        value = raw.get(key, [])
        if isinstance(value, list):
            return [str(item).strip() for item in value if str(item).strip()]
        if value:
            return [str(value).strip()]
        return []

    return {
        "investment_verdict": verdict,
        "conviction_score": round(conviction, 1),
        "market_thesis": str(raw.get("market_thesis", "")).strip(),
        "market_attractiveness": str(raw.get("market_attractiveness", "")).strip(),
        "competitor_weaknesses": _list("competitor_weaknesses"),
        "founder_wedges": _list("founder_wedges"),
        "winning_GTM": str(raw.get("winning_GTM", raw.get("winning_gtm", ""))).strip(),
        "biggest_risks": _list("biggest_risks"),
        "build_or_avoid": build_or_avoid,
        "final_recommendation": str(raw.get("final_recommendation", "")).strip(),
        "strategic_insight_complete": bool(
            str(raw.get("market_thesis", "")).strip()
            and (_list("competitor_weaknesses") or _list("founder_wedges"))
            and str(raw.get("winning_GTM", raw.get("winning_gtm", ""))).strip()
            and str(raw.get("final_recommendation", "")).strip()
        ),
    }


def boardroom_to_investment_decision(boardroom: dict, scorecard: dict | None = None) -> dict:
    boardroom = boardroom or {}
    verdict = str(boardroom.get("investment_verdict", "MAYBE")).upper()
    if verdict == "BUILD":
        verdict = "CONDITIONAL_YES"
    elif verdict == "AVOID":
        verdict = "NO"
    return {
        "verdict": verdict,
        "investment_score": boardroom.get("conviction_score", 0),
        "scorecard": scorecard or {},
        "rationale": [
            boardroom.get("market_thesis", ""),
            boardroom.get("market_attractiveness", ""),
            boardroom.get("final_recommendation", ""),
        ],
        "risks": boardroom.get("biggest_risks", []) or ["Execution and evidence quality still require diligence."],
        "founder_wedges": boardroom.get("founder_wedges", []),
        "competitor_weaknesses": boardroom.get("competitor_weaknesses", []),
        "winning_gtm": boardroom.get("winning_GTM", ""),
        "build_or_avoid": boardroom.get("build_or_avoid", ""),
        "analyst_mode": "boardroom_strategist",
        "analyst_model": boardroom.get("analyst_model", ""),
    }


def build_boardroom_strategist_prompt(
    report_sections: dict,
    evidence_summary: dict,
    market_model: dict,
    topic: str,
    industry: str,
    geography: str,
) -> str:
    return (
        "Analyze this market opportunity for a founder or investment committee.\n\n"
        f"Topic: {topic}\nIndustry: {industry}\nGeography: {geography}\n\n"
        "You must answer: market thesis, competitor map (via weaknesses), white space (via wedges), "
        "founder wedge, GTM for first 100 customers, and investment verdict.\n\n"
        "Return JSON with exactly these keys:\n"
        "investment_verdict, conviction_score, market_thesis, market_attractiveness, "
        "competitor_weaknesses, founder_wedges, winning_GTM, biggest_risks, build_or_avoid, final_recommendation\n\n"
        "investment_verdict must be one of: STRONG_YES, CONDITIONAL_YES, MAYBE, NO, BUILD, AVOID\n"
        "build_or_avoid must be one of: build, avoid, pilot, wait\n"
        "conviction_score must be 0-10.\n\n"
        f"MARKET_MODEL:\n{json.dumps(market_model or {}, ensure_ascii=False, default=str)[:8000]}\n\n"
        f"EVIDENCE_SUMMARY:\n{json.dumps(evidence_summary or {}, ensure_ascii=False, default=str)[:14000]}\n\n"
        f"REPORT_SECTIONS:\n{json.dumps(report_sections or {}, ensure_ascii=False, default=str)[:12000]}"
    )


def run_boardroom_strategist(
    report_sections: dict,
    evidence_summary: dict,
    market_model: dict,
    topic: str = "",
    industry: str = "",
    geography: str = "",
) -> dict | None:
    if str(os.getenv("IIDATECH_BOARDROOM_STRATEGIST", "1")).strip().lower() in {"0", "false", "off", "no"}:
        return None
    if not cloud_llm_configured():
        return None
    try:
        text, model = anthropic_text_request(
            build_boardroom_strategist_prompt(
                report_sections, evidence_summary, market_model, topic, industry, geography
            ),
            BOARDROOM_STRATEGIST_SYSTEM,
            candidates=ANTHROPIC_BOARDROOM_MODEL_CANDIDATES,
            max_tokens=2200,
            temperature=0.2,
        )
        parsed = json.loads(extract_json_object(text))
        if not isinstance(parsed, dict):
            return None
        normalized = normalize_boardroom_strategist_output(parsed)
        normalized["analyst_model"] = model
        return normalized
    except Exception as exc:
        return {"_boardroom_strategist_error": str(exc)[:240]}


def render_boardroom_strategist_output(boardroom: dict) -> None:
    boardroom = boardroom or {}
    if boardroom.get("_boardroom_strategist_error"):
        if not client_report_mode():
            st.warning(f"Boardroom strategist unavailable: {boardroom.get('_boardroom_strategist_error')}")
        return
    verdict = str(boardroom.get("investment_verdict", "MAYBE")).replace("_", " ")
    st.markdown("## Boardroom Verdict")
    st.markdown(f"**Investment verdict:** {verdict}")
    st.markdown(f"**Conviction:** {boardroom.get('conviction_score', 'n/a')}/10")
    st.markdown(f"**Build or avoid:** {str(boardroom.get('build_or_avoid', 'n/a')).title()}")
    if boardroom.get("market_thesis"):
        st.markdown("### Market thesis")
        st.markdown(sanitize_report_text(str(boardroom.get("market_thesis"))))
    if boardroom.get("market_attractiveness"):
        st.markdown("### Market attractiveness")
        st.markdown(sanitize_report_text(str(boardroom.get("market_attractiveness"))))
    if boardroom.get("competitor_weaknesses"):
        st.markdown("### Competitor weaknesses")
        for item in boardroom.get("competitor_weaknesses", []):
            st.markdown(f"- {sanitize_report_text(str(item))}")
    if boardroom.get("founder_wedges"):
        st.markdown("### Founder wedges")
        for item in boardroom.get("founder_wedges", []):
            st.markdown(f"- {sanitize_report_text(str(item))}")
    if boardroom.get("winning_GTM"):
        st.markdown("### Winning GTM")
        st.markdown(sanitize_report_text(str(boardroom.get("winning_GTM"))))
    if boardroom.get("biggest_risks"):
        st.markdown("### Biggest risks")
        for item in boardroom.get("biggest_risks", []):
            st.markdown(f"- {sanitize_report_text(str(item))}")
    if boardroom.get("final_recommendation"):
        st.markdown("### Final recommendation")
        st.markdown(sanitize_report_text(str(boardroom.get("final_recommendation"))))


def build_tam_inputs(evidence_rows, report_context) -> dict:
    """Derive explicit bottom-up TAM inputs from trusted evidence rows."""
    report_context = report_context or {}
    topic = report_context.get("topic", "")
    industry = report_context.get("industry", "")
    target = report_context.get("geography") or report_context.get("target", "")
    domain = classify_topic_domain(topic, industry) if topic or industry else "general_market"
    rows = list(evidence_rows or [])
    if topic and industry and target:
        for section in ("Market Size & Valuation", "Pricing Analysis", "Consumer Behavior"):
            try:
                rows.extend(select_market_records(topic, industry, target, section, max_records=12))
            except Exception:
                pass
    diligence = report_context.get("diligence_pack", {}) or {}
    for value in diligence.values():
        if isinstance(value, list):
            rows.extend(row for row in value if isinstance(row, dict))
        elif isinstance(value, dict):
            for nested in value.values():
                if isinstance(nested, list):
                    rows.extend(row for row in nested if isinstance(row, dict))
                elif isinstance(nested, dict):
                    rows.append(nested)

    blocked_families = {"reddit_practitioner", "community_forum", "forum", "reddit", "social_media", "buyer_signal"}
    rows = [
        r for r in rows
        if isinstance(r, dict)
        and not _is_synthetic_record(r)
        and str(r.get("source_family", "")).lower() not in blocked_families
    ]

    def confidence(row: dict, base: float = 0.55) -> float:
        grade = str(row.get("quality_grade") or row.get("grade") or "").upper()
        score = float(row.get("quality_score", 0) or 0)
        if score:
            base = max(base, min(0.92, score / 100))
        base = max(base, {"A": 0.86, "B": 0.74, "C": 0.58}.get(grade[:1], base))
        if row.get("citation_allowed") is True:
            base += 0.04
        return round(min(0.95, base), 2)

    def number_from(value) -> float:
        if isinstance(value, (int, float)):
            return float(value)
        text = str(value or "")
        match = re.search(r"(\d+(?:,\d{3})*(?:\.\d+)?)(?:\s*([KMBT%])(?![A-Za-z]))?", text, re.I)
        if not match:
            return 0.0
        num = float(match.group(1).replace(",", ""))
        suffix = (match.group(2) or "").upper()
        if suffix == "%":
            return num / 100
        return num * {"K": 1e3, "M": 1e6, "B": 1e9, "T": 1e12}.get(suffix, 1)

    def row_text(row: dict) -> str:
        return " ".join(str(row.get(k, "")) for k in (
            "title", "metric_name", "metric_value", "value", "text", "summary",
            "source_family", "claim_type", "topic_tags", "record_type",
        )).lower()

    buyer_terms = ("business", "businesses", "smb", "sme", "store", "stores", "clinic", "clinics", "buyer", "buyers", "customer", "customers", "accounts")
    buyer_candidate = None
    for row in rows:
        hay = row_text(row)
        claim = canonical_claim_type(row.get("claim_type", ""))
        if claim != "market_denominator" and not any(term in hay for term in buyer_terms):
            continue
        value = max(number_from(row.get("metric_value")), number_from(row.get("value")), number_from(row.get("text")), number_from(row.get("title")))
        if value >= 100:
            cand = {
                "value": int(round(value)),
                "confidence": confidence(row, 0.62),
                "source": row.get("title") or row.get("source_family") or "market denominator",
                "record_id": row.get("record_id") or row.get("id"),
            }
            if not buyer_candidate or cand["confidence"] > buyer_candidate["confidence"]:
                buyer_candidate = cand

    pricing_candidate = None
    price_re = re.compile(r"(?P<cur>\$|₹|€|£)\s*(?P<num>\d+(?:,\d{3})*(?:\.\d+)?)\s*(?:/\s*|\s+per\s+)?(?P<unit>month|mo|monthly|year|yr|annual|annually)?", re.I)
    for row in rows:
        hay = row_text(row)
        if canonical_claim_type(row.get("claim_type", "")) != "pricing" and "pricing" not in hay and row.get("record_type") != "pricing":
            continue
        annual = number_from(row.get("annual_price"))
        monthly = number_from(row.get("monthly_price"))
        if monthly:
            annual = monthly * 12
        if not annual:
            for match in price_re.finditer(hay):
                value = float(match.group("num").replace(",", ""))
                unit = (match.group("unit") or "month").lower()
                annual = value if unit in {"year", "yr", "annual", "annually"} else value * 12
                break
        if annual and annual >= 12:
            cand = {
                "value": round(annual, 2),
                "confidence": confidence(row, 0.64),
                "source": row.get("title") or row.get("company") or row.get("source_family") or "pricing evidence",
                "record_id": row.get("record_id") or row.get("id"),
            }
            if not pricing_candidate or cand["confidence"] > pricing_candidate["confidence"]:
                pricing_candidate = cand

    penetration_candidate = None
    for row in rows:
        hay = row_text(row)
        if not any(term in hay for term in ("adoption", "penetration", "digital", "cloud", "software usage", "internet users")):
            continue
        for pct in re.findall(r"(\d+(?:\.\d+)?)\s*%", hay):
            value = float(pct) / 100
            if 0.01 <= value <= 0.95:
                penetration_candidate = {
                    "value": round(value, 4),
                    "confidence": confidence(row, 0.58),
                    "source": row.get("title") or row.get("source_family") or "adoption evidence",
                    "record_id": row.get("record_id") or row.get("id"),
                }
                break
        if penetration_candidate:
            break
    if not penetration_candidate:
        fallback = {
            "crm_automation": 0.35,
            "b2b_saas": 0.32,
            "revops_sales_automation": 0.28,
            "ai_workflow_automation": 0.24,
            "healthcare": 0.18,
            "agriculture": 0.10,
        }.get(domain, 0.20)
        penetration_candidate = {
            "value": fallback,
            "confidence": 0.42,
            "source": f"deterministic {domain} penetration band",
            "record_id": None,
        }

    return {
        "buyer_count": buyer_candidate or {"value": None, "confidence": 0.0, "source": "missing market denominator"},
        "penetration_rate": penetration_candidate,
        "annual_spend": pricing_candidate or {"value": None, "confidence": 0.0, "source": "missing pricing evidence"},
    }


def compute_bottom_up_tam(tam_inputs) -> dict:
    buyer_count = (tam_inputs.get("buyer_count") or {}).get("value")
    penetration = (tam_inputs.get("penetration_rate") or {}).get("value")
    annual_spend = (tam_inputs.get("annual_spend") or {}).get("value")
    confidences = [
        float((tam_inputs.get(key) or {}).get("confidence", 0) or 0)
        for key in ("buyer_count", "penetration_rate", "annual_spend")
    ]
    if not (buyer_count and penetration and annual_spend):
        return {
            "tam": None,
            "confidence": 0.0,
            "formula": "buyer_count * penetration_rate * annual_spend",
            "status": "missing_inputs",
        }
    return {
        "tam": round(float(buyer_count) * float(penetration) * float(annual_spend), 2),
        "confidence": round(min(confidences) * 0.95, 2),
        "formula": "buyer_count * penetration_rate * annual_spend",
        "status": "computed",
    }


def compute_sam_som(tam_result, evidence_rows) -> dict:
    tam = tam_result.get("tam")
    if not tam:
        return {"sam": None, "som": None, "sam_share": None, "som_share": None, "confidence": 0.0}
    blob = " ".join(str(row) for row in (evidence_rows or [])).lower()
    sam_share = 0.45 if any(t in blob for t in ("global", "online", "cloud", "smb")) else 0.30
    som_share = 0.08 if any(t in blob for t in ("strong wedge", "high pain", "automation limits", "poor reporting")) else 0.04
    return {
        "sam": round(float(tam) * sam_share, 2),
        "som": round(float(tam) * sam_share * som_share, 2),
        "sam_share": sam_share,
        "som_share": som_share,
        "confidence": round(float(tam_result.get("confidence", 0) or 0) * 0.9, 2),
    }


def build_bottom_up_market_model(evidence_rows, report_context) -> dict:
    inputs = build_tam_inputs(evidence_rows, report_context)
    tam = compute_bottom_up_tam(inputs)
    sam_som = compute_sam_som(tam, evidence_rows)
    return {"inputs": inputs, "tam_result": tam, "sam_som": sam_som}


def unique_models(candidates: list[str] | None = None) -> list[str]:
    models = []
    for model in (candidates or ANTHROPIC_MODEL_CANDIDATES):
        if model and model not in models:
            models.append(model)
    return models


def test_anthropic_connection(api_key: str) -> tuple[bool, str]:
    if not api_key.strip():
        return False, "No Anthropic key provided."
    last_error = ""
    for model in unique_models():
        try:
            r = requests.post(
                "https://api.anthropic.com/v1/messages",
                headers={
                    "x-api-key": api_key.strip(),
                    "anthropic-version": "2023-06-01",
                    "content-type": "application/json",
                },
                json={
                    "model": model,
                    "max_tokens": 16,
                    "messages": [{"role": "user", "content": "Reply with OK."}],
                },
                timeout=SEARCH_TIMEOUT,
            )
            if r.status_code == 200:
                return True, f"Connected with model {model}."
            last_error = f"{model}: HTTP {r.status_code} {r.text[:180]}"
            if r.status_code == 401:
                break
        except Exception as e:
            last_error = f"{model}: {e}"
    return False, last_error or "Anthropic connection failed."

