def web_hit_to_record(hit: dict, provider: str) -> dict | None:
    title = str(hit.get("title") or "").strip()
    url = str(hit.get("url") or "").strip()
    text = str(hit.get("content") or hit.get("text") or hit.get("snippet") or "").strip()
    if not (title and url and text):
        return None
    host = urlparse(url).netloc.lower().replace("www.", "")
    blob = f"{title} {url} {text}".lower()
    vendor_hosts = ("salesforce", "hubspot", "zoho", "freshworks", "freshsales", "pipedrive")
    review_hosts = ("g2.com", "capterra", "gartner", "getapp")
    filing_terms = ("sec.gov", "annual report", "10-k", "10k", "investor relations", "earnings")
    analyst_hosts = ("mckinsey", "bcg", "bain", "deloitte", "pwc", "gartner", "forrester", "idc")
    academic_hosts = ("arxiv", "ssrn", "springer", "sciencedirect", "researchgate", "ieee", "acm.org")
    crm_terms = ("crm", "customer relationship management", "salesforce", "hubspot", "zoho", "freshsales", "pipedrive", "sales automation", "revops", "sales ops")
    saas_terms = ("saas", "subscription software", "cloud software", "business software", "workflow software")
    domains = []
    if any(t in blob for t in crm_terms):
        domains.append("crm_automation")
    if any(t in blob for t in saas_terms):
        domains.append("b2b_saas")
    if any(t in blob for t in ("revops", "revenue operations", "sales ops", "lead enrichment", "sales workflow")):
        domains.append("revops_sales_automation")
    if not domains:
        domains = ["general_market"]
    citation_allowed = True
    numeric_allowed = True
    source_family = "public_web"
    source_type = "web_source"
    quality_score = 62
    if any(h in host or h in blob for h in vendor_hosts) and any(t in blob for t in ("pricing", "price", "plans", "crm", "sales")):
        source_family, source_type, quality_score = "vendor_pricing", "commercial_vendor", 88
    elif any(h in host for h in review_hosts):
        source_family, source_type, quality_score = "market_reviews", "commercial_reviews", 78
        citation_allowed = numeric_allowed = False
    elif any(t in blob for t in filing_terms):
        source_family, source_type, quality_score = "filings", "financial_filing", 94
    elif any(h in host for h in analyst_hosts):
        source_family, source_type, quality_score = "analyst_research", "industry_analysis", 82
        numeric_allowed = any(t in blob for t in ("market size", "cagr", "adoption", "benchmark", "survey"))
    elif any(h in host for h in academic_hosts):
        source_family, source_type, quality_score = "academic_research", "academic", 55
        citation_allowed = numeric_allowed = False
        if not any(t in blob for t in crm_terms + saas_terms):
            quality_score = 45
            domains = ["general_market"]
    if any(d in domains for d in ("crm_automation", "b2b_saas", "revops_sales_automation")) and source_family in {"vendor_pricing", "filings", "analyst_research"}:
        quality_score = min(98, quality_score + 4)
    row = {
        "record_id": "web_" + hashlib.sha256(url.encode("utf-8")).hexdigest()[:16],
        "title": title,
        "url": url,
        "publisher": host or provider,
        "text": text[:1200],
        "source_family": source_family,
        "source_type": source_type,
        "domains": domains,
        "roles": ["retrieved_web", provider],
        "evidence_namespace": "real_evidence",
        "retrieval_allowed": True,
        "citation_allowed": citation_allowed,
        "numeric_evidence_allowed": numeric_allowed,
        "investor_evidence_allowed": citation_allowed,
        "quality_score": quality_score,
        "quality_grade": "A" if quality_score >= 85 else "B" if quality_score >= 70 else "C",
        "is_synthetic": False,
        "is_route_only": False,
    }
    if record_trace_enabled():
        trace_record_stage(
            row,
            stage="web_hit_to_record",
            accepted=True,
            quality_score=quality_score,
            detected_record_type=source_type,
            extracted_fields={"source_family": source_family, "domains": domains},
        )
    return row


