def _commercial_domains_for(domain: str) -> list[str]:
    if domain in {"crm_automation", "b2b_saas", "revops_sales_automation"}:
        return ["crm_automation", "b2b_saas", "revops_sales_automation"]
    if domain in {"automotive", "automotive_retail"}:
        return ["automotive", "automotive_retail"]
    if domain in {"ecommerce_retail", "consumer", "fashion"}:
        return ["ecommerce_retail", "consumer", "fashion"]
    return [domain or "general_market"]


def _known_company_matches(text: str, domain: str) -> list[tuple[str, str, str]]:
    blob = text.lower()
    vendors = dict(_COMMERCIAL_VENDOR_NAMES.get(domain, {}))
    if domain in {"crm_automation", "b2b_saas", "revops_sales_automation"}:
        for vendor_map in (
            _COMMERCIAL_VENDOR_NAMES["crm_automation"],
            _COMMERCIAL_VENDOR_NAMES["b2b_saas"],
            _COMMERCIAL_VENDOR_NAMES["revops_sales_automation"],
        ):
            vendors.update(vendor_map)
    if domain in {"automotive", "automotive_retail"}:
        vendors.update(_COMMERCIAL_VENDOR_NAMES.get("automotive", {}))
        vendors.update(_COMMERCIAL_VENDOR_NAMES.get("automotive_retail", {}))
    if domain in {"ecommerce_retail", "consumer", "fashion"}:
        vendors.update(_COMMERCIAL_VENDOR_NAMES.get("ecommerce_retail", {}))
    matches = []
    for company, (category, segment) in vendors.items():
        aliases = [company.lower(), company.lower().replace("freshworks", "freshsales"), company.lower().replace("-", " ")]
        if any(alias in blob for alias in aliases):
            matches.append((company, category, segment))
    return matches


def extract_competitor_records(text, topic, domain) -> list[dict]:
    records = []
    url_match = re.search(r"https?://\S+", text or "")
    url = url_match.group(0).rstrip(").,") if url_match else ""
    for company, category, segment in _known_company_matches(f"{topic} {text}", domain):
        rid = hashlib.sha256(f"competitor|{company}|{url}|{topic}".encode("utf-8")).hexdigest()[:16]
        evidence_text = clean_text(text, limit=500)
        confidence = "high" if company.lower() in evidence_text.lower() else "medium"
        row = {
            "record_id": f"web_competitor_{rid}",
            "record_type": "competitor",
            "claim_type": "competitor",
            "entity_name": company,
            "company": company,
            "category": category,
            "segment": segment,
            "title": f"{company} competitor intelligence",
            "text": f"{company} appears as a named competitor for {topic}. Category: {category}; segment: {segment}. Evidence: {evidence_text}",
            "evidence_text": evidence_text,
            "confidence_label": confidence,
            "url": url,
            "publisher": urlparse(url).netloc.lower().replace("www.", "") if url else "web",
            "source_family": "competitor_intelligence",
            "source_type": "commercial_web_extraction",
            "domains": _commercial_domains_for(domain),
            "topic_tags": ["competitive_landscape", "vendor_proxy", company.lower(), category.lower(), segment.lower()],
            "roles": ["structured_web_extraction", "competitor"],
            "evidence_namespace": "real_evidence",
            "retrieval_allowed": True,
            "citation_allowed": True,
            "numeric_evidence_allowed": False,
            "investor_evidence_allowed": True,
            "quality_score": 78,
            "quality_grade": "B",
            "is_synthetic": False,
            "is_route_only": False,
        }
        records.append(row)
        if record_trace_enabled():
            trace_record_stage(
                row,
                stage="extract_competitor_records",
                accepted=True,
                detected_record_type="competitor",
                extracted_fields={"entity_name": company, "confidence": confidence},
                quality_score=78,
            )
    return records


def extract_pricing_records(text, url, topic, domain) -> list[dict]:
    host_blob = f"{url} {topic} {text}"
    companies = _known_company_matches(host_blob, domain) or [("Unknown vendor", "SaaS", "pricing")]
    price_res = [
        re.compile(
            r"(?:(?:starting at|from)\s+)?(?P<cur>\$|₹|€|£|Rs\.?|INR|USD|EUR|GBP)\s*(?P<num>\d+(?:,\d{3})*(?:\.\d+)?)\s*(?P<suffix>[kKmM])?"
            r"(?:\s*/\s*|\s+per\s+|\s+)?(?P<unit>user|seat|month|mo|monthly|year|yr|annual|annually)?",
            re.I,
        ),
        re.compile(
            r"(?P<num>\d+(?:,\d{3})*(?:\.\d+)?)\s*(?P<cur>USD|EUR|GBP|INR|Rs\.?|₹|\$)\s*(?:/|\s+per\s+|\s+)?(?P<unit>user|seat|month|mo|monthly|year|yr|annual|annually)?",
            re.I,
        ),
        re.compile(
            r"(?P<num>\d+(?:,\d{3})*(?:\.\d+)?)\s*(?:INR|Rs\.?)\b(?:\s*/\s*|\s+per\s+)?(?P<unit>month|mo|monthly|year|user|seat)?",
            re.I,
        ),
    ]
    records = []
    blob_l = (text or "").lower()
    model = "subscription"
    if "usage-based" in blob_l or "usage based" in blob_l:
        model = "usage_based"
    elif "credit" in blob_l:
        model = "credits_based"
    elif "enterprise" in blob_l and "contact us" in blob_l:
        model = "enterprise_custom"
    seen_prices: set[str] = set()
    for price_re in price_res:
        for match in price_re.finditer(text or ""):
            raw = match.group(0).strip()
            if raw.lower() in seen_prices:
                continue
            seen_prices.add(raw.lower())
            num = float(match.group("num").replace(",", ""))
            if (match.groupdict().get("suffix") or "").lower() == "k":
                num *= 1000
            elif (match.groupdict().get("suffix") or "").lower() == "m":
                num *= 1000000
            period = (match.groupdict().get("unit") or match.groupdict().get("period") or "month").lower()
            unit = (match.groupdict().get("unit") or "").lower()
            pricing_model = "seat_based" if unit in {"user", "seat"} else model
            cur_token = match.groupdict().get("cur") or "$"
            currency = {
                "$": "USD", "₹": "INR", "€": "EUR", "£": "GBP",
                "rs.": "INR", "rs": "INR", "inr": "INR", "usd": "USD", "eur": "EUR", "gbp": "GBP",
            }.get(str(cur_token).lower(), "USD")
            lead = text[max(0, match.start() - 70):match.start()]
            plan = re.findall(r"(Free|Starter|Basic|Standard|Professional|Pro|Enterprise|Growth|Advanced)", lead, flags=re.I)
            company = companies[0][0]
            rid = hashlib.sha256(f"pricing|{company}|{url}|{raw}".encode("utf-8")).hexdigest()[:16]
            row = {
                "record_id": f"web_pricing_{rid}",
                "record_type": "pricing",
                "claim_type": "pricing",
                "entity_name": company,
                "company": company,
                "plan_name": plan[-1].title() if plan else None,
                "price_value": raw,
                "monthly_price": num if period in {"month", "mo", "monthly"} else None,
                "annual_price": num if period in {"year", "yr", "annual", "annually"} else None,
                "currency": currency,
                "billing_model": pricing_model,
                "pricing_model": pricing_model,
                "title": f"{company} pricing: {raw}",
                "text": f"{company} pricing evidence: {raw}. Billing model: {pricing_model}. Source text: {clean_text(text, limit=500)}",
                "evidence_text": clean_text(text, limit=500),
                "url": url,
                "publisher": urlparse(url).netloc.lower().replace("www.", "") if url else "web",
                "source_family": "vendor_pricing",
                "source_type": "commercial_vendor",
                "domains": _commercial_domains_for(domain),
                "topic_tags": ["pricing", "unit_economics", "vendor_proxy", company.lower(), pricing_model],
                "roles": ["structured_web_extraction", "pricing"],
                "evidence_namespace": "real_evidence",
                "retrieval_allowed": True,
                "citation_allowed": True,
                "numeric_evidence_allowed": True,
                "investor_evidence_allowed": True,
                "quality_score": 88,
                "quality_grade": "A",
                "is_synthetic": False,
                "is_route_only": False,
            }
            records.append(row)
            if record_trace_enabled():
                trace_record_stage(
                    row,
                    stage="extract_pricing_records",
                    accepted=True,
                    detected_record_type="pricing",
                    extracted_fields={"entity_name": company, "price_value": raw, "billing_model": pricing_model},
                    quality_score=88,
                )
    if not records and model in {"usage_based", "credits_based", "enterprise_custom"}:
        company = companies[0][0]
        rid = hashlib.sha256(f"pricing-model|{company}|{url}|{model}".encode("utf-8")).hexdigest()[:16]
        records.append({
            "record_id": f"web_pricing_{rid}",
            "record_type": "pricing",
            "claim_type": "pricing",
            "company": company,
            "plan_name": None,
            "monthly_price": None,
            "annual_price": None,
            "currency": "USD",
            "pricing_model": model,
            "title": f"{company} pricing model: {model}",
            "text": f"{company} uses {model.replace('_', ' ')} pricing. Source text: {clean_text(text, limit=500)}",
            "url": url,
            "publisher": urlparse(url).netloc.lower().replace("www.", "") if url else "web",
            "source_family": "vendor_pricing",
            "source_type": "commercial_vendor",
            "domains": _commercial_domains_for(domain),
            "topic_tags": ["pricing", "unit_economics", "vendor_proxy", model],
            "roles": ["structured_web_extraction", "pricing"],
            "evidence_namespace": "real_evidence",
            "retrieval_allowed": True,
            "citation_allowed": True,
            "numeric_evidence_allowed": True,
            "investor_evidence_allowed": True,
            "quality_score": 82,
            "quality_grade": "B",
            "is_synthetic": False,
            "is_route_only": False,
        })
    return records[:6]


def extract_buyer_pain_records(text, source_family) -> list[dict]:
    allowed_families = {
        "market_reviews", "review_platform", "reddit", "forum", "social_media",
        "community_forum", "buyer_signal", "reddit_practitioner", "public_web",
        "magazine_article", "youtube_transcript", "podcast_interview", "buyer_voice",
    }
    if str(source_family or "").lower() not in allowed_families:
        if record_trace_enabled():
            trace_record_stage(
                {"source_family": source_family, "text": text},
                stage="extract_buyer_pain_records",
                accepted=False,
                rejection_reason="source_precision_excluded",
            )
        return []
    pain_terms = {
        "too expensive": ("too expensive", "overpriced", "pricey", "costly"),
        "poor support": ("poor support", "bad support", "slow support", "unresponsive support"),
        "buggy product": ("buggy", "glitchy", "crashes", "unstable"),
        "difficult onboarding": ("difficult onboarding", "hard to onboard", "steep learning curve", "confusing setup"),
        "integration issues": ("integration issues", "bad integration", "poor integration", "doesn't integrate", "integration problems"),
        "slow service": ("slow service", "delayed service", "long wait", "slow turnaround"),
        "delayed delivery": ("delayed delivery", "late delivery", "shipping delay"),
        "costly maintenance": ("costly maintenance", "expensive maintenance", "high service cost"),
        "poor data hygiene": ("data hygiene", "duplicate data", "dirty data"),
        "slow workflows": ("slow workflow", "too many clicks", "manual workflow", "slow to use"),
        "poor reporting": ("poor reporting", "reporting limitations", "weak reporting"),
    }
    blob = (text or "").lower()
    records = []
    for pain, aliases in pain_terms.items():
        if any(alias in blob for alias in aliases):
            severity = "high" if any(t in blob for t in ("hate", "terrible", "dealbreaker", "churn", "cancel")) else "medium"
            frequency = "high" if blob.count(pain.split()[0]) > 1 or "many users" in blob else "medium"
            rid = hashlib.sha256(f"buyer-pain|{pain}|{text[:160]}".encode("utf-8")).hexdigest()[:16]
            entity = ""
            for name in KNOWN_SAAS_COMPETITOR_NAMES + KNOWN_AUTOMOTIVE_COMPETITOR_NAMES:
                if name.lower() in blob:
                    entity = name
                    break
            row = {
                "record_id": f"web_buyer_pain_{rid}",
                "record_type": "buyer_pain",
                "claim_type": "buyer_voice",
                "entity_name": entity,
                "pain_point": pain,
                "complaint": pain,
                "severity": severity,
                "frequency": frequency,
                "persona": "SMB operator" if "smb" in blob or "small business" in blob else None,
                "title": f"Buyer pain: {pain}",
                "text": f"Buyer pain signal: {pain}. Severity: {severity}; frequency: {frequency}. Source text: {clean_text(text, limit=500)}",
                "evidence_text": clean_text(text, limit=500),
                "source_family": "buyer_signal",
                "source_type": "review_or_forum_signal",
                "domains": ["crm_automation", "b2b_saas", "revops_sales_automation", "ai_support_ecommerce", "automotive", "ecommerce_retail"],
                "topic_tags": ["buyer_behavior", "buyer_voice", "workflow_value", pain],
                "roles": ["structured_web_extraction", "buyer_pain"],
                "evidence_namespace": "real_evidence",
                "retrieval_allowed": True,
                "citation_allowed": False,
                "numeric_evidence_allowed": False,
                "investor_evidence_allowed": False,
                "quality_score": 72,
                "quality_grade": "B",
                "is_synthetic": False,
                "is_route_only": False,
            }
            records.append(row)
            if record_trace_enabled():
                trace_record_stage(
                    row,
                    stage="extract_buyer_pain_records",
                    accepted=True,
                    detected_record_type="buyer_pain",
                    extracted_fields={"entity_name": entity, "complaint": pain},
                    quality_score=72,
                )
    return records[:8]


def get_recent_structured_web_records(topic: str | None = None) -> list[dict]:
    """Return PR3-A extracted web records from the most recent deep_vector_search call.

    Filters out synthetic rows, very-low-quality rows, and records that don't
    carry ``evidence_namespace == "real_evidence"``.  Optional *topic* string is
    used for a lightweight keyword relevance check so that stale cache records
    from a previous section's retrieval don't contaminate unrelated sections.
    """
    if not _LATEST_WEB_RECORDS:
        return []

    topic_tokens: set[str] = set()
    if topic:
        topic_tokens = set(re.findall(r"[a-z0-9]+", topic.lower())) - {
            "for", "the", "and", "with", "of", "in", "on", "a", "an", "to",
        }

    out: list[dict] = []
    for rec in _LATEST_WEB_RECORDS:
        if _is_synthetic_record(rec):
            if record_trace_enabled():
                trace_record_stage(rec, stage="get_recent_structured_web_records", accepted=False, rejection_reason="synthetic_blocked")
            continue
        if rec.get("evidence_namespace") != "real_evidence":
            if record_trace_enabled():
                trace_record_stage(rec, stage="get_recent_structured_web_records", accepted=False, rejection_reason="synthetic_blocked")
            continue
        trusted = record_host_is_trusted_research(str(rec.get("url", "")), str(rec.get("publisher", "")))
        quality_floor = 30 if trusted else 40
        quality = int(rec.get("quality_score", 0) or 0)
        if quality < quality_floor:
            if record_trace_enabled():
                trace_record_stage(rec, stage="get_recent_structured_web_records", accepted=False, rejection_reason="quality_below_threshold", quality_score=quality)
            continue
        if topic_tokens:
            haystack = " ".join(
                str(rec.get(f, "")) for f in ("title", "text", "publisher", "url", "domains", "company", "entity_name")
            ).lower()
            token_hits = sum(1 for t in topic_tokens if t in haystack)
            if token_hits == 0:
                if record_trace_enabled():
                    trace_record_stage(rec, stage="get_recent_structured_web_records", accepted=False, rejection_reason="topic_mismatch")
                continue
        if record_trace_enabled():
            trace_record_stage(rec, stage="get_recent_structured_web_records", accepted=True, quality_score=quality)
        out.append(rec)
    return out


def _structured_web_records_block(
    records: list[dict],
    topic: str = "",
    industry: str = "",
    target: str = "",
    section: dict | None = None,
) -> str:
    if topic and industry and target and section:
        domain = classify_topic_domain(topic, industry)
        query_terms = set(re.findall(r"[a-z0-9]+", f"{topic} {industry} {target} {section.get('title', '')}".lower()))
        preferred_tags = SECTION_EVIDENCE_TAGS.get(section.get("title", ""), []) + DOMAIN_EVIDENCE_TAGS.get(domain, [])
        preferred_claims = section_claim_type_preferences(section.get("title", ""))
        quality_lookup = {
            str(r.get("record_id") or r.get("id") or ""): r
            for r in records
            if str(r.get("record_id") or r.get("id") or "")
        }
        market_niche = identify_market_niche(topic, industry, target)
        min_domain_confidence = 0.38 if domain != "general_market" else 0.0
        scored = []
        for record in records:
            record = dict(record)
            record.setdefault("id", record.get("record_id"))
            record.setdefault("geography", target or "global")
            result = _score_market_record_for_section(
                record,
                topic=topic,
                industry=industry,
                target=target,
                section=section,
                domain=domain,
                query_terms=query_terms,
                preferred_tags=preferred_tags,
                preferred_claims=preferred_claims,
                quality_lookup=quality_lookup,
                min_domain_confidence=min_domain_confidence,
                exact_local_or_operator_niche=False,
                market_niche=market_niche,
                country_mode=False,
                target_l=target.lower(),
            )
            if result:
                score, scored_record, _precision = result
                scored.append((score, scored_record))
        records = [r for _score, r in sorted(scored, key=lambda item: item[0], reverse=True)]
        if not records:
            return ""
        source_table = source_relevance_table(records, topic, industry, target, section.get("title", ""))[:12]
    else:
        source_table = []
    rows = []
    for r in records[:12]:
        rows.append(
            f"[WEB STRUCTURED | {r.get('source_family')} | {r.get('source_type')} | score {r.get('quality_score')}]\n"
            f"Title: {r.get('title', '')}\n"
            f"Summary: {clean_text(r.get('text', ''), limit=700)}\n"
            f"Source: {r.get('url', '')}\n"
            f"Publisher: {r.get('publisher', '')}\n"
            f"Domains: {', '.join(r.get('domains', []))}\n"
            f"Allowed: citation={r.get('citation_allowed')} numeric={r.get('numeric_evidence_allowed')} investor={r.get('investor_evidence_allowed')}"
        )
    table = "\n\nWEB EVIDENCE SOURCE RELEVANCE TABLE:\n" + json.dumps(source_table, indent=2) if source_table else ""
    return "STRUCTURED WEB EVIDENCE RECORDS:\n" + "\n\n".join(rows) + table


def fetch_tavily(query: str, return_records: bool = False, topic: str = "", domain: str = "") -> str | dict:
    """Pull top 5 results from Tavily and extract clean text snippets."""
    if not TAVILY_KEY:
        return ""
    try:
        from iidatech.storage.cache_repository import infer_cache_kind
        from iidatech.storage.provider_cache import cached_provider_call

        try:
            from tavily import TavilyClient
        except ImportError:
            return {"raw": "", "records": []} if return_records else ""

        client = TavilyClient(api_key=TAVILY_KEY)
        res = cached_provider_call(
            "tavily",
            query,
            infer_cache_kind(query, "tavily"),
            "",
            lambda: client.search(query=query, search_depth="advanced", max_results=5, timeout=SEARCH_TIMEOUT),
            model="tavily",
            estimated_cost=0.01,
        )
        # res["results"] is a list of dicts with keys: title, url, content, score
        snippets = []
        records = []
        for r in res.get("results", []):
            title   = r.get("title", "")
            content = r.get("content", "")
            url     = r.get("url", "")
            if content:
                snippets.append(f"- [{title}] ({url})\n  {content[:600]}")
                record = web_hit_to_record(r, "tavily")
                if record:
                    records.append(record)
                    evidence_text = f"{title}\n{url}\n{content}"
                    records.extend(extract_competitor_records(evidence_text, topic or query, domain or "general_market"))
                    records.extend(extract_pricing_records(evidence_text, url, topic or query, domain or "general_market"))
                    records.extend(extract_buyer_pain_records(evidence_text, record.get("source_family")))
        if not snippets:
            raw = "[Tavily: no results returned]"
        else:
            raw = "TAVILY RESULTS:\n" + "\n\n".join(snippets)
        return {"raw": raw, "records": records} if return_records else raw
    except Exception:
        return {"raw": "", "records": []} if return_records else ""


def fetch_exa(query: str, return_records: bool = False, topic: str = "", domain: str = "") -> str | dict:
    """Pull 3 results from Exa with full text content."""
    if not EXA_KEY:
        return ""
    try:
        from iidatech.storage.cache_repository import infer_cache_kind
        from iidatech.storage.provider_cache import cached_provider_call

        def _exa_call():
            resp = requests.post(
                "https://api.exa.ai/search",
                headers={
                    "x-api-key":    EXA_KEY,
                    "Content-Type": "application/json",
                },
                json={
                    "query":         query,
                    "numResults":    3,
                    "useAutoprompt": True,
                    "contents":      {"text": True},   # request full text
                },
                timeout=SEARCH_TIMEOUT,
            )
            if resp.status_code != 200:
                return {}
            return resp.json()

        data = cached_provider_call(
            "exa",
            query,
            infer_cache_kind(query, "exa"),
            "",
            _exa_call,
            model="exa",
            estimated_cost=0.01,
        )
        if not data:
            return {"raw": "", "records": []} if return_records else ""
        snippets = []
        records = []
        for r in data.get("results", []):
            title = r.get("title", "")
            url   = r.get("url", "")
            text  = r.get("text", r.get("snippet", ""))[:800]
            if text:
                snippets.append(f"- [{title}] ({url})\n  {text}")
                record = web_hit_to_record(r, "exa")
                if record:
                    records.append(record)
                    evidence_text = f"{title}\n{url}\n{text}"
                    records.extend(extract_competitor_records(evidence_text, topic or query, domain or "general_market"))
                    records.extend(extract_pricing_records(evidence_text, url, topic or query, domain or "general_market"))
                    records.extend(extract_buyer_pain_records(evidence_text, record.get("source_family")))
        if not snippets:
            raw = "[Exa: no results returned]"
        else:
            raw = "EXA RESULTS:\n" + "\n\n".join(snippets)
        return {"raw": raw, "records": records} if return_records else raw
    except Exception:
        return {"raw": "", "records": []} if return_records else ""


def fetch_firecrawl(query: str) -> str:
    """Search via Firecrawl and extract markdown content."""
    if not FIRECRAWL_KEY:
        return ""
    try:
        res = requests.post(
            "https://api.firecrawl.dev/v2/search",
            headers={
                # Firecrawl requires 'Bearer fc-<key>' OR raw key depending on version
                # Using raw key in Authorization as per their latest docs
                "Authorization": f"Bearer {FIRECRAWL_KEY}",
                "Content-Type":  "application/json",
            },
            json={
                "query": query,
                "limit": min(LIVE_RESEARCH_API_BUDGETS["firecrawl"]["results_per_query"], 3),
                "sources": [{"type": "web"}],
                "scrapeOptions": {"formats": [{"type": "markdown"}], "onlyMainContent": True},
            },
            timeout=SEARCH_TIMEOUT,
        )
        if res.status_code != 200:
            return ""

        data     = res.json()
        payload = data.get("data") or data
        result_rows = payload.get("web") if isinstance(payload, dict) else payload
        result_rows = result_rows or data.get("results") or data.get("data") or []
        snippets = []
        for r in result_rows:
            title   = r.get("metadata", {}).get("title", r.get("url", ""))
            url     = r.get("url", "")
            content = r.get("markdown", r.get("content", ""))[:800]
            if content:
                snippets.append(f"- [{title}] ({url})\n  {content}")
        if not snippets:
            return "[Firecrawl: no results returned]"
        return "FIRECRAWL RESULTS:\n" + "\n\n".join(snippets)
    except Exception:
        return ""


def xcrawl_search_rows(query: str, target: str = "", limit: int = 3) -> list[dict]:
    if not XCRAEL_KEY:
        return []
    try:
        payload = {
            "query": query,
            "limit": limit,
            "language": "en",
        }
        if target:
            payload["location"] = target
        res = requests.post(
            "https://run.xcrawl.com/v1/search",
            headers={
                "Authorization": f"Bearer {XCRAEL_KEY}",
                "Content-Type": "application/json",
            },
            json=payload,
            timeout=SEARCH_TIMEOUT,
        )
        if res.status_code != 200:
            return []

        data = res.json()
        return data.get("data", {}).get("data", []) or []
    except Exception:
        return []


def fetch_xcrael(query: str, target: str = "", industry: str = "") -> str:
    """Search via XCrawl/Xcrael and extract lightweight result snippets."""
    rows = xcrawl_search_rows(query, target=target, limit=3)
    if not rows:
        return ""
    snippets = []
    for row in rows:
        title = row.get("title") or row.get("url", "")
        url = row.get("url", "")
        snippet = row.get("snippet") or row.get("description") or ""
        body = f"- [{title}] ({url})"
        if snippet:
            body += f"\n  {snippet[:600]}"
        if industry:
            body += f"\n  Source route: XCrawl keyword search for {industry}"
        snippets.append(body)
    if not snippets:
        return "[XCrawl: no results returned]"
    return "XCRAWL RESULTS:\n" + "\n\n".join(snippets)


def url_host(url: str) -> str:
    try:
        host = urlparse(url).netloc.lower()
    except Exception:
        host = ""
    if host.startswith("www."):
        host = host[4:]
    return host


def allowed_country_domains(country: str | None) -> list[str]:
    if country_source_domains is None:
        return []
    return country_source_domains(country)


def url_allowed_for_country(url: str, country: str | None) -> bool:
    host = url_host(url)
    if not host:
        return False
    allowed = allowed_country_domains(country)
    return any(host == domain or host.endswith("." + domain) for domain in allowed)


def filter_web_block_to_country(block: str, country: str | None) -> str:
    """Keep only web-search snippets whose URL belongs to the selected country pack."""
    if not block:
        return ""
    kept = []
    for chunk in block.split("\n\n"):
        urls = re.findall(r"https?://[^\s)>\]]+", chunk)
        if urls and any(url_allowed_for_country(url.rstrip(".,;"), country) for url in urls):
            kept.append(chunk)
    return "\n\n".join(kept)


def country_grounding_context(country: str | None, topic: str, industry: str, section: dict) -> str:
    if country_grounding_profile is None:
        return ""
    profile = country_grounding_profile(country)
    sources = profile.get("sources", [])
    source_lines = []
    query_lines = []
    for item in sources:
        source_lines.append(
            f"- {item['publisher']} | domain: {item['domain']} | coverage: {item['coverage']} | url: {item['url']}"
        )
        query_lines.append(f"- {item['scraper_query']} {topic} {industry} {section.get('title', '')}")
    return (
        "COUNTRY GROUNDING CONTROL:\n"
        f"Country: {profile.get('country', country or '')}\n"
        f"Region family: {profile.get('region', '')}\n"
        f"Status: {profile.get('status', '')}; official source count: {profile.get('source_count', 0)}; "
        f"minimum required: {profile.get('minimum_source_count', 3)}\n"
        f"Allowed country-local source domains: {', '.join(profile.get('domains', [])) or 'none'}\n"
        f"Country-constrained scraper routes: {', '.join(profile.get('scraper_routes', [])) or 'none'}\n"
        f"Routing rule: {profile.get('routing_rule', '')}\n"
        "Figure rule: every figure must show Source, Inputs, Formula/Derivation, and Confidence. "
        "If hard-source inputs are missing or only proxy evidence exists, show the stored 2026 ESTIMATED model value and the missing-input table.\n"
        "Country-local source families:\n"
        + "\n".join(source_lines)
        + "\nMandatory country-constrained scraper queries:\n"
        + "\n".join(query_lines)
    )


def scraper_result_block(label: str, domain: str, rows: list[str]) -> str:
    if not rows:
        return ""
    return f"[COUNTRY SCRAPER | {label} | {domain} | confidence 80%]\n" + "\n\n".join(rows)


@st.cache_data(show_spinner=False, ttl=60 * 60 * 12)
def fetch_country_official_web_context(topic: str, industry: str, country: str, section_title: str) -> str:
    """Use only selected-country source domains for live web evidence."""
    if country_grounding_profile is None:
        return ""
    profile = country_grounding_profile(country)
    if profile.get("status") != "ready":
        return (
            "COUNTRY OFFICIAL WEB SCRAPER RESULTS:\n"
            f"No ready country grounding pack exists for {country}. Country-specific hard figures are not verified; use stored ESTIMATED figures only."
        )

    blocks = []
    source_items = profile.get("sources", [])[: max(1, COUNTRY_LIVE_DOMAIN_LIMIT)]
    for idx, source in enumerate(source_items):
        domain = source.get("domain", "")
        if not domain:
            continue
        query = (
            f"site:{domain} {country} {topic} {industry} {section_title} "
            "market data statistics business count regulation pricing revenue financials"
        )
        rows = []

        for row in xcrawl_search_rows(query, target=country, limit=3):
            url = row.get("url", "")
            if not url_allowed_for_country(url, country):
                continue
            title = row.get("title") or url
            snippet = (row.get("snippet") or row.get("description") or "")[:700]
            rows.append(f"Title: {title}\nSummary: {snippet}\nSource: {url}")
        block = scraper_result_block("XCRAWL", domain, rows[:3])
        if block:
            blocks.append(block)

        # Optional live routes remain country-constrained. They run only for the
        # first official domains to avoid making every section slow or expensive.
        if idx < 2:
            for label, fetcher in (("TAVILY", fetch_tavily), ("EXA", fetch_exa), ("FIRECRAWL", fetch_firecrawl)):
                raw = filter_web_block_to_country(fetcher(query), country)
                if raw:
                    blocks.append(f"[COUNTRY SCRAPER | {label} | {domain} | confidence 70%]\n{raw[:1600]}")

    if not blocks:
        route_notes = [
            f"{item.get('publisher')} ({item.get('domain')})"
            for item in profile.get("sources", [])
        ]
        return (
            "COUNTRY OFFICIAL WEB SCRAPER RESULTS:\n"
            "No live country-domain snippets were returned for this exact section. "
            "Use the country-local dataset records and stored ESTIMATED model values; do not call unsupported figures verified.\n"
            "Configured country sources: " + "; ".join(route_notes)
        )

    return "COUNTRY OFFICIAL WEB SCRAPER RESULTS:\n" + "\n\n".join(blocks[:10])


def fetch_public_packets(topic: str, industry: str, target: str, limit: int = 5) -> str:
    """Fetch and verify public research packets from the v2 live-source pipeline."""
    if not ENABLE_V2_LIVE_PACKETS:
        return (
            "[Public verified source packets: skipped during interactive preview for responsiveness. "
            "The report still uses the local market dataset, curated source packs, country packs, "
            "RAG memory, and configured live search routes. Set IIDATECH_ENABLE_V2_LIVE_PACKETS=1 "
            "for slower full live-packet harvesting.]"
        )
    if LiveMultiFetcher is None or CrossVerifier is None:
        return "[Public packet fetcher unavailable]"

    try:
        query = f"{topic} {target}".strip()
        fetcher = LiveMultiFetcher()
        verifier = CrossVerifier()
        packets = fetcher.fetch_all(query=query, industry=industry.lower(), limit_per_source=limit)
        verified = verifier.verify(packets)
        if not verified:
            return "[Public sources: no packets returned]"

        blocks = []
        ai_topic = is_ai_workflow_topic(topic, industry)
        for p in verified:
            packet_text = f"{p.title} {p.summary} {p.source_url}"
            if ai_topic and not relevant_to_ai_workflow(packet_text):
                continue
            status = getattr(p.status, "value", str(p.status))
            source = getattr(p.source_type, "value", str(p.source_type))
            blocks.append(
                f"[{status.upper()} | {source.upper()} | confidence {p.confidence:.0%}]\n"
                f"Title: {p.title}\n"
                f"Date: {p.date[:10]} | Geography: {p.geography}\n"
                f"Summary: {p.summary[:700]}\n"
                f"Source: {p.source_url}"
            )
            if len(blocks) >= 18:
                break
        if ai_topic and not blocks:
            return "[Public sources: live fetch returned no topic-relevant packets]"
        return "PUBLIC VERIFIED SOURCE PACKETS:\n" + "\n\n".join(blocks)
    except Exception as e:
        return f"[Public packet fetch error: {e}]"


