def extract_prompt_field(prompt: str, label: str, default: str = "") -> str:
    match = re.search(rf"^{re.escape(label)}:\s*(.+)$", prompt, flags=re.MULTILINE)
    return match.group(1).strip() if match else default


def extract_prompt_json_block(prompt: str, label: str) -> dict:
    match = re.search(
        rf"=== {re.escape(label)} ===\n(.+?)\n=== END {re.escape(label)} ===",
        prompt,
        flags=re.DOTALL,
    )
    if not match:
        return {}
    try:
        return json.loads(match.group(1))
    except Exception:
        return {}


def extract_research_summary(prompt: str) -> str:
    match = re.search(
        r"=== RESEARCH DATA ===\n(.+?)\n=== END RESEARCH DATA ===",
        prompt,
        flags=re.DOTALL,
    )
    raw = match.group(1).strip() if match else ""
    if not raw:
        return "No live research text was available for this section."

    lines = []
    for line in raw.splitlines():
        cleaned = line.strip()
        if not cleaned or cleaned.startswith("[") or " error:" in cleaned.lower():
            continue
        if len(cleaned) > 240:
            cleaned = cleaned[:237] + "..."
        lines.append(cleaned)
        if len(lines) >= 8:
            break
    return "\n".join(lines) if lines else raw[:1200]


BACKEND_NOISE_RE = re.compile(
    r"(DeepSeek\s+(?:error|HTTP|request failed)|Anthropic\s+(?:error|HTTP|request failed|synthesis failed)|"
    r"Cloud synthesis failed|Authentication\s+Fails?|401|403|api key|backend failure|fallback text|debug status|"
    r"Traceback|request failed)",
    flags=re.IGNORECASE,
)


def contains_backend_noise(text: str) -> bool:
    return bool(BACKEND_NOISE_RE.search(text or ""))


def strip_prior_memory(raw: str) -> str:
    """Prior report memory can contain old hallucinations; do not use it as numeric proof."""
    return re.sub(
        r"PRIOR MEMORY \(RAG\):.*?(?=\n\n(?:PUBLIC VERIFIED SOURCE PACKETS|TAVILY RESULTS|EXA RESULTS|FIRECRAWL RESULTS|XCRAWL RESULTS|RESEARCH ROUTING)|$)",
        "",
        raw,
        flags=re.DOTALL | re.IGNORECASE,
    )


def filter_research_context(raw: str, topic: str = "", industry: str = "") -> str:
    """Remove connector failure noise before it reaches report synthesis."""
    raw = strip_prior_memory(raw)
    cleaned_lines = []
    for line in raw.splitlines():
        if contains_backend_noise(line):
            continue
        cleaned_lines.append(line)
    cleaned = "\n".join(cleaned_lines)
    domain = classify_topic_domain(topic, industry) if topic or industry else "general_market"
    country_context_markers = (
        "COUNTRY GROUNDING CONTROL",
        "COUNTRY-SPECIFIC LOCAL MARKET DATASETS",
        "COUNTRY OFFICIAL WEB SCRAPER RESULTS",
        "COUNTRY SCRAPER",
        "COUNTRY MODE SOURCE BOUNDARY",
    )
    if domain == "ai_workflow_automation":
        relevant_blocks = []
        for block in cleaned.split("\n\n"):
            if (
                "CURATED AI WORKFLOW AUTOMATION SOURCE PACK" in block
                or "IIDATECH SIZING ASSUMPTIONS" in block
                or any(marker in block for marker in country_context_markers)
                or relevant_to_ai_workflow(block)
            ):
                relevant_blocks.append(block)
        cleaned = "\n\n".join(relevant_blocks)
    elif domain == "fashion":
        relevant_blocks = []
        for block in cleaned.split("\n\n"):
            if "CURATED FASHION / APPAREL SOURCE PACK" in block or any(marker in block for marker in country_context_markers) or relevant_to_fashion(block):
                relevant_blocks.append(block)
        cleaned = "\n\n".join(relevant_blocks)
    elif domain == "agriculture":
        relevant_blocks = []
        for block in cleaned.split("\n\n"):
            if "CURATED AGRICULTURE / AGRIBUSINESS SOURCE PACK" in block or any(marker in block for marker in country_context_markers) or relevant_to_agriculture(block):
                relevant_blocks.append(block)
        cleaned = "\n\n".join(relevant_blocks)
    elif domain == "water_environment":
        relevant_blocks = []
        for block in cleaned.split("\n\n"):
            if any(marker in block for marker in country_context_markers) or relevant_to_water_environment(block):
                relevant_blocks.append(block)
        cleaned = "\n\n".join(relevant_blocks)
    if topic or industry:
        leak_terms = REPORT_DOMAIN_LEAK_TERMS.get(domain, ())
        topic_terms = relevant_topic_tokens(topic, industry, "")
        if leak_terms:
            filtered_blocks = []
            for block in cleaned.split("\n\n"):
                block_l = block.lower()
                leak_hits = sum(1 for term in leak_terms if term in block_l)
                topic_hits = sum(1 for term in topic_terms if term in block_l)
                if leak_hits >= 2 and topic_hits < 2:
                    continue
                filtered_blocks.append(block)
            cleaned = "\n\n".join(filtered_blocks)
    cleaned = re.sub(r"\n{3,}", "\n\n", cleaned).strip()
    return cleaned or "No publishable research context was retrieved for this section."


def extract_evidence_items(prompt: str, limit: int = 10, topic: str = "", industry: str = "") -> list[dict]:
    match = re.search(
        r"=== RESEARCH DATA ===\n(.+?)\n=== END RESEARCH DATA ===",
        prompt,
        flags=re.DOTALL,
    )
    raw = match.group(1).strip() if match else ""
    topic = topic or extract_prompt_field(prompt, "Topic", "")
    industry = industry or extract_prompt_field(prompt, "Industry Vertical", "")
    raw = filter_research_context(raw, topic, industry)
    items = []
    current = {}

    for line in raw.splitlines():
        line = line.strip()
        if not line:
            continue
        if line.startswith("[") and "|" in line:
            if current:
                items.append(current)
            current = {"meta": line.strip("[]"), "title": "", "summary": "", "source": ""}
        elif line.startswith("Title:"):
            current["title"] = line.replace("Title:", "", 1).strip()
        elif line.startswith("Summary:"):
            current["summary"] = line.replace("Summary:", "", 1).strip()
        elif line.startswith("Source:"):
            current["source"] = line.replace("Source:", "", 1).strip()
        elif line.startswith("•") or line.startswith("â€¢") or line.startswith("-"):
            if current:
                items.append(current)
            match = re.search(r"(?:[\u2022-]|â€¢)\s*(?:\[(?P<title>[^\]]+)\]\s*)?\((?P<url>https?://[^)]+)\)", line)
            title = match.group("title") if match and match.group("title") else line[:160]
            source = match.group("url") if match else ""
            current = {"meta": "WEB", "title": title, "summary": "", "source": source}
        elif current and not current.get("summary") and not line.startswith(("PUBLIC", "TAVILY", "EXA", "FIRECRAWL", "XCRAWL", "RESEARCH")):
            current["summary"] = line[:700]

    if current:
        items.append(current)

    for idx, url in enumerate(re.findall(r"https?://[^\s)>\]]+", raw), start=1):
        clean_url = url.rstrip(".,;")
        host = re.sub(r"^www\.", "", re.sub(r"^https?://", "", clean_url).split("/")[0])
        items.append({
            "meta": "URL",
            "title": f"Retrieved source from {host}",
            "summary": "",
            "source": clean_url,
        })

    cleaned = []
    seen = set()
    for item in items:
        meta = str(item.get("meta", "")).lower()
        if "country_industry_pack" in meta:
            continue
        title = item.get("title") or item.get("summary", "")[:90]
        source = item.get("source", "")
        if not title or title in seen or source == "source URL unavailable":
            continue
        seen.add(title)
        cleaned.append(item)
        if len(cleaned) >= limit:
            break
    return cleaned


def citation_lines(evidence: list[dict], limit: int = 6) -> list[str]:
    lines = []
    for idx, item in enumerate(evidence[:limit], start=1):
        title = item.get("title") or "Untitled source"
        source = item.get("source") or "source URL unavailable"
        meta = item.get("meta") or "SOURCE"
        lines.append(f"[{idx}] {title} ({meta}) - {source}")
    return lines


