def render_active_pipeline_actions(mode: str, topic: str, industry: str, target: str, snapshot: dict) -> None:
    st.markdown(f"**Active pipeline: {mode}**")
    if mode == "Founder":
        st.table(founder_action_rows(snapshot))
        action_cols = st.columns(3)
        with action_cols[0]:
            if st.button("Send Idea To Business Builder", width="stretch"):
                st.session_state["business_builder_idea"] = topic
                st.session_state["business_builder_industry"] = industry
                st.session_state["business_builder_geo"] = target
                st.session_state["iidatech_active_pipeline"] = "Founder"
                st.success("Founder pipeline selected. The current idea is now loaded into the Agentic Business Builder context.")
        with action_cols[1]:
            if st.button("Create Founder Source Brief", width="stretch"):
                st.session_state["iidatech_source_collection_brief"] = source_collection_brief(topic, industry, target, mode, snapshot)
        with action_cols[2]:
            if st.button("Mark As IIDA Workspace", width="stretch"):
                st.session_state["iidatech_active_pipeline"] = "Founder"
                st.success("IIDA workspace mode is active for this session.")
    else:
        st.table(b2b_action_rows(snapshot))
        action_cols = st.columns(3)
        with action_cols[0]:
            if st.button("Prepare B2B Client Workspace", width="stretch"):
                st.session_state["iidatech_b2b_workspace"] = {
                    "topic": topic,
                    "industry": industry,
                    "market": target,
                    "deliverables": [
                        "market report",
                        "source appendix",
                        "business plan",
                        "financial assumptions table",
                        "client QA summary",
                    ],
                    "status": "draft client workspace",
                }
                st.session_state["iidatech_active_pipeline"] = "B2B"
                st.success("B2B client workspace prepared for this session.")
        with action_cols[1]:
            if st.button("Create B2B Source SLA", width="stretch"):
                st.session_state["iidatech_source_collection_brief"] = source_collection_brief(topic, industry, target, mode, snapshot)
        with action_cols[2]:
            if st.button("Mark As B2B Workspace", width="stretch"):
                st.session_state["iidatech_active_pipeline"] = "B2B"
                st.success("B2B workspace mode is active for this session.")

    brief = st.session_state.get("iidatech_source_collection_brief")
    if isinstance(brief, dict) and brief.get("mode") == mode:
        with st.expander(f"{mode} source collection brief", expanded=True):
            st.table([
                {"Field": "Topic", "Value": brief.get("topic", "")},
                {"Field": "Industry", "Value": brief.get("industry", "")},
                {"Field": "Market", "Value": brief.get("market", "")},
                {"Field": "Current market records", "Value": _commercial_number((brief.get("current_dataset_state") or {}).get("market_records"))},
                {"Field": "Indexed evidence rows", "Value": _commercial_number((brief.get("current_dataset_state") or {}).get("indexed_evidence"))},
                {"Field": "Targets needing collection", "Value": _commercial_number((brief.get("current_dataset_state") or {}).get("targets_needing_collection"))},
            ])
            st.markdown("**Priority source collection tasks**")
            for source in brief.get("priority_sources", []):
                st.markdown(f"- {source}")


