OPPORTUNITY_WORKSPACE_ROOT = APP_DIR / "opportunity_workspaces"


def opportunity_workspace_slug(topic: str, country: str, industry: str) -> str:
    return safe_filename(f"{topic}_{country}_{industry}")[:110] or "opportunity"


def opportunity_workspace_dir(topic: str, country: str, industry: str) -> Path:
    path = OPPORTUNITY_WORKSPACE_ROOT / opportunity_workspace_slug(topic, country, industry)
    path.mkdir(parents=True, exist_ok=True)
    return path


def store_opportunity_uploads(uploaded_files, topic: str, country: str, industry: str) -> list[dict]:
    if not uploaded_files:
        return []
    upload_dir = opportunity_workspace_dir(topic, country, industry) / "uploads"
    upload_dir.mkdir(parents=True, exist_ok=True)
    saved = []
    for uploaded in uploaded_files:
        try:
            file_name = safe_filename(getattr(uploaded, "name", "upload"))
            path = upload_dir / file_name
            data = uploaded.getvalue()
            path.write_bytes(data)
            saved.append({
                "name": getattr(uploaded, "name", file_name),
                "path": str(path),
                "mime": getattr(uploaded, "type", "") or Path(file_name).suffix,
                "bytes": len(data),
            })
        except Exception as exc:
            saved.append({
                "name": getattr(uploaded, "name", "upload"),
                "path": "",
                "error": str(exc)[:180],
            })
    return saved


def current_opportunity_workspace_payload(
    topic: str,
    country: str,
    industry: str,
    workflow_choice: str,
    upload_contexts: list[dict],
    saved_uploads: list[dict],
    scope_assessment: dict,
) -> dict:
    report = st.session_state.get("last_iidatech_report")
    plan = st.session_state.get("business_builder_plan")
    founder_plan = st.session_state.get("founder_readable_business_plan")
    leads = st.session_state.get("business_builder_leads") or st.session_state.get("apify_lead_results") or []
    source_ledger = []
    financial_model = {}
    if isinstance(report, dict):
        source_ledger = (((report.get("diligence_pack") or {}).get("citation_ledger")) or [])[:60]
        financial_model = report.get("quantitative_model", {}) or {}
    icp = plan.get("validated_icp", {}) if isinstance(plan, dict) else {}
    execution_system = plan.get("employee_execution_system", {}) if isinstance(plan, dict) else {}
    workspace_dir = opportunity_workspace_dir(topic, country, industry)
    return {
        "workspace_id": opportunity_workspace_slug(topic, country, industry),
        "workspace_dir": str(workspace_dir),
        "updated_at": datetime.utcnow().isoformat() + "Z",
        "idea": topic,
        "country": country,
        "industry": industry,
        "current_path": workflow_choice,
        "uploaded_files": saved_uploads,
        "uploaded_file_context": [
            {
                "name": item.get("name"),
                "kind": item.get("kind"),
                "mime": item.get("mime"),
                "bytes": item.get("bytes"),
                "text_preview": clean_text(item.get("text", ""), limit=600),
                "notes": item.get("notes", []),
            }
            for item in upload_contexts
        ],
        "source_ledger": source_ledger,
        "research_report": {
            "available": isinstance(report, dict),
            "topic": report.get("topic") if isinstance(report, dict) else "",
            "geography": report.get("geography") if isinstance(report, dict) else "",
            "section_count": len(report.get("sections", {}) or {}) if isinstance(report, dict) else 0,
        },
        "business_plan": {
            "available": isinstance(plan, dict),
            "quality": (plan.get("quality_gate") or {}) if isinstance(plan, dict) else {},
            "founder_readable_available": isinstance(founder_plan, dict),
        },
        "ICP": icp,
        "leads": leads[:100] if isinstance(leads, list) else leads,
        "financial_model": financial_model,
        "employees_team_tasks": execution_system,
        "exports": [
            "Founder business plan",
            "Investor memo",
            "GTM plan",
            "Financial model CSV/XLSX",
            "Lead list CSV",
            "Team task plan",
            "Source ledger",
        ],
        "scope_assessment": scope_assessment,
    }


def save_opportunity_workspace(payload: dict) -> Path | None:
    try:
        path = Path(payload["workspace_dir"]) / "workspace.json"
        path.write_text(json.dumps(payload, indent=2, ensure_ascii=False, default=str), encoding="utf-8")
        return path
    except Exception:
        return None


def list_opportunity_workspaces(limit: int = 20) -> list[dict]:
    rows = []
    if not OPPORTUNITY_WORKSPACE_ROOT.exists():
        return rows
    for path in OPPORTUNITY_WORKSPACE_ROOT.glob("*/workspace.json"):
        payload = read_json_file(path, {})
        if not isinstance(payload, dict):
            continue
        rows.append({
            "workspace_id": payload.get("workspace_id", path.parent.name),
            "idea": payload.get("idea", ""),
            "country": payload.get("country", ""),
            "industry": payload.get("industry", ""),
            "current_path": payload.get("current_path", ""),
            "updated_at": payload.get("updated_at", ""),
            "path": str(path),
            "uploaded_files": len(payload.get("uploaded_files", []) or []),
            "source_rows": len(payload.get("source_ledger", []) or []),
            "has_report": bool((payload.get("research_report") or {}).get("available")),
            "has_plan": bool((payload.get("business_plan") or {}).get("available")),
        })
    rows.sort(key=lambda row: str(row.get("updated_at", "")), reverse=True)
    return rows[:limit]


def opportunity_readiness_rows(workspace: dict) -> list[dict]:
    evidence_count = int(workspace.get("evidence_count", 0) or 0)
    has_report = bool(workspace.get("has_report"))
    has_plan = bool(workspace.get("has_business_plan"))
    has_leads = bool(workspace.get("has_leads"))
    has_financial = bool(workspace.get("has_financial_model"))
    return [
        {
            "Badge": "Market evidence",
            "Status": "Strong" if has_report and evidence_count >= 3 else "Medium" if has_report or evidence_count else "Weak",
            "Meaning": "Use for strategy" if has_report else "Needs source collection before hard claims.",
        },
        {
            "Badge": "ICP confidence",
            "Status": "Validated" if workspace.get("icp_validated") else "Hypothesis",
            "Meaning": "Validated by buyer/lead evidence." if workspace.get("icp_validated") else "Treat buyer profile as a testable wedge.",
        },
        {
            "Badge": "Financial confidence",
            "Status": "Modeled" if has_financial else "Needs data",
            "Meaning": "Financial model exists." if has_financial else "Add pricing, CAC, churn, margin, and conversion evidence.",
        },
        {
            "Badge": "Execution readiness",
            "Status": "Ready" if has_plan and has_leads else "Needs approval" if has_plan else "Not ready",
            "Meaning": "Execution can move to approval gates." if has_plan and has_leads else "Create plan and review leads before sending/posting.",
        },
    ]


