def founder_workspace_state(topic: str, industry: str, target: str, scope_assessment: dict, workflow_choice: str, upload_contexts: list[dict] | None = None) -> dict:
    """Compact state object used by the founder-friendly workspace shell."""
    plan = st.session_state.get("business_builder_plan")
    report = st.session_state.get("last_iidatech_report")
    founder_plan = st.session_state.get("founder_readable_business_plan")
    evidence_items = st.session_state.get("business_builder_current_evidence") or st.session_state.get("business_builder_evidence", [])
    upload_contexts = upload_contexts or []
    scope_ok = bool(scope_assessment.get("ok", True)) if isinstance(scope_assessment, dict) else True
    plan_ok = isinstance(plan, dict) and business_plan_matches_current(plan, topic, industry, target)
    report_ok = isinstance(report, dict) and str(report.get("topic", "")).strip().lower() == str(topic).strip().lower()
    financial_model = {}
    if isinstance(report, dict):
        financial_model = report.get("quantitative_model", {}) or {}
    if isinstance(plan, dict) and plan.get("financial_model"):
        financial_model = plan.get("financial_model", {}) or financial_model
    icp_block = plan.get("validated_icp", {}) if isinstance(plan, dict) else {}
    icp_evidence_gate = icp_block.get("evidence_gate", {}) if isinstance(icp_block, dict) else {}
    direct_records = int(icp_evidence_gate.get("direct_record_count", 0) or 0) if isinstance(icp_evidence_gate, dict) else 0
    combined_evidence_count = len(evidence_items) + len(upload_contexts)
    return {
        "topic": clean_text(topic, limit=180),
        "industry": clean_text(industry, limit=120),
        "target": clean_text(target, limit=80),
        "workflow_choice": workflow_choice,
        "scope_ok": scope_ok,
        "scope_issues": scope_assessment.get("issues", []) if isinstance(scope_assessment, dict) else [],
        "evidence_count": combined_evidence_count,
        "uploaded_file_count": len(upload_contexts),
        "has_report": report_ok,
        "has_business_plan": plan_ok,
        "has_founder_plan": isinstance(founder_plan, dict),
        "has_leads": bool(st.session_state.get("business_builder_leads") or st.session_state.get("apify_lead_results")),
        "has_financial_model": bool(financial_model),
        "icp_validated": direct_records >= 3 or combined_evidence_count >= 3,
        "opportunity_workspace_path": st.session_state.get("current_opportunity_workspace_path", ""),
        "has_team_memory": bool(plan.get("employee_execution_system")) if isinstance(plan, dict) else False,
    }


def founder_readiness_badges(workspace: dict) -> list[dict]:
    return opportunity_readiness_rows(workspace)


def founder_next_actions(workspace: dict) -> list[str]:
    actions = []
    if not workspace.get("scope_ok"):
        actions.append("Narrow the topic to one buyer, one geography, one product/use case, and one channel.")
    if not workspace.get("has_report"):
        actions.append("Generate market research and source readiness before relying on market claims.")
    if not workspace.get("has_business_plan"):
        actions.append("Build the business plan from the current idea and evidence.")
    if workspace.get("has_business_plan") and not workspace.get("has_founder_plan"):
        actions.append("Create the founder-readable business plan for clean execution steps.")
    if not workspace.get("has_leads"):
        actions.append("Find or import exact-fit leads, then review them before outreach.")
    if not actions:
        actions.append("Review the plan, source ledger, leads, financial model, and approval gate before execution.")
    return actions


def founder_workspace_markdown(workspace: dict) -> str:
    issue_lines = "\n".join(f"- {issue}" for issue in workspace.get("scope_issues", [])) or "- None"
    badge_lines = "\n".join(f"- {row['Badge']}: {row['Status']} - {row['Meaning']}" for row in founder_readiness_badges(workspace))
    action_lines = "\n".join(f"- {action}" for action in founder_next_actions(workspace))
    workspace_path = workspace.get("opportunity_workspace_path") or "created after first save"
    return f"""# IIDATECH Opportunity Workspace Brief

## Current Workspace
- Topic: {workspace.get('topic') or 'not set'}
- Industry: {workspace.get('industry') or 'not set'}
- Market: {workspace.get('target') or 'not set'}
- Current path: {workspace.get('workflow_choice')}
- Saved workspace: {workspace_path}

## Readiness
{badge_lines}

## Scope Issues
{issue_lines}

## Recommended Next Actions
{action_lines}

## Execution Boundary
Do not send emails, publish posts, contact leads, or spend money until the user approves the execution step and the source/contact evidence is visible.
"""


def render_guided_founder_workspace(workspace: dict) -> None:
    st.markdown("### Opportunity Workspace")
    st.caption("One saved workspace connects the idea, country, industry, files, source ledger, report, business plan, ICP, leads, model, team tasks, and exports.")
    st.markdown("**Plan of action**")
    step_rows = opportunity_step_rows(workspace)
    st.caption("This is a progress tracker. It moves forward when the matching output exists: evidence, report, plan, leads, or approved team work.")
    for idx, row in enumerate(step_rows):
        with st.container(border=True):
            step_cols = st.columns([0.9, 2.6, 0.9])
            step_cols[0].markdown(f"**{row['Status']}**")
            step_cols[1].markdown(f"**{row['Step']}** - {row['What to do']}  \nOwner: {row['Owner']}")
            button_label = "Review" if row["Status"] == "Done" else "Open step"
            if step_cols[2].button(button_label, key=f"workspace_step_{idx}_{safe_filename(row['Step'])}", width="stretch"):
                st.session_state["pending_founder_workflow_choice"] = row.get("Destination", WORKFLOW_UNDERSTAND)
                st.rerun()
    done_count = sum(1 for row in step_rows if row["Status"] == "Done")
    st.progress(done_count / max(len(step_rows), 1), text=f"{done_count}/{len(step_rows)} steps complete")
    st.table(founder_readiness_badges(workspace))
    if workspace.get("opportunity_workspace_path"):
        st.caption(f"Saved workspace: {workspace.get('opportunity_workspace_path')}")
    st.markdown("**Action-based next steps**")
    st.dataframe(opportunity_action_rows(workspace), width="stretch", hide_index=True)

    if not workspace.get("has_report") or workspace.get("evidence_count", 0) == 0:
        with st.expander("Data actions when information is missing", expanded=False):
            empty_cols = st.columns(3)
            empty_actions = [
                ("Find sources", WORKFLOW_UNDERSTAND),
                ("Upload competitor list", WORKFLOW_UNDERSTAND),
                ("Add customer interview notes", "Turn idea into business plan"),
                ("Collect pricing data", WORKFLOW_UNDERSTAND),
                ("Generate survey questions", "Turn idea into business plan"),
                ("Find leads", WORKFLOW_EMPLOYEE_OS2),
                ("Create automation", "Build automations"),
            ]
            for idx, (label, destination) in enumerate(empty_actions):
                if empty_cols[idx % 3].button(label, key=f"empty_action_{safe_filename(label)}", width="stretch"):
                    st.session_state["pending_founder_workflow_choice"] = destination
                    st.rerun()

    actions = founder_next_actions(workspace)
    st.info(actions[0])
    with st.expander("Workspace exports and actions", expanded=False):
        report = st.session_state.get("last_iidatech_report") if isinstance(st.session_state.get("last_iidatech_report"), dict) else {}
        model = report.get("quantitative_model", {}) if isinstance(report, dict) else {}
        source_ledger = (report.get("diligence_pack", {}) or {}).get("citation_ledger", []) if isinstance(report, dict) else []
        financial_rows = []
        for key in ("formula_rows", "scenario_rows", "driver_rows", "workload_rows", "sensitivity_rows"):
            for row in model.get(key, []) or []:
                if isinstance(row, dict):
                    financial_rows.append({"table": key, **row})
        leads = st.session_state.get("business_builder_leads") or st.session_state.get("apify_lead_results") or []
        lead_rows = [lead for lead in leads if isinstance(lead, dict)] if isinstance(leads, list) else []
        workspace_md = founder_workspace_markdown(workspace)
        gtm_rows = opportunity_action_rows(workspace)
        export_cols = st.columns(3)
        export_cols[0].download_button(
            "Founder business plan PDF",
            data=simple_pdf_bytes("Founder Business Plan", workspace_md),
            file_name=f"IIDATECH_FounderBusinessPlan_{safe_filename(workspace.get('topic') or 'idea')}.pdf",
            mime="application/pdf",
            width="stretch",
        )
        export_cols[1].download_button(
            "Investor memo",
            data=workspace_md.replace("Opportunity Workspace Brief", "Investor Memo"),
            file_name=f"IIDATECH_InvestorMemo_{safe_filename(workspace.get('topic') or 'idea')}.md",
            mime="text/markdown",
            width="stretch",
        )
        export_cols[2].download_button(
            "GTM plan",
            data=simple_csv(gtm_rows),
            file_name=f"IIDATECH_GTMPlan_{safe_filename(workspace.get('topic') or 'idea')}.csv",
            mime="text/csv",
            width="stretch",
        )
        export_cols_2 = st.columns(4)
        export_cols_2[0].download_button(
            "Financial model XLSX",
            data=simple_xlsx_bytes({"financial_model": financial_rows or [{"status": "No financial model yet"}]}),
            file_name=f"IIDATECH_FinancialModel_{safe_filename(workspace.get('topic') or 'idea')}.xlsx",
            mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            width="stretch",
        )
        export_cols_2[1].download_button(
            "Lead list CSV",
            data=simple_csv(lead_rows or [{"status": "No leads loaded yet"}]),
            file_name=f"IIDATECH_LeadList_{safe_filename(workspace.get('topic') or 'idea')}.csv",
            mime="text/csv",
            width="stretch",
        )
        export_cols_2[2].download_button(
            "Team task plan",
            data="\n".join(f"- {row['Owner']}: {row['Answer']}" for row in gtm_rows),
            file_name=f"IIDATECH_TeamTasks_{safe_filename(workspace.get('topic') or 'idea')}.md",
            mime="text/markdown",
            width="stretch",
        )
        export_cols_2[3].download_button(
            "Source ledger",
            data=simple_csv(source_ledger or [{"status": "No source ledger yet"}]),
            file_name=f"IIDATECH_SourceLedger_{safe_filename(workspace.get('topic') or 'idea')}.csv",
            mime="text/csv",
            width="stretch",
        )
        action_cols = st.columns(2)
        if action_cols[0].button("Use in Business Builder", width="stretch"):
            st.session_state["business_builder_idea"] = workspace.get("topic", "")
            st.session_state["business_builder_industry"] = workspace.get("industry", "")
            st.session_state["business_builder_geo"] = workspace.get("target", "")
            st.session_state["pending_founder_workflow_choice"] = "Turn idea into business plan"
            st.rerun()
        if action_cols[1].button("Run this with team", width="stretch"):
            st.session_state["pending_founder_workflow_choice"] = WORKFLOW_EMPLOYEE_OS2
            st.rerun()


LOCAL_USER_STORE_PATH = APP_DIR / "business_build_outputs" / "local_users.json"


def hash_local_password(password: str) -> str:
    salt = "iidatech-local-auth-v1"
    return hashlib.sha256(f"{salt}:{password}".encode("utf-8")).hexdigest()


def load_local_users() -> dict:
    users = read_json_file(LOCAL_USER_STORE_PATH, {})
    return users if isinstance(users, dict) else {}


def save_local_users(users: dict) -> None:
    write_json_file(LOCAL_USER_STORE_PATH, users)


def render_home_auth_shell() -> None:
    st.markdown('<div class="iid-hero">', unsafe_allow_html=True)
    st.markdown("## Build the business from idea to execution")
    st.write(
        "Understand your market with IIDATECH, turn evidence into a founder-readable business plan, and run approved execution with a company team. "
        "The workspace keeps research, ICP, financial model, team tasks, leads, exports, and source evidence together."
    )
    hero_cols = st.columns(3)
    hero_cols[0].metric("Research", "Evidence-led")
    hero_cols[1].metric("Planning", "Founder-ready")
    hero_cols[2].metric("Execution", "Approval-gated")
    st.markdown("</div>", unsafe_allow_html=True)

    auth_tabs = st.tabs(["Log in", "Register", "Continue as demo"])
    with auth_tabs[0]:
        email = st.text_input("Email", key="login_email")
        password = st.text_input("Password", type="password", key="login_password")
        if st.button("Log in", type="primary", width="stretch", key="login_button"):
            users = load_local_users()
            record = users.get(email.strip().lower())
            if record and record.get("password_hash") == hash_local_password(password):
                st.session_state["iidatech_authenticated"] = True
                st.session_state["iidatech_user_email"] = email.strip().lower()
                st.session_state["iidatech_app_page"] = "Dashboard"
                st.success("Logged in. Opening your dashboard.")
                st.rerun()
            else:
                st.error("Login failed. Check email and password, or register a local account.")
    with auth_tabs[1]:
        reg_email = st.text_input("Work email", key="register_email")
        reg_name = st.text_input("Name", key="register_name")
        reg_password = st.text_input("Create password", type="password", key="register_password")
        if st.button("Create account", type="primary", width="stretch", key="register_button"):
            if "@" not in reg_email or len(reg_password) < 6:
                st.error("Use a valid email and a password with at least 6 characters.")
            else:
                users = load_local_users()
                key = reg_email.strip().lower()
                if key in users:
                    st.warning("This local account already exists. Log in instead.")
                else:
                    users[key] = {
                        "name": reg_name.strip() or key.split("@")[0],
                        "email": key,
                        "password_hash": hash_local_password(reg_password),
                        "created_at": datetime.utcnow().isoformat() + "Z",
                    }
                    save_local_users(users)
                    st.session_state["iidatech_authenticated"] = True
                    st.session_state["iidatech_user_email"] = key
                    st.session_state["iidatech_app_page"] = "Dashboard"
                    st.success("Account created. Opening your dashboard.")
                    st.rerun()
    with auth_tabs[2]:
        st.write("Use demo mode for local testing without creating an account.")
        if st.button("Continue as demo", width="stretch", key="demo_login_button"):
            st.session_state["iidatech_authenticated"] = True
            st.session_state["iidatech_user_email"] = "demo@local"
            st.session_state["iidatech_app_page"] = "Dashboard"
            st.rerun()


