def activate_opportunity_project(payload: dict) -> None:
    idea = str(payload.get("idea") or payload.get("topic") or "").strip()
    industry = str(payload.get("industry") or "General").strip()
    country = str(payload.get("country") or payload.get("target") or "Global").strip()
    project_id = str(payload.get("workspace_id") or opportunity_workspace_slug(idea, country, industry))
    previous_project_id = st.session_state.get("active_opportunity_project_id")
    if previous_project_id != project_id:
        for key in (
            "last_iidatech_report",
            "business_builder_plan",
            "founder_readable_business_plan",
            "business_builder_leads",
            "apify_lead_results",
            "business_execution_pack",
            "deployment_readiness_pack",
            "business_builder_current_evidence",
            "business_builder_current_report_context",
        ):
            st.session_state.pop(key, None)
    st.session_state["active_opportunity_project_id"] = project_id
    st.session_state["workspace_topic"] = idea
    st.session_state["workspace_industry"] = industry
    st.session_state["workspace_country"] = country
    st.session_state["business_builder_idea"] = idea
    st.session_state["business_builder_industry"] = industry
    st.session_state["business_builder_geo"] = country
    st.session_state["current_opportunity_workspace"] = payload
    st.session_state["current_opportunity_workspace_path"] = str(Path(payload.get("workspace_dir", "")) / "workspace.json") if payload.get("workspace_dir") else payload.get("path", "")


def render_project_gate() -> None:
    st.markdown("## Create or open a project")
    st.caption("A project holds the idea, country, industry, uploaded evidence, report, business plan, team memory, leads, and exports.")
    create_tab, open_tab = st.tabs(["Create project", "Open existing"])
    with create_tab:
        project_idea = st.text_area("Project idea / topic", height=110, key="new_project_idea")
        cols = st.columns(2)
        project_industry = cols[0].text_input("Industry", value="", key="new_project_industry")
        project_country = cols[1].text_input("Country / market", value="Global", key="new_project_country")
        if st.button("Create project", type="primary", width="stretch", key="create_project_button"):
            if not project_idea.strip() or not project_industry.strip() or not project_country.strip():
                st.error("Add an idea, industry, and country/market to create a project.")
            else:
                scope = assess_topic_scope(project_idea, project_industry, project_country)
                payload = current_opportunity_workspace_payload(
                    project_idea.strip(),
                    project_country.strip(),
                    project_industry.strip(),
                    "Dashboard",
                    [],
                    [],
                    scope,
                )
                path = save_opportunity_workspace(payload)
                if path:
                    payload["path"] = str(path)
                activate_opportunity_project(payload)
                st.session_state.pop("founder_workflow_choice_value", None)
                st.success("Project created. Choose what to do first.")
                st.rerun()
    with open_tab:
        rows = list_opportunity_workspaces(limit=50)
        if not rows:
            st.info("No saved projects yet. Create one first.")
        else:
            selected_id = st.selectbox(
                "Saved projects",
                options=[row["workspace_id"] for row in rows],
                format_func=lambda workspace_id: next(
                    (
                        f"{row['idea'][:70]} | {row['country']} | {row['industry']}"
                        for row in rows
                        if row["workspace_id"] == workspace_id
                    ),
                    workspace_id,
                ),
                key="open_project_select",
            )
            selected = next((row for row in rows if row["workspace_id"] == selected_id), None)
            if selected:
                st.dataframe([selected], width="stretch", hide_index=True)
            if selected and st.button("Open project", type="primary", width="stretch", key="open_project_button"):
                payload = read_json_file(Path(selected["path"]), {})
                if isinstance(payload, dict):
                    payload["path"] = selected["path"]
                    activate_opportunity_project(payload)
                    st.session_state.pop("founder_workflow_choice_value", None)
                    st.success("Project opened. Choose what to do first.")
                    st.rerun()
                else:
                    st.error("Could not read that project file.")


