def _ensure_active_opportunity_project() -> None:
    if st.session_state.get("active_opportunity_project_id"):
        return
    recent_workspaces = list_opportunity_workspaces(limit=1)
    if recent_workspaces:
        latest_payload = read_json_file(Path(recent_workspaces[0]["path"]), {})
        if isinstance(latest_payload, dict):
            latest_payload["path"] = recent_workspaces[0]["path"]
            activate_opportunity_project(latest_payload)
    if not st.session_state.get("active_opportunity_project_id"):
        default_topic = st.session_state.get("workspace_topic") or st.session_state.get("business_builder_idea") or "AI workflow automation for small businesses"
        default_industry = st.session_state.get("workspace_industry") or st.session_state.get("business_builder_industry") or "Technology"
        default_country = st.session_state.get("workspace_country") or st.session_state.get("business_builder_geo") or "Global"
        default_scope = assess_topic_scope(default_topic, default_industry, default_country)
        default_payload = current_opportunity_workspace_payload(
            default_topic,
            default_country,
            default_industry,
            WORKFLOW_UNDERSTAND,
            [],
            [],
            default_scope,
        )
        default_path = save_opportunity_workspace(default_payload)
        if default_path:
            default_payload["path"] = str(default_path)
        activate_opportunity_project(default_payload)


