def _should_render_streamlit_workspace() -> bool:
    """Render workspace unless app.py was imported as a duplicate of the active script."""
    import sys

    this_mod = sys.modules.get(__name__)
    main_mod = sys.modules.get("__main__")
    if this_mod is main_mod or main_mod is None:
        return True

    this_file = os.path.normpath(getattr(this_mod, "__file__", "") or "")
    main_file = os.path.normpath(getattr(main_mod, "__file__", "") or "")

    # Home.py / streamlit_app.py delegate to app.py via runpy — same Streamlit session.
    if this_file.endswith(os.path.normpath("app.py")) and main_file:
        entry = os.path.basename(main_file).lower()
        if entry in {"home.py", "streamlit_app.py"}:
            return True

    return not (this_file and main_file and this_file == main_file)


if not _should_render_streamlit_workspace():
    st.stop()

